def load_user_permissions(username):
    """★ إضافة (إصدار 8 — الميزة 5): قراءة صلاحيات مستخدم من جدول users —
    المدير يملك كل الصلاحيات دائماً، والصلاحيات مخزنة نص JSON داخل العمود
    (والبائع القديم قبل الترقية يحصل تلقائياً على الافتراضية: إضافة العمليات فقط)"""
    row = get_user_row(username)
    if row is None:
        return []
    if row["role"] == "مدير":
        return [k for k, _ in PERMISSIONS]
    try:
        return json.loads(row["permissions"] or "[]")
    except Exception:
        return []

# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (المرحلة الأولى — الصلاحيات الدقيقة): المحرك والقراءة/الكتابة ★★★
# دوال جديدة كليًا مستقلة لا تُستدعى من أي دالة قائمة في هذه المرحلة،
# وتحفظ توافق صيغة القائمة الحالية في حقل permissions (نظام الإصدار 8):
# القائمة تبقى قائمة JSON كما يقرأها النظام القائم، ومفاتيح النظام القديم
# وكل قيمة أخرى موجودة تبقى في القائمة بترتيبها ولا تُكسر أي بيانات
# موجودة فيه، والقيمة الرقمية «أقصى نسبة خصم %» تُخزن داخل القائمة
# نفسها عنصرًا نصيًا ثابتًا (max_discount=N)
# ═══════════════════════════════════════════════════════════
def read_user_permissions_safe(username):
    """★ إضافة (المرحلة الأولى): قراءة آمنة لصلاحيات المستخدم الدقيقة —
    تُرجع قاموسًا: fine_keys (المفاتيح الدقيقة الممنوحة مرتبة)، وmax_discount
    (القيمة الرقمية — 0 = ممنوع من الخصم)، وlegacy (كل عناصر القائمة الأخرى
    كما هي بترتيبها الأصلي). أي خلل يُتجاهل بهدوء بلا كسر شيء"""
    out = {"fine_keys": [], "max_discount": 0.0, "legacy": []}
    try:
        row = get_user_row(username)
        if row is None:
            return out
        try:
            data = json.loads(row["permissions"] or "[]")
        except Exception:
            return out            # حقل فارغ أو تالف: بلا صلاحيات — ولا يُكسر شيء
        if not isinstance(data, list):
            return out            # صيغة غير متوقعة: يُتجاهل بأمان
        for item in data:
            if not isinstance(item, str):
                continue
            if item in PERMISSIONS_CATALOG:
                out["fine_keys"].append(item)
            elif item.startswith("max_discount="):
                try:
                    out["max_discount"] = float(item.split("=", 1)[1])
                except (ValueError, TypeError):
                    pass
            else:
                out["legacy"].append(item)
        out["fine_keys"].sort()
        return out
    except Exception:
        return out

def write_user_permissions_safe(username, fine_keys, max_discount):
    """★ إضافة (المرحلة الأولى): كتابة آمنة لصلاحيات المستخدم الدقيقة في
    حقل permissions — تبقى الصيغة قائمة JSON كما هي (توافقًا كاملًا مع
    النظام القائم الذي يقرأها قائمة)، وعناصر legacy تبقى أول القائمة
    بترتيبها الأصلي ثم المفاتيح الدقيقة مرتبة ثم عنصر القيمة الرقمية
    (max_discount=N) في نهايتها. تُرجع True عند النجاح وFalse لأي خلل"""
    try:
        if get_user_row(username) is None:
            return False          # مستخدم غير موجود — لا يُكتب شيء
        try:
            val = max(0.0, min(100.0, float(max_discount)))
        except (ValueError, TypeError):
            val = 0.0
        current = read_user_permissions_safe(username)
        clean_fine = sorted({str(k) for k in fine_keys if k in PERMISSIONS_CATALOG})
        final_list = (list(current["legacy"]) + clean_fine
                      + ["max_discount=%g" % val])
        with connect() as conn:
            conn.execute("UPDATE users SET permissions=? WHERE username=?",
                         (json.dumps(final_list, ensure_ascii=False), username))
        return True
    except Exception:
        return False

def user_has_permission(username, permission_key):
    """★ إضافة (المرحلة الأولى): محرك الفحص المستقل — أدمن نشط يملك كل
    الصلاحيات دائمًا (True)، وغير ذلك يُفحص حقل permissions الموجود في جدول
    users لهذا المستخدم (توافقًا مع صيغة القائمة الحالية)، وأي حالة أخرى
    تُرجع False: مستخدم غير موجود، أو غير نشط (اختيار أمان موثق: حتى لو
    كان أدمن)، أو مفتاح غير معروف في الكتالوج (اختيار أمان موثق: حتى
    للأدمن) — حماية من طبقتين: الزر لا يظهر إلا لمن مُنح صلاحيته، وهذا
    الفحص الداخلي الثاني عند التنفيذ"""
    try:
        row = get_user_row(username)
        if row is None:
            return False
        if not row["active"]:
            return False
        if permission_key not in PERMISSIONS_CATALOG:
            return False
        if row["role"] == ADMIN_ROLE:
            return True
        try:
            perms = json.loads(row["permissions"] or "[]")
        except Exception:
            return False
        if not isinstance(perms, list):
            return False
        return permission_key in perms
    except Exception:
        return False

# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (المرحلة الثانية — مركز المتابعة والرقابة): الجلسات والحدود ★★★
# طبقة متابعة مستقلة فوق كل ما هو قائم: جدول active_sessions جديد يُنشأ
# من هذه الدوال نفسها عند أول استخدام (CREATE TABLE IF NOT EXISTS — بلا
# أي مساس بدالة تهيئة القاعدة أو أي دالة إنشاء جداول قائمة)، ودوال تسجيل
# الجلسة ونبضها كل 30 ثانية وعرض المتصلين الآن، وحدود التنبيهات الست
# مفاتيح جديدة في جدول settings القائم بقيم افتراضية تُستخدم إن غاب
# المفتاح، وسطر مقارنة الأسبوع الماضي حتى نفس الساعة، وجامع الأنشطة غير
# الطبيعية قارئاً للسجلات الموجودة فقط (لا يُنشئ أي نوع حدث جديد في
# audit_log إطلاقاً) — وكل التوقيتات بنظام 24 ساعة وبنفس صيغ التوقيت
# المستخدمة في الكود، وكل حسابات «اليوم» من get_business_day() حصراً
# ═════════════════════════════════════════════════════════════

def monitor_hostname():
    """★ إضافة (المرحلة الثانية — المطلب 1): اسم هذا الجهاز لجدول الجلسات —
    بنفس أسلوب الكود القائم في device_printer_key تماماً (استيراد socket
    داخل الدالة وقراءة gethostname وأي فشل يرجع اسماً آمناً ثابتاً)"""
    try:
        import socket
        return (socket.gethostname() or "").strip() or "THIS-PC"
    except Exception:
        return "THIS-PC"

def _ensure_active_sessions_table():
    """★ إضافة (المرحلة الثانية — المطلب 1): إنشاء جدول active_sessions عند
    أول استخدام — CREATE TABLE IF NOT EXISTS من داخل هذه الدالة الجديدة
    نفسها حصراً (لا تُمس دالة تهيئة القاعدة ولا أي دالة إنشاء جداول
    قائمة)، وكل استدعاء بعده لا يفعل شيئاً لأن الجدول موجود أصلاً"""
    with connect() as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS active_sessions(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            hostname TEXT NOT NULL,
            login_time TEXT NOT NULL,
            last_seen TEXT NOT NULL)""")

def record_login_session(username):
    """★ إضافة (المرحلة الثانية — المطلب 2 + الاستثناء أ المصرح به): تسجيل
    صف جلسة جديد باسم المستخدم واسم هذا الجهاز ووقت الدخول — تُستدعى بسطر
    واحد من نهاية معالج تسجيل الدخول الناجح الموجود فقط (وهو معالج واحد
    يغطي دخول الإقلاع ودخول تبديل المستخدم معاً)، وأي فشل فيها لا يعطل
    الدخول أبداً؛ وتحاول بدء نبضة الجلسات إن لم تكن تعمل (تعمل فوراً عند
    تبديل المستخدم لأن النافذة الرئيسية حية، وتنتظر بدء البرنامج عند
    الإقلاع لأن شاشة الدخول تُغلق في اللحظة نفسها)"""
    try:
        _ensure_active_sessions_table()
        now_s = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with connect() as conn:
            conn.execute("INSERT INTO active_sessions(username,hostname,login_time,last_seen)"
                         " VALUES(?,?,?,?)",
                         (username, monitor_hostname(), now_s, now_s))
    except Exception:
        pass          # فشل تسجيل الجلسة لا يمنع الدخول أبداً
    try:
        start_session_heartbeat()
    except Exception:
        pass

def update_session_heartbeat():
    """★ إضافة (المرحلة الثانية — المطلب 2): نبضة الجلسة الدورية — تحدّث
    last_seen لكل صفحات المستخدم الحالي على هذا الجهاز، وتحذف الجلسات
    الأقدم من 24 ساعة تنظيفاً تلقائياً — كتابة على الجدول الجديد وحده
    ولا تُمس أي بيانات أخرى إطلاقاً"""
    try:
        _ensure_active_sessions_table()
        now = datetime.now()
        now_s = now.strftime("%Y-%m-%d %H:%M:%S")
        cutoff = datetime.fromtimestamp(now.timestamp() - 24 * 3600).strftime("%Y-%m-%d %H:%M:%S")
        with connect() as conn:
            conn.execute("UPDATE active_sessions SET last_seen=? WHERE username=? AND hostname=?",
                         (now_s, CURRENT_USER["name"], monitor_hostname()))
            conn.execute("DELETE FROM active_sessions WHERE last_seen < ?", (cutoff,))
    except Exception:
        pass

def get_online_users():
    """★ إضافة (المرحلة الثانية — المطلب 2): الجلسات التي آخر ظهور لها خلال
    آخر دقيقتين — هؤلاء هم «المتصلون الآن» على كل الأجهزة (الأحدث ظهوراً
    أولاً)"""
    try:
        _ensure_active_sessions_table()
        cutoff = datetime.fromtimestamp(datetime.now().timestamp() - 2 * 60).strftime("%Y-%m-%d %H:%M:%S")
        with connect() as conn:
            rows = conn.execute("SELECT username, hostname, login_time, last_seen "
                                "FROM active_sessions WHERE last_seen >= ? "
                                "ORDER BY last_seen DESC", (cutoff,)).fetchall()
        return [dict(r) for r in rows]
    except Exception:
        return []

# نبضة الجلسات: مؤقت root.after جديد مستقل تماماً كل 30 ثانية — لا يلمس
# مؤقت اليوم التجاري الستيني ولا أي مؤقت قائم، وتُعاد جدولته على النافذة
# الحية الحالية مع كل دقة فيبقى مع البرنامج كله حتى إغلاقه
SESSION_HEARTBEAT = {"root": None, "ms": 30000}

def _monitor_living_root():
    """★ إضافة (المرحلة الثانية): نافذة حية يمكن جدولة النبضة عليها —
    النافذة الرئيسية الافتراضية إن كانت قائمة (بعد فتح البرنامج أو أثناء
    تبديل المستخدم)، وإلا None (لحظة بين إغلاق شاشة الدخول وفتح البرنامج)"""
    try:
        r = tk._default_root
        if r is not None and r.winfo_exists():
            return r
    except Exception:
        pass
    return None

def _session_heartbeat_tick():
    """★ إضافة (المرحلة الثانية — المطلب 2): دقة النبضة — تحديث جلسة هذا
    الجهاز ثم إعادة جدولة نفسها بعد 30 ثانية على النافذة الحية الحالية"""
    try:
        update_session_heartbeat()
    except Exception:
        pass
    try:
        root = _monitor_living_root()
        if root is not None:
            SESSION_HEARTBEAT["root"] = root
            root.after(SESSION_HEARTBEAT["ms"], _session_heartbeat_tick)
        else:
            SESSION_HEARTBEAT["root"] = None   # لا نافذة حية: تهدأ بهدوء
    except Exception:
        SESSION_HEARTBEAT["root"] = None

def start_session_heartbeat(root=None):
    """★ إضافة (المرحلة الثانية — المطلب 2): بدء حلقة النبضة مرة واحدة —
    إن كانت تعمل على نافذة حية فلا شيء (منع النبضة المزدوجة أبداً)، وإلا
    تُجدول أول دقة بعد 30 ثانية على النافذة المعطاة أو على النافذة الحية
    إن وجدت؛ تُستدعى من record_login_session عند كل دخول ناجح ومن سطر
    البدء المعلن في App.__init__ عند إقلاع البرنامج — ولا تفعل شيئاً إن
    لم توجد نافذة حية (لحظة الإقلاع بين شاشة الدخول والنافذة الرئيسية)"""
    try:
        cur = SESSION_HEARTBEAT["root"]
        if cur is not None:
            try:
                if cur.winfo_exists():
                    return               # تعمل بالفعل — لا نبضة مزدوجة أبداً
            except Exception:
                pass                    # نافذة ميتة: تُجدول من جديد تحتها
        target = None
        if root is not None:
            try:
                if root.winfo_exists():
                    target = root
            except Exception:
                target = None
        if target is None:
            target = _monitor_living_root()
        if target is None:
            return                      # لا نافذة حية الآن — لا جدولة
        SESSION_HEARTBEAT["root"] = target
        target.after(SESSION_HEARTBEAT["ms"], _session_heartbeat_tick)
    except Exception:
        pass


# حدود التنبيهات الست — مفاتيح جديدة في جدول settings القائم، والقيم
# الافتراضية تُستخدم إن غاب المفتاح (ولا تُكتب تلقائياً أبداً: الكتابة
# عند الحفظ من شاشة المركز للأدمن وحده فقط)
ALERT_SETTINGS_DEFAULTS = {
    "alert_large_op_amount":       "5000",   # الحد الأدنى لتنبيه عملية كبيرة
    "alert_returns_limit":         "3",      # مرتجعات البائع في اليوم التي تثير تنبيهاً
    "alert_quick_return_minutes":  "30",     # الفترة بالدقائق التي يعتبر بعدها المرتجع طبيعياً
    "anomaly_price_deviation_pct": "20",     # نسبة انخفاض السعر عن معتاد الصنف %
    "shop_hours_start":            "09:00",  # بداية دوام المحل
    "shop_hours_end":              "23:59",  # نهاية دوام المحل (تدعم العبور لمنتصف الليل)
}
ALERT_SETTINGS_LABELS = {
    "alert_large_op_amount":       "الحد الأدنى لتنبيه عملية كبيرة",
    "alert_returns_limit":         "حد مرتجعات البائع في اليوم",
    "alert_quick_return_minutes":  "دقائق المرتجع السريع",
    "anomaly_price_deviation_pct": "نسبة انخفاض السعر المشكوك فيها %",
    "shop_hours_start":            "بداية دوام المحل (HH:MM)",
    "shop_hours_end":              "نهاية دوام المحل (HH:MM)",
}

def get_alert_setting(key):
    """★ إضافة (المرحلة الثانية — المطلب 3): قراءة حد تنبيه من جدول
    settings القائم — القيمة المخزنة إن وجدت، وإلا الافتراضية عند غياب
    المفتاح (القراءة لا تكتب المفتاح أبداً)"""
    try:
        v = get_setting(key)
        if v is not None and str(v).strip() != "":
            return str(v).strip()
    except Exception:
        pass
    return ALERT_SETTINGS_DEFAULTS.get(key, "")

def get_all_alert_settings():
    """★ إضافة (المرحلة الثانية — المطلب 3): قيم الحدود الست دفعة واحدة —
    قاموس {المفتاح: القيمة النصية} بالافتراضيات عند غياب أي مفتاح"""
    return {k: get_alert_setting(k) for k in ALERT_SETTINGS_DEFAULTS}

def save_alert_settings(new_vals):
    """★ إضافة (المرحلة الثانية — المطلب 4-أ): حفظ حدود التنبيهات الست في
    جدول settings القائم — تُكتب المفاتيح المتغيرة فقط (لا تغيير لا كتابة
    ولا تدقيق)، وتُسجل جلسة تدقيق واحدة بنوع alert_settings_changed
    باستدعاء دالة التسجيل القائمة audit من داخل هذه الدالة الجديدة حصراً.
    يرجع (تم؟, رسالة الخطأ إن وجدت)"""
    old = get_all_alert_settings()
    changed = []
    for k in ALERT_SETTINGS_DEFAULTS:
        v = str(new_vals.get(k, "")).strip()
        if v == "":
            return False, f"«{ALERT_SETTINGS_LABELS[k]}»: القيمة فارغة — أدخل قيمة صحيحة"
        if v != old[k]:
            changed.append((k, old[k], v))
    if not changed:
        return True, ""            # لا تغيير — لا كتابة ولا جلسة تدقيق
    for k, _o, v in changed:
        set_setting(k, v)
    audit("alert_settings_changed",
          "بواسطة: " + CURRENT_USER["name"] + " — "
          + " | ".join(f"{ALERT_SETTINGS_LABELS[k]}: {o} ← {v}" for k, o, v in changed))
    return True, ""

def _parse_hhmm(s):
    """★ إضافة (المرحلة الثانية): قراءة "HH:MM" بنظام 24 ساعة — يرجع
    (الساعة, الدقيقة) أو None عند أي صيغة خاطئة"""
    try:
        parts = str(s or "").strip().split(":")
        if len(parts) != 2:
            return None
        h, m = int(parts[0]), int(parts[1])
        if 0 <= h <= 23 and 0 <= m <= 59:
            return h, m
    except Exception:
        pass
    return None

def outside_shop_hours(dt_or_str):
    """★ إضافة (المرحلة الثانية — المطلبان 3+4): هل هذه اللحظة خارج دوام
    المحل؟ — يقارن وقت اليوم بنظام 24 مع shop_hours_start وshop_hours_end
    مع دعم تجاوز نهاية الدوام لمنتصف الليل: البداية أكبر من النهاية يعني
    دواماً يعبر منتصف الليل فيكون الداخل من ≥ البداية أو ≤ النهاية، وغير
    ذلك خارج الدوام؛ وأي صيغة دوام خاطئة ترجع للافتراضية 09:00 — 23:59"""
    if isinstance(dt_or_str, str):
        dt = parse_dt_str(dt_or_str)
    else:
        dt = dt_or_str
    if dt is None:
        return False
    sh = _parse_hhmm(get_alert_setting("shop_hours_start")) or (9, 0)
    eh = _parse_hhmm(get_alert_setting("shop_hours_end")) or (23, 59)
    t = dt.hour * 60 + dt.minute
    s, e = sh[0] * 60 + sh[1], eh[0] * 60 + eh[1]
    if s <= e:
        return t < s or t > e
    return not (t >= s or t <= e)     # دوام يعبر منتصف الليل

def list_out_of_hours_sessions():
    """★ إضافة (المرحلة الثانية — المطلبان 4-أ و4-ب-7): جلسات الدخول
    المسجلة خارج دوام المحل — من active_sessions القائم مقابل حدود الدوام
    (قراءة فقط) — تُعرض في تنبيهات اللوحة الحية وفي تبويب الأنشطة معاً"""
    out = []
    try:
        _ensure_active_sessions_table()
        with connect() as conn:
            rows = conn.execute("SELECT username, hostname, login_time, last_seen "
                                "FROM active_sessions ORDER BY id").fetchall()
        for s in rows:
            ldt = parse_dt_str(s["login_time"])
            if ldt is not None and outside_shop_hours(ldt):
                out.append(dict(s))
    except Exception:
        pass
    return out

def monitor_op_times():
    """★ إضافة (المرحلة الثانية): أوقات الحركات الحقيقية للقارئ — مطابقة
    سجل التدقيق القائمة (حفظ عملية/حفظ فاتورة) ثم أحداث add_operation
    للمضافة من محطة حركات الأيام ثم وقت التاريخ المسجل نفسه إن حمل وقتاً
    — قراءة فقط لا تُسجل شيئاً ولا تُمس سلسلة التدقيق الموقعة أبداً.
    يرجع {رقم الحركة: "YYYY-MM-DD HH:MM[:SS]"}"""
    out = {}
    try:
        out.update(match_op_times_from_audit())
    except Exception:
        pass
    try:
        out.update(station_added_op_times())
    except Exception:
        pass
    return out

def monitor_save_times():
    """★ إضافة (المرحلة الثانية): لحظات تسجيل الحركات فعلياً — لكل حركة وقت
    كتابتها في البرنامج: مطابقة سجل التدقيق القائمة (حفظ عملية/حفظ فاتورة
    وطابعها الزمني هو لحظة الحفظ نفسها) ثم أحداث add_operation للمضافة من
    محطة حركات الأيام (رقم الحركة داخل التفاصيل وطابع الحدث هو لحظة
    الإضافة الفعلية) — قراءة فقط لا يُسجل شيء. يرجع
    {رقم الحركة: "YYYY-MM-DD HH:MM[:SS]"}"""
    out = {}
    try:
        out.update(match_op_times_from_audit())
    except Exception:
        pass
    try:
        with connect() as conn:
            rows = conn.execute("SELECT ts, details FROM audit_log "
                                "WHERE action='add_operation' ORDER BY id").fetchall()
        for row in rows:
            m = re.search(r"رقم (\d+)", row["details"] or "")
            if m:
                try:
                    out[int(m.group(1))] = row["ts"]
                except ValueError:
                    pass
    except Exception:
        pass
    return out

def monitor_compare_last_week(tmap=None):
    """★ إضافة (المرحلة الثانية — المطلب 4-أ): سطر المقارنة — تراكم اليوم
    التجاري الحالي حتى ساعة الجهاز الحالية مقابل تراكم نفس اليوم التجاري
    من الأسبوع الماضي حتى نفس الساعة (الصافي: مبيعات نقداً وشبكة ناقصاً
    المرتجعات) بأوقات الحركات الحقيقية وحد 05:00 نفسه؛ وحركات الأسبوع
    الماضي بلا أوقات مسجلة تجعل المقارنة غير موثوقة فتُعلن بدل حسابها
    خطأً — وكل حساب «اليوم» من get_business_day() حصراً"""
    try:
        d1 = get_business_day()
        now = datetime.now()
        d2 = date.fromordinal(date.fromisoformat(d1).toordinal() - 7).isoformat()
        if tmap is None:
            tmap = monitor_op_times()
        with connect() as conn:
            ops = conn.execute("SELECT id, date, total FROM operations ORDER BY id").fetchall()
        cur = 0.0
        old, old_rows, old_timed = 0.0, 0, 0
        cutoff2 = datetime.fromtimestamp(now.timestamp() - 7 * 24 * 3600)
        for r in ops:
            ts = parse_dt_str(tmap.get(r["id"]) or "")
            if ts is not None:
                bday = derive_business_day_from_dt(ts)
            else:
                bday = op_business_day_from_date_val(r["date"])
            if bday == d1:
                cur += (r["total"] or 0)      # حركات اليوم كلها قبل الآن حتماً
            elif bday == d2:
                old_rows += 1
                if ts is not None:
                    old_timed += 1
                    if ts <= cutoff2:
                        old += (r["total"] or 0)
        if old_rows == 0:
            return "لا يوجد سجل كافٍ للمقارنة — لا حركات لليوم المقابل الأسبوع الماضي"
        if old_timed < old_rows:
            return "لا يوجد سجل كافٍ للمقارنة — بعض حركات الأسبوع الماضي بلا أوقات مسجلة"
        if old == 0:
            if cur > 0:
                return (f"صافي مبيعاتك الآن {money(cur)} — الأسبوع الماضي كان صفراً "
                        "حتى هذه الساعة نفسها")
            return "لا مبيعات حتى هذه الساعة لا اليوم ولا الأسبوع الماضي — لا نسبة للمقارنة"
        pct = (cur - old) / abs(old) * 100.0
        if pct >= 0:
            return (f"صافي مبيعاتك الآن ({money(cur)}) أعلى من نفس الوقت الأسبوع الماضي "
                    f"({money(old)}) بنسبة {abs(pct):.0f}%")
        return (f"صافي مبيعاتك الآن ({money(cur)}) أقل من نفس الوقت الأسبوع الماضي "
                f"({money(old)}) بنسبة {abs(pct):.0f}%")
    except Exception:
        return "لا يوجد سجل كافٍ للمقارنة"


def collect_monitor_anomalies(period_days=None):
    """★ إضافة (المرحلة الثانية — المطلب 4-ب): جامع الأنشطة غير الطبيعية —
    قارئ للسجلات الموجودة فقط (audit_log بأنواعها الفعلية الواردة في
    الكود، وoperations، وdaily_reports، وactive_sessions، وبيانات
    deleted_operations مرجعاً) ولا يُنشئ أي نوع حدث جديد في audit_log
    إطلاقاً. period_days: None = كل السجل، 0 = اليوم، 7 = آخر 7 أيام
    (الفترة على زمن الحدث نفسه). يرجع قائمة صفوف مرتبة من الأحدث:
    {kind: نوع الحدث, details: التفاصيل, who: من, when: متى, host: الجهاز
    أو «—»}"""
    rows_out = []
    today_d = get_business_day()
    now = datetime.now()
    # حد الفترة على تاريخ زمن الحدث (اليوم = تاريخ اليوم فما فوق)
    lo = None
    if period_days == 0:
        lo = now.strftime("%Y-%m-%d")
    elif period_days:
        lo = date.fromordinal(now.date().toordinal() - (period_days - 1)).isoformat()

    def _in_period(when_s):
        if lo is None or not when_s:
            return True
        return str(when_s)[:10] >= lo

    try:
        with connect() as conn:
            # الفئتان 1+2: أنواع الحذف والاسترجاع كما وردت فعلياً في الكود —
            # «حذف عملية» (شاشة اليوم) و«delete_operation» (المحطة)،
            # و«استعادة عملية» من السلة (لا يوجد نوع استرجاع آخر بالكود
            # فتُعرض الفئة فارغة إن خلا السجل منها)
            # ★ إضافة (المرحلة الرابعة): أنواع تدقيق المرحلة الرابعة
            # مستثناة من قارئ الأنشطة غير الطبيعية حصراً (credit_sale_recorded
            # وdebt_payment_recorded وlarge_op_approved — أحداث عمل عادية)
            # دون تغيير أي شيء آخر في القارئ
            arows = conn.execute(
                "SELECT ts, username, action, details FROM audit_log "
                "WHERE action IN ('حذف عملية','delete_operation','استعادة عملية') "
                "AND action NOT IN (?,?,?) "
                "ORDER BY id", tuple(ANOMALY_EXCLUDED_ACTIONS)).fetchall()
            # الفئة 8: محاولة استخدام صلاحية غير ممنوحة — إن وُجدت سجلات
            # بهذا المعنى في سجل التدقيق (ستبدأ بالظهور عند ربط الميزات في
            # مراحل لاحقة) — لا يُنشئ أي تسجيل جديد لها الآن إطلاقاً
            prows = conn.execute(
                "SELECT ts, username, action, details FROM audit_log "
                "WHERE (action LIKE '%صلاحية غير ممنوحة%' "
                "OR action LIKE '%محاولة صلاحية%') "
                "AND action NOT IN (?,?,?) ORDER BY id",
                tuple(ANOMALY_EXCLUDED_ACTIONS)).fetchall()
            # deleted_operations مرجعاً — لإثراء أحداث الحذف القصيرة
            # («رقم N») ببيانات الحركة المحذوفة كاملة
            dref = {}
            for row in conn.execute(
                    "SELECT op_id, item_name, quantity, price, total, type, "
                    "deleted_by, deleted_at FROM deleted_operations ORDER BY id").fetchall():
                if row["op_id"] is not None:
                    try:
                        dref[int(row["op_id"])] = row   # الأحدث يبقى (ترتيب تصاعدي)
                    except Exception:
                        pass
    except Exception:
        arows, prows, dref = [], [], {}

    for r in arows:
        if not _in_period(r["ts"]):
            continue
        if r["action"] in ("حذف عملية", "delete_operation"):
            det = r["details"] or "—"
            if r["action"] == "حذف عملية":
                oid = None
                try:
                    oid = int(str(det).replace("رقم", "").strip())
                except Exception:
                    oid = None
                ref = dref.get(oid) if oid is not None else None
                if ref is not None:
                    det = (f"رقم {oid} — {ref['item_name']} — {ref['quantity']:g} × "
                           f"{money(ref['price'])} = {money(ref['total'])} ({ref['type']})"
                           f" — من سلة المحذوفات: حُذفت بواسطة {ref['deleted_by'] or '—'} "
                           f"في {ref['deleted_at']}")
            rows_out.append({"kind": "حذف حركة", "details": det,
                             "who": r["username"] or "—", "when": r["ts"], "host": "—"})
        else:
            rows_out.append({"kind": "استرجاع حركة محذوفة", "details": r["details"] or "—",
                             "who": r["username"] or "—", "when": r["ts"], "host": "—"})
    for r in prows:
        if not _in_period(r["ts"]):
            continue
        rows_out.append({"kind": "محاولة صلاحية غير ممنوحة",
                         "details": (str(r["action"]) + (" — " + r["details"] if r["details"] else "")),
                         "who": r["username"] or "—", "when": r["ts"], "host": "—"})

    # الفئة 3: إغلاق يوم تجاري متأخر عن وقته — من daily_reports بأنواع
    # الإغلاق الفعلية الموجودة في التدقيق (إغلاق يوم / auto_close_day /
    # manual_close_day) لمعرفة من أغلق؛ اليوم التجاري ينتهي 05:00 صباح
    # اليوم التالي، فالإغلاق بعد ذلك (بسماحية 5 دقائق لدقة المؤقت
    # الستيني) يعتبر متأخراً عن وقته
    try:
        with connect() as conn:
            drs = conn.execute("SELECT report_date, closed_at FROM daily_reports "
                               "WHERE closed_at IS NOT NULL AND closed_at != '' "
                               "ORDER BY report_date DESC").fetchall()
            closers = conn.execute("SELECT username, action, details FROM audit_log "
                                   "WHERE action IN ('إغلاق يوم','auto_close_day',"
                                   "'manual_close_day') ORDER BY id").fetchall()
        closer_of = {}
        for c in closers:
            dpart = str(c["details"] or "").split(":", 1)[0]
            closer_of[dpart] = c["username"] or "—"
        for r in drs:
            ca = parse_dt_str(r["closed_at"])
            if ca is None or not _in_period(r["closed_at"]):
                continue
            rd = None
            try:
                y, m, dd = map(int, str(r["report_date"]).split("-"))
                rd = date(y, m, dd)
            except Exception:
                rd = None
            if rd is None:
                continue
            end0 = datetime(rd.year, rd.month, rd.day, BUSINESS_DAY_START_HOUR)
            deadline = datetime.fromtimestamp(end0.timestamp() + 24 * 3600 + 5 * 60)
            if ca <= deadline:
                continue            # أُغلق في وقته أو ضمن سماحية المؤقت
            late_min = int((ca - end0).total_seconds() // 60) - 24 * 60
            if late_min >= 60:
                late_txt = f"{late_min // 60} ساعة و{late_min % 60} دقيقة"
            else:
                late_txt = f"{max(late_min, 1)} دقيقة"
            rows_out.append({"kind": "إغلاق يوم تجاري متأخر",
                             "details": (f"يوم {r['report_date']} أُغلق في {r['closed_at']} — "
                                         f"متأخراً عن نهايته (05:00 صباح اليوم التالي) بـ {late_txt}"),
                             "who": closer_of.get(str(r["report_date"]), "—"),
                             "when": r["closed_at"], "host": "—"})
    except Exception:
        pass

    # الفئات 4+5+6: من جدول العمليات بأوقاتها الحقيقية
    try:
        with connect() as conn:
            ops = conn.execute("SELECT id, date, item_name, quantity, price, total, "
                               "type, customer_name, seller_name, original_op_id "
                               "FROM operations ORDER BY id").fetchall()
    except Exception:
        ops = []
    tmap = monitor_op_times()
    quick_min = 30.0
    try:
        v = to_num(get_alert_setting("alert_quick_return_minutes"))
        if v is not None and v >= 1:
            quick_min = v
    except Exception:
        pass
    dev_pct = 20.0
    try:
        v = to_num(get_alert_setting("anomaly_price_deviation_pct"))
        if v is not None and v >= 1:
            dev_pct = v
    except Exception:
        pass
    by_id = {}
    for r in ops:
        by_id[r["id"]] = r
    # الفئة 4: مرتجع سريع — مرتجع مربوط بعملية بيع أصلية عبر original_op_id
    # ووقتا البيع والمرتجع أقرب من الحد المحدد (بصيغة التاريخ الموجودة)
    for r in ops:
        if r["type"] != "مرتجع" or not r["original_op_id"]:
            continue
        ret_ts = parse_dt_str(tmap.get(r["id"]) or "")
        orig = by_id.get(r["original_op_id"])
        if orig is None or ret_ts is None:
            continue
        sale_ts = parse_dt_str(tmap.get(orig["id"]) or "")
        if sale_ts is None:
            continue
        mins = abs((ret_ts - sale_ts).total_seconds()) / 60.0
        if mins >= quick_min:
            continue
        when_s = ret_ts.strftime("%Y-%m-%d %H:%M:%S")
        if not _in_period(when_s):
            continue
        mins_txt = ("أقل من دقيقة" if mins < 1 else f"{mins:.0f} دقيقة")
        rows_out.append({"kind": "مرتجع سريع",
                         "details": (f"مرتجع «{r['item_name']}» بقيمة {money(r['total'])} بعد "
                                     f"{mins_txt} من بيعه — مربوط بالعملية رقم "
                                     f"{r['original_op_id']} (حد المرتجع السريع: {quick_min:g} دقيقة)"),
                         "who": r["seller_name"] or "—", "when": when_s, "host": "—"})
    # الفئة 5: عملية بتاريخ سابق — أي حركة تاريخها المسجل ليس اليوم التجاري
    # الحالي من get_business_day() حصراً، وزمن الحدث = لحظة تسجيلها الفعلية
    # (وقت الحفظ من سجل التدقيق أو لحظة إضافتها من محطة حركات الأيام)،
    # وإلا تاريخها المسجل نفسه — فتظهر التأريخات التي سُجلت اليوم في فلتر
    # «اليوم» ويظهر تاريخها القديم في نص التفاصيل
    savemap = monitor_save_times()
    for r in ops:
        bday = op_business_day_from_date_val(r["date"])
        if bday == today_d:
            continue
        when_s = savemap.get(r["id"]) or str(r["date"])
        if not _in_period(when_s):
            continue
        rows_out.append({"kind": "عملية بتاريخ سابق",
                         "details": (f"حركة رقم {r['id']} بتاريخ {bday} — {r['item_name']}: "
                                     f"{r['quantity']:g} × {r['price']:g} = {r['total']:g} "
                                     f"({r['type']}) — اليوم التجاري الحالي {today_d}"),
                         "who": r["seller_name"] or "—", "when": when_s, "host": "—"})
    # الفئة 6: سعر بيع منخفض بشكل ملحوظ — بيع اليوم سعره أقل من متوسط أسعار
    # نفس الصنف في عمليات البيع السابقة عليه بنسبة تتجاوز الحد، وبشرط
    # وجود 3 عمليات بيع سابقة على الأقل لنفس الصنف
    prior_prices = {}
    for r in ops:
        if r["type"] not in ("نقداً", "شبكة"):
            continue
        lst = prior_prices.setdefault(r["item_name"], [])
        if r["date"] == today_d and len(lst) >= 3:
            avg = sum(lst) / len(lst)
            if avg > 0:
                drop = (avg - (r["price"] or 0)) / avg * 100.0
                if drop > dev_pct:
                    when_s = tmap.get(r["id"]) or str(r["date"])
                    if _in_period(when_s):
                        rows_out.append({"kind": "سعر بيع منخفض",
                                         "details": (f"«{r['item_name']}» بيع اليوم بسعر "
                                                     f"{money(r['price'])} — أقل من متوسطه المعتاد "
                                                     f"{money(avg)} بنسبة {drop:.0f}% "
                                                     f"(من {len(lst)} عملية بيع سابقة)"),
                                         "who": r["seller_name"] or "—",
                                         "when": when_s, "host": "—"})
        lst.append(r["price"])

    # الفئة 7: جلسة دخول خارج دوام المحل — من active_sessions مقابل
    # shop_hours_start وshop_hours_end (الوحيدة التي يظهر فيها الجهاز)
    for s in list_out_of_hours_sessions():
        if not _in_period(s["login_time"]):
            continue
        rows_out.append({"kind": "دخول خارج دوام المحل",
                         "details": (f"دخول في {s['login_time']} خارج دوام المحل "
                                     f"({get_alert_setting('shop_hours_start')} — "
                                     f"{get_alert_setting('shop_hours_end')})"),
                         "who": s["username"] or "—", "when": s["login_time"],
                         "host": s["hostname"] or "—"})

    # الترتيب من الأحدث (ما لا يُقرأ وقته يبقى آخر القائمة)
    def _sk(row):
        w = str(row.get("when") or "")
        d = parse_dt_str(w)
        if d is None:
            d = parse_dt_str(w + " 00:00:00")
        try:
            return d.timestamp() if d is not None else 0.0
        except Exception:
            return 0.0
    rows_out.sort(key=_sk, reverse=True)
    return rows_out

def active_users_list():
    """★ إضافة (إصدار 8 — الميزة 2): المستخدمون المفعّلون لقائمة تسجيل الدخول
    المنسدلة — المدير أولاً ثم الباقي أبجدياً
    ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الأدمن أولاً ثم المدير ثم الباقي
    أبجدياً (ترتيب العرض فقط — حساب الأدمن يظهر في القائمة كأي حساب)"""
    with connect() as conn:
        rows = conn.execute("SELECT username FROM users WHERE active=1 "
                            "ORDER BY (role='أدمن') DESC, (role='مدير') DESC, username").fetchall()
    return [r[0] for r in rows]

# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (المرحلة الرابعة): العملاء والديون والضمانات ★★★
# طبقة مستقلة فوق كل ما هو قائم: جداول جديدة فقط بـ CREATE TABLE IF NOT
# EXISTS وأعمدة جديدة فقط بـ ALTER TABLE ADD COLUMN داخل try/except يتحمل
# وجود العمود مسبقاً (لا حذف ولا تعديل ولا إعادة تسمية لأي شيء قائم)،
# وعداد فواتير عالمي واحد لا يتكرر أبداً، وسقف الخصم لكل مستخدم من
# القيمة الرقمية المحفوظة بالمرحلة الأولى، وحد العمليات الكبيرة من إعدادات
# التنبيه القائمة نفسها (alert_large_op_amount) بلا أي تعديل في نافذتها،
# وقائمة أسباب المرتجع الثابتة، وقائمة استثناءات أنواع التدقيق الجديدة من
# قارئ الأنشطة غير الطبيعية في مركز المتابعة
# ═══════════════════════════════════════════════════════════

RETURN_REASONS = ("عيب مصنعي", "خطأ في الطلب", "غير متوافق مع الحاجة",
                  "تلف أثناء النقل", "العميل غيّر رأيه", "سبب آخر")

# مفاتيح النافذة الجديدة الخمسة — الزر يظهر لمن ملك واحداً منها على الأقل
STAGE4_WINDOW_KEYS = ("sell_on_credit", "collections_list", "warranty_reminder",
                      "inactive_customers", "return_reasons_report")

# أنواع تدقيق المرحلة الرابعة مستثناة حصراً من قارئ الأنشطة غير الطبيعية
# في مركز المتابعة (أحداث عمل عادية بحكم وظيفتها لا تنبيهات منها)
ANOMALY_EXCLUDED_ACTIONS = ("credit_sale_recorded", "debt_payment_recorded",
                            "large_op_approved")

_STAGE4_READY = {"done": False}   # إنشاء الجداول مرة واحدة عند أول استخدام

def _ensure_stage4_tables():
    """★ إضافة (المرحلة الرابعة): إنشاء جداول المرحلة الرابعة الخمسة
    (customers / debts / debt_payments / warranties / counters) بـ CREATE
    TABLE IF NOT EXISTS وأعمدة المرحلة الرابعة الستة على operations بـ
    ALTER TABLE ADD COLUMN داخل try/except يتحمل وجود العمود مسبقاً —
    الجداول الجديدة فقط ولا يُمس أي جدول أو عمود قائم إطلاقاً، وبعد أول
    نجاح تعود الدالة فوراً بلا أي استعلام إضافي، وزرع عداد الفواتير مرة
    واحدة من أكبر رقم فاتورة موجود في القاعدة (لا شيء = 0)"""
    if _STAGE4_READY["done"]:
        return
    with connect() as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS customers(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            phone TEXT,
            notes TEXT,
            created_at TEXT NOT NULL)""")
        conn.execute("""CREATE TABLE IF NOT EXISTS debts(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            customer_id INTEGER NOT NULL,
            invoice_number TEXT,
            sale_id INTEGER,
            total_amount REAL NOT NULL DEFAULT 0,
            paid_amount REAL NOT NULL DEFAULT 0,
            status TEXT NOT NULL DEFAULT 'مفتوح',
            created_at TEXT NOT NULL)""")
        conn.execute("""CREATE TABLE IF NOT EXISTS debt_payments(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            debt_id INTEGER NOT NULL,
            amount REAL NOT NULL,
            collected_by TEXT,
            note TEXT,
            created_at TEXT NOT NULL)""")
        conn.execute("""CREATE TABLE IF NOT EXISTS warranties(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            customer_id INTEGER NOT NULL,
            invoice_number TEXT,
            product_name TEXT NOT NULL,
            purchase_date TEXT NOT NULL,
            warranty_months INTEGER NOT NULL,
            end_date TEXT NOT NULL,
            created_at TEXT NOT NULL)""")
        conn.execute("""CREATE TABLE IF NOT EXISTS counters(
            key TEXT PRIMARY KEY,
            value INTEGER NOT NULL DEFAULT 0)""")
        # أعمدة جديدة على operations — كل عمود بفحصه ويتحمل وجوده مسبقاً
        try:
            _ocols4 = [rr[1] for rr in conn.execute("PRAGMA table_info(operations)")]
            if "return_reason" not in _ocols4:
                conn.execute("ALTER TABLE operations ADD COLUMN return_reason TEXT")
            if "return_note" not in _ocols4:
                conn.execute("ALTER TABLE operations ADD COLUMN return_note TEXT")
            if "payment_kind" not in _ocols4:
                conn.execute("ALTER TABLE operations ADD COLUMN payment_kind TEXT")
            if "customer_id" not in _ocols4:
                conn.execute("ALTER TABLE operations ADD COLUMN customer_id INTEGER")
            if "invoice_number" not in _ocols4:
                conn.execute("ALTER TABLE operations ADD COLUMN invoice_number TEXT")
            if "discount_percent" not in _ocols4:
                conn.execute("ALTER TABLE operations ADD COLUMN discount_percent REAL")
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        # زرع عداد الفواتير مرة واحدة من أكبر رقم فاتورة موجود (لا شيء = 0)
        try:
            if conn.execute("SELECT 1 FROM counters WHERE key='invoice_seq'"
                            ).fetchone() is None:
                _mx4 = 0
                try:
                    _rr4 = conn.execute(
                        "SELECT MAX(CAST(invoice_number AS INTEGER)) FROM operations "
                        "WHERE invoice_number IS NOT NULL").fetchone()
                    _mx4 = int(_rr4[0] or 0)
                except Exception:
                    _mx4 = 0
                conn.execute("INSERT INTO counters(key,value) VALUES('invoice_seq',?)",
                             (max(_mx4, 0),))
        except Exception as e:
            log_error(e, sys.exc_info()[2])
    _STAGE4_READY["done"] = True

def get_next_invoice_number():
    """★ إضافة (المرحلة الرابعة): الرقم التالي من عداد الفواتير العالمي
    الواحد — القراءة والزيادة داخل معاملة واحدة (BEGIN IMMEDIATE) فلا
    يتكرر الرقم أبداً حتى بعد إغلاق اليوم وإعادة التشغيل، ويرجع نص الرقم
    أو None عند أي فشل (الحفظ يستمر بلا رقم خير من تعطل البيع)"""
    _ensure_stage4_tables()
    con = sqlite3.connect(DB, timeout=15)
    try:
        con.execute("PRAGMA busy_timeout=15000")
        con.execute("BEGIN IMMEDIATE")
        rr = con.execute("SELECT value FROM counters WHERE key='invoice_seq'"
                         ).fetchone()
        cur_v = 0
        try:
            cur_v = int(rr[0])
        except Exception:
            cur_v = 0
        nxt = cur_v + 1
        con.execute("INSERT INTO counters(key,value) VALUES('invoice_seq',?) "
                    "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (nxt,))
        con.execute("COMMIT")
        return str(nxt)
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        try:
            con.execute("ROLLBACK")
        except Exception:
            pass
        return None
    finally:
        try:
            con.close()
        except Exception:
            pass

def user_discount_cap(username):
    """★ إضافة (المرحلة الرابعة): سقف الخصم للمستخدم — الأدمن بلا سقف
    (None)، وغيره القيمة الرقمية «أقصى نسبة خصم %» المحفوظة له من المرحلة
    الأولى بنفس طريقة قراءة الصلاحيات (0 = ممنوع من الخصم كلياً)"""
    try:
        rr = get_user_row(username)
        if rr is not None and rr["role"] == ADMIN_ROLE:
            return None
        return float(read_user_permissions_safe(username)["max_discount"])
    except Exception:
        return 0.0

def stage4_large_op_threshold():
    """★ إضافة (المرحلة الرابعة): حد العملية الكبيرة من إعدادات التنبيه
    القائمة نفسها (alert_large_op_amount — الافتراضي 5000) قراءة فقط بلا
    أي تعديل في نافذة حدود التنبيه أو قيمها"""
    try:
        v = to_num(get_alert_setting("alert_large_op_amount"))
        if v is not None and v >= 0:
            return float(v)
    except Exception:
        pass
    return 5000.0

def row_val4(row, key):
    """★ إضافة (المرحلة الرابعة): قراءة عمود من صف عملية قد يغيب عن
    استعلام قديم — قيمة آمنة أو فراغ، بلا أي خطأ أبداً"""
    try:
        v = row[key]
        return "" if v is None else v
    except Exception:
        return ""

def customers_all():
    """★ إضافة (المرحلة الرابعة): كل العملاء (الأحدث أولاً)"""
    _ensure_stage4_tables()
    with connect() as conn:
        return conn.execute("SELECT id, name, phone, notes, created_at "
                            "FROM customers ORDER BY id DESC").fetchall()

def customer_debt_total(customer_id):
    """★ إضافة (المرحلة الرابعة): إجمالي الدين المتبقي لعميل — الديون
    المفتوحة والجزئية فقط (المسددة لا تُحسب ديناً قائماً)"""
    try:
        _ensure_stage4_tables()
        with connect() as conn:
            rr = conn.execute("SELECT COALESCE(SUM(total_amount - paid_amount), 0) "
                              "FROM debts WHERE customer_id=? AND status != 'مسدد'",
                              (customer_id,)).fetchone()
        return float(rr[0] or 0)
    except Exception:
        return 0.0

def customer_last_purchase(customer_id, name):
    """★ إضافة (المرحلة الرابعة): تاريخ آخر شراء لعميل — أحدث عملية بيع
    مرتبطة به بمعرفه (بيع بالدين) أو تحمل اسمه (المطابقة بالاثنين معاً)"""
    try:
        with connect() as conn:
            rr = conn.execute(
                "SELECT MAX(date) FROM operations "
                "WHERE type IN ('نقداً','شبكة') "
                "AND (customer_id=? OR (customer_name IS NOT NULL AND customer_name=?))",
                (customer_id, name)).fetchone()
        return (rr[0] if rr and rr[0] else None)
    except Exception:
        return None


# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (حزمة الصندوق والرقابة المالية — المرحلة الأولى): طبقة البيانات ★★★
# خمس ميزات محكومات بثلاثة مفاتيح صلاحيات جديدة في PERMISSIONS_CATALOG
# حصراً (cash_report_view / expenses_manage / debt_aging_view — كلها مطفأة
# افتراضيًا لكل المستخدمين والأدمن يملكها بدوره دائماً عبر
# user_has_permission القائم): كشف الصندوق اليومي، المصروفات الموثقة،
# متابعة الديون (أعمار + من أطالب به اليوم)، والديون المتعثرة في مركز
# المتابعة — كلها قراءة صامتة من الجداول القائمة وحدها بأسمائها
# وأعمدتها الفعلية، ويوم تجاري واحد مرجع وحيد: get_business_day()
# بالقاعدة القائمة 05:00 حرفيًا، ولا يُنشأ هنا أي جدول غير جدول
# expenses الجديد (CREATE TABLE IF NOT EXISTS) وعمود واحد جديد
# promised_date على جدول الديون القائم (ALTER TABLE ADD COLUMN داخل
# try/except يتحمل وجوده مسبقًا) — لا حذف ولا تعديل لأي جدول أو عمود قائم
# ═══════════════════════════════════════════════════════════

# تصنيفات المصروفات الجاهزة — القائمة الوحيدة المسموحة في نافذة التسجيل
EXPENSE_CATEGORIES = ("توصيل", "مستلزمات محل", "صيانة وإصلاح", "ضيافة", "أخرى")

_CASH_READY = {"done": False}   # تجهيز قاعدة الحزمة مرة واحدة عند أول استخدام

def _ensure_cash_tables():
    """★ إضافة (حزمة الصندوق والرقابة المالية): تجهيز قاعدة البيانات
    لميزات الحزمة — جدول expenses الجديد وحده بـ CREATE TABLE IF NOT
    EXISTS وعمود واحد جديد promised_date على جدول الديون القائم بـ ALTER
    TABLE ADD COLUMN داخل try/except يتحمل وجوده مسبقًا؛ يستدعي
    _ensure_stage4_tables القائمة أولاً فيضمن وجود جدول الديون قبل العمود
    الجديد (بلا أي كلفة إضافية بعد أول نجاح لها)، ولا يُمس أي جدول أو
    عمود قائم إطلاقًا، وبعد نجاح العمود تعود الدالة فوراً — وإن تعذر
    العمود (جدول الديون غائب بعد) تعود المحاولة عند الاستدعاء التالي
    دون أي أثر جانبي أبدًا"""
    if _CASH_READY["done"]:
        return
    try:
        _ensure_stage4_tables()
    except Exception as e:
        log_error(e, sys.exc_info()[2])
    _ok_debts6 = False
    with connect() as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS expenses(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            amount REAL NOT NULL,
            category TEXT,
            note TEXT,
            username TEXT,
            created_at TEXT NOT NULL)""")
        try:
            _cols6 = [rr[1] for rr in conn.execute("PRAGMA table_info(debts)")]
            if "promised_date" not in _cols6:
                conn.execute("ALTER TABLE debts ADD COLUMN promised_date TEXT")
            _ok_debts6 = True
        except Exception as e:
            log_error(e, sys.exc_info()[2])
    _CASH_READY["done"] = _ok_debts6

def cash_report_data(d):
    """★ إضافة (حزمة الصندوق والرقابة المالية — الميزة 1): كل أرقام كشف
    الصندوق لليوم التجاري d — قراءة صامتة من الجداول القائمة وحدها:
    operations (type القائم 'نقداً'/'شبكة'/'مرتجع' بقيمه المخزنة والمرتجع
    سالب كما في day_totals القائمة حرفيًا، وpayment_kind='دين' هو ما يميز
    صفوف البيع بالدين عن النقدي المدفوع)، وdebts/debt_payments القائمة
    (التحصيلات اللاحقة وحدها فيها — الدفعة الأولى لا تُسجل فيها أصلًا لأن
    الدين يُنشأ بالباقي مباشرة فتُحسب من فرق صفوف الدين عن الديون
    المرتبطة بها)، وexpenses الجديد؛ واليوم التجاري لكل دفعة ومصروف من
    وقته الكامل بقاعدة 05:00 نفسها (derive_business_day_from_dt القائمة)
    — يرجع قاموس الأرقام الكامل أو None عند أي فشل"""
    try:
        _ensure_cash_tables()
        d = str(d)
        try:
            _dnext6 = next_day(d)
        except Exception:
            _dnext6 = d
        with connect() as conn:
            rows = conn.execute("SELECT type, total, payment_kind FROM operations "
                                "WHERE date=?", (d,)).fetchall()
        paid_cash = sum((r["total"] or 0) for r in rows
                        if r["type"] == "نقداً" and (r["payment_kind"] or "") != "دين")
        paid_network = sum((r["total"] or 0) for r in rows
                           if r["type"] == "شبكة" and (r["payment_kind"] or "") != "دين")
        credit_sales = sum((r["total"] or 0) for r in rows
                           if (r["payment_kind"] or "") == "دين"
                           and r["type"] in ("نقداً", "شبكة"))
        returns_total = -sum((r["total"] or 0) for r in rows if r["type"] == "مرتجع")
        # الدفعات الأولى المسجلة = مجموع صفوف الوسم «دين» في يومها (بكل
        # أنواعها — فاتورة الدين قد تحمل مرتجعات داخلها) ناقص مجموع أصول
        # الديون المرتبطة بها (debts.sale_id القائم) — فمن دفع كامل المبلغ
        # دفعة أولى لا يُنشأ له دين أصلًا فيظهر كامل مبلغه دفعة أولى صحيحة
        first_payments = 0.0
        try:
            with connect() as conn:
                _trows6 = conn.execute(
                    "SELECT COALESCE(SUM(total),0) FROM operations "
                    "WHERE date=? AND payment_kind='دين'", (d,)).fetchone()
                _tdebts6 = conn.execute(
                    "SELECT COALESCE(SUM(b.total_amount),0) FROM debts b "
                    "WHERE b.sale_id IN (SELECT id FROM operations "
                    "WHERE date=? AND payment_kind='دين')", (d,)).fetchone()
            first_payments = max(0.0, float(_trows6[0] or 0) - float(_tdebts6[0] or 0))
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            first_payments = 0.0
        # التحصيلات المسجلة = دفعات debt_payments في يومها التجاري بقاعدة 05:00
        collections = 0.0
        try:
            with connect() as conn:
                _prows6 = conn.execute(
                    "SELECT amount, created_at FROM debt_payments "
                    "WHERE substr(created_at,1,10) BETWEEN ? AND ?",
                    (d, _dnext6)).fetchall()
            for r in _prows6:
                _dt6 = parse_dt_str(r["created_at"])
                if _dt6 is not None and derive_business_day_from_dt(_dt6) == d:
                    collections += (r["amount"] or 0)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        # المصروفات بنفس القاعدة نفسها
        expenses_total = 0.0
        try:
            with connect() as conn:
                _erows6 = conn.execute(
                    "SELECT amount, created_at FROM expenses "
                    "WHERE substr(created_at,1,10) BETWEEN ? AND ?",
                    (d, _dnext6)).fetchall()
            for r in _erows6:
                _dt6 = parse_dt_str(r["created_at"])
                if _dt6 is not None and derive_business_day_from_dt(_dt6) == d:
                    expenses_total += (r["amount"] or 0)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        cash_in = paid_cash + first_payments + collections
        cash_out = returns_total + expenses_total
        return {
            "paid_cash": paid_cash, "paid_network": paid_network,
            "credit_sales": credit_sales,
            "total_sales": paid_cash + paid_network + credit_sales,
            "first_payments": first_payments, "collections": collections,
            "returns": returns_total, "expenses": expenses_total,
            "cash_in": cash_in, "cash_out": cash_out,
            "expected_drawer": cash_in - cash_out,
        }
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return None

def expenses_period_rows(period_label):
    """★ إضافة (حزمة الصندوق والرقابة المالية — الميزة 2): مصروفات فترة
    جاهزة (اليوم / آخر 7 أيام / آخر 30 يومًا) — الأيام التجارية من
    last_business_days القائمة حصراً، وكل مصروف يُنسب ليومه التجاري بقاعدة
    05:00 نفسها؛ يرجع (الصفوف الأحدث أولاً، الإجمالي، وصف الفترة) وقيمًا
    فارغة آمنة عند أي فشل"""
    try:
        _ensure_cash_tables()
        n = (7 if period_label == "آخر 7 أيام"
             else (30 if period_label == "آخر 30 يومًا" else 1))
        days = last_business_days(n)
        _dset6 = set(days)
        _lo6, _hi6 = min(days), max(days)
        try:
            _hinext6 = next_day(_hi6)
        except Exception:
            _hinext6 = _hi6
        with connect() as conn:
            rows = conn.execute(
                "SELECT id, amount, category, note, username, created_at "
                "FROM expenses WHERE substr(created_at,1,10) BETWEEN ? AND ? "
                "ORDER BY id DESC", (_lo6, _hinext6)).fetchall()
        out, total = [], 0.0
        for r in rows:
            _dt6 = parse_dt_str(r["created_at"])
            if _dt6 is None or derive_business_day_from_dt(_dt6) not in _dset6:
                continue
            out.append(dict(r))
            total += (r["amount"] or 0)
        _desc6 = ("اليوم التجاري" if n == 1 else f"آخر {n} أيام تجارية")
        return out, total, _desc6
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return [], 0.0, "—"

# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (ميزة «المصروفات» الجديدة — تسجيل وتقرير): طبقة البيانات ★★★
# مفتاحان جديدان في PERMISSIONS_CATALOG حصراً (expense_record لزر «تسجيل
# مصروف» في الشاشة الرئيسية وexpense_report لتبويب «المصروفات» داخل
# «التقارير الإدارية» — كلاهما مطفأ افتراضيًا لكل المستخدمين والأدمن
# يملكهما بدوره دائمًا عبر user_has_permission القائم)، وجدول expenses
# القائم نفسه بلا أي تعديل عليه إطلاقًا (id, amount, category, note,
# username, created_at — يُنشأ من _ensure_cash_tables القائمة عند الإقلاع
# وعند أول استخدام)، واليوم التجاري بقاعدة 05:00 نفسها من
# derive_business_day_from_dt القائمة حصراً — وكل دالة هنا تبدأ بفحص
# الصلاحية (الطبقة الثانية) وتتحمل أي فشل بتسجيله في error_log.txt مع
# اسم الدالة والوقت ورسالة عربية دون انهيار أبدًا
# ═══════════════════════════════════════════════════════════

# أنواع المصروفات الجاهزة — القائمة المنسدلة الوحيدة في نافذة «تسجيل
# مصروف» الجديدة (نافذة «المصروفات الموثقة» القائمة تحتفظ بتصنيفاتها
# القائمة كما هي حرفيًا — لا مساس بسلوكها)
EXPENSE_TYPE_CHOICES = ("نقل", "ضيافة", "كهرباء", "أجرة توصيل", "صيانة", "أخرى")

def expenses_report_data(username, d_from, d_to, note_text=""):
    """★ إضافة (ميزة «المصروفات» — التقرير): مصروفات الفترة التجارية
    [d_from, d_to] مع بحث نصي اختياري في الملاحظة (ويشمل النوع — فالبحث
    بكلمة «نقل» يجمع مصروفات النقل حتى لو خلت ملاحظتها من الكلمة) —
    الطبقة الثانية أول سطر: لا بيانات بلا expense_report، وكل مصروف
    يُنسب ليومه التجاري بقاعدة 05:00 نفسها؛ يرجع قاموس {rows, total,
    count, highest} أو None عند فقدان الصلاحية أو أي فشل"""
    if not user_has_permission(username, "expense_report"):
        return None
    try:
        _ensure_cash_tables()
        d_from = str(d_from)[:10]
        d_to = str(d_to)[:10]
        if d_from > d_to:
            d_from, d_to = d_to, d_from      # تحمّل قلب الفترة بلا انهيار
        try:
            _dnext8 = next_day(d_to)
        except Exception:
            _dnext8 = d_to
        with connect() as conn:
            rows = conn.execute(
                "SELECT id, amount, category, note, username, created_at "
                "FROM expenses WHERE substr(created_at,1,10) BETWEEN ? AND ? "
                "ORDER BY id DESC", (d_from, _dnext8)).fetchall()
        _needle8 = str(note_text or "").strip().lower()
        out = []
        for r in rows:
            _dt8 = parse_dt_str(r["created_at"])
            if _dt8 is None:
                continue
            _bd8 = derive_business_day_from_dt(_dt8)
            if _bd8 < d_from or _bd8 > d_to:
                continue
            if _needle8:
                _hay8 = (str(r["note"] or "") + " "
                         + str(r["category"] or "")).lower()
                if _needle8 not in _hay8:
                    continue
            out.append(dict(r))
        _total8 = sum((r["amount"] or 0) for r in out)
        _high8 = max(((r["amount"] or 0) for r in out), default=0.0)
        return {"rows": out, "total": _total8,
                "count": len(out), "highest": _high8}
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return None

def expense_delete_row(username, exp_id):
    """★ إضافة (ميزة «المصروفات» — الحذف): حذف مصروف واحد نهائيًا — أدمن
    حصريًا بلا مفتاح جديد (الأدمن يملك expense_report بدوره دائمًا)،
    والطبقة الثانية مزدوجة: فحص الصلاحية ثم فحص أن المنفّذ أدمن فعلاً من
    جدول users نفسه، والحذف يُسجَّل سطر تدقيق في error_log.txt باسم الدالة
    والوقت والمبلغ والملاحظة ومن سجّله ومن حذفه؛ يرجع (True, رسالة نجاح)
    أو (False, رسالة عربية واضحة) — دون انهيار أبدًا"""
    if not user_has_permission(username, "expense_report"):
        return False, "لا تملك صلاحية «عرض تقرير المصروفات» — لم يُحذف شيء"
    _row8 = get_user_row(username)
    if _row8 is None or _row8["role"] != ADMIN_ROLE:
        return False, "حذف المصروفات متاح للأدمن فقط — لم يُحذف شيء"
    try:
        _id8 = int(exp_id)
        with connect() as conn:
            r = conn.execute(
                "SELECT id, amount, category, note, username, created_at "
                "FROM expenses WHERE id=?", (_id8,)).fetchone()
            if r is None:
                return False, "هذا المصروف غير موجود — ربما حُذف من قبل"
            conn.execute("DELETE FROM expenses WHERE id=?", (_id8,))
        try:
            with open(ERRLOG, "a", encoding="utf-8") as f:
                f.write("\n[" + datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                        + "] expense_delete_row: حذف مصروف — الرقم: "
                        + str(r["id"])
                        + " | المبلغ: " + money(r["amount"] or 0)
                        + " | النوع: " + str(r["category"] or "—")
                        + " | الملاحظة: " + str(r["note"] or "—")
                        + " | سجّله: " + str(r["username"] or "—")
                        + " | حذفه: " + str(username) + "\n")
        except Exception:
            pass
        return True, ("حُذف المصروف نهائيًا — اختفى من التقرير ومن كشف "
                      "الصندوق فورًا")
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return False, "تعذر حذف المصروف — سُجّل السبب في error_log.txt"

# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (ميزة «عروض الأسعار»): طبقة البيانات ★★★
# مفتاح واحد جديد في PERMISSIONS_CATALOG حصراً (quotations_manage — إنشاء
# وعرض وتعديل وتحويل وإلغاء العروض، مطفأ افتراضيًا لكل المستخدمين والأدمن
# يملكه بدوره دائمًا عبر user_has_permission القائم)، وجدول quotations
# جديد وحده (CREATE TABLE IF NOT EXISTS) وعداد مستقل وحيد quote_seq في
# جدول counters القائم (يُزرع مرة واحدة من أكبر رقم عرض موجود — بلا أي
# مساس بعداد الفواتير invoice_seq إطلاقًا)، والأصناف تُخزن JSON داخل
# items_json بنفس فلسفة تخزين بيانات JSON القائمة في البرنامج، وكل دالة
# تبدأ بفحص الصلاحية (الطبقة الثانية) وترجع بهدوء عند أي فشل مع تسجيل في
# error_log.txt — ونطاق الرؤية (غير الأدمن عروضه هو وحده) مطبَّق داخل
# الاستعلامات نفسها، والفترات باليوم التجاري 05:00 نفسها
# (derive_business_day_from_dt القائمة حصراً)
# ═══════════════════════════════════════════════════════════

# حالات العرض الثلاث كما نصت المواصفة — مفاتيح إنجليزية مخزنة وعناوين
# عربية معروضة (نفس فلسفة مفاتيح الحالات القائمة في الديون)
QUOTATION_STATUSES = {"open": "قيد الانتظار", "converted": "محول لفاتورة",
                      "cancelled": "ملغي"}

_QUOT_READY = {"done": False}   # تجهيز قاعدة العروض مرة واحدة عند أول استخدام

def _ensure_quotations_table():
    """★ إضافة (عروض الأسعار): تجهيز قاعدة العروض — جدول quotations الجديد
    وحده بـ CREATE TABLE IF NOT EXISTS وعداد quote_seq المستقل وحده في
    جدول counters القائم يُزرع مرة واحدة من أكبر رقم عرض موجود (لا شيء =
    0) بنفس أسلوب زرع عداد الفواتير القائم حرفيًا؛ يستدعي
    _ensure_stage4_tables أولاً فيضمن وجود جدول العدادات، ولا يُمس أي جدول
    أو عداد قائم إطلاقًا، وفشل التجهيز لا يوقف البرنامج: يُسجل في
    error_log.txt وتُكمل المحاولة عند الاستدعاء التالي دون أي أثر جانبي"""
    if _QUOT_READY["done"]:
        return
    try:
        _ensure_stage4_tables()
    except Exception as e:
        log_error(e, sys.exc_info()[2])
    with connect() as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS quotations(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            quote_no TEXT,
            customer_id INTEGER,
            customer_text TEXT,
            items_json TEXT,
            total REAL NOT NULL DEFAULT 0,
            username TEXT,
            status TEXT NOT NULL DEFAULT 'open',
            created_at TEXT NOT NULL,
            converted_invoice_no TEXT)""")
        try:
            if conn.execute("SELECT 1 FROM counters WHERE key='quote_seq'"
                            ).fetchone() is None:
                _mx9 = 0
                try:
                    _rr9 = conn.execute(
                        "SELECT MAX(CAST(quote_no AS INTEGER)) FROM quotations "
                        "WHERE quote_no IS NOT NULL").fetchone()
                    _mx9 = int(_rr9[0] or 0)
                except Exception:
                    _mx9 = 0
                conn.execute("INSERT INTO counters(key,value) "
                             "VALUES('quote_seq',?)", (max(_mx9, 0),))
            _QUOT_READY["done"] = True
        except Exception as e:
            log_error(e, sys.exc_info()[2])

def get_next_quote_number():
    """★ إضافة (عروض الأسعار): الرقم التالي من عداد العروض المستقل الوحيد
    — نسخة حرفية من أسلوب get_next_invoice_number القائم (معاملة واحدة
    BEGIN IMMEDIATE فلا يتكرر الرقم أبدًا) لكن على المفتاح المستقل
    quote_seq حصراً، فترقيم العروض مستقل تمامًا عن ترقيم الفواتير ولا
    يمسه إطلاقًا؛ يرجع نص الرقم أو None عند أي فشل (لا يوقف الحفظ شيئًا)"""
    _ensure_quotations_table()
    con = sqlite3.connect(DB, timeout=15)
    try:
        con.execute("PRAGMA busy_timeout=15000")
        con.execute("BEGIN IMMEDIATE")
        rr = con.execute("SELECT value FROM counters WHERE key='quote_seq'"
                         ).fetchone()
        cur_v = 0
        try:
            cur_v = int(rr[0])
        except Exception:
            cur_v = 0
        nxt = cur_v + 1
        con.execute("INSERT INTO counters(key,value) VALUES('quote_seq',?) "
                    "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                    (nxt,))
        con.execute("COMMIT")
        return str(nxt)
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        try:
            con.execute("ROLLBACK")
        except Exception:
            pass
        return None
    finally:
        try:
            con.close()
        except Exception:
            pass

def _quote_items_from_json(items_json):
    """★ إضافة (عروض الأسعار): قراءة أصناف عرض من items_json بأمان —
    قائمة قواميس {item, qty, price} أو قائمة فارغة عند أي خلل (لا يكسر
    عرضًا قديمًا أبدًا)"""
    try:
        data = json.loads(items_json or "[]")
        if not isinstance(data, list):
            return []
        out = []
        for it in data:
            if not isinstance(it, dict):
                continue
            out.append({"item": str(it.get("item") or ""),
                        "qty": float(it.get("qty") or 0),
                        "price": float(it.get("price") or 0)})
        return out
    except Exception:
        return []

def quotations_list_rows(username, period_label="كل العروض",
                         status_filter="الكل", seller_filter="كل البائعين"):
    """★ إضافة (عروض الأسعار): قائمة العروض بالفلاتر — الطبقة الثانية أول
    سطر: لا قراءة بلا quotations_manage؛ نطاق الرؤية داخل الاستعلام نفسه:
    غير الأدمن يرى عروضه هو وحده (شرط username=? حتمي في الاستعلام) والأدمن
    يرى الكل ويستطيع التصفية بالبائع؛ الفترة باليوم التجاري 05:00 نفسها
    (كل عرض يُنسب ليومه التجاري من وقته الكامل)، والحالة بعرضها العربي أو
    «الكل»، ويُرجع قائمة صفوف كاملة (مع العمر بالأيام التجارية وعدد
    الأصناف) أو None عند فقدان الصلاحية أو أي فشل"""
    if not user_has_permission(username, "quotations_manage"):
        return None
    try:
        _ensure_quotations_table()
        _urow9 = get_user_row(username)
        _is_adm9 = (_urow9 is not None and _urow9["role"] == ADMIN_ROLE)
        _bd9 = get_business_day()
        # نطاق الفترة أيامًا تجارية (طقم أيام أو حدود من-إلى أو الكل)
        _days9 = None
        _lo9 = _hi9 = None
        if period_label == "اليوم التجاري":
            _days9 = {_bd9}
        elif period_label == "أمس (تجاري)":
            _ds9 = last_business_days(2)
            _days9 = {_ds9[1] if len(_ds9) > 1 else _ds9[0]}
        elif period_label == "آخر 7 أيام":
            _days9 = set(last_business_days(7))
        elif period_label == "هذا الشهر":
            _lo9 = _bd9[:8] + "01"
            _hi9 = _bd9
        # «كل العروض» = بلا حدود
        _st_key9 = None
        for k9, v9 in QUOTATION_STATUSES.items():
            if v9 == status_filter:
                _st_key9 = k9
                break
        _cond9 = []
        _prm9 = []
        if not _is_adm9:
            _cond9.append("username = ?")           # نطاق الرؤية داخل الاستعلام
            _prm9.append(username)
        elif seller_filter and seller_filter != "كل البائعين":
            _cond9.append("username = ?")
            _prm9.append(seller_filter)
        if _st_key9 is not None:
            _cond9.append("status = ?")
            _prm9.append(_st_key9)
        _sql9 = ("SELECT id, quote_no, customer_id, customer_text, items_json, "
                 "total, username, status, created_at, converted_invoice_no "
                 "FROM quotations")
        if _cond9:
            _sql9 += " WHERE " + " AND ".join(_cond9)
        _sql9 += " ORDER BY id DESC"
        with connect() as conn:
            rows = conn.execute(_sql9, _prm9).fetchall()
        out = []
        _today9 = date.fromisoformat(_bd9)
        for r in rows:
            _dt9 = parse_dt_str(r["created_at"])
            _qbd9 = (derive_business_day_from_dt(_dt9) if _dt9 is not None
                     else str(r["created_at"] or "")[:10])
            if _days9 is not None and _qbd9 not in _days9:
                continue
            if _lo9 is not None and not (_lo9 <= _qbd9 <= _hi9):
                continue
            _age9 = 0
            try:
                _age9 = (_today9 - date.fromisoformat(_qbd9)).days
            except Exception:
                _age9 = 0
            _items9 = _quote_items_from_json(r["items_json"])
            out.append({"id": r["id"], "quote_no": r["quote_no"],
                        "customer_id": r["customer_id"],
                        "customer_text": r["customer_text"] or "",
                        "items": _items9, "count": len(_items9),
                        "total": (r["total"] or 0), "username": r["username"],
                        "status": r["status"],
                        "status_ar": QUOTATION_STATUSES.get(r["status"],
                                                            r["status"] or "—"),
                        "created_at": r["created_at"],
                        "converted_invoice_no": r["converted_invoice_no"],
                        "age": max(0, _age9)})
        return out
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return None

def quotation_get_row(username, quote_id):
    """★ إضافة (عروض الأسعار): صف عرض واحد بالمعرف — الطبقة الثانية أولًا،
    ونطاق الرؤية نفسه داخل الاستعلام (غير الأدمن عروضه هو وحده)، ويرجع
    قاموس الصف أو None عند فقدان الصلاحية أو الغياب"""
    if not user_has_permission(username, "quotations_manage"):
        return None
    try:
        _ensure_quotations_table()
        _urow9 = get_user_row(username)
        _is_adm9 = (_urow9 is not None and _urow9["role"] == ADMIN_ROLE)
        with connect() as conn:
            r = conn.execute(
                "SELECT id, quote_no, customer_id, customer_text, items_json, "
                "total, username, status, created_at, converted_invoice_no "
                "FROM quotations WHERE id=?", (int(quote_id),)).fetchone()
        if r is None:
            return None
        if not _is_adm9 and (r["username"] or "") != username:
            return None          # ليس عرضه وغير أدمن: كأنه غير موجود
        _items9 = _quote_items_from_json(r["items_json"])
        return {"id": r["id"], "quote_no": r["quote_no"],
                "customer_id": r["customer_id"],
                "customer_text": r["customer_text"] or "",
                "items": _items9, "count": len(_items9),
                "total": (r["total"] or 0), "username": r["username"],
                "status": r["status"],
                "status_ar": QUOTATION_STATUSES.get(r["status"],
                                                    r["status"] or "—"),
                "created_at": r["created_at"],
                "converted_invoice_no": r["converted_invoice_no"], "age": 0}
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return None

def quotation_save_new(username, customer_id, customer_text, items):
    """★ إضافة (عروض الأسعار): إنشاء عرض جديد مرقّمًا برقم مستقل — الطبقة
    الثانية أولًا، وإعادة التحقق من الأصناف (صنف واحد على الأقل باسم
    وسعر صحيحين) داخل الدالة نفسها، والترقيم من get_next_quote_number
    المستقل وحده؛ يرجع (True, رقم العرض) أو (False, رسالة عربية)"""
    if not user_has_permission(username, "quotations_manage"):
        return False, "لا تملك صلاحية «عروض الأسعار» — لم يُحفظ شيء"
    try:
        _clean9 = []
        for it in (items or []):
            _nm9 = str(it.get("item") or "").strip()
            _q9 = it.get("qty")
            _p9 = it.get("price")
            if not _nm9:
                return False, "كل صنف في العرض يحتاج اسمًا — راجع الأصناف"
            try:
                _q9 = float(_q9)
                _p9 = float(_p9)
            except (TypeError, ValueError):
                return False, f"كمية أو سعر غير صحيح للصنف «{_nm9}»"
            if _q9 <= 0:
                return False, f"كمية الصنف «{_nm9}» يجب أن تكون أكبر من صفر"
            if _p9 < 0:
                return False, f"سعر الصنف «{_nm9}» غير صحيح"
            _clean9.append({"item": _nm9, "qty": _q9, "price": _p9})
        if not _clean9:
            return False, "أضف صنفًا واحدًا على الأقل إلى العرض قبل الحفظ"
        _no9 = get_next_quote_number()
        if _no9 is None:
            return False, ("تعذر توليد رقم العرض — سُجّل السبب في "
                           "error_log.txt ولم يُحفظ شيء")
        _total9 = sum(i9["qty"] * i9["price"] for i9 in _clean9)
        with connect() as conn:
            conn.execute(
                "INSERT INTO quotations(quote_no, customer_id, customer_text, "
                "items_json, total, username, status, created_at, "
                "converted_invoice_no) VALUES(?,?,?,?,?,?,?,?,?)",
                (_no9, customer_id, (customer_text or "").strip() or None,
                 json.dumps(_clean9, ensure_ascii=False), _total9, username,
                 "open", datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                 None))
        return True, _no9
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return False, "تعذر حفظ العرض — سُجّل السبب في error_log.txt"

def quotation_update_row(username, quote_id, customer_id, customer_text, items):
    """★ إضافة (عروض الأسعار): تعديل عرض مفتوح بنفس رقمه دون استهلاك رقم
    جديد — الطبقة الثانية أولًا، والتحقق أن العرض موجود ومفتوح (قراءة
    حية) وأنه عرض منشئ المستخدم نفسه لغير الأدمن، ثم إعادة تحقق الأصناف
    نفسها؛ يرجع (True, رقم العرض) أو (False, رسالة عربية)"""
    if not user_has_permission(username, "quotations_manage"):
        return False, "لا تملك صلاحية «عروض الأسعار» — لم يُحفظ شيء"
    try:
        _old9 = quotation_get_row(username, quote_id)
        if _old9 is None:
            return False, "العرض غير موجود (أو ليس من عروضك) — لم يُحفظ شيء"
        if _old9["status"] != "open":
            return False, ("التعديل متاح للعروض المفتوحة فقط — حالة هذا "
                           "العرض: " + _old9["status_ar"])
        _clean9 = []
        for it in (items or []):
            _nm9 = str(it.get("item") or "").strip()
            try:
                _q9 = float(it.get("qty"))
                _p9 = float(it.get("price"))
            except (TypeError, ValueError):
                return False, f"كمية أو سعر غير صحيح للصنف «{_nm9}»"
            if not _nm9:
                return False, "كل صنف في العرض يحتاج اسمًا — راجع الأصناف"
            if _q9 <= 0:
                return False, f"كمية الصنف «{_nm9}» يجب أن تكون أكبر من صفر"
            if _p9 < 0:
                return False, f"سعر الصنف «{_nm9}» غير صحيح"
            _clean9.append({"item": _nm9, "qty": _q9, "price": _p9})
        if not _clean9:
            return False, "أضف صنفًا واحدًا على الأقل إلى العرض قبل الحفظ"
        _total9 = sum(i9["qty"] * i9["price"] for i9 in _clean9)
        with connect() as conn:
            conn.execute(
                "UPDATE quotations SET customer_id=?, customer_text=?, "
                "items_json=?, total=? WHERE id=? AND status='open'",
                (customer_id, (customer_text or "").strip() or None,
                 json.dumps(_clean9, ensure_ascii=False), _total9,
                 int(quote_id)))
        return True, _old9["quote_no"]
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return False, "تعذر تحديث العرض — سُجّل السبب في error_log.txt"

def quotation_cancel_row(username, quote_id):
    """★ إضافة (عروض الأسعار): إلغاء عرض مفتوح — الطبقة الثانية أولًا ثم
    قراءة حية: المفتوح وحده يُلغى (والمحول والملغي لا يتغيران أبدًا)؛
    يرجع (True, رسالة) أو (False, رسالة عربية)"""
    if not user_has_permission(username, "quotations_manage"):
        return False, "لا تملك صلاحية «عروض الأسعار» — لم يُلغَ شيء"
    try:
        _old9 = quotation_get_row(username, quote_id)
        if _old9 is None:
            return False, "العرض غير موجود (أو ليس من عروضك)"
        if _old9["status"] != "open":
            return False, ("الإلغاء متاح للعروض المفتوحة فقط — حالة هذا "
                           "العرض: " + _old9["status_ar"])
        with connect() as conn:
            conn.execute("UPDATE quotations SET status='cancelled' "
                         "WHERE id=? AND status='open'", (int(quote_id),))
        return True, ("أُلغي عرض السعر رقم " + str(_old9["quote_no"] or "—")
                      + " — لا يمكن تحويله إلى فاتورة أبدًا")
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return False, "تعذر إلغاء العرض — سُجّل السبب في error_log.txt"

def quotation_mark_converted(quote_id, invoice_no):
    """★ إضافة (عروض الأسعار): تعليم عرض «محول لفاتورة» برقم الفاتورة —
    تُستدعى حصرًا من خطاف نجاح حفظ الفاتورة داخل save_invoice بعد إتمام
    الحفظ فعليًا (فشل الفاتورة أو إلغاؤها لا يصل إلى هنا أبدًا فيبقى
    العرض مفتوحًا كما كان)؛ الطبقة الثانية (صاحب الجلسة الذي بدأ التحويل
    نفسه) ثم قراءة حية: المفتوح وحده يُعلَّم، والتحديث نفسه مشروط بالحالة
    في عبارة SQL نفسها؛ يرجع (True, رسالة) أو (False, رسالة)"""
    if not user_has_permission(CURRENT_USER["name"], "quotations_manage"):
        return False, "لا تملك صلاحية «عروض الأسعار» — لم يُعلَّم العرض"
    try:
        with connect() as conn:
            _cur9 = conn.execute(
                "UPDATE quotations SET status='converted', converted_invoice_no=? "
                "WHERE id=? AND status='open'",
                ((str(invoice_no) if invoice_no else None), int(quote_id)))
            _n9 = getattr(_cur9, "rowcount", 0)
        if not _n9:
            return False, "العرض ليس مفتوحًا — لم يُعلَّم"
        return True, "تم تعليم العرض «محول لفاتورة»"
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return False, "تعذر تعليم العرض — سُجّل السبب في error_log.txt"

def quotation_build_text(row):
    """★ إضافة (عروض الأسعار): بناء نص العرض العربي المنسق — اسم المحل
    ورقم العرض والتاريخ والعميل والأصناف بالأسعار والإجمالي واسم البائع
    — دالة نقية لا تلمس القرص إطلاقًا (الحفظ في quotation_save_text_file
    وحدها والنسخ للحافظة في نافذة القائمة)"""
    lines = []
    _store9 = (get_setting("store_name") or "نظام المبيعات والمُرتجعات")
    lines.append("عرض سعر" + (f" — {_store9}" if _store9 else ""))
    lines.append("رقم العرض: " + str(row.get("quote_no") or "—"))
    lines.append("التاريخ: " + str(row.get("created_at") or "—")[:16])
    lines.append("العميل: " + ((row.get("customer_text") or "").strip()
                               or "عميل غير محدد"))
    lines.append("البائع: " + str(row.get("username") or "—"))
    lines.append("-" * 46)
    lines.append("الأصناف (الصنف | الكمية | سعر الوحدة | الإجمالي):")
    _items9 = row.get("items") or []
    if _items9:
        for it9 in _items9:
            lines.append("  {} | {} | {} | {}".format(
                it9["item"], f'{it9["qty"]:g}', money(it9["price"]),
                money(it9["qty"] * it9["price"])))
    else:
        lines.append("  لا أصناف")
    lines.append("-" * 46)
    lines.append("الإجمالي: " + money(row.get("total") or 0))
    lines.append("-" * 46)
    lines.append("هذا عرض سعر وليس فاتورة — الأسعار قابلة للتأكيد وقت الشراء")
    return "\n".join(lines) + "\n"

def quotation_save_text_file(username, row):
    """★ إضافة (عروض الأسعار): حفظ نسخة العرض النصية بترميز utf-8 في
    data_dir/reports/ (إنشاء المجلد إن لم يوجد) — تبدأ بفحص الصلاحية
    مجددًا (الطبقة الثانية)، وترجع (True, المسار) عند النجاح أو (False,
    رسالة عربية واضحة) عند الفشل — دون انهيار أبدًا (نفس أسلوب حفظ
    كشف الصندوق النصي القائم حرفيًا)"""
    if not user_has_permission(username, "quotations_manage"):
        return False, "لا تملك صلاحية «عروض الأسعار» — لم يُحفظ شيء"
    try:
        _dir9 = os.path.join(data_dir(), "reports")
        os.makedirs(_dir9, exist_ok=True)
        _no9 = str(row.get("quote_no") or "0")
        _path9 = os.path.join(
            _dir9, datetime.now().strftime("quote_%Y%m%d_%H%M%S")
            + "_" + _no9 + ".txt")
        with open(_path9, "w", encoding="utf-8") as f:
            f.write(quotation_build_text(row))
        return True, _path9
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return False, "تعذر حفظ النسخة النصية — سُجّل السبب في error_log.txt"

def aging_bucket(age):
    """★ إضافة (حزمة الصندوق والرقابة المالية — الميزة 3): فئة العمر —
    0–30 يومًا / 31–60 يومًا / أكثر من 60 يومًا"""
    try:
        age = int(age)
    except Exception:
        age = 0
    if age <= 30:
        return "0–30 يومًا"
    if age <= 60:
        return "31–60 يومًا"
    return "أكثر من 60 يومًا"

def debt_aging_rows():
    """★ إضافة (حزمة الصندوق والرقابة المالية — الميزة 3): كل الديون
    المفتوحة والجزئية مع عمر كل دين بالأيام من تاريخ إنشائه created_at
    القائم محسوبًا باليوم التجاري بقاعدة 05:00 نفسها، والمتبقي، والفئة
    العمرية، والموعد المتفق عليه promised_date — يرجع قائمة قواميس (الأقدم
    أولًا) أو قائمة فارغة عند أي فشل"""
    try:
        _ensure_cash_tables()
        _today6 = date.fromisoformat(get_business_day())
        with connect() as conn:
            rows = conn.execute(
                "SELECT d.id, d.invoice_number, d.created_at, d.total_amount, "
                "d.paid_amount, d.status, d.promised_date, d.customer_id, "
                "c.name AS cname FROM debts d LEFT JOIN customers c "
                "ON c.id = d.customer_id WHERE d.status IN ('مفتوح','جزئي') "
                "ORDER BY d.id").fetchall()
        out = []
        for r in rows:
            _dt6 = parse_dt_str(r["created_at"])
            if _dt6 is None:
                continue
            try:
                _age6 = (_today6 - date.fromisoformat(
                    derive_business_day_from_dt(_dt6))).days
            except Exception:
                _age6 = 0
            d6 = dict(r)
            d6["remaining"] = max(r["total_amount"] - r["paid_amount"], 0.0)
            d6["age"] = max(_age6, 0)
            d6["bucket"] = aging_bucket(d6["age"])
            out.append(d6)
        return out
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return []

def delinquent_debts_summary():
    """★ إضافة (حزمة الصندوق والرقابة المالية — الميزة 5): ملخص الديون
    المتعثرة — الديون المفتوحة أو الجزئية التي تجاوز عمرها 60 يومًا من
    تاريخ إنشائها بلا سداد كامل، بعددها وإجمالي مبالغها المتبقية —
    يرجع (العدد، الإجمالي) وقيمًا صفرية آمنة عند أي فشل"""
    try:
        rows = debt_aging_rows()
        _bad6 = [r for r in rows if r["age"] > 60]
        return len(_bad6), sum(r["remaining"] for r in _bad6)
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return 0, 0.0


# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (موعد التحصيل): وعد العميل بالسداد عند البيع بالدين ★★★
# طبقة مستقلة فوق كل ما هو قائم: التعديل الوحيد على قاعدة البيانات هو
# عمود واحد جديد collection_date على جدول الديون القائم بترحيل آمن
# (فحص PRAGMA table_info ثم ALTER TABLE مرة واحدة فقط داخل try/except)،
# والمقارنة في كل حسابات هذه الميزة بتاريخ اليوم الميلادي العادي
# date.today() حصراً (وليس حدود اليوم التجاري 05:00) لأن الموعد وعد
# واقعي من العميل، والصيغة الموحدة YYYY-MM-DD — وفشل الترحيل لا يوقف
# البرنامج أبداً بل يعمل بدون الميزة ويُسجل الخطأ في error_log.txt
# ═══════════════════════════════════════════════════════════

_COLL_READY = {"done": False}   # ترحيل عمود الموعد مرة واحدة عند أول استخدام

def _ensure_collection_date_column():
    """★ إضافة (موعد التحصيل): الترحيل الآمن لعمود collection_date TEXT
    الجديد وحده على جدول الديون القائم — يستدعي _ensure_stage4_tables
    القائمة أولاً فيضمن وجود جدول الديون قبل العمود الجديد، ثم يفحص
    PRAGMA table_info(debts) فلا ينفذ ALTER TABLE إلا مرة واحدة فقط إن
    كان العمود غائباً، وكل خطأ يُسجل في error_log.txt ولا يوقف البرنامج؛
    بعد أول نجاح تعود الدالة فوراً بلا أي استعلام إضافي، وإن تعذر العمود
    تعود المحاولة عند الاستدعاء التالي دون أي أثر جانبي أبدًا (والبرنامج
    يعمل بلا الميزة: كل الإدراجات والقراءات تتحقق من العلم قبل لمسه)"""
    if _COLL_READY["done"]:
        return
    try:
        _ensure_stage4_tables()
    except Exception as e:
        log_error(e, sys.exc_info()[2])
    _ok_c = False
    try:
        with connect() as conn:
            _cols_c = [rr[1] for rr in conn.execute("PRAGMA table_info(debts)")]
            if "collection_date" not in _cols_c:
                conn.execute("ALTER TABLE debts ADD COLUMN collection_date TEXT")
        _ok_c = True
    except Exception as e:
        log_error(e, sys.exc_info()[2])
    _COLL_READY["done"] = _ok_c

def parse_collection_date(s):
    """★ إضافة (موعد التحصيل): تحقق صارم من صيغة تاريخ الموعد الموحدة
    YYYY-MM-DD (يقبل الأرقام العربية ويحوّلها إنجليزية) — يرجع كائن
    date الصالح أو None لأي خلل في الصيغة أو القيمة (مثل 2026-13-45
    أو 2026-1-5) دون أي استثناء أبداً"""
    try:
        v = str(s or "").strip().translate(AR_DIGITS)
        if not v:
            return None
        parts = v.split("-")
        if len(parts) != 3:
            return None
        y, m, dd = parts
        if not (len(y) == 4 and len(m) == 2 and len(dd) == 2
                and y.isdigit() and m.isdigit() and dd.isdigit()):
            return None
        d = date(int(y), int(m), int(dd))
        if d.isoformat() != v:
            return None
        return d
    except Exception:
        return None

def collection_due_rows(limit=20):
    """★ إضافة (موعد التحصيل): كل الديون المفتوحة والجزئية ذات موعد
    تحصيل مع العميل وهاتفه والمتبقي وحالة الموعد — المقارنة بتاريخ
    اليوم الميلادي العادي date.today() (وليس حدود اليوم التجاري 05:00)
    لأن الموعد وعد واقعي من العميل؛ الحالة: متأخر X يوم (أحمر) /
    مستحق اليوم / بعد Y يوم، والترتيب بالأقدم استحقاقًا أولًا (المتأخرة
    الأشد ثم مستحقة اليوم ثم الأقرب قادمًا) — يرجع قائمة قواميس أو
    قائمة فارغة عند أي فشل أو غياب العمود (الميزة معطلة بأمان)"""
    try:
        _ensure_collection_date_column()
        if not _COLL_READY["done"]:
            return []
        _today_c = date.today()
        with connect() as conn:
            rows = conn.execute(
                "SELECT d.id, d.invoice_number, d.customer_id, d.total_amount, "
                "d.paid_amount, d.collection_date, c.name AS cname, c.phone "
                "FROM debts d LEFT JOIN customers c ON c.id = d.customer_id "
                "WHERE d.status IN ('مفتوح','جزئي') ORDER BY d.id").fetchall()
        out = []
        for r in rows:
            _v = str(r["collection_date"] or "").strip()
            if not _v:
                continue              # دين بلا موعد — ليس من هذه القائمة
            try:
                _cd = date.fromisoformat(_v)
            except Exception:
                continue              # تاريخ مخزن غير صالح — يُتجاهل بصمت
            _diff = (_cd - _today_c).days
            _rem = max(r["total_amount"] - r["paid_amount"], 0.0)
            if _diff < 0:
                _kind, _st = "late", f"متأخر {-_diff} يوم"
            elif _diff == 0:
                _kind, _st = "today", "مستحق اليوم"
            else:
                _kind, _st = "future", f"بعد {_diff} يوم"
            out.append({"id": r["id"], "cname": r["cname"] or "—",
                        "phone": (str(r["phone"] or "").strip() or "—"),
                        "invoice_number": r["invoice_number"],
                        "remaining": _rem,
                        "collection_date": _cd.isoformat(),
                        "days": _diff, "kind": _kind, "status_text": _st})
        out.sort(key=lambda x: (x["days"], x["id"]))
        if limit:
            out = out[:max(1, int(limit))]
        return out
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return []

def collection_due_counts():
    """★ إضافة (موعد التحصيل): أرقام شريط تنبيه التحصيلات — (عدد الديون
    المتأخرة، عدد المستحقة اليوم، إجمالي المتبقي لهما معًا) بقاعدة
    اليوم الميلادي العادي نفسها — يرجع قيمًا صفرية آمنة عند أي فشل"""
    try:
        rows = collection_due_rows(limit=None)
        _late_c = [r for r in rows if r["kind"] == "late"]
        _today_c = [r for r in rows if r["kind"] == "today"]
        _tot_c = (sum(r["remaining"] for r in _late_c)
                  + sum(r["remaining"] for r in _today_c))
        return len(_late_c), len(_today_c), _tot_c
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return 0, 0, 0.0


# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (كشف الصندوق — التبويب السادس في التقارير الإدارية): ★★★
# طبقة قراءة فقط فوق كل ما هو قائم: جامع حركات النقدية لأي فترة تجارية
# مع تصفية البائع، وبانية نص التقرير، وحافظة النسخة النصية في
# data_dir/reports — لا تُنشئ أي جدول ولا تعدل أي جدول قائم ولا تكتب أي
# سجل تدقيق إطلاقًا، وكل حساب «اليوم» بقاعدة 05:00 نفسها
# (derive_business_day_from_dt القائمة)، وتمييز النقدي من الديني بنفس
# منطق cash_report_data القائمة حرفيًا: payment_kind='دين' هو الفيصل
# والدفعات الأولى = مجموع صفوف الدين ناقص أصول الديون المرتبطة بها،
# والمرتجعات المستقلة (غير الموسومة دين) وحدها خارج نقدي لأن مرتجع
# فاتورة الدين داخلها مقفول أصلًا ضمن دفعتها الأولى فلم يخرج من الدرج
# — وصفوف الشبكة لا تدخل الدرج أصلًا فلا تظهر، وكل دالة هنا تبدأ بفحص
# الصلاحية مجددًا (الطبقة الثانية بعد إخفاء التبويب) وترجع None عند
# فشلها فلا يُعرض رقم خاطئ أبدًا
# ═══════════════════════════════════════════════════════════

def cash_box_period_data(username, d_from, d_to, seller=None):
    """★ إضافة (كشف الصندوق): كل حركات النقدية في الفترة التجارية
    [d_from, d_to] — قراءة صامتة من الجداول القائمة وحدها: عمليات
    operations في الفترة (عمود date هو اليوم التجاري المسجل وقت الحفظ
    نفسه)، والدفعة الأولى لكل فاتورة دين من فرق صفوفها الموسومة «دين»
    عن أصل الدين المرتبط بها (debts.sale_id القائم — فمن دفع كامل
    المبلغ أولًا لا دين له فيظهر كامل مبلغه دفعة أولى)، وتحصيلات
    debt_payments في أيامها التجارية بقاعدة 05:00 نفسها، والمرتجعات
    المستقلة وحدها خارجًا نقديًا؛ وتصفية البائع تُطبق على فواتيره
    وتحصيلاته ومرتجعاته وحدها — يرجع قاموس الحركات والإجماليات أو
    None عند فقدان الصلاحية أو أي فشل"""
    if not user_has_permission(username, "cash_box_view"):
        return None
    try:
        d_from = str(d_from)[:10]
        d_to = str(d_to)[:10]
        if d_from > d_to:
            d_from, d_to = d_to, d_from      # تحمّل قلب الفترة بلا انهيار
        try:
            _dnext7 = next_day(d_to)
        except Exception:
            _dnext7 = d_to
        movements = []
        # (1) فواتير الفترة بترتيبها الطبيعي (id) — قراءة واحدة
        _cond7 = ["date >= ?", "date <= ?"]
        _prm7 = [d_from, d_to]
        if seller:
            _cond7.append("seller_name = ?")
            _prm7.append(seller)
        with connect() as conn:
            rows = conn.execute(
                "SELECT id, date, type, total, customer_name, seller_name, "
                "payment_kind, invoice_number, return_reason FROM operations "
                "WHERE " + " AND ".join(_cond7) + " ORDER BY id",
                _prm7).fetchall()
        # التجميع: برقم الفاتورة إن وُجد، وإلا فكل عملية قديمة مجموعة
        # قائمة بذاتها تظهر برقم فاتورة «—»
        _groups7 = {}
        _order7 = []
        for r in rows:
            _k7 = (r["invoice_number"] or "").strip()
            if not _k7:
                _k7 = "op:%d" % r["id"]
            if _k7 not in _groups7:
                _groups7[_k7] = []
                _order7.append(_k7)
            _groups7[_k7].append(r)
        # أصول الديون المرتبطة بصفوف الدين في الفترة — استعلام واحد
        # (لعزل الدفعة الأولى من كل فاتورة دين على حدة)
        _credit_ids7 = [r["id"] for g in _groups7.values() for r in g
                        if (r["payment_kind"] or "") == "دين"]
        _debt_by_sale7 = {}
        if _credit_ids7:
            try:
                with connect() as conn:
                    _ph7 = ",".join("?" * len(_credit_ids7))
                    for _dr7 in conn.execute(
                            "SELECT sale_id, total_amount FROM debts "
                            "WHERE sale_id IN (" + _ph7 + ")",
                            list(_credit_ids7)):
                        _debt_by_sale7[_dr7["sale_id"]] = \
                            _debt_by_sale7.get(_dr7["sale_id"], 0.0) + \
                            (_dr7["total_amount"] or 0)
            except Exception as e:
                log_error(e, sys.exc_info()[2])
        # أوقات الحركات الحقيقية — نفس مطابق سجل التدقيق القائم
        # (monitor_op_times: قراءة فقط لا يُسجل شيئًا)
        try:
            _tmap7 = monitor_op_times()
        except Exception:
            _tmap7 = {}
        # بناء الحركات لكل فاتورة: نقديها داخل، ومرتجعها المستقل خارج،
        # ودفعة فاتورة الدين داخل، ودين بلا دفعة أولى لا يظهر أصلًا
        for _k7 in _order7:
            g = _groups7[_k7]
            _ids7 = [r["id"] for r in g]
            _times7 = sorted(_tmap7.get(i, "") for i in _ids7
                             if _tmap7.get(i, ""))
            _tstr7 = (_times7[0] if _times7 else (g[0]["date"] or ""))
            _sort7 = (_tstr7 if len(_tstr7) > 10 else _tstr7 + " 00:00:00")
            _inv7 = (g[0]["invoice_number"] or "").strip() or "—"
            _cred7 = [r for r in g if (r["payment_kind"] or "") == "دين"]
            _norm7 = [r for r in g if (r["payment_kind"] or "") != "دين"]
            if _cred7:
                _b7 = _cred7[0]
                _rows_sum7 = sum((r["total"] or 0) for r in _cred7)
                _debt_sum7 = sum(_debt_by_sale7.get(i, 0.0) for i in _ids7)
                _down7 = max(0.0, _rows_sum7 - _debt_sum7)
                if _down7 > 1e-9:
                    movements.append({
                        "sort": _sort7, "time": _tstr7[:16],
                        "kind": "دفعة أولى (بيع بالدين)", "invoice": _inv7,
                        "customer": (_b7["customer_name"] or "").strip() or "—",
                        "seller": (_b7["seller_name"] or "").strip() or "—",
                        "amount": _down7,
                        "note": "إجمالي الفاتورة " + money(_rows_sum7)})
            if _norm7:
                _b7 = _norm7[0]
                _cash7 = 0.0
                _netw7 = 0.0
                _rets7 = 0.0
                _reasons7 = []
                for r in _norm7:
                    _tt7 = r["type"]
                    if _tt7 == "مرتجع":
                        _rets7 += -(r["total"] or 0)
                        _rr7 = (r["return_reason"] or "").strip()
                        if _rr7 and _rr7 not in _reasons7:
                            _reasons7.append(_rr7)
                    elif _tt7 == "شبكة":
                        _netw7 += (r["total"] or 0)
                    else:      # نقداً (وقيم البيع القديمة بعد الترقية)
                        _cash7 += (r["total"] or 0)
                if abs(_cash7) > 1e-9:
                    movements.append({
                        "sort": _sort7, "time": _tstr7[:16],
                        "kind": "فاتورة نقدية", "invoice": _inv7,
                        "customer": (_b7["customer_name"] or "").strip() or "—",
                        "seller": (_b7["seller_name"] or "").strip() or "—",
                        "amount": _cash7,
                        "note": (f"{len(_norm7)} صنفاً" +
                                 (f" + شبكة {money(_netw7)} خارج الدرج"
                                  if abs(_netw7) > 1e-9 else ""))})
                if _rets7 > 1e-9:
                    movements.append({
                        "sort": _sort7, "time": _tstr7[:16],
                        "kind": "مرتجع نقدي", "invoice": _inv7,
                        "customer": (_b7["customer_name"] or "").strip() or "—",
                        "seller": (_b7["seller_name"] or "").strip() or "—",
                        "amount": -_rets7,
                        "note": ("سبب: " + "، ".join(_reasons7)[:60]
                                 if _reasons7 else "مرتجع نقدي")})
        # (2) تحصيلات debt_payments اللاحقة في أيامها التجارية داخل الفترة
        # (قاعدة 05:00 نفسها) — بنفس أسلوب cash_report_data القائمة
        try:
            _pcond7 = ["substr(p.created_at,1,10) >= ?",
                       "substr(p.created_at,1,10) <= ?"]
            _pprm7 = [d_from, _dnext7]
            if seller:
                _pcond7.append("p.collected_by = ?")
                _pprm7.append(seller)
            with connect() as conn:
                prows = conn.execute(
                    "SELECT p.amount, p.collected_by, p.note, p.created_at, "
                    "d.invoice_number, c.name AS cname FROM debt_payments p "
                    "LEFT JOIN debts d ON d.id = p.debt_id "
                    "LEFT JOIN customers c ON c.id = d.customer_id "
                    "WHERE " + " AND ".join(_pcond7) + " ORDER BY p.id",
                    _pprm7).fetchall()
            for r in prows:
                _dt7 = parse_dt_str(r["created_at"])
                if _dt7 is None:
                    continue
                _bd7 = derive_business_day_from_dt(_dt7)
                if _bd7 < d_from or _bd7 > d_to:
                    continue
                movements.append({
                    "sort": str(r["created_at"])[:19],
                    "time": str(r["created_at"])[:16],
                    "kind": "تحصيل دين",
                    "invoice": (r["invoice_number"] or "").strip() or "—",
                    "customer": (r["cname"] or "").strip() or "—",
                    "seller": (r["collected_by"] or "").strip() or "—",
                    "amount": (r["amount"] or 0),
                    "note": ((r["note"] or "").strip() or "تحصيل دين")[:60]})
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        # (3) ★ إضافة (ميزة «المصروفات» — التعديل المصرح به الوحيد على
        # كشف الصندوق القائم): مصروفات المحل المسجلة في أيامها التجارية
        # داخل الفترة (قاعدة 05:00 نفسها) تُضاف حركات «مصروف» سالبة ضمن
        # «نقد خارج» — ببنية الحركة نفسها وأسلوب قراءة التحصيلات القائم
        # حرفيًا، وتصفية البائع على المصروف الذي سجّله هو بنفسه (عمود
        # username)، فتتحدث بطاقة «صافي الحركة» وقيمة «نقد خارج» تلقائيًا
        try:
            _econd7 = ["substr(created_at,1,10) >= ?",
                       "substr(created_at,1,10) <= ?"]
            _eprm7 = [d_from, _dnext7]
            if seller:
                _econd7.append("username = ?")
                _eprm7.append(seller)
            with connect() as conn:
                erows = conn.execute(
                    "SELECT amount, category, note, username, created_at "
                    "FROM expenses WHERE " + " AND ".join(_econd7)
                    + " ORDER BY id", _eprm7).fetchall()
            for r in erows:
                _dt7 = parse_dt_str(r["created_at"])
                if _dt7 is None:
                    continue
                _bd7 = derive_business_day_from_dt(_dt7)
                if _bd7 < d_from or _bd7 > d_to:
                    continue
                _note7 = str(r["note"] or "").strip()
                movements.append({
                    "sort": str(r["created_at"])[:19],
                    "time": str(r["created_at"])[:16],
                    "kind": "مصروف",
                    "invoice": "—",
                    "customer": "—",
                    "seller": (r["username"] or "").strip() or "—",
                    "amount": -(r["amount"] or 0),
                    "note": ((str(r["category"] or "").strip() or "مصروف")
                             + ((" — " + _note7) if _note7 else ""))[:60]})
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        # الترتيب الزمني والإجماليات
        movements.sort(key=lambda m: m["sort"])
        cash_in = sum(m["amount"] for m in movements if m["amount"] > 0)
        cash_out = -sum(m["amount"] for m in movements if m["amount"] < 0)
        first_pay = sum(m["amount"] for m in movements
                        if m["kind"] == "دفعة أولى (بيع بالدين)")
        collects = sum(m["amount"] for m in movements
                       if m["kind"] == "تحصيل دين")
        cash_sales = sum(m["amount"] for m in movements
                         if m["kind"] == "فاتورة نقدية")
        rets = -sum(m["amount"] for m in movements
                    if m["kind"] == "مرتجع نقدي")
        # ★ إضافة (ميزة «المصروفات»): إجمالي مصروفات الفترة نقدًا خارجًا
        # (صفوف «مصروف» سالبة ضمن الحركات نفسها) — بند إضافي في قاموس
        # العودة وحده، وكل الإجماليات القائمة تظل كما تُحسب حرفيًا
        exps = -sum(m["amount"] for m in movements
                    if m["kind"] == "مصروف")
        return {"movements": movements,
                "cash_in": cash_in, "cash_out": cash_out,
                "net": cash_in - cash_out,
                "cash_sales": cash_sales, "first_payments": first_pay,
                "collections": collects, "returns": rets,
                "expenses": exps}
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return None


def cash_box_seller_options():
    """★ إضافة (كشف الصندوق): قائمة تصفية البائع — «كل البائعين» ثم اتحاد
    المستخدمين النشطين مع كل أسماء البائعين الواردة في العمليات (حتى تظل
    عمليات بائع قديم أو متوقف قابلة للتصفية) — قراءة فقط، وقائمة آمنة
    عند أي فشل"""
    try:
        _names7 = set(active_users_list())
        try:
            with connect() as conn:
                for r in conn.execute(
                        "SELECT DISTINCT seller_name FROM operations "
                        "WHERE seller_name IS NOT NULL"):
                    _s7 = (r[0] or "").strip()
                    if _s7:
                        _names7.add(_s7)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        return ["كل البائعين"] + sorted(_names7)
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return ["كل البائعين"]


def cash_box_build_text(store, period_desc, d_from, d_to, seller_label,
                        data, opening, actual):
    """★ إضافة (كشف الصندوق): بناء نص التقرير المنسق — دالة نقية لا تلمس
    القرص إطلاقًا (الحفظ في cash_box_save_text_file وحدها)"""
    lines = []
    lines.append("كشف الصندوق" + (f" — {store}" if store else ""))
    lines.append(f"الفترة: من {d_from} إلى {d_to} ({period_desc})")
    lines.append(f"البائع: {seller_label}")
    lines.append("-" * 46)
    lines.append(f"نقد داخل: {money(data['cash_in'])}")
    lines.append("  منها فواتير نقدية: " + money(data["cash_sales"]))
    lines.append("  منها دفعات أولى (بيع بالدين): "
                 + money(data["first_payments"]))
    lines.append("  منها تحصيلات ديون: " + money(data["collections"]))
    lines.append(f"نقد خارج: {money(data['cash_out'])}")
    lines.append("  منها مرتجعات نقدية: " + money(data["returns"]))
    # ★ إضافة (ميزة «المصروفات»): تفصيل المصروفات ضمن «نقد خارج» في
    # النص المحفوظ — يقرأ المفتاح الجديد بأمان (.get) فلا يتأثر أي
    # مستدعٍ قديم
    lines.append("  منها مصروفات المحل: "
                 + money(data.get("expenses", 0)))
    lines.append(f"صافي الحركة (داخل - خارج): {money(data['net'])}")
    lines.append("-" * 46)
    if opening is not None:
        _exp7 = opening + data["net"]
        lines.append("تسوية الدرج:")
        lines.append(f"  رصيد افتتاحي: {money(opening)}")
        lines.append(f"  المتوقع في الدرج: {money(_exp7)}")
        if actual is not None:
            _dif7 = actual - _exp7
            if abs(_dif7) < 0.005:
                _res7 = "مطابق تمامًا"
            elif _dif7 > 0:
                _res7 = "زيادة " + money(_dif7)
            else:
                _res7 = "عجز " + money(-_dif7)
            lines.append(f"  النقد الفعلي في الدرج: {money(actual)}")
            lines.append(f"  النتيجة: {_res7}")
    lines.append("-" * 46)
    lines.append("الحركات النقدية (الوقت | النوع | الفاتورة | العميل | "
                 "البائع | المبلغ | ملاحظة):")
    if data["movements"]:
        for m in data["movements"]:
            lines.append("  {} | {} | {} | {} | {} | {} | {}".format(
                m["time"], m["kind"], m["invoice"], m["customer"],
                m["seller"], money(m["amount"]), m["note"]))
    else:
        lines.append("  لا حركات نقدية في هذه الفترة")
    lines.append("-" * 46)
    lines.append("طُبع بواسطة: " + CURRENT_USER["name"] + " — "
                 + datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
    return "\n".join(lines) + "\n"


def cash_box_save_text_file(username, store, period_desc, d_from, d_to,
                            seller_label, data, opening, actual):
    """★ إضافة (كشف الصندوق): حفظ النسخة النصية بترميز utf-8 في
    data_dir/reports/cash_box_YYYYMMDD_HHMMSS.txt (إنشاء المجلد إن لم
    يوجد) — تبدأ بفحص الصلاحية مجددًا (الطبقة الثانية)، وترجع (True,
    المسار) عند النجاح أو (False, رسالة عربية واضحة) عند الفشل — دون
    انهيار أبدًا"""
    if not user_has_permission(username, "cash_box_view"):
        return False, "لا تملك صلاحية «كشف الصندوق» — لم يُحفظ شيء"
    try:
        _dir7 = os.path.join(data_dir(), "reports")
        os.makedirs(_dir7, exist_ok=True)
        _path7 = os.path.join(
            _dir7,
            datetime.now().strftime("cash_box_%Y%m%d_%H%M%S") + ".txt")
        _text7 = cash_box_build_text(store, period_desc, d_from, d_to,
                                     seller_label, data, opening, actual)
        with open(_path7, "w", encoding="utf-8") as f:
            f.write(_text7)
        return True, _path7
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        return False, ("تعذر حفظ النسخة النصية — سُجّل السبب في "
                       "error_log.txt")

# ═══════════════════════════════════════════════════════════
# ★★★ إضافات (المرحلة الثالثة — التقارير الإدارية): جامعو البيانات ★★★
# طبقة قراءة فقط فوق كل ما هو قائم: زر «التقارير الإدارية» يظهر لمن يملك
# واحدة على الأقل من مفاتيح التقارير الخمسة في الكتالوج القائم (والأدمن
# يملكها كلها بدوره عبر user_has_permission القائم)، ونافذة واحدة بخمسة
# تبويبات يُنشأ كل تبويب لمن يملك مفتاحه فقط — وكل الدوال هنا قراءة صامتة
# من الجداول القائمة بأسمائها وأعمدتها الفعلية (operations وusers و
# active_sessions وaudit_log وsettings) ولا تُنشئ أي جداول جديدة ولا
# تُعدل أي جدول قائم ولا تكتب أي سجل تدقيق جديد إطلاقًا، وكل حساب «اليوم»
# من get_business_day() حصراً وبقاعدة 05:00 نفسها، وكل الأرقام تُعرض بفواصل
# الآلاف بنفس أسلوب money() القائم، وكل دالة تجمع بيانات تقرير تفحص
# الصلاحية مجددًا في بدايتها (الطبقة الثانية بعد الإخفاء) وترجع None عند
# فشلها فتظهر رسالة «لا تملك صلاحية» ولا تُعرض البيانات
# ═══════════════════════════════════════════════════════════

# مفاتيح التقارير الخمسة كما هي حرفيًا في PERMISSIONS_CATALOG القائم
ADMIN_REPORT_KEYS = ("morning_summary", "weekly_report", "discipline_report",
                     "system_health_view", "backup_monitor_view")

def admin_reports_permission(username):
    """★ إضافة (المرحلة الثالثة): هل يملك هذا المستخدم واحدة على الأقل من
    صلاحيات التقارير الخمس؟ — عبر محرك user_has_permission القائم وحده
    (الأدمن النشط يملكها كلها دائمًا بدوره)"""
    # ★ تعديل مصرح به (ميزة «المصروفات»): يُفتح باب نافذة «التقارير
    # الإدارية» أيضًا لمن يملك expense_report الجديد وحده — لأن تبويب
    # «المصروفات» داخلها لا يُبنى إلا له (وإلا لما وصل إليه مدير أو بائع
    # حتى بعد منحه المفتاح من «الصلاحيات الدقيقة»)؛ مفاتيح التقارير
    # الخمسة كما هي وفحوصها كلها لم تُمس، وزر النافذة يظهر له بنفس شرطه
    return (any(user_has_permission(username, k) for k in ADMIN_REPORT_KEYS)
            or user_has_permission(username, "expense_report"))

def last_business_days(n):
    """★ إضافة (المرحلة الثالثة): آخر n يومًا تجاريًا كسلاسل ISO جاهزة —
    أولها اليوم التجاري الجاري من get_business_day() حصراً ثم الأقدم
    تنازليًا بعده"""
    try:
        d0 = date.fromisoformat(get_business_day())
        return [date.fromordinal(d0.toordinal() - i).isoformat()
                for i in range(max(1, int(n)))]
    except Exception:
        return [get_business_day()]

def _reports_table_exists(conn, name):
    """★ إضافة (المرحلة الثالثة): هل يوجد جدول بهذا الاسم؟ — قراءة فقط من
    sqlite_master ولا يُنشئ شيئًا أبدًا"""
    try:
        return conn.execute("SELECT 1 FROM sqlite_master "
                            "WHERE type='table' AND name=?", (name,)).fetchone() is not None
    except Exception:
        return False

# أسماء شائعة لجدول المقبوضات إن وُجد — الفحص قراءة فقط ولا يُنشئ شيئًا
_REPORTS_RECEIPT_TABLES = ("receipts", "مقبوضات", "collections", "payments", "تحصيل")

def _reports_receipts_table():
    """★ إضافة (المرحلة الثالثة): اسم أول جدول مقبوضات موجود (أو None) —
    قراءة فقط من sqlite_master، فلا تظهر بطاقة المقبوضات أصلًا إن لم يوجد"""
    try:
        with connect() as conn:
            for t in _REPORTS_RECEIPT_TABLES:
                if _reports_table_exists(conn, t):
                    return t
    except Exception:
        pass
    return None

def _reports_receipts_total(d):
    """★ إضافة (المرحلة الثالثة): إجمالي المقبوضات لليوم التجاري d إن وُجد
    جدول للمقبوضات — يجمع عمود المبلغ فيه (وإن وُجد عمود تاريخ صفّى على
    يومه)، ويرجع None إن لم يوجد الجدول فلا تُعرض البطاقة أصلًا — قراءة
    فقط وأي خلل يرجع None بهدوء"""
    t = _reports_receipts_table()
    if t is None:
        return None
    try:
        with connect() as conn:
            cols = [str(r[1]) for r in conn.execute(f"PRAGMA table_info({t})")]
            low = {c.lower(): c for c in cols}
            amt = None
            for cand in ("amount", "total", "value", "مبلغ", "المبلغ", "قيمة", "القيمة"):
                if cand in low:
                    amt = low[cand]
                    break
            if amt is None:
                return None          # جدول بلا عمود مبلغ واضح — لا بطاقة
            dcol = None
            for cand in ("date", "day", "تاريخ", "اليوم"):
                if cand in low:
                    dcol = low[cand]
                    break
            if dcol is not None:
                r = conn.execute(f"SELECT SUM({amt}) FROM {t} "
                                 f"WHERE substr({dcol},1,10)=?", (d,)).fetchone()
            else:
                r = conn.execute(f"SELECT SUM({amt}) FROM {t}").fetchone()
            return (r[0] or 0.0) if r is not None else 0.0
    except Exception:
        return None

def _reports_invoice_counts(days):
    """★ إضافة (المرحلة الثالثة): عدد الفواتير لكل بائع على أيام تجارية —
    من سجل التدقيق القائم وحده بقراءة فقط: كل حدث «حفظ فاتورة» فاتورة
    واحدة، وكل «حفظ عملية» أو «add_operation» ليست مرتجعًا فاتورة بيع
    واحدة (هذه هي آلية الفواتير الفعلية في الكود — لا يوجد جدول فواتير
    مستقل)، واليوم التجاري لكل حدث من وقته الكامل بقاعدة 05:00 نفسها —
    يرجع {اليوم: {البائع: عدد الفواتير}}"""
    out = {d: {} for d in days}
    try:
        with connect() as conn:
            rows = conn.execute("SELECT ts, username, action, details FROM audit_log "
                                "WHERE action IN ('حفظ فاتورة','حفظ عملية',"
                                "'add_operation') ORDER BY id").fetchall()
        for r in rows:
            dt = parse_dt_str(r["ts"])
            if dt is None:
                continue
            bday = derive_business_day_from_dt(dt)
            if bday not in out:
                continue
            det = str(r["details"] or "")
            if r["action"] in ("حفظ عملية", "add_operation"):
                if det.lstrip().startswith("مرتجع") or "— مرتجع:" in det:
                    continue          # المرتجع ليس فاتورة بيع
            who = r["username"] or "—"
            out[bday][who] = out[bday].get(who, 0) + 1
    except Exception:
        pass
    return out

def collect_morning_summary(d):
    """★ إضافة (المرحلة الثالثة — التبويب 1): بيانات الملخص الصباحي ليوم
    تجاري واحد d — قراءة فقط: بطاقات المبيعات والمرتجعات والصافي وعددي
    عمليات البيع والمرتجعات والمقبوضات إن وُجد جدول لها، وأعلى 5 منتجات
    مبيعًا، وإجمالي كل بائع مع عدد فواتيره من سجل التدقيق؛ واليوم التجاري
    لكل حركة من قيمة تاريخها الفعلية بقاعدة 05:00 (نفس منطق مركز
    المتابعة). يرجع None بلا صلاحية، أو قاموسًا فيه error عند الخلل"""
    if not user_has_permission(CURRENT_USER["name"], "morning_summary"):
        return None
    out = {"sales": 0.0, "rets": 0.0, "net": 0.0, "sales_count": 0, "rets_count": 0,
           "receipts": None, "top_items": [], "sellers": [], "error": False}
    try:
        items, sellers = {}, {}
        with connect() as conn:
            rows = conn.execute("SELECT date, type, item_name, quantity, total, "
                                "seller_name FROM operations WHERE date LIKE ? "
                                "ORDER BY id", (str(d) + "%",)).fetchall()
        for r in rows:
            if op_business_day_from_date_val(r["date"]) != str(d):
                continue             # حركة قبل حد 05:00 تخص يومها التجاري الصحيح
            if r["type"] == "مرتجع":
                out["rets_count"] += 1
                out["rets"] += -(r["total"] or 0)
                continue
            out["sales_count"] += 1
            out["sales"] += (r["total"] or 0)
            it = items.setdefault(r["item_name"] or "—", {"q": 0.0, "s": 0.0})
            it["q"] += (r["quantity"] or 0)
            it["s"] += (r["total"] or 0)
            key = r["seller_name"] or "—"
            sellers[key] = sellers.get(key, 0.0) + (r["total"] or 0)
        out["net"] = out["sales"] - out["rets"]
        out["top_items"] = [{"name": n, "q": v["q"], "s": v["s"]}
                            for n, v in sorted(items.items(),
                                               key=lambda kv: -kv[1]["s"])[:5]]
        inv = _reports_invoice_counts([d])
        names = set(sellers) | set(inv.get(d, {}))
        out["sellers"] = [{"name": n, "invoices": inv.get(d, {}).get(n, 0),
                           "total": sellers.get(n, 0.0)}
                          for n in names]
        out["sellers"].sort(key=lambda s: -s["total"])
        out["receipts"] = _reports_receipts_total(d)
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        out["error"] = True
    return out

def collect_weekly_report():
    """★ إضافة (المرحلة الثالثة — التبويب 2): بيانات التقرير الأسبوعي —
    آخر 7 أيام تجارية (أولها اليوم التجاري الجاري من get_business_day()
    حصراً): لكل يوم المبيعات والمرتجعات والصافي وعدد العمليات + الإجمالي
    الكلي + أعلى 5 منتجات خلال الأسبوع + إجمالي كل بائع مع عدد فواتيره —
    قراءة فقط من جدول العمليات وسجل التدقيق. يرجع None بلا صلاحية أو
    قاموسًا فيه error عند الخلل"""
    if not user_has_permission(CURRENT_USER["name"], "weekly_report"):
        return None
    out = {"days": [], "totals": {"sales": 0.0, "rets": 0.0, "net": 0.0, "ops": 0},
           "top_items": [], "sellers": [], "error": False}
    try:
        days = last_business_days(7)
        dayset = set(days)
        per = {d: {"sales": 0.0, "rets": 0.0, "ops": 0} for d in days}
        items, sellers = {}, {}
        with connect() as conn:
            rows = conn.execute("SELECT date, type, item_name, quantity, total, "
                                "seller_name FROM operations WHERE date >= ? "
                                "ORDER BY id", (days[-1],)).fetchall()
        for r in rows:
            bday = op_business_day_from_date_val(r["date"])
            if bday not in dayset:
                continue
            p = per[bday]
            p["ops"] += 1
            if r["type"] == "مرتجع":
                p["rets"] += -(r["total"] or 0)
                continue
            p["sales"] += (r["total"] or 0)
            it = items.setdefault(r["item_name"] or "—", {"q": 0.0, "s": 0.0})
            it["q"] += (r["quantity"] or 0)
            it["s"] += (r["total"] or 0)
            key = r["seller_name"] or "—"
            sellers[key] = sellers.get(key, 0.0) + (r["total"] or 0)
        for d in days:
            p = per[d]
            out["days"].append({"date": d, "sales": p["sales"], "rets": p["rets"],
                                "ops": p["ops"], "net": p["sales"] - p["rets"]})
            out["totals"]["sales"] += p["sales"]
            out["totals"]["rets"] += p["rets"]
            out["totals"]["ops"] += p["ops"]
        out["totals"]["net"] = out["totals"]["sales"] - out["totals"]["rets"]
        out["top_items"] = [{"name": n, "q": v["q"], "s": v["s"]}
                            for n, v in sorted(items.items(),
                                               key=lambda kv: -kv[1]["s"])[:5]]
        inv = _reports_invoice_counts(days)
        names = set(sellers)
        for d in days:
            names |= set(inv.get(d, {}))
        out["sellers"] = [{"name": n,
                           "invoices": sum(inv.get(d, {}).get(n, 0) for d in days),
                           "total": sellers.get(n, 0.0)}
                          for n in names]
        out["sellers"].sort(key=lambda s: -s["total"])
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        out["error"] = True
    return out

def collect_discipline_report(n_days):
    """★ إضافة (المرحلة الثالثة — التبويب 3): بيانات الانضباط الإداري —
    قراءة فقط من سجل التدقيق القائم وحده: لكل مستخدم ولكل يوم تقويمي في
    المدة المختارة (آخر 7/14/30 يومًا): أول حدث «تسجيل دخول» ناجح له في
    ذلك اليوم (البرنامج يسجل الدخول أصلاً بهذا النوع القائم فلا يُنشأ أي
    نوع جديد)، وآخر حدث تدقيق باسمه في اليوم نفسه (آخر نشاط)، والدقائق
    المتأخرة عن بداية الدوام shop_hours_start من settings بعد مهلة سماح
    ثابتة 15 دقيقة لا تُحسب تأخيرًا — يرجع None بلا صلاحية أو error عند
    الخلل، وrows فارغة تعني: بيانات الانضباط تُسجل من تاريخ تفعيل المرحلة"""
    if not user_has_permission(CURRENT_USER["name"], "discipline_report"):
        return None
    out = {"rows": [], "has_login_data": False,
           "shop_start": get_alert_setting("shop_hours_start"), "error": False}
    try:
        n = max(1, min(int(n_days), 60))
        lo = date.fromordinal(date.today().toordinal() - (n - 1)).isoformat()
        sh = _parse_hhmm(out["shop_start"]) or (9, 0)
        start_min = sh[0] * 60 + sh[1]
        grace = 15                   # مهلة السماح الثابتة — لا تُحسب تأخيرًا
        with connect() as conn:
            arows = conn.execute("SELECT id, ts, username, action FROM audit_log "
                                 "WHERE ts >= ? ORDER BY id", (lo,)).fetchall()
        first_login, last_seen = {}, {}
        for r in arows:
            ts = str(r["ts"] or "")
            day = ts[:10]
            if day < lo:
                continue
            who = r["username"] or "—"
            key = (who, day)
            if r["action"] == "تسجيل دخول" and key not in first_login:
                first_login[key] = ts
            last_seen[key] = ts      # ترتيب id تصاعدي — آخر حدث يبقى
        keys = sorted(last_seen.keys(), key=lambda k: k[0])        # بالمستخدم
        keys = sorted(keys, key=lambda k: k[1], reverse=True)      # باليوم الأحدث أولاً
        for (who, day) in keys:
            fl = first_login.get((who, day))
            late = None
            if fl is not None:
                out["has_login_data"] = True
                dt = parse_dt_str(fl)
                if dt is not None:
                    late = max(0, dt.hour * 60 + dt.minute - (start_min + grace))
            out["rows"].append({"user": who, "day": day,
                                "first_login": (fl[11:] if fl else None),
                                "last_seen": (str(last_seen[(who, day)])[11:] or None),
                                "late": late})
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        out["error"] = True
    return out

def _reports_last_backup_info():
    """★ إضافة (المرحلة الثالثة): أحدث ملف نسخة احتياطية داخل مجلد backups
    بكل مجلداته الفرعية بوقته الفعلي من نظام الملفات — يرجع None إن لم
    توجد أي نسخة، أو (الاسم، الحجم بالبايت، وقت الإنشاء datetime)"""
    best = None
    try:
        for root, _dirs, files in os.walk(BACKUP_ROOT):
            for fn in files:
                if not fn.endswith((".db", ".zip")):
                    continue
                p = os.path.join(root, fn)
                try:
                    mt = os.path.getmtime(p)
                except Exception:
                    continue
                if best is None or mt > best[3]:
                    best = (fn, os.path.getsize(p), datetime.fromtimestamp(mt), mt)
    except Exception:
        return None
    return best

def collect_system_health():
    """★ إضافة (المرحلة الثالثة — التبويب 4): بيانات فحص صحة النظام —
    قراءة فقط: حجم ملف القاعدة ونتيجة PRAGMA quick_check وعدد سجلات
    الجداول الرئيسية (المبيعات والمرتجعات من operations والمستخدمين
    والجلسات النشطة) وحجم error_log.txt وتاريخ آخر خطأ فيه وآخر نسخة
    احتياطية والمساحة الحرة على القرص عبر shutil.disk_usage لمجلد
    البرنامج وإصدار بايثون الحالي — أي بند يفشل يظهر «—» وحده ولا يوقف
    بقية البطاقات أبدًا. يرجع None بلا صلاحية أو error عند الخلل"""
    if not user_has_permission(CURRENT_USER["name"], "system_health_view"):
        return None
    out = {"db_size": None, "quick_check": None, "sales_count": None,
           "returns_count": None, "users_count": None, "sessions_count": None,
           "errlog_size": None, "errlog_last": None, "last_backup": None,
           "disk_free": None, "python_version": None, "error": False}
    try:
        try:
            out["db_size"] = os.path.getsize(DB)
        except Exception:
            pass
        try:
            with connect() as conn:
                out["quick_check"] = str(
                    conn.execute("PRAGMA quick_check").fetchone()[0])
                out["sales_count"] = conn.execute(
                    "SELECT COUNT(*) FROM operations WHERE type IN "
                    "('نقداً','شبكة')").fetchone()[0]
                out["returns_count"] = conn.execute(
                    "SELECT COUNT(*) FROM operations WHERE type='مرتجع'"
                ).fetchone()[0]
                out["users_count"] = conn.execute(
                    "SELECT COUNT(*) FROM users").fetchone()[0]
                if _reports_table_exists(conn, "active_sessions"):
                    out["sessions_count"] = conn.execute(
                        "SELECT COUNT(*) FROM active_sessions").fetchone()[0]
                else:
                    out["sessions_count"] = 0
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        try:
            out["errlog_size"] = os.path.getsize(ERRLOG)
            if out["errlog_size"]:
                with open(ERRLOG, "r", encoding="utf-8", errors="replace") as f:
                    txt = f.read()
                ms = re.findall(r"\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\]", txt)
                if ms:
                    out["errlog_last"] = ms[-1]
        except Exception:
            pass
        try:
            out["last_backup"] = _reports_last_backup_info()
        except Exception:
            pass
        try:
            out["disk_free"] = shutil.disk_usage(data_dir()).free
        except Exception:
            pass
        try:
            out["python_version"] = ".".join(str(x) for x in sys.version_info[:3])
        except Exception:
            pass
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        out["error"] = True
    return out

def collect_backup_monitor():
    """★ إضافة (المرحلة الثالثة — التبويب 5): بيانات مراقبة النسخ
    الاحتياطي — قراءة فقط من نظام الملفات لكل ملفات مجلد backups (اليومية
    والشهرية والفورية ونسخ الأمان) مرتبة من الأحدث بوقت الإنشاء الفعلي:
    الاسم والحجم والتاريخ، وحالة آخر نسخة (ok = أقل من 24 ساعة / late =
    أكثر من 24 ساعة / none = لا نسخ أبدًا). يرجع None بلا صلاحية أو error
    عند الخلل"""
    if not user_has_permission(CURRENT_USER["name"], "backup_monitor_view"):
        return None
    out = {"files": [], "status": "none", "last": None, "error": False}
    try:
        rows = []
        for root, _dirs, files in os.walk(BACKUP_ROOT):
            for fn in files:
                if not fn.endswith((".db", ".zip")):
                    continue
                p = os.path.join(root, fn)
                try:
                    st = os.stat(p)
                except Exception:
                    continue
                rows.append({"name": fn, "size": st.st_size,
                             "when": datetime.fromtimestamp(st.st_mtime)})
        rows.sort(key=lambda r: r["when"], reverse=True)
        out["files"] = rows
        if rows:
            age_h = (datetime.now() - rows[0]["when"]).total_seconds() / 3600.0
            out["status"] = ("ok" if age_h < 24.0 else "late")
            out["last"] = rows[0]
        else:
            out["status"] = "none"
    except Exception as e:
        log_error(e, sys.exc_info()[2])
        out["error"] = True
    return out

