    def _on_sidebar_wheel(self, e):
        """★ إضافة (المرحلة الثالثة — الاستثناء أ المصرح به): معالج عجلة
        الفأرة لتمرير حاوية القائمة الجانبية — مُسجَّل عبر bind_all بمرشّح:
        يتجاهل أي حدث وقع خارج حاوية القائمة (فلا يُمس أي تمرير آخر في أي
        نافذة من نوافذ البرنامج)، ويتجاهل الـCanvas نفسه لأن ربطه المباشر
        وصنفه القياسي يتمررونه (فلا يتكرر التمرير فوقه)، ويمرر أي عنصر آخر
        داخل الحاوية ولو أُنشئ بعد بناء الشريط — وأي خلل يُتجاهل بهدوء
        كعادة الكود القائم"""
        try:
            w = e.widget
            cvs = getattr(self, "sidebar_canvas", None)
            box = getattr(self, "sidebar_nav_box", None)
            if cvs is None or box is None or w is None or w is cvs:
                return None            # فوق الـCanvas نفسه: ربطه يتكفل به
            p = w
            while p is not None:
                if p is box:
                    cvs.yview_scroll(-1 * int(e.delta / 120), "units")
                    return "break"
                p = getattr(p, "master", None)
            return None                 # خارج الحاوية: لا يُلمس أي شيء
        except Exception:
            return None

    def refresh_sidebar_permissions(self):
        """★ تعديل (المرحلة الخامسة — الأكورديون): نفس الدالة القائمة بنفس
        اسمها ومواضع استدعائها الثلاثة كما هي (عند الإقلاع، ومن apply_role_ui
        بعد كل تبديل، ومن rebuild_ui_for_current_user) — تغيّر جسمها فقط:
        بدل العناوين الثابتة القديمة وإعادة الحزم داخل إطار الشريط العام،
        تُطبّق الآن مجموعات الأكورديون الخمس القابلة للطي: كل زر يظهر حسب
        شرطه القائم نفسه حرفيًا (NAV_PERMS + استثناء زر «التحديث» بتوفر
        إصدار أحدث فعليًا + وجود الزر الشرطي نفسه) ويُحزم داخل جسم مجموعته
        بترتيبه الحالي، والمجموعة التي كل أزرارها مخفية تختفي كلياً بإطارها
        ورأسها (لا يُنشأ رأسها أصلًا)، والمجموعة الأولى غير الفارغة تُفتح
        تلقائيًا ويُطوي الباقي — والأزرار نفسها ودوالها لم تُمس"""
        try:
            self._accordion_apply()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        # تحديث نص زر قائمة المستخدم بعد أي دخول/تبديل
        if getattr(self, "btn_user_menu", None) is not None:
            self.btn_user_menu.config(text=f"👤 {self.user_name} ({self.role})",
                                      fg=("#a78bfa" if self.role == ADMIN_ROLE else "#93c5fd"))

    def _accordion_body_for(self, key):
        """★ إضافة (المرحلة الخامسة — الأكورديون): إطار جسم المجموعة التي
        يتبعها الزر — يستخدمه rebuild_ui_for_current_user عند إنشاء زر
        شرطي (الصلاحيات الدقيقة/المركز/التقارير الإدارية/العملاء) فيوضعه
        داخل مجموعته بدل إطار الشريط العام؛ والاحتياط إن غاب الهيكل:
        إطار الشريط نفسه كما كان قبل الأكورديون"""
        for _gt, _gkeys in self.NAV_ACCORDION_GROUPS:
            if key in _gkeys:
                g = (getattr(self, "accordion_groups", None) or {}).get(_gt)
                if g is not None:
                    try:
                        if g["body"] is not None and g["body"].winfo_exists():
                            return g["body"]
                    except Exception:
                        pass
        return getattr(self, "sidebar_nav_box", None)

    def _accordion_make_header(self, gt):
        """★ إضافة (المرحلة الخامسة — الأكورديون): رأس المجموعة العريض
        بكامل عرض العمود — خلفية أغمق درجة من لون الشريط نفس عائلة ألوان
        البرنامج وخط عريض، والمؤشر النصي بجانب الاسم (◀ مطويًا / ▼ مفتوحًا
        ويحدّثه _accordion_toggle و_accordion_apply)، والضغط عليه يفتح
        مجموعته ويطوي المفتوحة قبلها"""
        try:
            g = self.accordion_groups.get(gt)
            if g is None or g.get("header") is not None:
                return
            body = g["body"]
            try:
                body.pack(fill="x")      # يُدار ترتيب الجسم بعد رأسه دائمًا
            except Exception:
                pass
            h = tk.Button(g["frame"], text=f"◀  {gt}", font=("Segoe UI", 12, "bold"),
                          bd=0, cursor="hand2", anchor="e", bg="#0f172a", fg="white",
                          activebackground=ACCENT, activeforeground="white",
                          padx=16, pady=10, highlightthickness=0,
                          command=lambda t=gt: self._accordion_toggle(t))
            h.pack(fill="x", before=body)
            g["header"] = h
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    def _accordion_toggle(self, gt):
        """★ إضافة (المرحلة الخامسة — الأكورديون): فتح/طي مجموعة — فتح أي
        مجموعة يطوي المفتوحة قبلها تلقائيًا (لا تُفتح أكثر من واحدة في
        نفس الوقت)، والضغط على رأس المفتوحة مجددًا يطويها — وكل خطوة
        محصنة فلا ينهار البرنامج عند أي خلل"""
        try:
            gmap = getattr(self, "accordion_groups", None) or {}
            g = gmap.get(gt)
            if g is None:
                return
            cur = getattr(self, "accordion_open_key", None)
            if cur == gt:            # الضغط على المفتوحة مجددًا: تُطوى
                try:
                    g["body"].pack_forget()
                except Exception:
                    pass
                h = g.get("header")
                if h is not None:
                    try:
                        h.config(text=f"◀  {gt}")
                    except Exception:
                        pass
                self.accordion_open_key = None
                return
            if cur is not None:      # طي المفتوحة قبلها أولًا
                g2 = gmap.get(cur)
                if g2 is not None:
                    try:
                        g2["body"].pack_forget()
                    except Exception:
                        pass
                    h2 = g2.get("header")
                    if h2 is not None:
                        try:
                            h2.config(text=f"◀  {cur}")
                        except Exception:
                            pass
            try:
                g["body"].pack(fill="x")     # يُحزم بعد رأسه في ترتيب الإطار
            except Exception:
                pass
            h = g.get("header")
            if h is not None:
                try:
                    h.config(text=f"▼  {gt}")
                except Exception:
                    pass
            self.accordion_open_key = gt
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    def _accordion_apply(self):
        """★ إضافة (المرحلة الخامسة — الأكورديون): تطبيق المجموعات الخمس على
        أزرار الشريط حسب صلاحيات المستخدم الحالي — كل مجموعة داخل
        try/except مستقل (فشل مجموعة يُكتب في error_log.txt وتُبنى بقية
        المجموعات ولا ينهار البرنامج عند الإقلاع ولا عند التبديل أبدًا)،
        وشرط كل زر هو شرطه القائم نفسه حرفيًا: صلاحية NAV_PERMS كما هي
        (وزر «التحديث» لا يظهر إلا بتوفر إصدار أحدث فعليًا كما هو القرار
        القائم)، والزر الشرطي (الصلاحيات الدقيقة/المركز/التقارير الإدارية/
        العملاء) شرطه وجوده نفسه لأنه لا يُنشأ إلا لمن استحقه ويُهدم عند
        فقدانه من rebuild_ui_for_current_user القائمة كما هي"""
        groups = getattr(self, "accordion_order", None) or []
        gmap = getattr(self, "accordion_groups", None) or {}
        if not groups:
            return
        # (1) أزرار كل مجموعة: الظاهر يُحزم داخل جسمها بترتيبه الحالي
        #     والمخفي يُفك حزمه — والمفقود من nav_buttons زر شرطي غير
        #     منشأ لهذه الجلسة فشرطه نفسه يتخطاه
        visible_titles = []
        for gt in groups:
            try:
                g = gmap.get(gt)
                if g is None:
                    continue
                count = 0
                for key in g["keys"]:
                    b = self.nav_buttons.get(key)
                    if b is None:
                        continue
                    try:
                        if not b.winfo_exists():
                            continue
                    except Exception:
                        continue
                    perm = self.NAV_PERMS.get(key)
                    ok = perm is None or self.has_permission(perm)
                    if key == "update":
                        ok = ok and bool(getattr(self, "update_available_version", None))
                    if ok:
                        b.pack_forget()
                        b.pack(fill="x", padx=10, pady=3)
                        count += 1
                    else:
                        b.pack_forget()
                g["_visible"] = count > 0
                if count > 0:
                    visible_titles.append(gt)
            except Exception as e:
                log_error(e, sys.exc_info()[2])
        # (2) الرؤوس والإطارات بترتيب المجموعات: الفارغة تختفي كلياً
        #     (يُهدم رأسها ويُفك حزم إطارها — لا رأس أصلًا لها)، وغير
        #     الفارغة يُنشأ رأسها إن غاب ويعود إطارها لموضعه بين جاراته
        for i, gt in enumerate(groups):
            try:
                g = gmap.get(gt)
                if g is None:
                    continue
                fr = g["frame"]
                if g.get("_visible"):
                    if g.get("header") is None:
                        self._accordion_make_header(gt)
                    if fr.winfo_manager() != "pack":
                        anchor = None
                        for gt2 in groups[i + 1:]:
                            g2 = gmap.get(gt2)
                            if g2 is not None and g2["frame"].winfo_manager() == "pack":
                                anchor = g2["frame"]
                                break
                        if anchor is not None:
                            fr.pack(fill="x", pady=(0, 10), before=anchor)
                        else:
                            fr.pack(fill="x", pady=(0, 10))
                else:
                    try:
                        if g.get("header") is not None:
                            g["header"].destroy()
                    except Exception:
                        pass
                    g["header"] = None
                    try:
                        if fr.winfo_manager() == "pack":
                            fr.pack_forget()
                    except Exception:
                        pass
            except Exception as e:
                log_error(e, sys.exc_info()[2])
        # (3) حالة الفتح الافتدائية: المجموعة الأولى غير الفارغة تُفتح
        #     تلقائيًا والباقي مطوي (وإن لم توجد أي مجموعة ظاهرة فكله مطوي)
        open_title = visible_titles[0] if visible_titles else None
        for gt in groups:
            try:
                g = gmap.get(gt)
                if g is None:
                    continue
                is_open = (gt == open_title)
                try:
                    if is_open:
                        g["body"].pack(fill="x")
                    else:
                        g["body"].pack_forget()
                except Exception:
                    pass
                h = g.get("header")
                if h is not None:
                    try:
                        h.config(text=(("▼  " if is_open else "◀  ") + gt))
                    except Exception:
                        pass
            except Exception as e:
                log_error(e, sys.exc_info()[2])
        self.accordion_open_key = open_title

    def show_user_menu(self):
        """★ إضافة (إصدار 8 — الميزة 7): قائمة المستخدم المنسدلة — تجمع إعداداته
        في مكان واحد، وتنفذ نفس الدوال الأربع الموجودة تماماً دون أي تغيير فيها"""
        m = tk.Menu(self, tearoff=0, bg=CARD, fg=DARK, font=("Segoe UI", 10),
                    activebackground=ACCENT, activeforeground="white", bd=0, relief="flat")
        m.add_command(label="🔑 تغيير كلمة المرور", command=self.change_password_dialog)
        m.add_command(label="💾 نسخة احتياطية الآن", command=self.backup_now)
        m.add_command(label="🔄 تبديل المستخدم", command=self.switch_user)
        # ★ إضافة (الإصدار 14 — البند 10): قفل الجلسة — إخفاء البرنامج كاملاً
        # خلف نافذة كلمة مرور الحساب الحالي (الاسم معروض ثابتاً)، والعودة
        # تُعيد كل شيء كما كان بالضبط (الصفحة والسلة والنوافذ)
        m.add_command(label="🔒 قفل الجلسة", command=self.session_lock)
        m.add_separator()
        # ★ إضافة (إصلاح 2): مدخل دائم واضح لنافذة «عن البرنامج» لكل
        # المستخدمين من قائمة المستخدم — قراءة فقط بلا أي اتصال شبكي
        m.add_command(label="ℹ️ عن البرنامج", command=self.about_dialog)
        # ★ إضافة (إصلاح 3 — البند ب): «فحص التحديثات الآن» دائم الظهور
        # للمدير — فحص فوري برسالة نتيجة عربية دائماً (وللشريط الأصفر زره
        # الخاص بجانب «تحديث الآن")
        # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الفحص والأرشيف للأدمن أيضاً
        if manager_level(self.role):
            m.add_command(label="🔄 فحص التحديثات الآن",
                          command=lambda: self.update_check_manual(None))
            # ★ إضافة (أرشيف الإصدارات): عرض أرشيف الإصدارات — للمدير فقط
            m.add_command(label="🗃️ أرشيف الإصدارات",
                          command=self.archive_versions_dialog)
        m.add_separator()
        m.add_command(label="⏻ خروج (إغلاق البرنامج)", command=self.exit_app)
        try:
            x = self.btn_user_menu.winfo_rootx()
            y = self.btn_user_menu.winfo_rooty() + self.btn_user_menu.winfo_height()
            m.tk_popup(x, y)
        finally:
            m.grab_release()

    # ---------- ★ الشريط العلوي ----------
    def build_stats_bar(self):
        bar = tk.Frame(self.container, bg=BG)
        bar.pack(fill="x", padx=25, pady=(15, 5))
        # ★ إضافة (إصدار 10): حفظ مرجع الشريط الإحصائي كي يوضع شريط إشعار
        # التحديث الأصفر فوقه مباشرة (before=) دون أي تغيير آخر في البناء
        self.stats_bar_frame = bar
        self.stats_widgets = {}
        # ★ إضافة (الإصدار 14 — الجزء الأول): سطر يوم العمل أعلى البطاقات —
        # «📅 يوم العمل: [التاريخ] [🌙 بعد منتصف الليل]» والهلال يظهر فقط
        # عندما يكون تاريخ الجهاز أحدث من يوم العمل المفتوح
        self.lbl_bday = tk.Label(bar, text="", bg=BG, fg=GRAY,
                                 font=("Segoe UI", 10, "bold"), anchor="e")
        self.lbl_bday.pack(fill="x", side="top", pady=(0, 3))
        # ★ إضافة (الإصدار 17 — التعديل 4): تلميح سطر يوم العمل — الحد الفجري
        add_tip(self.lbl_bday, "اليوم التجاري ينتهي 05:00 فجراً ويبدأ الجديد بعده — "
                               "العمليات قبل 05:00 تُسجَّل على يوم الأمس التجاري")
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): الشريط العلوي 5 بطاقات —
        # عدد العمليات (رمادي) / نقداً (أخضر) / شبكة (أزرق) / المرتجعات (أحمر) /
        # الإجمالي (أزرق) — لفصل مبيعات الدرج النقدي عن مبيعات جهاز الشبكة
        for title, color in [("عدد العمليات", "#334155"), ("نقداً", GREEN),
                             ("شبكة", ACCENT), ("المرتجعات", RED),
                             ("الإجمالي", "#1d4ed8")]:
            fr, val = self.mk_card(bar, title, color)
            fr.pack(side="right", expand=True, fill="x", padx=5)
            self.stats_widgets[title] = val
        self.refresh_stats()

    def refresh_stats(self):
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): day_totals ترجع الآن
        # (عدد العمليات، نقداً، شبكة، المرتجعات، الإجمالي)
        # ★ تعديل مصرح به (الإصدار 14 — الجزء الأول): البطاقات تعرض إحصائيات
        # يوم العمل المفتوح (وبلا يوم مفتوح = تاريخ اليوم كما كان دائماً)
        n, cash, netw, rets, net = day_totals(current_business_day())
        self.stats_widgets["عدد العمليات"].config(text=str(n))
        self.stats_widgets["نقداً"].config(text=money(cash))
        self.stats_widgets["شبكة"].config(text=money(netw))
        self.stats_widgets["المرتجعات"].config(text=money(rets))
        self.stats_widgets["الإجمالي"].config(text=money(net),
                                               fg=(GREEN if net >= 0 else RED))
        # ★ إضافة (الإصدار 14 — الجزء الأول): تحديث سطر يوم العمل وأزراره
        # مع كل تحديث للشريط العلوي (نقطة تجميع واحدة تُستدعى مع كل تنقل)
        self.refresh_business_day_ui()
        # ★ إضافة (موعد التحصيل): مزامنة شريط تنبيه التحصيلات مع كل تحديث
        # للشريط العلوي — نقطة تجميع تُستدعى مع كل تنقل وبعد كل حفظ، سطر
        # محمي واحد لا يغيّر أي سلوك قائم (الكاش يمنع أي إعادة بناء بلازم)
        try:
            self._refresh_collections_alert_bar()
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    def show_page(self, key):
        for k, b in self.nav_buttons.items():
            b.config(bg=(ACCENT if k == key else SIDEBAR), fg=("white" if k == key else "#cbd5e1"))
        for pg in self.pages.values():
            pg.pack_forget()
        self.pages[key].pack(fill="both", expand=True)
        self.refresh_stats()   # ★ تحديث الشريط عند كل تنقل
        if key == "new":
            self.refresh_items(); self.update_closed_banner()
        elif key == "today":
            self.refresh_today()
        elif key == "archive":
            self.refresh_archive()

    # ---------- صفحة عملية جديدة ----------
    def build_new_page(self, p):
        self.page_head(p, "➕ عملية جديدة", f"تاريخ اليوم: {today_str()}  ({day_name(today_str())})")
        self.banner_closed = tk.Label(p, text="", bg=BG, fg=RED, font=FB, wraplength=900)
        self.banner_closed.pack(fill="x", padx=25)

        form = tk.Frame(p, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        form.pack(fill="x", padx=25, pady=10)

        def field_row(label):
            fr = tk.Frame(form, bg=CARD); fr.pack(fill="x", padx=22, pady=6)
            tk.Label(fr, text=label, bg=CARD, fg=DARK, font=FB, width=11, anchor="e").pack(side="right")
            inner = tk.Frame(fr, bg=CARD)
            inner.pack(side="right", padx=(0, 10))
            return inner

        in1 = field_row("اسم الصنف:")
        self.cb_item = ttk.Combobox(in1, font=F, width=30)
        self.cb_item.pack(side="right", ipady=4)

        in2 = field_row("الكمية:")
        self.e_qty = tk.Entry(in2, font=F, justify="center", relief="solid", bd=1, width=30)
        self.e_qty.pack(side="right", ipady=4)
        # ★ إضافة (الإصدار 14 — البند 13): فلترة إدخال الكمية/السعر — أرقام
        # عربية/إنجليزية وفاصلة الكسر فقط، أي حرف آخر لا يُكتب من الأساس
        digits_only_filter(self.e_qty)

        in3 = field_row("السعر:")
        self.e_price = tk.Entry(in3, font=F, justify="center", relief="solid", bd=1, width=30)
        self.e_price.pack(side="right", ipady=4)
        digits_only_filter(self.e_price)   # ★ إضافة (الإصدار 14 — البند 13)

        # ★★★ إضافة (المرحلة الرابعة — سقف الخصم): صف «خصم %» الاختياري —
        # 0 أو فراغ = بلا خصم (نفس السلوك القديم تماماً)، يسري على مبيعات
        # نقداً/شبكة فقط (المرتجع بسعر أصله المقفل دائماً)، وسقف المستخدم
        # «أقصى نسبة خصم %» المحفوظ من المرحلة الأولى يُفحص عند الحفظ
        # بطبقتيه، والإجمالي المعروض يتحدث معه لحظياً
        in_d4 = field_row("خصم % (اختياري):")
        self.e_disc = tk.Entry(in_d4, font=F, justify="center", relief="solid", bd=1, width=30)
        self.e_disc.pack(side="right", ipady=4)
        self.e_disc.insert(0, "0")
        digits_only_filter(self.e_disc)
        add_tip(self.e_disc, "نسبة خصم 0-100 على العملية — 0 = بلا خصم. تُفحص عند "
                             "الحفظ ضد سقف الخصم المسموح لك")

        # ★ إضافة (ميزة 5): صف اسم العميل الاختياري — يُخزن مع العملية
        in_c = field_row("اسم العميل:")
        self.e_customer = tk.Entry(in_c, font=F, justify="center", relief="solid", bd=1, width=30)
        self.e_customer.pack(side="right", ipady=4)
        tk.Label(in_c, text="(اختياري)", bg=CARD, fg=GRAY,
                 font=("Segoe UI", 9)).pack(side="right", padx=(6, 0))

        trow = tk.Frame(form, bg=CARD); trow.pack(fill="x", padx=22, pady=8)
        tk.Label(trow, text="النوع:", bg=CARD, fg=DARK, font=FB).pack(side="right")
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): ثلاثة أنواع — نقداً (أخضر:
        # الدرج النقدي) وشبكة (أزرق: جهاز الشبكة) بقيمة موجبة عادية،
        # ومرتجع (أحمر) بقيمة سالبة كما هو الآن
        self.type_var = tk.StringVar(value="نقداً")
        for txt, col in [("نقداً", GREEN), ("شبكة", ACCENT), ("مرتجع", RED)]:
            tk.Radiobutton(trow, text=txt, variable=self.type_var, value=txt, font=FB,
                           fg=col, bg=CARD, selectcolor="#dbeafe", activebackground=CARD,
                           activeforeground=col, indicatoron=0, width=10, bd=1,
                           relief="solid", cursor="hand2", command=self.update_calc).pack(side="right", padx=10)

        # ★★★ إضافة (الإصدار 16 — القسم 1-1): ربط المرتجع بعملية البيع الأصلية —
        # صف «العملية المُرجَعة» يظهر عند اختيار «مرتجع» فقط: قائمة إلزامية
        # بعمليات البيع الصالحة (نفس الصنف، نقداً/شبكة، الأحدث أولاً، والكمية
        # المعروضة = المتبقي الصالح للإرجاع بعد خصم المرتجعات السابقة)،
        # والسعر يُعبأ بسعر الأصل ويُقفل للتعديل — ممنوع مرتجع بلا أصل
        self._orig_map = {}
        self._trow_ref = trow
        self.fr_orig = tk.Frame(form, bg=CARD)
        orow = tk.Frame(self.fr_orig, bg=CARD); orow.pack(fill="x", pady=4)
        tk.Label(orow, text="العملية المُرجَعة:", bg=CARD, fg=RED, font=FB,
                 width=17, anchor="e").pack(side="right")
        inner_o = tk.Frame(orow, bg=CARD)
        inner_o.pack(side="right", padx=(0, 10))
        self.cb_orig = ttk.Combobox(inner_o, font=F, width=42, state="readonly")
        self.cb_orig.pack(side="right", ipady=4)
        self.lbl_orig_info = tk.Label(orow, text="", bg=CARD, fg=GRAY,
                                      font=("Segoe UI", 9, "bold"))
        self.lbl_orig_info.pack(side="right", padx=8)
        add_tip(self.cb_orig,
                "اختر عملية البيع الأصلية لهذا المرتجع — الكمية المعروضة هي المتبقي الصالح "
                "للإرجاع بعد خصم المرتجعات السابقة، والسعر يُعبأ بسعر الأصل تلقائياً ويُقفل")
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع): صف السبب الإلزامي
        # والملاحظة الاختيارية داخل صفوف المرتجع (يظهران ويختفيان مع صف
        # «العملية المُرجَعة» عند اختيار «مرتجع» فقط) — من دون سبب من
        # القائمة الثابتة لا يتم حفظ أي مرتجع
        rrow4 = tk.Frame(self.fr_orig, bg=CARD); rrow4.pack(fill="x", pady=4)
        tk.Label(rrow4, text="سبب المرتجع:", bg=CARD, fg=RED, font=FB,
                 width=17, anchor="e").pack(side="right")
        inner_r4 = tk.Frame(rrow4, bg=CARD)
        inner_r4.pack(side="right", padx=(0, 10))
        self.cb_ret_reason = ttk.Combobox(inner_r4, font=F, width=30, state="readonly",
                                          values=list(RETURN_REASONS))
        self.cb_ret_reason.pack(side="right", ipady=4)
        add_tip(self.cb_ret_reason, "إلزامي — لا يتم حفظ المرتجع دون اختيار سبب من القائمة")
        nrow4 = tk.Frame(self.fr_orig, bg=CARD); nrow4.pack(fill="x", pady=4)
        tk.Label(nrow4, text="ملاحظة (اختياري):", bg=CARD, fg=GRAY, font=FB,
                 width=17, anchor="e").pack(side="right")
        inner_n4 = tk.Frame(nrow4, bg=CARD)
        inner_n4.pack(side="right", padx=(0, 10))
        self.e_ret_note = tk.Entry(inner_n4, font=F, justify="center",
                                   relief="solid", bd=1, width=32)
        self.e_ret_note.pack(side="right", ipady=4)
        self.cb_orig.bind("<<ComboboxSelected>>", lambda e: self._orig_selected())
        self.type_var.trace_add("write", lambda *_: self._sync_return_ui())
        self.cb_item.bind("<KeyRelease>", lambda e: self._refresh_orig_list())
        self.cb_item.bind("<<ComboboxSelected>>", lambda e: self._refresh_orig_list())
        self._sync_return_ui()

        crow = tk.Frame(form, bg="#f8fafc"); crow.pack(fill="x", padx=22, pady=(4, 10))
        fr = tk.Frame(crow, bg="#f8fafc"); fr.pack(expand=True, fill="x")
        tk.Label(fr, text="المبيع (الكمية × السعر)", bg="#f8fafc", fg=GRAY, font=("Segoe UI", 10)).pack()
        self.lbl_total_v = tk.Label(fr, text="—", bg="#f8fafc", fg=DARK, font=FV)
        self.lbl_total_v.pack()

        srow = tk.Frame(form, bg=CARD); srow.pack(fill="x", padx=22, pady=(2, 16))
        self.mk_btn(srow, "💾  حفظ العملية", self.save_op).pack(side="right")
        self.lbl_status = tk.Label(srow, text="", bg=CARD, font=FB)
        self.lbl_status.pack(side="right", padx=14)
        # ★★★ إضافة (المرحلة الرابعة — البيع بالدين): زر «بيع بالدين» بجانب
        # زر إتمام البيع — لا يُبنى أصلاً إلا لمن يملك sell_on_credit
        # (والأدمن دائماً بدوره عبر المحرك القائم)، وإخفاؤه وإظهاره مع تبديل
        # المستخدم يديره rebuild_ui_for_current_user بنفس منطق الأزرار
        # الشرطية (إخفاء كلي لا تعطيل)
        self._srow_credit_host = srow
        if user_has_permission(self.user_name, "sell_on_credit"):
            b_credit4 = self.mk_btn(srow, "🧾 بيع بالدين",
                                    lambda: self._credit_sale_dialog("op"), ORANGE)
            b_credit4.pack(side="right", padx=6, before=self.lbl_status)
            self.b_credit_op = b_credit4
            add_tip(b_credit4, "بيع بالدين — نافذة اختيار العميل والدفعة الأولى ثم "
                               "الحفظ بنفس دالة حفظ العملية القائمة وتسجيل الباقي ديناً")
        else:
            self.b_credit_op = None

        for e in (self.e_qty, self.e_price):
            e.bind("<KeyRelease>", self.update_calc)
            e.bind("<Return>", lambda e: self.save_op())
        self.cb_item.bind("<Return>", lambda e: self.save_op())
        # ★★★ إضافة (المرحلة الرابعة): الخصم يحدّث الإجمالي المعروض لحظياً
        self.e_disc.bind("<KeyRelease>", self.update_calc)

    def update_calc(self, *_):
        q, pr = to_num(self.e_qty.get()), to_num(self.e_price.get())
        if q is None or pr is None:
            self.lbl_total_v.config(text="—", fg=DARK); return
        total = q * pr
        if self.type_var.get() == "مرتجع":
            total = -total
        # ★★★ إضافة (المرحلة الرابعة — سقف الخصم): العرض بعد الخصم لمبيعات
        # نقداً/شبكة فقط (المرتجع بسعر أصله بلا خصم) + سقف خصم المستخدم
        # الحالي توضيحياً بجانب الإجمالي
        try:
            if self.type_var.get() != "مرتجع" and hasattr(self, "e_disc"):
                dv4 = to_num(self.e_disc.get())
                if dv4 is not None and dv4 > 0:
                    total = q * pr * (1.0 - min(dv4, 100.0) / 100.0)
        except Exception:
            pass
        try:
            _cap4 = user_discount_cap(CURRENT_USER["name"])
            _cap_txt4 = "" if _cap4 is None else f"   (سقف خصمك: {_cap4:g}%)"
        except Exception:
            _cap_txt4 = ""
        self.lbl_total_v.config(text=money(total) + _cap_txt4,
                                fg=(ACCENT if total >= 0 else RED))

    # ★★★ إضافات (الإصدار 16 — القسم 1-1): دوال ربط المرتجع بالأصل ↩ ★★★
    def _sync_return_ui(self):
        """إظهار/إخفاء صف «العملية المُرجَعة» حسب النوع (يستدعيه تتبع type_var
        تلقائياً مع كل تغيير) — عند غير المرتجع يُفتح قفل السعر ويُمسح الاختيار"""
        try:
            if self.type_var.get() == "مرتجع":
                self.fr_orig.pack(fill="x", padx=22, pady=6, after=self._trow_ref)
                self._refresh_orig_list()
            else:
                self.fr_orig.pack_forget()
                self.cb_orig.set("")
                self._orig_map = {}
                self.lbl_orig_info.config(text="", fg=GRAY)
                if str(self.e_price.cget("state")) == "disabled":
                    self.e_price.config(state="normal")
                    self.e_price.delete(0, "end")
        except Exception:
            pass

    def _refresh_orig_list(self):
        """تحديث قائمة عمليات البيع الصالحة للمرتجع حسب الصنف المكتوب — أي
        تغيير لاسم الصنف يمسح الاختيار ويفتح قفل السعر (الأصل قد يختلف)"""
        try:
            self.cb_orig.set("")
            self._orig_map = {}
            self.lbl_orig_info.config(text="", fg=GRAY)
            if str(self.e_price.cget("state")) == "disabled":
                self.e_price.config(state="normal")
                self.e_price.delete(0, "end")
            if self.type_var.get() != "مرتجع":
                self.cb_orig["values"] = []
                return
            item = self.cb_item.get().strip()
            if not item:
                self.cb_orig["values"] = []
                self.lbl_orig_info.config(text="اكتب اسم الصنف لعرض عمليات بيعه", fg=ORANGE)
                return
            lst = return_eligible_originals(item)
            labels = []
            for o in lst:
                lbl = (f'[{o["id"]}] — [{o["date"]}] — كمية [{o["qty"]:g}] — '
                       f'بـ [{o["price"]:g}] — [{o["type"]}]')
                labels.append(lbl)
                self._orig_map[lbl] = o
            self.cb_orig["values"] = labels
            if not labels:
                self.lbl_orig_info.config(text="لا عمليات بيع صالحة للمرتجع لهذا الصنف", fg=RED)
        except Exception:
            pass

    def _orig_selected(self):
        """تعبئة السعر بسعر الأصل وقفله + عرض المتاح للإرجاع — مرتجع بسعر
        مختلف ممنوع: السعر يعود تلقائياً بسعر العملية الأصلية"""
        try:
            sel = self._orig_map.get(self.cb_orig.get())
            if not sel:
                return
            self.e_price.config(state="normal")
            self.e_price.delete(0, "end")
            self.e_price.insert(0, f'{sel["price"]:g}')
            self.e_price.config(state="disabled", disabledforeground=DARK)
            self.lbl_orig_info.config(text=f'المتاح للإرجاع: {sel["qty"]:g}', fg="#0d9488")
            self.update_calc()
        except Exception:
            pass

    def _return_selected_original(self):
        """العملية الأصلية المختارة حالياً (dict) أو None إن لم يُختر أصل"""
        return self._orig_map.get(self.cb_orig.get())

    def save_op(self):
        # ★ إضافة (إصدار 8 — الميزة 5): صلاحية «إضافة عمليات وفواتير» — الفحص
        # الدقيق الجديد (المدير يملك كل الصلاحيات دائماً ولا يلاحظ الفرق)
        if not self.has_permission("add_ops"):
            messagebox.showwarning("صلاحية", "ليست لديك صلاحية «إضافة عمليات وفواتير»")
            return
        # ★★★ إضافة (المرحلة الرابعة — البيع بالدين): التقاط سياق البيع
        # بالدين إن وجد (نافذة الدين تضبطه ثم تستدعي هذه الدالة القائمة
        # نفسها) — يُلتقط مرة واحدة في البداية وتُصفَّر الحالة فوراً فلا
        # يبقى لها أثر إن أُجهض الحفظ من أي نقطة تالية (لا دين بلا حفظ ناجح)
        _credit4 = self._pending_credit
        self._pending_credit = None
        # ★★★ إضافة (الإصدار 21 — المطلوب 1-3/ج — الاستثناء ب): نقطة التفتيش
        # قبل حفظ أي عملية بيع أو مرتجع مباشرة — يستحيل بعدها تسجيل حركة على
        # يوم تجاري قديم: إن كان اليوم المخزن أقدم من اليوم التجاري الصحيح
        # يُغلق تلقائيًا ويُفتح اليوم الجديد هنا قبل الحفظ (نفس الدالة المركزية
        # الوحيدة، وبلا أي سؤال يعطل البيع الجاري)
        try:
            self.ensure_business_day_current()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        # ★ تعديل مصرح به (الإصدار 14 — الجزء الأول): الحفظ صار على يوم العمل
        # المفتوح لا تاريخ الجهاز (وبعد منتصف الليل يستمر على يوم الأمس)،
        # وبلا يوم مفتوح الحفظ ممنوع برسالة واضحة حتى يُبدأ يوم جديد
        d = business_day_open()
        if not d:
            messagebox.showwarning("لا يوم عمل مفتوح",
                "لا يمكن حفظ العمليات — لا يوم عمل مفتوح.\n"
                "اضغط «▶️ بدء يوم جديد» في شاشة عمليات يوم العمل.")
            return
        if is_closed(d):
            messagebox.showwarning("اليوم مغلق",
                "تم إغلاق اليوم وحفظ تقريره.\nلا يمكن إضافة عمليات على يوم مغلق.\n"
                "➡ يمكنك إعادة فتح اليوم من شاشة الأرشيف.")
            return
        item = self.cb_item.get().strip()
        if not item:
            messagebox.showwarning("تنبيه", "اكتب اسم الصنف أولاً"); return
        q  = to_num(self.e_qty.get())
        pr = to_num(self.e_price.get())
        if q is None or q <= 0:
            messagebox.showwarning("تنبيه",
                f"الكمية غير صحيحة: «{self.e_qty.get()}»\nأدخل رقماً أكبر من صفر"); return
        if pr is None or pr < 0:
            messagebox.showwarning("تنبيه",
                f"السعر غير صحيح: «{self.e_price.get()}»\nأدخل رقماً صحيحاً"); return
        t = self.type_var.get()
        # ★ إضافة (الإصدار 16 — القسم 1-1): المرتجع يُربط بعملية بيع أصلية —
        # لا حفظ بلا أصل، ولا كمية فوق المتبقي، والسعر بسعر الأصل دائماً
        orig_id = None
        if t == "مرتجع":
            orig = self._return_selected_original()
            if orig is None:
                messagebox.showwarning("مرتجع بلا أصل",
                    "اختر «العملية المُرجَعة» من القائمة أولاً —\n"
                    "ممنوع تسجيل مرتجع بلا عملية بيع أصلية.")
                return
            remaining = return_remaining_of(orig["id"])
            if q > remaining + RET_EPS:
                messagebox.showwarning("كمية المرتجع أكبر من المتاح",
                    f"الكمية المتاحة للإرجاع من العملية رقم {orig['id']}: {remaining:g}\n"
                    "(كمية الأصل ناقصاً ما رُجّع منه سابقاً)")
                return
            pr = orig["price"]          # السعر يعود تلقائياً بسعر الأصل
            orig_id = orig["id"]
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع الإلزامي): لا يتم أي
        # مرتجع دون اختيار سبب من القائمة الثابتة (والملاحظة اختيارية) —
        # يُخزن السبب بنصه العربي في عمود return_reason والملاحظة في
        # return_note، والمرتجعات القديمة بلا سبب تبقى كما هي تماماً
        _reason4 = ""
        _note4 = ""
        if t == "مرتجع":
            _reason4 = (self.cb_ret_reason.get().strip()
                        if hasattr(self, "cb_ret_reason") else "")
            if not _reason4:
                messagebox.showwarning("سبب المرتجع إلزامي",
                    "اختر سبب المرتجع من القائمة أولاً —\n"
                    "لا تُسجَّل عملية مرتجع دون سبب.")
                return
            _note4 = (self.e_ret_note.get().strip()
                      if hasattr(self, "e_ret_note") else "")
        # ★★★ إضافة (المرحلة الرابعة — سقف الخصم): قراءة نسبة الخصم — 0 أو
        # فراغ = بلا خصم (نفس السلوك القديم)، تسري على نقداً/شبكة فقط
        # (المرتجع بسعر أصله المقفل)، ثم الطبقة الأولى: النسبة المدخلة ضد
        # السقف المحفوظ للمستخدم (0 = ممنوع من الخصم كلياً، والأدمن بلا سقف)
        _disc4 = 0.0
        if t != "مرتجع" and hasattr(self, "e_disc"):
            dv4 = to_num(self.e_disc.get())
            if dv4 is None or dv4 < 0 or dv4 > 100:
                messagebox.showwarning("خصم غير صحيح",
                    f"نسبة الخصم غير صحيحة: «{self.e_disc.get()}»\n"
                    "أدخل رقماً بين 0 و100")
                return
            _disc4 = dv4
        if _disc4 > 0:
            cap4 = user_discount_cap(CURRENT_USER["name"])
            if cap4 is not None and _disc4 > cap4 + 1e-9:
                messagebox.showwarning("سقف الخصم",
                    f"سقف الخصم المسموح لك {cap4:g}% فقط\n"
                    f"خفّض نسبة الخصم ({_disc4:g}%) ثم أعد الحفظ")
                return
        total = q * pr
        if t == "مرتجع":
            total = -total   # المرتجع بقيمة سالبة
        # ★★★ إضافة (المرحلة الرابعة — سقف الخصم): تطبيق الخصم على إجمالي
        # البيع + الطبقة الثانية: إعادة حساب النسبة الفعلية (مبلغ الخصم ÷
        # الإجمالي قبل الخصم × 100) ورفض الحفظ إن تجاوزت السقف
        if _disc4 > 0 and t != "مرتجع":
            _base4 = q * pr
            total = _base4 * (1.0 - _disc4 / 100.0)
            _amt4 = _base4 - total
            _eff4 = (_amt4 / _base4 * 100.0) if _base4 > 0 else 0.0
            cap4 = user_discount_cap(CURRENT_USER["name"])
            if cap4 is not None and _eff4 > cap4 + 1e-9:
                messagebox.showwarning("سقف الخصم",
                    f"سقف الخصم المسموح لك {cap4:g}% فقط\n"
                    f"النسبة الفعلية للخصم {_eff4:g}% — عدّلها ثم أعد الحفظ")
                return
        cust = self.e_customer.get().strip()   # ★ إضافة (ميزة 5): العميل الاختياري
        # ★★★ إضافة (المرحلة الرابعة — العمليات الكبيرة): الطبقة الثانية —
        # أي بيع أو مرتجع تساوي قيمته الإجمالية حد التنبيه القائم
        # alert_large_op_amount أو تتجاوزه يمر بالموافقة المسبقة: من يملك
        # approve_large_operations يتم مباشرة، وغيره تفتح له نافذة موافقة
        # مستخدم آخر (نفس آلية التحقق الحالية للدخول) وعند الإلغاء أو فشل
        # التحقق تتوقف العملية ولا يُسجل شيء
        _approver4 = None
        if abs(total) >= stage4_large_op_threshold() - 1e-9:
            _ok4, _approver4 = self._require_large_op_approval(abs(total))
            if not _ok4:
                messagebox.showwarning("عملية كبيرة",
                    "توقفت العملية ولم يُسجل شيء — العمليات بهذا المبلغ "
                    "تتطلب موافقة مستخدم يملك صلاحية "
                    "«الموافقة على العمليات الكبيرة»")
                return
        # ★★★ إضافة (المرحلة الرابعة — رقم فاتورة متسلسل): رقم عالمي واحد
        # لا يتكرر من عداد invoice_seq (القراءة والزيادة في معاملة واحدة)
        # يُسند للعملية بعد إدراجها مباشرة — يبدأ من أكبر رقم فاتورة موجود
        _inv4 = None
        try:
            _inv4 = get_next_invoice_number()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        try:
            with connect() as conn:
                # ★ تعديل ضروري معلن (ميزة 5): أصبح الحفظ يشمل عمود customer_name
                # ★ تعديل ضروري معلن (إصدار 3 — ميزة 3): الحفظ يسجل اسم البائع تلقائياً
                # ★ تعديل ضروري معلن (الإصدار 16 — القسم 1-1): الحفظ يشمل رابط
                # عملية البيع الأصلية (NULL لغير المرتجعات كما كانت)
                # ★ تعديل مصرح به (المرحلة الرابعة): التقاط مؤشر الإدراج لمعرف
                # الصف (لوسم أعمدة المرحلة الرابعة عليه بعد الإدراج مباشرة)
                cur4 = conn.execute("INSERT INTO operations(date,item_name,quantity,price,total,type,customer_name,seller_name,original_op_id)"
                             " VALUES(?,?,?,?,?,?,?,?,?)",
                             (d, item, q, pr, total, t, cust, CURRENT_USER["name"], orig_id))
                _nid4 = cur4.lastrowid
                # ★★★ إضافة (المرحلة الرابعة): وسم العملية بأعمدة المرحلة
                # الرابعة بعد إدراجها مباشرة وبلا أي تغيير في عبارة الإدراج
                # القائمة: رقم الفاتورة المتسلسل، سبب المرتجع وملاحظته،
                # نسبة الخصم، ووسم نوع الدفع «دين» وربط العميل للبيع بالدين
                try:
                    conn.execute(
                        "UPDATE operations SET invoice_number=?, return_reason=?, "
                        "return_note=?, discount_percent=?, payment_kind=?, customer_id=? "
                        "WHERE id=?",
                        (_inv4, _reason4 or None, _note4 or None,
                         (_disc4 if (_disc4 > 0 and t != "مرتجع") else None),
                         ("دين" if _credit4 else None),
                         (_credit4["customer_id"] if _credit4 else None), _nid4))
                except Exception as e:
                    log_error(e, sys.exc_info()[2])
        except Exception as e:
            messagebox.showerror("خطأ في الحفظ", f"تعذر حفظ العملية:\n{e}")
            return
        # ★★★ إضافة (المرحلة الرابعة — البيع بالدين): بعد نجاح الحفظ بنفس
        # دالة الحفظ القائمة نفسها (نفس أثر المخزون والتقارير وإغلاق اليوم)
        # — تسجيل الدين بالباقي (إجمالي الفاتورة ناقص الدفعة الأولى) على
        # العميل المختار + سطر تدقيق مستقل credit_sale_recorded بنفس أسلوب
        # الكاتب الحالي (المستخدم ورقم الفاتورة والعميل والمبلغ)
        if _credit4:
            try:
                _down4 = float(_credit4.get("down") or 0)
                _remain4 = total - _down4
                if _remain4 > 1e-9:
                    _ensure_stage4_tables()
                    # ★★★ إضافة (موعد التحصيل): الترحيل الآمن أولًا — إن نجح
                    # أُدرج موعد التحصيل مع الدين في العمود الجديد، وإن فشل
                    # الترحيل يُدرج الدين بالعبارة القديمة نفسها حرفيًا بلا
                    # الموعد (البرنامج يعمل بدون الميزة ولا يتوقف شيء)
                    try:
                        _ensure_collection_date_column()
                    except Exception as e:
                        log_error(e, sys.exc_info()[2])
                    _cdate_ins4 = (str(_credit4.get("collection_date"))
                                   if (_COLL_READY["done"]
                                       and _credit4.get("collection_date"))
                                   else None)
                    with connect() as conn:
                        if _COLL_READY["done"]:
                            conn.execute(
                                "INSERT INTO debts(customer_id, invoice_number, "
                                "sale_id, total_amount, paid_amount, status, "
                                "created_at, collection_date) VALUES(?,?,?,?,?,?,?,?)",
                                (_credit4["customer_id"], _inv4, _nid4, _remain4,
                                 0.0, "مفتوح",
                                 datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                                 _cdate_ins4))
                        else:
                            # عبارة الإدراج القديمة نفسها حرفيًا (بلا الموعد)
                            conn.execute(
                                "INSERT INTO debts(customer_id, invoice_number, sale_id, "
                                "total_amount, paid_amount, status, created_at) "
                                "VALUES(?,?,?,?,?,?,?)",
                                (_credit4["customer_id"], _inv4, _nid4, _remain4, 0.0,
                                 "مفتوح", datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
                audit("credit_sale_recorded",
                      f"فاتورة رقم {_inv4 or '—'} | العميل: {_credit4['customer_name']} | "
                      f"الإجمالي: {money(total)} | الدفعة الأولى: {money(_down4)} | "
                      f"الدين المسجل: {money(max(_remain4, 0.0))}"
                      # ★ إضافة (موعد التحصيل): الموعد إن وُجد في سطر التدقيق
                      + (f" | موعد التحصيل: {_credit4['collection_date']}"
                         if _credit4.get("collection_date") else ""))
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                messagebox.showwarning("بيع بالدين",
                    "حُفظت الفاتورة لكن تعذر تسجيل الدين — سُجّل الخطأ في "
                    "error_log.txt (راجع تبويب الديون والتحصيل)")
        # ★★★ إضافة (المرحلة الرابعة): تدقيق موافقة العملية الكبيرة إن مرت
        # عبر نافذة الموافقة (الموافق، رقم الفاتورة، المبلغ)
        if _approver4:
            try:
                audit("large_op_approved",
                      f"الموافق: {_approver4} | فاتورة رقم {_inv4 or '—'} | "
                      f"المبلغ: {money(abs(total))} | {t}: {item}")
            except Exception:
                pass
        for e in (self.e_qty, self.e_price):
            e.delete(0, "end")
        self.e_customer.delete(0, "end")       # ★ إضافة (ميزة 5): مسح حقل العميل بعد الحفظ
        self.type_var.set("نقداً"); self.update_calc()   # ★ تعديل (إصدار 5): عودة الاختيار تلقائياً إلى «نقداً» بعد الحفظ
        # ★★★ إضافة (المرحلة الرابعة): تصفير الخصم والسبب والملاحظة بعد الحفظ
        if hasattr(self, "e_disc"):
            self.e_disc.delete(0, "end"); self.e_disc.insert(0, "0")
        if hasattr(self, "cb_ret_reason"):
            self.cb_ret_reason.set("")
        if hasattr(self, "e_ret_note"):
            self.e_ret_note.delete(0, "end")
        self.refresh_items(); self.refresh_today(); self.refresh_stats()
        # ★ تعديل مصرح به (المرحلة الرابعة): رسالة الحالة تذكر رقم الفاتورة
        self.lbl_status.config(text=f"✔ تم حفظ العملية ({t})"
                               + (f" — فاتورة رقم {_inv4}" if _inv4 else "")
                               + (" — بالدين" if _credit4 else ""), fg=GREEN)
        audit("حفظ عملية",                      # ★ إضافة (ميزة 2): تسجيل الحفظ في سجل التدقيق
              f"{t}: {item} — {q:g} × {pr:g} = {total:g}" + (f" | عميل: {cust}" if cust else "")
              # ★ إضافة (الإصدار 16 — القسم 1-1): توثيق ربط المرتجع بأصله
              + (f" | مرتبط بالعملية رقم {orig_id}" if orig_id else "")
              # ★ إضافة (المرحلة الرابعة): رقم الفاتورة والخصم وسبب المرتجع
              + (f" | فاتورة رقم {_inv4}" if _inv4 else "")
              + (f" | خصم {_disc4:g}%" if _disc4 > 0 else "")
              + (f" | سبب المرتجع: {_reason4}" if _reason4 else "")
              + (" | بيع بالدين" if _credit4 else ""))

    def refresh_items(self):
        with connect() as conn:
            vals = [r[0] for r in conn.execute("SELECT DISTINCT item_name FROM operations ORDER BY item_name")]
        self.cb_item["values"] = vals
        # ★ إضافة (ميزة 6): نفس قائمة الأصناف تتذكر لشاشة الفاتورة أيضاً
        if hasattr(self, "cb_inv_item"):
            self.cb_inv_item["values"] = vals

    def update_closed_banner(self):
        # ★ تعديل مصرح به (الإصدار 14 — الجزء الأول): اللافتة تتبع يوم العمل
        # المفتوح — بلا يوم مفتوح توجّه لزر بدء يوم جديد، ومغلقاً كما كانت
        d = business_day_open()
        if not d:
            self.banner_closed.config(text="⚠️ لا يوم عمل مفتوح — لا يمكن حفظ العمليات. (ابدأ يوماً جديداً من شاشة عمليات يوم العمل)")
        elif is_closed(d):
            self.banner_closed.config(text="⚠️ تم إغلاق يوم العمل وحفظ تقريره — لا يمكن إضافة عمليات. (يمكن إعادة الفتح من الأرشيف)")
        else:
            self.banner_closed.config(text="")

    # ---------- صفحة عمليات اليوم ----------
    def build_today_page(self, p):
        # ★ تعديل مصرح به (الإصدار 14 — الجزء الأول): الرأس يُبنى يدوياً بدل
        # page_head كي يُحفظ مرجع العنوان الديناميكي «عمليات يوم العمل [التاريخ]»
        # (بنفس شكل page_head ونفس خطوطه تماماً — التاريخ يُحدّث من
        # refresh_business_day_ui مع كل تغيّر ليوم العمل)
        head = tk.Frame(p, bg=BG)
        head.pack(fill="x", padx=25, pady=(18, 8))
        head_right = tk.Frame(head, bg=BG); head_right.pack(side="right")
        self.lbl_today_title = tk.Label(head_right, text="📋 عمليات يوم العمل",
                                        bg=BG, fg=DARK, font=FT)
        self.lbl_today_title.pack(anchor="e")
        tk.Label(head_right, text="الإحصائيات ظاهرة في الشريط العلوي ↑", bg=BG, fg=GRAY,
                 font=("Segoe UI", 10)).pack(anchor="e")
        self.mk_btn(head, "🔄 تحديث", self.refresh_today, "#475569").pack(side="left", pady=6)

        # ★ إضافة (إصدار 4 — ميزة 4): فلتر النوع بجانب زر التحديث —
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): أصبح (الكل/نقداً/شبكة/مرتجع) —
        # فلترة عرض الجدول فقط، يتكامل مع فلتر البائع (البائع + النوع معاً)،
        # واختيار «مرتجع» يعرض الصفوف بالأحمر كما هي موجودة
        self.fr_today_type = tk.Frame(head, bg=BG)
        self.fr_today_type.pack(side="left", padx=(12, 0))
        self.today_type_var = tk.StringVar(value="الكل")
        for txt, col, tip in [("الكل", DARK, "عرض كل العمليات"),
                              ("نقداً", GREEN, "عرض عمليات الدرج النقدي فقط"),
                              ("شبكة", ACCENT, "عرض عمليات جهاز الشبكة فقط"),
                              ("مرتجع", RED, "عرض عمليات المرتجع فقط")]:
            rb = tk.Radiobutton(self.fr_today_type, text=txt, variable=self.today_type_var,
                                value=txt, font=FB, fg=col, bg=BG, selectcolor="#dbeafe",
                                activebackground=BG, activeforeground=col, indicatoron=0,
                                width=7, bd=1, relief="solid", cursor="hand2",
                                command=self.refresh_today)
            rb.pack(side="right", padx=3)
            add_tip(rb, tip)          # ★ (إصدار 4 — ميزة 5): تلميح الفلتر

        # ★ تعديل ضروري معلن (إصدار 4 — ميزة 1): ملاحظة البائع وفلتر البائع يُنشآن
        # دائماً ويُظهر أحدهما حسب الدور — لتتكيف الشاشة عند تبديل المستخدم دون إعادة بنائها
        # ★ إضافة (إصدار 3 — ميزة 4): البائع يرى عملياته فقط — والمدير يفلتر حسب البائع
        self.lbl_today_only = tk.Label(head, text="تُعرض عملياتك فقط", bg=BG, fg=GRAY,
                                       font=("Segoe UI", 10, "bold"))
        self.fr_today_filter = ffr = tk.Frame(head, bg=BG)
        tk.Label(ffr, text="البائع:", bg=BG, fg=DARK, font=FB).pack(side="right")
        self.cb_today_filter = ttk.Combobox(ffr, font=F, width=14, state="readonly",
                                            values=["الكل"])
        self.cb_today_filter.current(0)
        self.cb_today_filter.pack(side="right", padx=(0, 6))
        self.cb_today_filter.bind("<<ComboboxSelected>>", lambda e: self.refresh_today())
        # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الأدمن يرى كل العمليات
        # وفلتر البائعين كالمدير تماماً (كان الشرط للمدير وحده)
        if not manager_level(self.role):
            self.lbl_today_only.pack(side="left", padx=12)
        else:
            ffr.pack(side="left", padx=12)

        self.lbl_closed = tk.Label(p, text="", bg=BG, fg=GREEN, font=FB)
        self.lbl_closed.pack(fill="x", padx=25)

        # ★ تعديل ضروري معلن (إصدار 3 — ميزة 3): عمود البائع في جدول عمليات اليوم
        frm, self.tv_today = self.mk_tree(p,
            ["النوع", "المبيع", "السعر", "الكمية", "اسم الصنف", "العميل", "البائع", "التاريخ"],
            [80, 110, 100, 80, 190, 140, 100, 100])
        frm.pack(fill="both", expand=True, padx=25, pady=8)
        self.tv_today.tag_configure("ret", foreground=RED)
        # ★ إضافة (الإصدار 14 — الجزء الثاني): فرز الأعمدة + صفوف متناوبة +
        # تحديد متعدد لجدول عمليات يوم العمل (عرض فقط لا يمس قاعدة البيانات)
        self.tv_today.configure(selectmode="extended")
        enable_tree_sorting(self.tv_today)
        config_tree_stripes(self.tv_today)
        # ★ إضافة (الإصدار 14 — البندان 7+8): سطر العد والمجموع الدائم أسفل
        # الجدول — يعرض «اعرض [عدد] صفوف — المجموع الكلي» وعند التحديد يتغير
        # إلى «المحدد: [عدد] صفوف — المجموع: [مجموع المبيع]» لحظياً
        self.lbl_today_sel = tk.Label(p, text="", bg=BG, fg="#1d4ed8", font=FB, anchor="e")
        self.lbl_today_sel.pack(fill="x", padx=25, pady=(0, 2))
        self.tv_today.bind("<<TreeviewSelect>>", lambda _e: self.on_today_select())

        bar = tk.Frame(p, bg=BG); bar.pack(fill="x", padx=25, pady=(0, 18))
        self.mk_btn(bar, "🗑 حذف العملية المحددة", self.delete_selected, RED).pack(side="right", padx=6)
        # ★★★ إضافة (الإصدار 18 — المشكلة 2): زر «✏️ تصحيح العملية المحددة» —
        # يظهر لمن يملك صلاحية «✏️ تصحيح عملية» فقط (مدير/أدمن افتراضياً):
        # نسخ الأصل كاملاً لسلة المحذوفات بوسم «تصحيح» ثم تحديث نفس الصف
        # بنفس رقمه مع توثيق كل تغيير قبل ← بعد في سجل التدقيق — ماضٍ لا يُمحى
        self.btn_correct_op = self.mk_btn(bar, "✏️ تصحيح العملية المحددة",
                                          self.correct_selected_op, "#0d9488")
        add_tip(self.btn_correct_op, "تصحيح العملية المحددة (لعمليات يوم العمل المفتوح فقط) — "
                                     "الأصل يُحفظ في سلة المحذوفات وكل تغيير يُوثق قبل ← بعد في سجل التدقيق")
        if self.has_permission("edit_op"):
            self.btn_correct_op.pack(side="right", padx=6)
        # ★ إضافة (الإصدار 14 — البند 12): زر استعادة آخر عملية محذوفة من سلة
        # المحذوفات + زر فتح السلة كاملة (استعادة أي صف) — لمن يملك صلاحية الحذف
        b_undo = self.mk_btn(bar, "♻️ آخر حذف", self.restore_last_deleted, "#0d9488")
        b_undo.pack(side="right", padx=6)
        add_tip(b_undo, "استعادة آخر عملية حُذفت إلى جدول العمليات مرة أخرى")
        b_bin = self.mk_btn(bar, "🗑 سلة المحذوفات", self.recycle_bin_dialog, "#475569")
        b_bin.pack(side="right", padx=6)
        add_tip(b_bin, "نافذة كل العمليات المحذوفة — استعادة أي صف منها (آخر 50)")
        # ★ تعديل مصرح به (الإصدار 21 — الاستثناء أ — إصلاح آلية الإغلاق المعطلة):
        # زر «إغلاق اليوم» القائم نفسه بنصه صار يستدعي المسار اليدوي الجديد
        # manual_close_day_flow (تأكيد يوضح أنه سيبدأ يومًا جديدًا فورًا ثم الدالة
        # المركزية الوحيدة بنوع manual_close_day في التدقيق) — الدالة القديمة
        # close_day باقية كما هي بلا أي حذف لخدمة مسار فحص الإقلاع القائم
        self.btn_close = self.mk_btn(bar, "🔒 إغلاق اليوم وحفظ التقرير",
                                      self.manual_close_day_flow, ORANGE)
        self.btn_close.pack(side="left", padx=6)
        # ★★★ إضافة (الإصدار 21 — المطلوب 3): زر «✏️ تعديل الحركة» — للأدمن
        # والمدير فقط حصراً بالدور (لا يظهر للبائع نهائياً حتى لو كان هو من
        # سجل الحركة)، يعمل بعد اختيار حركة من جدول اليوم التجاري الحالي فقط
        # ★ تعديل أدنى حد معلن (الإصدار 23 — المطلوب 3): الزر نفسه صار يفتح
        # نافذة التعديل المركزية الجديدة نفسها المستخدمة في محطة حركات
        # الأيام (نفس النافذة ونفس المنطق بلا أي تكرار كود) — والدالة
        # القديمة edit_selected_op_v21 باقية كما هي لم تُحذف
        self.btn_edit_op21 = self.mk_btn(bar, "✏️ تعديل الحركة", self._quick_edit_today_v23, "#1d4ed8")
        add_tip(self.btn_edit_op21, "تعديل الحركة المحددة (حركات اليوم التجاري الحالي فقط) — "
                                    "للأدمن والمدير فقط، والإجمالي يُحتسب تلقائيًا كمية × سعر، "
                                    "وقبل الحفظ تأكيد بالقديمة والجديدة لكل حقل معدّل")
        if manager_level(self.role):
            self.btn_edit_op21.pack(side="left", padx=6)
        # ★★★ إضافة (الإصدار 17 — الإضافة 1): زر «🖨️ تقرير البائعين» — متاح
        # للجميع (البائع والمدير): معاينة أداء جميع البائعين ثم طباعتها أو
        # تصديرها — في شريط عمليات اليوم بجانب زر إغلاق اليوم
        b_sellers = self.mk_btn(bar, "🖨️ تقرير البائعين", self.open_sellers_report, "#0d9488")
        b_sellers.pack(side="left", padx=6)
        add_tip(b_sellers, "تقرير شامل لأداء جميع البائعين (عدد العمليات ونقداً وشبكة "
                           "والمرتجعات والصافي) — معاينة ثم طباعة حرارية أو A4 أو تصدير Excel، "
                           "متاح للبائع والمدير")
        # ★ إضافة (الإصدار 14 — الجزء الأول): زر بدء يوم عمل جديد — يحل محل
        # زر الإغلاق عندما لا يوم مفتوح (يديره refresh_business_day_ui)
        self.btn_start_day = self.mk_btn(bar, "▶️ بدء يوم جديد", self.start_new_business_day, GREEN)
        add_tip(self.btn_start_day, "بدء يوم عمل جديد بتاريخ اليوم (أو تاريخ تدخله يدوياً) — يُفتح الحفظ من جديد")

    def refresh_today(self):
        # ★ تعديل مصرح به (الإصدار 14 — الجزء الأول): الصفحة تعرض عمليات يوم
        # العمل المفتوح [التاريخ] لا تاريخ الجهاز — وبلا يوم مفتوح تُفرَّغ
        # ويظهر تنبيه البدء (والحفظ معطل من save_op/save_invoice)
        d = business_day_open()
        self.tv_today.delete(*self.tv_today.get_children())
        if not d:
            self.lbl_closed.config(text="⚠️ لا يوم عمل مفتوح — الحفظ معطل حتى بدء يوم جديد",
                                   fg=RED)
            if hasattr(self, "lbl_today_sel"):
                self.lbl_today_sel.config(text="اعرض 0 صفوف — المجموع الكلي: 0.00")
            self.btn_close.config(state="disabled")
            return
        # ★ تعديل ضروري معلن (إصدار 3 — ميزة 4): البائع يرى عملياته فقط،
        # والمدير يرى الكل أو بائعاً محدداً من القائمة المنسدلة
        q = "SELECT * FROM operations WHERE date=?"
        params = [d]
        # ★ تعديل ضروري معلن (إصدار 4 — ميزة 4): احترام فلتر النوع
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): القيم (الكل/نقداً/شبكة/مرتجع) —
        # فلترة عرض الجدول فقط (البطاقات والشريط العلوي كما هما)، ويتكامل مع فلتر البائع
        if getattr(self, "today_type_var", None) is not None and \
                self.today_type_var.get() not in ("الكل", ""):
            q += " AND type=?"
            params.append(self.today_type_var.get())
        # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الأدمن كالمدير — يرى الكل
        # ويفلتر بالبائع (كان الشرط «مدير فقط» للرؤية الكاملة)
        if not manager_level(self.role):
            q += " AND seller_name=?"
            params.append(self.user_name)
        elif hasattr(self, "cb_today_filter"):
            flt = self.cb_today_filter.get()
            if flt not in ("الكل", ""):
                q += " AND seller_name=?"
                params.append("" if flt == "غير محدد" else flt)
        q += " ORDER BY id DESC"
        with connect() as conn:
            rows = conn.execute(q, params).fetchall()
        total_shown = 0.0
        for i, r in enumerate(rows):
            total_shown += (r["total"] or 0)
            # ★ إضافة (الإصدار 14 — البند 6): شارة الصف المتناوب مع بقاء المرتجع أحمر
            self.tv_today.insert("", "end", iid=str(r["id"]),
                tags=stripe_tags(i, r["type"] == "مرتجع"),
                # ★ إضافة (الإصدار 16 — القسم 1-1): صف المرتجع يعرض بجانبه
                # «↩ مرجع: [رقم الأصل]» — والقديمة بلا رابط تعرض «—»
                values=(r["type"], money(r["total"]), money(r["price"]),
                        f'{r["quantity"]:g}',
                        r["item_name"] + ret_ref_mark(r["type"] == "مرتجع", r["original_op_id"]),
                        (r["customer_name"] or ""),
                        (r["seller_name"] or "—"), r["date"]))   # ★ ميزة 3+5 (إصدار 3): عمودا العميل والبائع
        # ★ إضافة (الإصدار 14 — البند 8): العداد الدائم — يُحدّث مع كل تعبئة
        if hasattr(self, "lbl_today_sel"):
            self.lbl_today_sel.config(
                text=f"اعرض {len(rows)} صفوف — المجموع الكلي: {money(total_shown)}")
        # ★ إضافة (إصدار 3 — ميزة 4): تحديث قائمة الفلترة بأسماء بائعي اليوم
        if manager_level(self.role) and hasattr(self, "cb_today_filter"):
            with connect() as conn:
                names = [r[0] or "غير محدد" for r in conn.execute(
                    "SELECT DISTINCT seller_name FROM operations WHERE date=? "
                    "ORDER BY seller_name", (d,))]
            self.cb_today_filter["values"] = ["الكل"] + names
        closed = is_closed(d)
        self.btn_close.config(state=("disabled" if closed else "normal"))
        self.lbl_closed.config(text=("🔒 تم إغلاق هذا اليوم وحفظ تقريره في الأرشيف" if closed else ""),
                               fg=GREEN)

    # ★ إضافة (الإصدار 14 — البندان 7+8): مجموع الصفوف المحددة — «المحدد:
    # [عدد] صفوف — المجموع: [مجموع عمود المبيع]» لحظياً مع كل تحديد، والعودة
    # إلى العداد الدائم عند إلغاء التحديد
    def on_today_select(self):
        try:
            sel = self.tv_today.selection()
            if not sel:
                # إلغاء التحديد → العودة إلى العداد الدائم لكل الصفوف المعروضة
                kids = self.tv_today.get_children("")
                tot = sum((to_num(self.tv_today.set(iid, "المبيع")) or 0) for iid in kids)
                self.lbl_today_sel.config(
                    text=f"اعرض {len(kids)} صفوف — المجموع الكلي: {money(tot)}")
                return
            tot = 0.0
            for iid in sel:
                v = to_num(self.tv_today.set(iid, "المبيع")) or 0
                tot += v
            self.lbl_today_sel.config(
                text=f"المحدد: {len(sel)} صفوف — المجموع: {money(tot)}")
        except Exception:
            pass

    def delete_selected(self):
        # ★ تعديل مصرح به (إصدار 8 — الميزة 5): صلاحية «حذف عملية» بدل «المدير فقط»
        if not self.require_admin("delete_op"):
            return
        sel = self.tv_today.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر عملية من الجدول أولاً"); return
        # ★ تعديل مصرح به (الإصدار 14 — الجزء الأول): الحذف من يوم العمل المفتوح
        d = business_day_open()
        if not d:
            messagebox.showwarning("لا يوم عمل مفتوح", "لا يمكن الحذف — لا يوم عمل مفتوح"); return
        if is_closed(d):
            messagebox.showwarning("اليوم مغلق", "لا يمكن الحذف — اليوم مغلق"); return
        if not messagebox.askyesno("تأكيد", "هل تريد حذف هذه العملية نهائياً؟"):
            return
        with connect() as conn:
            # ★ إضافة (الإصدار 14 — البند 12): نسخة كاملة إلى سلة المحذوفات قبل
            # الحذف — تُستعاد بزر «♻️ آخر حذف» أو من نافذة السلة (رسالة التأكيد
            # نفسها بقيت كما هي تماماً)
            op_row = conn.execute("SELECT * FROM operations WHERE id=?", (int(sel[0]),)).fetchone()
            if op_row is not None:
                recycle_add(op_row, CURRENT_USER["name"])
            conn.execute("DELETE FROM operations WHERE id=?", (int(sel[0]),))
        audit("حذف عملية", f"رقم {sel[0]}")     # ★ إضافة (ميزة 2): تسجيل الحذف
        self.refresh_today(); self.refresh_stats()
        self.lbl_status.config(text="🗑 تم حذف العملية (قابلة للاستعادة من ♻️ آخر حذف)", fg=RED)

    # ═══════════════════════════════════════════════════════
    # ★★★ إضافة (الإصدار 18 — المشكلة 2): تصحيح عمليات يوم العمل ✏️ ★★★
    # تعديل حقيقي بماضٍ لا يُمحى: الأصل يُنسخ كاملاً إلى سلة المحذوفات بوسم
    # «تصحيح — الأصل [#id]» ثم تُحدَّث العملية نفسها بنفس رقمها (فلا ينكسر
    # أي ربط مرتجعات أو مراجع) ويوثق سجل التدقيق كل تغيير قبل ← بعد —
    # لعمليات يوم العمل المفتوح فقط، ولمن يملك «✏️ تصحيح عملية» فقط
    # ═══════════════════════════════════════════════════════
    def correct_selected_op(self):
        """★ إضافة (الإصدار 18 — المشكلة 2): زر «✏️ تصحيح العملية المحددة» —
        بوابة الصلاحية والتاريخ ثم نافذة التصحيح: لمن يملك صلاحية «✏️ تصحيح
        عملية» فقط، وعلى عمليات يوم العمل المفتوح حصراً (يوم مغلق: رسالة
        إعادة الفتح من الأرشيف)"""
        if not self.has_permission("edit_op"):
            messagebox.showwarning("صلاحية", "ليست لديك صلاحية «✏️ تصحيح عملية»")
            return
        sel = self.tv_today.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر عملية من الجدول أولاً"); return
        d = business_day_open()
        if not d:
            messagebox.showwarning("لا يوم عمل مفتوح",
                "لا يمكن التصحيح — لا يوم عمل مفتوح.\n"
                "اضغط «▶️ بدء يوم جديد» في شاشة عمليات يوم العمل.")
            return
        if is_closed(d):
            messagebox.showwarning("اليوم مغلق",
                "لا يمكن التصحيح على يوم مغلق.\n"
                "أعد فتح اليوم أولاً من الأرشيف.")
            return
        op_id = int(sel[0])
        with connect() as conn:
            row = conn.execute("SELECT * FROM operations WHERE id=?", (op_id,)).fetchone()
        if row is None or row["date"] != d:
            messagebox.showwarning("تنبيه",
                "التصحيح متاح لعمليات يوم العمل المفتوح فقط —\n"
                "هذه العملية ليست ضمنه (ربما حُذفت أو تغيّر اليوم في الأثناء)")
            return
        self._correct_op_dialog(row)

    def _correct_op_dialog(self, row):
        """★ إضافة (الإصدار 18 — المشكلة 2): نافذة التصحيح — نفس حقول العملية
        معبأة بقيمها (الصنف/الكمية/السعر/النوع/العميل)، وقيود المرتجع المحفوظة:
        سعر المرتجع المربوط بأصل مقفول بسعر الأصل، وكميته ضمن المتبقي من أصله،
        والربط بالأصل لا ينكسر أبداً (النوع والصنف والسعر مقفلة له) — وعملية
        بيع عليها مرتجعات مربوطة يُقفل صنفها ولا تنزل كميتها دون مجموع
        مرتجعاتها حمايةً للربط. الحفظ بالتسلسل الصارم: (1) نسخة الأصل كاملة
        إلى سلة المحذوفات بوسم «تصحيح — الأصل [#id]» (2) تحديث العملية نفسها
        بنفس رقمها (3) توثيق كل تغيير قبل ← بعد في سجل التدقيق (4) تحديث فوري
        للشريط العلوي وجدول اليوم"""
        op_id = row["id"]
        is_ret = row["type"] == "مرتجع"
        orig_id = row["original_op_id"]
        # الأصل المرتبط (إن وُجد) — سعره هو السعر المقفول للمرتجع المربوط
        orig_row = None
        if is_ret and orig_id:
            with connect() as conn:
                orig_row = conn.execute("SELECT * FROM operations WHERE id=?",
                                        (orig_id,)).fetchone()
        # مرتجعات مربوطة بهذه العملية إن كانت أصلاً — تقيد صنفها وكميتها
        with connect() as conn:
            linked_qty = conn.execute(
                "SELECT COALESCE(SUM(quantity),0) FROM operations "
                "WHERE type='مرتجع' AND original_op_id=?", (op_id,)).fetchone()[0]
        has_linked = linked_qty > RET_EPS

        win = self.register_window(tk.Toplevel(self))
        win.title("✏️ تصحيح عملية")
        win.configure(bg=BG); win.resizable(False, False)
        win.transient(self)
        try:
            win.grab_set()
        except Exception:
            pass
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        card.pack(fill="both", expand=True, padx=18, pady=14)
        # القاعدة الذهبية: زرا الحفظ/الإلغاء يُحزمان side="bottom" أولاً
        fr_btns = tk.Frame(card, bg=CARD)
        fr_btns.pack(side="bottom", fill="x", pady=(8, 12))
        tk.Label(card, text="✏️ تصحيح عملية", bg=CARD, fg=DARK, font=FT).pack(pady=(12, 2))
        tk.Label(card, text=f"العملية رقم #{op_id} — {row['date']} ({day_name(row['date'])})"
                            f" — البائع: {row['seller_name'] or '—'}",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(pady=(0, 2))
        tk.Label(card, text="الأصل يُحفظ كاملاً في سلة المحذوفات بوسم «تصحيح» "
                            "وكل تغيير يُوثق قبل ← بعد في سجل التدقيق",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(pady=(0, 6))

        def frow(label, width=14):
            fr = tk.Frame(card, bg=CARD); fr.pack(fill="x", padx=16, pady=4)
            tk.Label(fr, text=label, bg=CARD, fg=DARK, font=FB, width=width,
                     anchor="e").pack(side="right")
            inner = tk.Frame(fr, bg=CARD)
            inner.pack(side="right", padx=(0, 8))
            return inner

        i_item = frow("اسم الصنف:")
        cb_item = ttk.Combobox(i_item, font=F, width=22)
        cb_item.pack(side="right", ipady=4)
        cb_item.set(row["item_name"])
        try:
            cb_item["values"] = self.cb_item["values"]   # نفس قائمة الأصناف القائمة
        except Exception:
            pass

        i_qty = frow("الكمية:")
        e_qty = tk.Entry(i_qty, font=F, justify="center", relief="solid", bd=1, width=22)
        e_qty.pack(side="right", ipady=4)
        e_qty.insert(0, f'{row["quantity"]:g}')
        digits_only_filter(e_qty)

        i_price = frow("السعر:")
        e_price = tk.Entry(i_price, font=F, justify="center", relief="solid", bd=1, width=22)
        e_price.pack(side="right", ipady=4)
        e_price.insert(0, f'{row["price"]:g}')
        digits_only_filter(e_price)

        trow = tk.Frame(card, bg=CARD); trow.pack(fill="x", padx=16, pady=(6, 2))
        tk.Label(trow, text="النوع:", bg=CARD, fg=DARK, font=FB).pack(side="right", padx=(0, 10))
        type_var = tk.StringVar(value=row["type"])
        type_btns = {}
        for txt, col in [("نقداً", GREEN), ("شبكة", ACCENT), ("مرتجع", RED)]:
            rb = tk.Radiobutton(trow, text=txt, variable=type_var, value=txt, font=FB,
                                fg=col, bg=CARD, selectcolor="#dbeafe", activebackground=CARD,
                                activeforeground=col, indicatoron=0, width=8, bd=1,
                                relief="solid", cursor="hand2")
            rb.pack(side="right", padx=5)
            type_btns[txt] = rb

        i_cust = frow("العميل:")
        e_cust = tk.Entry(i_cust, font=F, justify="center", relief="solid", bd=1, width=22)
        e_cust.pack(side="right", ipady=4)
        e_cust.insert(0, row["customer_name"] or "")

        lbl_rule = tk.Label(card, text="", bg=CARD, fg="#0d9488",
                            font=("Segoe UI", 9, "bold"), wraplength=370, justify="center")
        lbl_rule.pack(pady=(4, 0))
        lbl_err = tk.Label(card, text="", bg=CARD, fg=RED,
                           font=("Segoe UI", 9, "bold"), wraplength=370, justify="center")
        lbl_err.pack(pady=(2, 0))

        # ----- قيود التصحيح حسب نوع العملية (حماية لربط المرتجعات) -----
        if is_ret and orig_id:
            # مرتجع مربوط بأصل: النوع والصنف مقفلان والسعر بسعر الأصل مقفل
            # والكمية ضمن المتبقي (بإضافة كمية هذا المرتجع نفسه للمتاح) —
            # الربط بالأصل لا ينكسر أبداً
            for rb in type_btns.values():
                rb.config(state="disabled")
            cb_item.config(state="disabled")
            e_price.config(state="disabled", disabledforeground=DARK)
            _avail18 = return_remaining_of(orig_id) + (row["quantity"] or 0)
            lbl_rule.config(text=(f"↩ مرجع: العملية رقم #{orig_id} — بسعر الأصل "
                                  f"{((orig_row['price'] if orig_row else row['price']) or 0):g} (مقفل) — "
                                  f"المتاح للتصحيح: {_avail18:g}"))
        elif is_ret:
            # مرتجع قديم غير مربوط (قبل الإصدار 16): يبقى بلا ربط كما هو —
            # النوع مقفل مرتجعاً، والصنف والسعر والكمية قابلة للتصحيح
            for rb in type_btns.values():
                rb.config(state="disabled")
            lbl_rule.config(text="↩ مرجع: — (مرتجع قديم غير مربوط — يبقى بلا ربط كما هو)")
        else:
            # عملية بيع: النوع بين نقداً وشبكة فقط (لا يتحول بيع إلى مرتجع من
            # هنا — المرتجع يُسجل من شاشة العملية الجديدة بأصله)، وإن كانت
            # أصلاً لمرتجعات مربوطة فالصنف مقفل والكمية لا تنزل دون مجموعها
            type_btns["مرتجع"].config(state="disabled")
            if has_linked:
                cb_item.config(state="disabled")
                lbl_rule.config(text=f"↩ عليها مرتجعات مربوطة بمجموع {linked_qty:g} — "
                                     "الصنف مقفل والكمية لا تنزل دون مجموعها (حماية للربط)")

        def do_save():
            item = cb_item.get().strip()
            if not item:
                lbl_err.config(text="اكتب اسم الصنف أولاً"); shake_widget(card); return
            q = to_num(e_qty.get())
            if q is None or q <= 0:
                lbl_err.config(text=f"الكمية غير صحيحة: «{e_qty.get()}» — أدخل رقماً أكبر من صفر")
                shake_widget(card); return
            t = type_var.get()
            if is_ret and orig_id:
                # مرتجع مربوط: السعر بسعر الأصل دائماً والكمية ضمن المتبقي
                pr = (orig_row["price"] if orig_row else row["price"]) or 0
                avail = return_remaining_of(orig_id) + (row["quantity"] or 0)
                if q > avail + RET_EPS:
                    lbl_err.config(text=f"الكمية المتاحة للتصحيح من العملية رقم #{orig_id}: {avail:g}")
                    shake_widget(card); return
            else:
                pr = to_num(e_price.get())
                if pr is None or pr < 0:
                    lbl_err.config(text=f"السعر غير صحيح: «{e_price.get()}» — أدخل رقماً صحيحاً")
                    shake_widget(card); return
                if (not is_ret) and has_linked and q < linked_qty - RET_EPS:
                    lbl_err.config(text=f"الكمية لا يمكن أن تنزل دون مجموع المرتجعات "
                                        f"المربوطة بها ({linked_qty:g})")
                    shake_widget(card); return
            cust = e_cust.get().strip()
            total = (-q * pr) if t == "مرتجع" else (q * pr)
            # قائمة التغييرات قبل ← بعد (تُعرض للتأكيد وتُوثق في سجل التدقيق)
            changes = []
            if item != row["item_name"]:
                changes.append(f"الصنف {row['item_name']}→{item}")
            if q != (row["quantity"] or 0):
                changes.append(f"الكمية {row['quantity']:g}→{q:g}")
            if pr != (row["price"] or 0):
                changes.append(f"السعر {row['price']:g}→{pr:g}")
            if t != row["type"]:
                changes.append(f"النوع {row['type']}→{t}")
            if cust != (row["customer_name"] or ""):
                changes.append(f"العميل {row['customer_name'] or '—'}→{cust or '—'}")
            if not changes:
                messagebox.showinfo("لا تغييرات", "لم تُغيَّر أي قيمة — لا شيء يُحفظ",
                                    parent=win)
                return
            if not messagebox.askyesno("تأكيد التصحيح",
                    f"تصحيح العملية رقم #{op_id}:\n\n" + "\n".join(changes) +
                    "\n\nسيُحفظ الأصل كاملاً في سلة المحذوفات بوسم «تصحيح»\n"
                    "ثم تُحدَّث العملية بنفس رقمها ويُوثق كل تغيير في سجل التدقيق.\n"
                    "هل تريد المتابعة؟", parent=win):
                return
            # (1) نسخة الأصل كاملة إلى سلة المحذوفات بوسم «تصحيح — الأصل [#id]»
            try:
                with connect() as conn:
                    fresh = conn.execute("SELECT * FROM operations WHERE id=?",
                                         (op_id,)).fetchone()
                if fresh is not None:
                    recycle_add(fresh,
                                f"تصحيح — الأصل [#{op_id}] بواسطة {CURRENT_USER['name']}")
            except Exception as e:
                log_error(e, sys.exc_info()[2])
            # (2) تحديث العملية نفسها بنفس رقمها — لا ينكسر أي ربط أو مرجع
            try:
                with connect() as conn:
                    conn.execute("UPDATE operations SET item_name=?,quantity=?,price=?,"
                                 "total=?,type=?,customer_name=? WHERE id=?",
                                 (item, q, pr, total, t, cust, op_id))
            except Exception as e:
                messagebox.showerror("خطأ في الحفظ", f"تعذر حفظ التصحيح:\n{e}", parent=win)
                return
            # (3) توثيق كل تغيير قبل ← بعد في سجل التدقيق
            audit("تصحيح عملية",
                  f"[#{op_id}] بواسطة {CURRENT_USER['name']}: " + "، ".join(changes))
            # (4) تحديث فوري للشريط العلوي وجدول اليوم (وقائمة الأصناف)
            self.refresh_today(); self.refresh_stats(); self.refresh_items()
            self.lbl_status.config(
                text=f"✏️ تم تصحيح العملية #{op_id} — الأصل محفوظ في سلة المحذوفات",
                fg=GREEN)
            win.destroy()

        self.mk_btn(fr_btns, "💾 حفظ التصحيح", do_save, GREEN).pack(side="right", padx=6)
        self.mk_btn(fr_btns, "إلغاء", win.destroy, "#475569").pack(side="right", padx=6)
        e_qty.bind("<Return>", lambda _e: do_save())
        e_price.bind("<Return>", lambda _e: do_save())
        place_window(win, 500)

    # ★★★ إضافات (الإصدار 14 — البند 12): استعادة المحذوفات ♻️ ★★★
    # الزران في شريط عمليات اليوم يستدعيان هاتين الدالتين — لمن يملك صلاحية
    # الحذف مثل حذف العمليات نفسها (الاستعادة عكس الحذف فحُكِمت بنفس الصلاحية)
    def restore_last_deleted(self):
        """★ إضافة (الإصدار 14 — البند 12): زر «♻️ آخر حذف» — يستعيد آخر عملية
        حُذفت إلى جدول العمليات بنفس بياناتها الأصلية كاملة (التاريخ والنوع
        والعميل والبائع) — برسالة تأكيد تعرض ما سيُستعاد قبل التنفيذ، ويرفض
        الاستعادة على يوم مغلق في الأرشيف"""
        if not self.require_admin("delete_op"):
            return
        latest = recycle_last()
        if latest is None:
            messagebox.showinfo("سلة المحذوفات", "السلة فارغة — لا توجد عملية محذوفة حديثاً")
            return
        if not messagebox.askyesno("تأكيد الاستعادة",
                f"استعادة آخر عملية حُذفت إلى جدول العمليات؟\n\n"
                f"الصنف: {latest['item_name']}\n"
                f"{latest['quantity']:g} × {money(latest['price'])} = {money(latest['total'])} ({latest['type']})\n"
                f"حُذفت بواسطة: {latest['deleted_by'] or '—'} في {latest['deleted_at']}"):
            return
        ok, err = recycle_restore(latest["id"])
        if not ok:
            messagebox.showerror("لا يمكن الاستعادة", err)
            return
        audit("استعادة عملية", f"رقم {latest['op_id']} — {latest['item_name']} — {money(latest['total'])}")
        self.refresh_today(); self.refresh_stats()
        self.lbl_status.config(text="♻️ تمت استعادة العملية المحذوفة — جدول العمليات تحدّث", fg=GREEN)

    def recycle_bin_dialog(self):
        """★ إضافة (الإصدار 14 — البند 12): نافذة «🗑 سلة المحذوفات» — كل العمليات
        المحذوفة (آخر 50) بأعمدتها كاملة مع من حذفها ومتى، استعادة أي صف بزر
        «♻️ استعادة المحدد» أو بالنقر المزدوج عليه، وفرز الأعمدة بالنقر على
        الرؤوس وصفوف متناوبة الألوان ككل جداول البرنامج"""
        if not self.require_admin("delete_op"):
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("🗑 سلة المحذوفات")
        win.configure(bg=CARD)
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول — القاعدة الذهبية): شريط
        # الأزرار السفلي يُحزم أولاً side="bottom" قبل أي شيء آخر فلا يُدفع
        # خارج النافذة أبداً مهما طال الجدول — والأزرار تُنشأ فيه لاحقاً بعد
        # تعريف دوالها، ثم العنوان، والجدول يتمدد fill="both" expand=True
        fr_btns = tk.Frame(win, bg=CARD)
        fr_btns.pack(side="bottom", fill="x", pady=(4, 12))
        tk.Label(win, text="🗑 سلة المحذوفات", bg=CARD, fg=DARK, font=FT).pack(pady=(14, 2))
        tk.Label(win, text="كل عملية حُذفت تُنسخ هنا كاملة — تُستعاد بأمر واحد ولا يُحتفظ بآخر 50 فقط",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 10)).pack(pady=(0, 8))
        frm, tv = self.mk_tree(win,
            ["النوع", "المبيع", "السعر", "الكمية", "اسم الصنف", "العميل", "البائع", "من حذفها", "وقت الحذف"],
            [80, 110, 100, 80, 190, 130, 100, 110, 150])
        frm.pack(fill="both", expand=True, padx=18, pady=6)
        tv.tag_configure("ret", foreground=RED)
        # ★ إضافة (الإصدار 14 — البندان 5+6): فرز الرؤوس + الصفوف المتناوبة
        enable_tree_sorting(tv)
        config_tree_stripes(tv)
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول): العدّادات تُحزم
        # side="bottom" فوق شريط الأزرار مباشرة — ظاهرة دائماً فوقه
        lbl_empty = tk.Label(win, text="", bg=CARD, fg=GRAY, font=("Segoe UI", 10, "bold"))
        lbl_empty.pack(side="bottom", pady=(2, 0))
        lbl_count = tk.Label(win, text="", bg=CARD, fg=GRAY, font=("Segoe UI", 10))
        lbl_count.pack(side="bottom", pady=(2, 0))
        add_tip(tv, "انقر رأس أي عمود للفرز — والنقر المزدوج على أي صف يستعيده")

        def fill():
            """قراءة السلة من جديد وملء الجدول من الأحدث"""
            tv.delete(*tv.get_children())
            rows = recycle_list()
            for i, r in enumerate(rows):
                tv.insert("", "end", iid=str(r["id"]), tags=stripe_tags(i, r["type"] == "مرتجع"),
                    values=(r["type"], money(r["total"]), money(r["price"]), f'{r["quantity"]:g}',
                            r["item_name"], (r["customer_name"] or ""),
                            (r["seller_name"] or "—"), (r["deleted_by"] or "—"), r["deleted_at"]))
            lbl_count.config(text=f"عدد الصفوف: {len(rows)} — يُحتفظ بآخر 50 فقط (الأقدم يُحذف تلقائياً)")
            lbl_empty.config(text=("السلة فارغة الآن — لا عمليات محذوفة" if not rows else ""))
        fill()

        def restore_selected(_e=None):
            """استعادة الصف المحدد — رسالة تأكيد تعرض بياناته قبل التنفيذ"""
            sel = tv.selection()
            if not sel:
                messagebox.showinfo("تنبيه", "اختر صفًا من السلة أولاً", parent=win)
                return
            rec_id = int(sel[0])
            with connect() as conn:
                row = conn.execute("SELECT * FROM deleted_operations WHERE id=?",
                                   (rec_id,)).fetchone()
            if row is None:
                fill()      # حُذف من السلة في الأثناء — تحديث العرض
                return
            if not messagebox.askyesno("تأكيد الاستعادة",
                    f"استعادة هذه العملية إلى جدول العمليات؟\n\n"
                    f"الصنف: {row['item_name']}\n"
                    f"{row['quantity']:g} × {money(row['price'])} = {money(row['total'])} ({row['type']})\n"
                    f"حُذفت بواسطة: {row['deleted_by'] or '—'} في {row['deleted_at']}",
                    parent=win):
                return
            ok, err = recycle_restore(rec_id)
            if not ok:
                messagebox.showerror("لا يمكن الاستعادة", err, parent=win)
                return
            audit("استعادة عملية", f"رقم {row['op_id']} — {row['item_name']} — {money(row['total'])}")
            fill()
            self.refresh_today(); self.refresh_stats()
            self.lbl_status.config(text="♻️ تمت استعادة العملية المحذوفة — جدول العمليات تحدّث", fg=GREEN)

        tv.bind("<Double-1>", restore_selected)
        b_res = self.mk_btn(fr_btns, "♻️ استعادة المحدد", restore_selected, "#0d9488")
        b_res.pack(side="right", padx=6)
        add_tip(b_res, "إعادة الصف المحدد إلى جدول العمليات بنفس بياناته الأصلية كاملة")
        b_ref = self.mk_btn(fr_btns, "🔄 تحديث", fill, "#475569")
        b_ref.pack(side="right", padx=6)
        add_tip(b_ref, "إعادة قراءة سلة المحذوفات من جديد")
        b_close = self.mk_btn(fr_btns, "إغلاق", win.destroy, "#475569")
        b_close.pack(side="right", padx=6)
        add_tip(b_close, "إغلاق نافذة سلة المحذوفات")
        # ★ إضافة (الإصدار 15 — الجزء الأول): نافذة طويلة 1000×620 + minsize
        # + تمدد كامل + تمركز وسط الشاشة مع احترام الشاشات الصغيرة
        place_window(win, 1000, 620, 880, 540, can_resize=True)

    def close_day(self):
        # ★ تعديل مصرح به (إصدار 8 — الميزة 5): صلاحية «إغلاق اليوم» بدل «المدير فقط»
        if not self.require_admin("close_day"):
            return
        # ★ تعديل مصرح به (الإصدار 14 — الجزء الأول): الإغلاق يطابق يوم العمل
        # المفتوح [التاريخ] لا تاريخ الجهاز — المنطق نفسه انتقل كما هو إلى
        # _close_business_day لخدمة الإغلاق من زر اليوم ومن تبديل اليوم عند
        # الإقلاع معاً، وبعد الإغلاق يُسأل «بدء يوم عمل جديد؟»
        d = business_day_open()
        if not d:
            messagebox.showinfo("لا يوم عمل مفتوح",
                "لا يوم عمل مفتوح — ابدأ يوماً جديداً بزر «▶️ بدء يوم جديد»")
            return
        self._close_business_day(d, ask_start=True)

    # ★ إضافة (الإصدار 14 — الجزء الأول): جوهر الإغلاق الحالي نفسه بمعامل
    # التاريخ — يغلق أي يوم عمل مفتوح (اليوم أو يوم أمس بعد منتصف الليل)
    # بنفس الملخص والتأكيد والنسخ الاحتياطي والطباعة حرفياً كما كان
    def _close_business_day(self, d, ask_start=True):
        if is_closed(d):
            messagebox.showinfo("مغلق", "تم إغلاق اليوم مسبقاً"); return False
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): day_totals ترجع الآن
        # (عدد العمليات، نقداً، شبكة، المرتجعات، الإجمالي)
        n, cash, netw, rets, net = day_totals(d)
        if n == 0 and not messagebox.askyesno("تأكيد", "لا توجد عمليات اليوم.\nهل تريد إغلاق اليوم بتقرير فارغ؟"):
            return False
        # ★ تعديل (إصدار 5): الملخص قبل الإغلاق يعرض نقداً وشبكة منفصلين
        # حتى يطابق المدير الدرج النقدي وكشف جهاز الشبكة قبل القفل
        msg = (f"ملخص يوم {d}:\n\nعدد العمليات: {n}\nنقداً: {money(cash)}\n"
               f"شبكة: {money(netw)}\nالمرتجعات: {money(rets)}\nالإجمالي: {money(net)}\n\n"
               "سيُحفظ التقرير في الأرشيف ولا يمكن إضافة عمليات على هذا اليوم.\n"
               "✔ تأكد من مطابقة الدرج النقدي وكشف جهاز الشبكة قبل المتابعة.\nهل تريد المتابعة؟")
        if not messagebox.askyesno("إغلاق اليوم", msg):
            return False
        with connect() as conn:
            # ★ تعديل (إصدار 5): حفظ total_cash و total_network منفصلين
            # في تقرير اليوم مع total_sales = نقداً + شبكة
            conn.execute("""INSERT INTO daily_reports(report_date,ops_count,total_sales,
                            total_returns,net_total,total_cash,total_network,closed_at)
                            VALUES(?,?,?,?,?,?,?,?)""",
                         (d, n, cash + netw, rets, net, cash, netw,
                          datetime.now().strftime("%Y-%m-%d %H:%M")))
        audit("إغلاق يوم", f"{d}: {n} عملية — نقداً {money(cash)} | شبكة {money(netw)} | "
              f"مرتجعات {money(rets)} | إجمالي {money(net)}")
        # ★ إضافة (الإصدار 14 — الجزء الأول): إغلاق يوم العمل = لا يوم مفتوح
        # الآن (حتى يُبدأ يوم جديد أو يُرفض فيبقى الحفظ معطلاً بزر البدء البديل)
        try:
            del_setting(BDAY_KEY)
        except Exception:
            pass
        # ★ إضافة (إصدار 7 — طبقات الحماية 1+2+3): النسخ الاحتياطي التلقائي
        # بعد حفظ الإغلاق مباشرة — نسخة يومية (آخر 30) + شهرية أول إغلاق في
        # الشهر (لا تُحذف أبداً) وتُنسخان إلى المجلد الخارجي إن كان مختاراً —
        # وفشل النسخ لا يلغي إغلاق اليوم أبداً: رسالة تحذير + تسجيل في
        # error_log فقط (كما تنص المواصفة تماماً)
        try:
            bk_errors = make_auto_backup(d)
            if bk_errors:
                log_error(RuntimeError("؛ ".join(bk_errors)))
                messagebox.showwarning("تحذير النسخ الاحتياطي",
                    "تم إغلاق اليوم وحفظ تقريره بنجاح ✅\nلكن تعذر إتمام النسخ الاحتياطي:\n"
                    "• " + "\n• ".join(bk_errors) +
                    "\n\nسُجل الخطأ في error_log.txt.")
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showwarning("تحذير النسخ الاحتياطي",
                "تم إغلاق اليوم وحفظ تقريره بنجاح ✅\n"
                "لكن فشل النسخ الاحتياطي التلقائي (سُجل في error_log.txt).")
        self.refresh_today(); self.update_closed_banner(); self.refresh_stats()
        # ★ إضافة (الإصدار 14 — الجزء الأول): تحديث جدول الأرشيف أيضاً — اليوم
        # المغلق يظهر فيه فوراً (كان ينتظر تحديثاً يدوياً أو اختياراً آخر)
        try:
            self.refresh_archive()
        except Exception:
            pass
        if messagebox.askyesno("تم", "تم حفظ تقرير اليوم بنجاح ✅\nهل تريد عرض التقرير الآن؟"):
            self.open_day_details(d)
        # ★ إضافة (إصدار 6 — ربط الطباعة بالإغلاق): بعد حفظ تقرير اليوم بنجاح —
        # إن كانت الطباعة التلقائية مفعلة (auto_print_daily) تطبع مباشرة دون
        # سؤال، وإلا تُسأل «هل تريد طباعة تقرير اليوم؟» (بعد سؤال عرض التقرير
        # وليس بدله) — وفشل الطباعة لا يلغي حفظ اليوم أبداً لأن الحفظ حدث
        # قبلها بأمان، وأي خطأ يسجل في error_log دون أي انهيار
        try:
            if get_setting("auto_print_daily") == "1":
                self.print_day_report(d, closer=CURRENT_USER["name"], when="بعد الإغلاق")
            elif messagebox.askyesno("الطباعة", "هل تريد طباعة تقرير اليوم؟"):
                self.print_day_report(d, closer=CURRENT_USER["name"], when="بعد الإغلاق")
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        # ★ إضافة (الإصدار 14 — الجزء الأول): بعد نجاح الإغلاق — «بدء يوم عمل
        # جديد؟» بالرفض لا يوم مفتوح فيبقى الحفظ معطلاً ويحل زر «▶️ بدء يوم
        # جديد» محل زر الإغلاق حتى يبدأه المستخدم
        if ask_start:
            self.ask_start_new_business_day()
        return True

    # ═══════════════════════════════════════════════════════
    # ★★★ إضافات (الإصدار 14 — الجزء الأول): دوال يوم العمل 🌙 ★★★
    # الفحص الذكي عند الإقلاع + بدء يوم جديد + نافذة التاريخ اليدوي +
    # تحديث كل عناصر الواجهة التي تتبع يوم العمل
    # ═══════════════════════════════════════════════════════
    def business_day_startup_check(self):
        """★ إضافة (الإصدار 14 — الجزء الأول): الفحص الذكي ليوم العمل بعد
        الدخول مباشرة (مرة واحدة عند الإقلاع فقط — لا يُسأل عند كل حفظ):
        — يوم العمل = اليوم → دخول صامت بلا أي سؤال
        — يوم العمل أقدم من اليوم → ثلاثة خيارات: إغلاقه الآن كتقرير
          (بالملخص الكامل القائم ثم سؤال بدء يوم جديد [اليوم]) / الاستمرار
          عليه بعد منتصف الليل (العمليات تُسجَّل على تاريخه) / إلغاء الدخول
        — لا يوم مخزن → قاعدة جديدة تماماً: يُفتح اليوم بصمت (توافق كامل
          مع الإصدارات السابقة)، أو قاعدة قائمة: سؤال بدء يوم جديد [اليوم]
          مع خيار تعديل التاريخ يدوياً
        ★ تعديل مصرح به (الإصدار 17 — التعديل 4 — الاستثناء أ): المقارنات
        تعمل بحد 05:00 فجراً — الساعة قبل 05:00 ويوم الأمس مفتوح = ما نزال
        داخل يوم الأمس الذي يمتد حتى 05:00 القادمة فدخول عادي بلا أي سؤال
        (مع تدقيق وملاحظة لطيفة)، والساعة 05:00 فما فوق ويوم الأمس مفتوح =
        سؤال الإغلاق/الاستمرار (الاستمرار قرار المدير)، وأي حالة أخرى تبقى
        على منطق الأسئلة الموجود كما هو"""
        stored = business_day_open()
        today = today_str()
        # ★ (الإصدار 17 — التعديل 4): تاريخ الأمس وهل نحن قبل حد 05:00 فجراً
        yesterday = date.fromordinal(date.today().toordinal() - 1).isoformat()
        before_dawn = datetime.now().hour < BUSINESS_DAY_START_HOUR
        if stored is None:
            with connect() as conn:
                has_ops = conn.execute("SELECT 1 FROM operations LIMIT 1").fetchone() is not None
                has_reps = conn.execute("SELECT 1 FROM daily_reports LIMIT 1").fetchone() is not None
            if not has_ops and not has_reps:
                set_business_day(today)   # أول تشغيل فعلاً — بلا أي سؤال
                return
            self.ask_start_new_business_day(manual=True)
            return
        # ★ (الإصدار 17 — التعديل 4): الدخول الصامت — نفس اليوم (أو ساعة
        # الجهاز متأخرة) كما كان، وقبلها حالة الفجر الجديدة: قبل 05:00 ويوم
        # الأمس مفتوح = ما نزال داخل يومه حتى 05:00 القادمة بلا أي سؤال
        silent = (stored == today or stored > today
                  or (before_dawn and stored == yesterday))
        if silent:
            if before_dawn:
                audit("بدء تشغيل ضمن حد 05:00",
                      f"نحن قبل 05:00 — العمليات تُسجَّل على يوم {stored} (ضمن حد 05:00)")
                self._show_pre_dawn_note(stored)
            return
        # يوم العمل أقدم من اليوم — إن كان مغلقاً فعلاً فالسؤال بدء يوم جديد مباشرة
        if is_closed(stored):
            try:
                del_setting(BDAY_KEY)
            except Exception:
                pass
            self.ask_start_new_business_day(manual=True)
            return
        choice = self._ask_bday_switch(stored, today)
        if choice == "close":
            self._close_business_day(stored, ask_start=True)
        elif choice == "continue":
            # ★ تعديل مصرح به (الإصدار 17 — التعديل 4): نص التدقيق بالحد الفجري
            audit("استمرار يوم عمل", f"{stored} — العمليات بعد حد 05:00 فجراً تُسجَّل عليه")
            # يبقى اليوم القديم مفتوحاً — البيع بعد الحد الفجري يُسجَّل عليه
        else:
            self.exit_app()          # إلغاء الدخول — إغلاق آمن كما عند إلغاء الدخول نفسه

    def _ask_bday_switch(self, stored, today):
        """★ إضافة (الإصدار 14 — الجزء الأول): حوار الخيارات الثلاثة ليوم العمل
        الأقدم من اليوم — يرجع 'close' أو 'continue' أو 'cancel'"""
        box = {"choice": "cancel"}
        win = self.register_window(tk.Toplevel(self))
        win.title("يوم العمل المفتوح")
        win.resizable(False, False)
        win.configure(bg=BG)
        win.transient(self)
        try:
            win.grab_set()
        except Exception:
            pass
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول): بطاقة أعلى (440×320) كي
        # تظهر أزرارها الثلاثة كاملة، وشريط الأزرار يُحزم side="bottom" أولاً
        # داخلها (القاعدة الذهبية) فلا يُقص أبداً
        card.place(in_=win, relx=0.5, rely=0.5, anchor="c", width=440, height=320)
        fr = tk.Frame(card, bg=CARD)
        fr.pack(side="bottom", pady=4)
        tk.Label(card, text="🌙", bg=CARD, fg=DARK, font=("Segoe UI", 24)).pack(pady=(14, 0))
        tk.Label(card, text="يوم العمل المفتوح أقدم من تاريخ اليوم", bg=CARD, fg=DARK,
                 font=FT).pack(pady=(0, 6))
        tk.Label(card, text=(f"يوم العمل المفتوح: {stored} ({day_name(stored)})\n"
                             f"تاريخ الجهاز اليوم: {today}\n\nماذا تريد أن تفعل؟"),
                 bg=CARD, fg=GRAY, font=("Segoe UI", 10), justify="center").pack(pady=(0, 8))
        def pick(c):
            box["choice"] = c
            win.destroy()
        self.mk_btn(fr, "🔒 إغلاقه الآن كتقرير", lambda: pick("close"), ORANGE).pack(
            side="top", pady=4, ipadx=10)
        # ★ تعديل مصرح به (الإصدار 17 — التعديل 4): نص الزر بالحد الفجري —
        # الاستمرار الآن معناه بعد حد 05:00 فجراً لا بعد منتصف الليل
        self.mk_btn(fr, "🌙 الاستمرار عليه (بعد حد 05:00 فجراً)", lambda: pick("continue"), ACCENT).pack(
            side="top", pady=4, ipadx=10)
        self.mk_btn(fr, "✖ إلغاء الدخول", lambda: pick("cancel"), "#475569").pack(
            side="top", pady=4, ipadx=10)
        # ★ إضافة (الإصدار 15 — الجزء الأول): تمركز وسط الشاشة + احترام
        # الشاشات الصغيرة (الشاشة − 80) — البطاقة 440×320 داخل 520×380
        place_window(win, 520, 380)
        win.protocol("WM_DELETE_WINDOW", lambda: pick("cancel"))
        win.wait_window(win)
        return box["choice"]

    def ask_start_new_business_day(self, manual=False):
        """★ إضافة (الإصدار 14 — الجزء الأول): سؤال بدء يوم عمل جديد —
        التاريخ المقترح = اليوم، وإن كان اليوم مغلقاً بالأرشيف فاليوم التالي
        له؛ manual=True يفتح نافذة التاريخ اليدوي (بعد الإغلاق مباشرة أو عند
        الإقلاع بلا يوم مخزن)، ويرجع True إن صار يوم مفتوح
        ★ تعديل مصرح به (الإصدار 17 — التعديل 4): التاريخ المقترح صار بحد
        05:00 فجراً — قبل 05:00 يُقترح تاريخ الأمس (العمليات الفجرية تُسجَّل
        عليه)، ومن 05:00 فما فوق تاريخ اليوم — مع التعديل اليدوي المتاح"""
        # ★ (الإصدار 17 — التعديل 4): المقترح = تاريخ اليوم التجاري للحظة الحالية
        propose = business_now_date()
        if is_closed(propose):
            propose = next_day(propose)
        if manual:
            d = self.manual_business_day_dialog(propose)
            if d:
                set_business_day(d)
                self.refresh_business_day_ui()
                messagebox.showinfo("يوم عمل جديد", f"فُتح يوم عمل جديد بتاريخ {d}\n"
                                     "يمكنك الآن حفظ العمليات بشكل طبيعي.")
                return True
            return False
        if messagebox.askyesno("بدء يوم عمل جديد",
                               f"هل تريد بدء يوم عمل جديد بتاريخ {propose}؟"):
            ok, v = validate_new_business_day(propose)
            if ok:
                set_business_day(v)
                self.refresh_business_day_ui()
                messagebox.showinfo("يوم عمل جديد", f"فُتح يوم عمل جديد بتاريخ {v}\n"
                                     "يمكنك الآن حفظ العمليات بشكل طبيعي.")
                return True
            messagebox.showwarning("تنبيه", v)
        return False

    def manual_business_day_dialog(self, propose=""):
        """★ إضافة (الإصدار 14 — الجزء الأول): نافذة بدء يوم عمل بتاريخ يدوي —
        مقترح جاهز قابل للتعديل (بعد الإغلاق مباشرة أو عند الإقلاع بلا يوم
        مخزن)، وتحكم كامل: صيغة سليمة + ليس يوماً مغلقاً + ليس أقدم من آخر
        يوم مغلق؛ يرجع التاريخ أو None عند الإلغاء"""
        result = {"d": None}
        win = self.register_window(tk.Toplevel(self))
        win.title("بدء يوم عمل جديد")
        win.resizable(False, False)
        win.configure(bg=BG)
        win.transient(self)
        try:
            win.grab_set()
        except Exception:
            pass
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول): بطاقة أكبر (410×310) كي
        # يظهر زرا التأكيد كاملين، وشريط الأزرار يُحزم side="bottom" أولاً
        # داخلها (القاعدة الذهبية) فلا يُقص أبداً
        card.place(in_=win, relx=0.5, rely=0.5, anchor="c", width=410, height=310)
        fr = tk.Frame(card, bg=CARD)
        fr.pack(side="bottom", pady=(6, 10))
        tk.Label(card, text="▶️", bg=CARD, fg=DARK, font=("Segoe UI", 24)).pack(pady=(12, 0))
        tk.Label(card, text="بدء يوم عمل جديد", bg=CARD, fg=DARK, font=FT).pack(pady=(0, 4))
        tk.Label(card, text="تاريخ يوم العمل الذي ستُسجَّل عليه العمليات:", bg=CARD, fg=GRAY,
                 font=("Segoe UI", 10)).pack()
        e_date = tk.Entry(card, font=F, justify="center", relief="solid", bd=1, width=18)
        e_date.pack(pady=6, ipady=4)
        e_date.insert(0, propose)
        tk.Label(card, text="الصيغ المقبولة: 2026-01-10 أو 10-01-2026 أو 10/01/2026\n"
                            "(بالأرقام العربية أيضاً) — وليس يوماً مغلقاً في الأرشيف",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9), justify="center").pack()
        lbl_err = tk.Label(card, text="", bg=CARD, fg=RED, font=("Segoe UI", 9, "bold"),
                           wraplength=340, justify="center")
        lbl_err.pack(pady=(2, 0))
        def do_ok():
            ok, v = validate_new_business_day(e_date.get())
            if not ok:
                lbl_err.config(text=v)
                shake_widget(card)
                return
            result["d"] = v
            win.destroy()
        def do_cancel():
            win.destroy()
        self.mk_btn(fr, "✅ بدء اليوم", do_ok, GREEN).pack(side="right", padx=6)
        self.mk_btn(fr, "إلغاء", do_cancel, "#475569").pack(side="right", padx=6)
        e_date.bind("<Return>", lambda _e: do_ok())
        e_date.focus_set()
        # ★ إضافة (الإصدار 15 — الجزء الأول): تمركز وسط الشاشة + احترام
        # الشاشات الصغيرة (الشاشة − 80) — البطاقة 410×310 داخل 460×360
        place_window(win, 460, 360)
        win.protocol("WM_DELETE_WINDOW", do_cancel)
        win.wait_window(win)
        return result["d"]

    def start_new_business_day(self):
        """★ إضافة (الإصدار 14 — الجزء الأول): زر «▶️ بدء يوم جديد» — يفتح
        نافذة التاريخ (مقترحاً اليوم أو اليوم التالي إن كان اليوم مغلقاً)
        لمن يملك صلاحية إغلاق اليوم"""
        if not self.require_admin("close_day"):
            return
        self.ask_start_new_business_day(manual=True)

    def refresh_business_day_ui(self):
        """★ إضافة (الإصدار 14 — الجزء الأول): تحديث كل عناصر الواجهة التي
        تتبع يوم العمل — سطر الشريط العلوي (والهلال بعد منتصف الليل)، عنوان
        صفحة العمليات بتاريخه، وتبديل زر الإغلاق بزر البدء وبالعكس
        ★ تعديل مصرح به (الإصدار 17 — التعديل 4): سطر الشريط العلوي يذكر
        صراحة أن اليوم التجاري ينتهي 05:00 فجراً ويبدأ الجديد بعده"""
        d = business_day_open()
        if hasattr(self, "lbl_bday"):
            if d:
                extra = "  🌙 بعد منتصف الليل" if today_str() > d else ""
                self.lbl_bday.config(text=f"📅 يوم العمل: {d} ({day_name(d)})"
                                           f" — ينتهي 05:00 فجراً{extra}",
                                     fg="#1d4ed8")
            else:
                self.lbl_bday.config(
                    text="📅 لا يوم عمل مفتوح — الحفظ معطل حتى بدء يوم جديد", fg=RED)
        if hasattr(self, "lbl_today_title"):
            self.lbl_today_title.config(
                text=(f"📋 عمليات يوم العمل {d} ({day_name(d)})" if d
                      else "📋 عمليات يوم العمل"))
        if hasattr(self, "btn_close") and hasattr(self, "btn_start_day"):
            try:
                def _packed(w):
                    try:
                        w.pack_info(); return True
                    except Exception:
                        return False
                if d:
                    self.btn_start_day.pack_forget()
                    # ★ إضافة (الإصدار 14 — الجزء الأول): الحالة تُطبَّع هنا أيضاً —
                    # بعد بدء يوم جديد مباشرة كان زر الإغلاق قد يظل معطلاً من
                    # إغلاق اليوم السابق حتى تحديث لاحق (لاحظ 3058 و3010)
                    self.btn_close.config(
                        state=("disabled" if is_closed(d) else "normal"))
                    if not _packed(self.btn_close):
                        self.btn_close.pack(side="left", padx=6)
                else:
                    self.btn_close.pack_forget()
                    if not _packed(self.btn_start_day):
                        self.btn_start_day.pack(side="left", padx=6)
            except Exception:
                pass
        # ★ إضافة (الإصدار 14 — الجزء الأول): لافتة صفحة العملية تتبع يوم
        # العمل أيضاً — بعد بدء يوم جديد مباشرة كانت تبقى نصها السابق
        try:
            if hasattr(self, "banner_closed"):
                self.update_closed_banner()
        except Exception:
            pass
        # ★ إضافة (الإصدار 21 — المطلوب 1-5): زر «إغلاق اليوم» اليدوي خاص
        # بالإدارة فقط (أدمن/مدير) ولا يظهر للبائع نهائياً — البوابة هنا في
        # نقطة التجمع التي تُستدعى مع كل تحديث لليوم فتبقى صحيحة بعد تبديل
        # المستخدم، وللبائع يوجد زر «▶️ بدء يوم جديد» القائم وحده إن لا يوم
        try:
            if hasattr(self, "btn_close") and not manager_level(self.role):
                self.btn_close.pack_forget()
        except Exception:
            pass

    # ═════════════════════════════════════════════════════
    # ★★★ إضافات (الإصدار 21): الإغلاق التلقائي الصارم 🌅 ★★★
    # الدالة المركزية الوحيدة + نقاط التفتيش + المسار اليدوي الجديد
    # + شريط اليوم التجاري السفلي — ولا يتكرر منطق الإغلاق في أي مكان
    # ═════════════════════════════════════════════════════
    def _bday_auto_close_tick(self):
        """★ إضافة (الإصدار 21 — المطلوب 1-3/ب): مؤقت التكرار كل 60 ثانية —
        لا يخضع لأي صلاحية ولا يمكن لأحد إيقافه أو تعطيله بأي إعداد: يستدعي
        الدالة المركزية ثم يعيد جدولة نفسه دائماً مهما حدث داخل الدورة"""
        try:
            self.ensure_business_day_current()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        finally:
            try:
                self.after(60000, self._bday_auto_close_tick)
            except Exception:
                pass

    def ensure_business_day_current(self, force=False, event="auto_close_day"):
        """★ إضافة (الإصدار 21 — المطلوب 1-2): الدالة المركزية الوحيدة —
        تقارن اليوم المحفوظ في settings/business_day مع ناتج get_business_day():
        — تطابقا (وبلا force): اليوم صحيح فلا شيء يُعمل
        — اختلفا: إغلاق اليوم القديم تلقائيًا فورًا (إجمالياته من جدول operations
          حتى لو خلا فتُسجَّل بإجماليات صفرية، مع closed_at بنظام 24) ثم فتح
          اليوم الجديد بوضع ناتج get_business_day() بلا أي تدخل من أي مستخدم —
          وإن كان الناتج مغلقاً بالأرشيف (حالة نادرة) فاليوم التالي له بنفس
          مقترح «بدء يوم عمل جديد» القائم حرفياً، وإن ظل مغلقاً فُتح الأمر
          لزر «▶️ بدء يوم جديد» القائم (بلا أي حالة مكسورة)
        مع تحديث كل المجاميع والعدادات المعروضة فورًا لتنعكس على اليوم الجديد،
        وإشعار عربي واضح غير معطِّل في المسار التلقائي. force=True هو مسار
        الإغلاق اليدوي (نوع manual_close_day) وهو خيار مبكر اختياري لا يلغي
        النظام التلقائي أبداً ولا يتأثر به. يرجع True إن جرى إغلاق فعلي"""
        stored = business_day_open()
        target = get_business_day()
        # لا شيء يُعمل إن كان اليوم المخزن هو الصحيح — أو أحدث منه (يوم مفتوح
        # بتاريخ مستقبلي بعد إغلاق يدوي مبكر أو بدء يدوي قائم: نفس دلالة
        # «الدخول الصامت» في فحص الإقلاع القديم) — يُترك حتى يصير قديماً
        # فيُغلق تلقائياً عند 05:00 التالي له كالمعتاد
        if not force and stored is not None and stored >= target:
            return False
        do_close = False
        if stored is not None:
            if force:
                if is_closed(stored):
                    return False    # لا يوم مفتوح فعلاً — لا تقرير مزدوجاً أبداً
                do_close = True
            elif not is_closed(stored):
                do_close = True     # (ومغلقاً سلفاً بتقريره: يُفتح الجديد فقط)
        closed_done = False
        if do_close:
            # —— الإغلاق المركزي الوحيد (لا نسخ منه في أي مكان آخر) ——
            n, cash, netw, rets, net = day_totals(stored)
            closed_at = datetime.now().strftime("%Y-%m-%d %H:%M")
            with connect() as conn:
                conn.execute("""INSERT INTO daily_reports(report_date,ops_count,total_sales,
                                total_returns,net_total,total_cash,total_network,closed_at)
                                VALUES(?,?,?,?,?,?,?,?)""",
                             (stored, n, cash + netw, rets, net, cash, netw, closed_at))
            audit(event, f"{stored}: {n} عملية — نقداً {money(cash)} | شبكة {money(netw)} | "
                  f"مرتجعات {money(rets)} | إجمالي {money(net)} | أُغلق عند {closed_at}")
            try:
                del_setting(BDAY_KEY)
            except Exception:
                pass
            closed_done = True
        # فتح اليوم الجديد يُحل بعد الإغلاق فعلاً: فبعد إغلاق منتصف اليوم يكون
        # ناتج get_business_day() نفسه مغلقاً بالتقرير المحفوظ للتو، فيُفتح
        # اليوم التالي له بنفس مقترح «بدء يوم عمل جديد» القائم حرفياً
        nd = target
        if is_closed(nd):
            nd2 = next_day(nd)
            nd = None if is_closed(nd2) else nd2
        if nd:
            set_business_day(nd)    # الدالة القائمة توثق «بدء يوم عمل» بنفسها
        # —— تحديث كل المجاميع والعدادات والشاشات فورًا ——
        for _fn in ("refresh_stats", "refresh_today", "update_closed_banner", "refresh_archive"):
            try:
                getattr(self, _fn)()
            except Exception:
                pass
        self.refresh_business_day_status_bar()
        if closed_done and event == "auto_close_day":
            # إكسسوارات الإغلاق القائمة نفسها بلا أي نوافذ هنا (سياق غير مراقب):
            # النسخ الاحتياطي بعد كل إغلاق ناجح، والطباعة فقط إن كانت الطباعة
            # التلقائية مفعلة وعلى طابعة مختارة لهذا الجهاز (بلا الافتراضية)
            try:
                bk_errors = make_auto_backup(stored)
                if bk_errors:
                    log_error(RuntimeError("؛ ".join(bk_errors)))
            except Exception as e:
                log_error(e, sys.exc_info()[2])
            try:
                if get_setting("auto_print_daily") == "1":
                    if get_device_printer():
                        self.print_day_report(stored, closer=CURRENT_USER["name"],
                                              when="بعد الإغلاق")
                    else:
                        log_error(RuntimeError("تخطي الطباعة التلقائية عند الإغلاق "
                                               "التلقائي: لا طابعة مختارة لهذا الجهاز"))
            except Exception as e:
                log_error(e, sys.exc_info()[2])
            self._notify_auto_close(stored, nd or target, failed_open=(nd is None))
        return closed_done

    def _notify_auto_close(self, old_d, new_d, failed_open=False):
        """★ إضافة (الإصدار 21 — المطلوب 1-2): إشعار عربي واضح غير معطِّل —
        نافذة صغيرة عابرة بلا أي سؤال (لا تلغي ولا تعطّل أي عملية بيع جارية)،
        تختفي وحدها بعد 10 ثوانٍ أو بضغطة زر"""
        try:
            win = self.register_window(tk.Toplevel(self))
            win.title("إغلاق تلقائي لليوم التجاري")
            win.configure(bg=BG)
            win.resizable(False, False)
            card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=2)
            card.pack(fill="both", expand=True)
            tk.Label(card, text="🌅", bg=CARD, fg=DARK,
                     font=("Segoe UI", 26)).pack(pady=(14, 2))
            tk.Label(card, text=f"تم إغلاق يوم {old_d} تلقائيًا عند الساعة 05:00\n"
                                f"وبدأ يوم تجاري جديد {new_d}",
                     bg=CARD, fg=DARK, font=("Segoe UI", 11, "bold"),
                     justify="center", wraplength=380).pack(padx=24, pady=(4, 8))
            if failed_open:
                tk.Label(card, text="⚠️ تعذر فتح اليوم الجديد تلقائيًا (تاريخه مغلقاً "
                                    "بالأرشيف) — استخدم زر «▶️ بدء يوم جديد»",
                         bg=CARD, fg=RED, font=("Segoe UI", 10, "bold"),
                         justify="center", wraplength=380).pack(padx=24, pady=(0, 6))
            self.mk_btn(card, "حسناً", win.destroy, ACCENT).pack(pady=(4, 14))
            def _gone():
                try:
                    if win.winfo_exists():
                        win.destroy()
                except Exception:
                    pass
            win.after(10000, _gone)
            place_window(win, 480, 260)
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    def manual_close_day_flow(self):
        """★ إضافة (الإصدار 21 — المطلوب 1-5) عبر الاستثناء المصرح (أ): المسار
        اليدوي الجديد لزر «إغلاق اليوم» القائم — للأدمن والمدير فقط (لا يظهر
        للبائع نهائياً ولا يعمل له)، رسالة تأكيد عربية توضح أنه سيُغلق اليوم
        التجاري الحالي ويبدأ يوم جديد فورًا، وبعد الموافقة يُستدعى نفس الدوال
        المركزية أعلاه (ensure_business_day_current وحدها — بلا أي تكرار لمنطق
        الإغلاق في مكانين) بنوع manual_close_day في التدقيق، وبنفس إكسسوارات
        الإغلاق القائمة حرفياً بعدها (النسخ الاحتياطي التلقائي ثم عرض التقرير
        ثم خيار الطباعة) — والدالتان القديمتان close_day و_close_business_day
        باقيتان كما هما بلا أي حذف لخدمة مسار فحص الإقلاع القائم، والمؤقت
        التلقائي كل 60 ثانية يستمر كالمعتاد ولا يتأثر بالإغلاق اليدوي أبداً"""
        if not manager_level(self.role):
            messagebox.showwarning("صلاحية", "إغلاق اليوم يدويًا خاص بالإدارة فقط (أدمن/مدير)")
            return
        d = business_day_open()
        if not d:
            messagebox.showinfo("لا يوم عمل مفتوح",
                "لا يوم عمل مفتوح — ابدأ يوماً جديداً بزر «▶️ بدء يوم جديد»")
            return
        if is_closed(d):
            messagebox.showinfo("مغلق", "تم إغلاق هذا اليوم وحفظ تقريره مسبقاً")
            return
        n, cash, netw, rets, net = day_totals(d)
        msg = (f"سيُغلق اليوم التجاري الحالي {d} ({day_name(d)}) ويُحفظ تقريره في الأرشيف،\n"
               f"وسيبدأ يوم تجاري جديد فورًا تلقائيًا.\n\n"
               f"ملخص يوم {d}:\nعدد العمليات: {n}\nنقداً: {money(cash)}\nشبكة: {money(netw)}\n"
               f"المرتجعات: {money(rets)}\nالإجمالي: {money(net)}\n\n"
               "✔ تأكد من مطابقة الدرج النقدي وكشف جهاز الشبكة قبل المتابعة.\n"
               "هل تريد المتابعة؟")
        if not messagebox.askyesno("إغلاق اليوم يدويًا", msg):
            return
        if not self.ensure_business_day_current(force=True, event="manual_close_day"):
            return
        try:
            bk_errors = make_auto_backup(d)
            if bk_errors:
                log_error(RuntimeError("؛ ".join(bk_errors)))
                messagebox.showwarning("تحذير النسخ الاحتياطي",
                    "تم إغلاق اليوم وبدأ يوم جديد فورًا ✅\nلكن تعذر إتمام النسخ الاحتياطي:\n"
                    "• " + "\n• ".join(bk_errors) + "\n\nسُجل الخطأ في error_log.txt.")
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showwarning("تحذير النسخ الاحتياطي",
                "تم إغلاق اليوم وبدأ يوم جديد فورًا ✅\n"
                "لكن فشل النسخ الاحتياطي التلقائي (سُجل في error_log.txt).")
        if messagebox.askyesno("تم", "تم إغلاق اليوم وبدء يوم جديد فورًا ✅\nهل تريد عرض التقرير الآن؟"):
            self.open_day_details(d)
        try:
            if get_setting("auto_print_daily") == "1":
                self.print_day_report(d, closer=CURRENT_USER["name"], when="بعد الإغلاق")
            elif messagebox.askyesno("الطباعة", "هل تريد طباعة تقرير اليوم؟"):
                self.print_day_report(d, closer=CURRENT_USER["name"], when="بعد الإغلاق")
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        messagebox.showinfo("تم", f"أُغلق يوم {d} وبدأ يوم تجاري جديد "
                                  f"{business_day_open()} فورًا.\n"
                                  "العمليات التالية تُسجَّل عليه، والمؤقت التلقائي كل 60 "
                                  "ثانية مستمر كالمعتاد.")

    def refresh_business_day_status_bar(self):
        """★ إضافة (الإصدار 21 — المطلوب 2-3): «اليوم التجاري الحالي:
        [التاريخ]» في شريط الحالة السفلي للجميع — يتحدث تلقائيًا فور كل
        إغلاق (تلقائي أو يدوي) وفتح يوم جديد، من الدالة المركزية نفسها"""
        try:
            if not hasattr(self, "lbl_bday_status"):
                return
            d = business_day_open()
            if d:
                self.lbl_bday_status.config(
                    text=f"📅 اليوم التجاري الحالي: {d} ({day_name(d)})", fg=DARK)
            else:
                self.lbl_bday_status.config(
                    text="📅 اليوم التجاري الحالي: لا يوم مفتوح", fg=RED)
        except Exception:
            pass

    # ═════════════════════════════════════════════════════
    # ★★★ إضافات (الإصدار 21): حركات الأيام السابقة + إصلاح المدموج 🗓️ ★★★
    # ═════════════════════════════════════════════════════
    def show_past_days(self):
        """★ إضافة (الإصدار 21 — المطلوب 2): نافذة «حركات الأيام السابقة» —
        للأدمن والمدير فقط، عرض قراءة فقط دون أي تعديل أو حذف: أيام
        daily_reports من الأحدث للأقدم (التاريخ وعدد الحركات والنقد والشبكة
        والمرتجعات والصافي ووقت الإغلاق بنظام 24)، وعند اختيار يوم تُعرض كل
        حركات ذلك اليوم من operations (الوقت بنظام 24 والصنف والكمية والسعر
        والإجمالي والنوع والعميل والبائع) مع صف إجماليات أسفل الجدول مطابق
        لما في daily_reports — والربط بالآلية الموجودة (تاريخ الحركة المسجل
        على يوم عملها)، والتاريخ والوقت الكاملان لكل حركة من مطابقة سجل
        التقيق حيثما تُطابق (وإلا «—») حتى تُميَّز حركات كل يوم فعلي بوضوح،
        وفيها زر «إعادة احتساب وتوزيع حركات هذا اليوم» للأدمن وحده"""
        if not manager_level(self.role):
            messagebox.showwarning("صلاحية", "حركات الأيام السابقة خاصة بالإدارة فقط (أدمن/مدير)")
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("حركات الأيام السابقة (قراءة فقط)")
        win.configure(bg=BG)
        # القاعدة الذهبية: شريط الأزرار السفلي يُحزم أولاً فلا يُقص أبداً
        bar = tk.Frame(win, bg=BG)
        bar.pack(side="bottom", fill="x", padx=20, pady=(0, 12))
        lbl_totals = tk.Label(win, text="اختر يوماً من الجدول أعلاه لعرض حركاته",
                              bg=BG, fg=GRAY, font=("Segoe UI", 10, "bold"),
                              anchor="e", wraplength=940, justify="right")
        lbl_totals.pack(side="bottom", fill="x", padx=20)
        tk.Label(win, text="🗓️ حركات الأيام السابقة", bg=BG, fg=DARK,
                 font=FT).pack(pady=(12, 2))
        tk.Label(win, text="قراءة فقط — الأيام من الأرشيف (الأحدث أولاً)، واختيار أي يوم "
                           "يعرض كل حركاته كاملة بأوقاتها الحقيقية",
                 bg=BG, fg=GRAY, font=("Segoe UI", 10)).pack()
        frm_days, tv_days = self.mk_tree(win,
            ["وقت الإغلاق", "الصافي", "المرتجعات", "الشبكة", "النقد", "عدد الحركات", "التاريخ"],
            [130, 110, 110, 105, 105, 95, 100])
        frm_days.pack(fill="x", padx=20, pady=(6, 2))
        tv_days.configure(height=8)
        config_tree_stripes(tv_days)
        frm_det, tv_det = self.mk_tree(win,
            ["النوع", "المبيع", "السعر", "الكمية", "اسم الصنف", "العميل", "البائع",
             "اليوم التجاري المسجل", "التاريخ والوقت الكاملان"],
            [80, 110, 100, 80, 180, 130, 100, 120, 170])
        frm_det.pack(fill="both", expand=True, padx=20, pady=(2, 4))
        tv_det.tag_configure("ret", foreground=RED)
        config_tree_stripes(tv_det)
        state = {"sel": None}

        def fill_days():
            tv_days.delete(*tv_days.get_children())
            with connect() as conn:
                rows = conn.execute("SELECT * FROM daily_reports "
                                    "ORDER BY report_date DESC").fetchall()
            for i, r in enumerate(rows):
                tv_days.insert("", "end", iid=r["report_date"], tags=stripe_tags(i),
                    values=(r["closed_at"] or "—", money(r["net_total"]),
                            money(r["total_returns"]), money(r["total_network"] or 0),
                            money(r["total_cash"] or 0), r["ops_count"], r["report_date"]))
            return rows

        def fill_details(dd):
            state["sel"] = dd
            tv_det.delete(*tv_det.get_children())
            with connect() as conn:
                rep = conn.execute("SELECT * FROM daily_reports WHERE report_date=?",
                                   (dd,)).fetchone()
                rows = conn.execute("SELECT * FROM operations WHERE date=? "
                                    "ORDER BY id", (dd,)).fetchall()
            matched = match_op_times_from_audit()
            for i, r in enumerate(rows):
                ts = matched.get(r["id"])
                tv_det.insert("", "end", tags=stripe_tags(i, r["type"] == "مرتجع"),
                    values=(r["type"], money(r["total"]), money(r["price"]),
                            f'{r["quantity"]:g}',
                            r["item_name"] + ret_ref_mark(r["type"] == "مرتجع",
                                                          r["original_op_id"]),
                            (r["customer_name"] or ""),
                            (r["seller_name"] or "—"), r["date"], ts or "—"))
            if rep is not None:
                # صف الإجماليات أسفل الجدول — مطابق لما في daily_reports حرفياً
                lbl_totals.config(fg="#1d4ed8", text=(
                    f"صف الإجماليات المطابق لـ daily_reports — عدد الحركات: {rep['ops_count']}"
                    f" | النقد: {money(rep['total_cash'] or 0)}"
                    f" | الشبكة: {money(rep['total_network'] or 0)}"
                    f" | المرتجعات: {money(rep['total_returns'])}"
                    f" | الصافي: {money(rep['net_total'])}"
                    f" | وقت الإغلاق: {rep['closed_at'] or '—'} (بنظام 24)"))
            else:
                lbl_totals.config(fg=RED, text="لا صف لهذا اليوم في daily_reports")

        def on_pick(_e=None):
            sel = tv_days.selection()
            if sel:
                fill_details(sel[0])

        tv_days.bind("<<TreeviewSelect>>", on_pick)
        tv_days.bind("<Double-1>", on_pick)
        # الأزرار: إغلاق يميناً — وزر الإصلاح للأدمن وحده يساراً ولا يظهر
        # للمدير ولا للبائع داخل هذه النافذة أبداً
        self.mk_btn(bar, "إغلاق", win.destroy, "#475569").pack(side="right", padx=6)
        if self.role == ADMIN_ROLE:
            b_fix = self.mk_btn(bar, "🛠️ إعادة احتساب وتوزيع حركات هذا اليوم",
                                lambda: self.rebuild_selected_day_reports(
                                    state["sel"], fill_days, fill_details),
                                "#b45309")
            b_fix.pack(side="left", padx=6)
            add_tip(b_fix, "للأدمن وحده: يشتق اليوم التجاري الصحيح لكل حركة من وقتها "
                           "بحد 05:00 وينقلها إليه ثم يعيد بناء صفوف daily_reports "
                           "للأيام المتأثرة — إصلاح اليومين المدموجين معاً")
        tk.Label(bar, text="اختر اليوم من الجدول أعلاه ثم اعرض حركاته",
                 bg=BG, fg=GRAY, font=("Segoe UI", 9)).pack(side="right", padx=8)
        fill_days()
        place_window(win, 1100, 700, 940, 560, can_resize=True)

    def rebuild_selected_day_reports(self, d, refill_days=None, refill_details=None):
        """★ إضافة (الإصدار 21 — المطلوب 2-2): زر الأدمن وحده «إعادة احتساب
        وتوزيع حركات هذا اليوم» — يشتق من وقت كل حركة (وقتها الحقيقي من سجل
        التدقيق حيثما تُطابق مطابقة تامة) يومها التجاري الصحيح بحد 05:00،
        وينقل الحركات إلى أيامها الصحيحة (تحديث تاريخها المسجل نفسه)، ثم
        يُحدّث أو يُنشئ صفوف daily_reports لكل التواريخ المتأثرة من جدول
        operations نفسه — وهذا هو الإصلاح المطلوب لليومين الذين دُمجا معاً.
        اليوم التجاري المفتوح الحالي لا يُقفل بتقرير هنا أبداً (يُحتسب عند
        إغلاقه الفعلي من تواريخ حركاته بعد النقل)، وصفوف اليوم المحدثة تحفظ
        وقت إغلاقها الأصلي والمنشأة حديثاً بلا وقت إغلاق («—»)"""
        if self.role != ADMIN_ROLE:
            messagebox.showwarning("صلاحية", "إعادة الاحتساب والتوزيع خاصة بالأدمن وحده")
            return
        if not d:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً")
            return
        with connect() as conn:
            day_ops = conn.execute("SELECT * FROM operations WHERE date=? "
                                    "ORDER BY id", (d,)).fetchall()
        trues = op_true_day_map()
        moves = []          # [(رقم الحركة, التاريخ المسجل القديم, اليوم الصحيح)]
        for r in day_ops:
            _ts, true_day = trues.get(r["id"], (None, r["date"]))
            if true_day and true_day != r["date"]:
                moves.append((r["id"], r["date"], true_day))
        affected = {d}
        per_target = {}
        for _oid, _frm, true_day in moves:
            affected.add(true_day)
            per_target[true_day] = per_target.get(true_day, 0) + 1
        open_d = business_day_open()
        preview = "\n".join(f"• {cnt} حركة ← يوم {t}"
                            for t, cnt in sorted(per_target.items())) or "• لا شيء"
        if not messagebox.askyesno("تأكيد إعادة الاحتساب والتوزيع",
                f"سيُعاد اشتقاق اليوم التجاري الصحيح لكل حركة من يوم {d} "
                f"بقاعدة الساعة 05:00:\n\n"
                f"عدد حركات اليوم: {len(day_ops)}\n"
                f"سيُنقل إلى أيامها الصحيحة: {len(moves)} حركة\n{preview}\n\n"
                "ستُحدَّث أو تُنشأ صفوف daily_reports لكل الأيام المتأثرة: "
                + "، ".join(sorted(affected)) +
                "\nلتطابق جدول operations تماماً بعد النقل (تُنشأ إن لم توجد)، "
                "واليوم التجاري المفتوح الحالي لا يُقفل بتقرير.\n\n"
                "هل تريد المتابعة؟"):
            return
        # ١) نقل الحركات إلى أيامها الصحيحة (معاملة واحدة على التاريخ المسجل)
        with connect() as conn:
            for oid, _frm, true_day in moves:
                conn.execute("UPDATE operations SET date=? WHERE id=?", (true_day, oid))
        # ٢) إعادة احتساب صفوف كل الأيام المتأثرة من operations نفسه
        rebuilt, created = [], []
        with connect() as conn:
            for dd in sorted(affected):
                if dd == open_d:
                    continue        # اليوم المفتوح لا يُقفل بتقرير — يُحتسب عند إغلاقه
                n, cash, netw, rets, net = day_totals(dd)
                has = conn.execute("SELECT 1 FROM daily_reports WHERE report_date=?",
                                   (dd,)).fetchone()
                if has:
                    conn.execute("""UPDATE daily_reports SET ops_count=?,total_sales=?,
                                    total_returns=?,net_total=?,total_cash=?,total_network=?
                                    WHERE report_date=?""",
                                 (n, cash + netw, rets, net, cash, netw, dd))
                    rebuilt.append(dd)
                else:
                    conn.execute("""INSERT INTO daily_reports(report_date,ops_count,total_sales,
                                    total_returns,net_total,total_cash,total_network,closed_at)
                                    VALUES(?,?,?,?,?,?,?,NULL)""",
                                 (dd, n, cash + netw, rets, net, cash, netw))
                    created.append(dd)
        audit("rebuild_reports",
              f"يوم {d}: أُعيد توزيع {len(moves)} حركة — الأيام المتأثرة: "
              f"{sorted(affected)} — أُعيد بناء {rebuilt or '—'} وأُنشئ {created or '—'}")
        if refill_days:
            try:
                refill_days()
            except Exception:
                pass
        if refill_details:
            try:
                refill_details(d)
            except Exception:
                pass
        try:
            self.refresh_archive()
        except Exception:
            pass
        messagebox.showinfo("تم",
            f"أُعيد توزيع {len(moves)} حركة إلى أيامها الصحيحة.\n"
            f"عدد الأيام المتأثرة: {len(affected)}\n"
            f"أُعيد بناء صفوف: {'، '.join(rebuilt) or '—'}\n"
            f"أُنشئت صفوف: {'، '.join(created) or '—'}")

    # ════════════════════════
    # ★★★ إضافات (الإصدار 23): محطة حركات الأيام الكاملة 🧭 ★★★
    # المطلوب 2: مشاهدة وتعديل كاملة — اليوم التجاري الحالي أعلى القائمة
    # بعنوان «اليوم الحالي (لم يُغلق بعد)» ثم الأيام المغلقة من الأحدث
    # للأقدم، وثلاثة أزرار (إضافة/تعديل/حذف) للأدمن والمدير، وزر إعادة
    # الاحتساب والتوزيع للأدمن وحده كما هو — وبعد كل تغيير يُعاد احتساب
    # صف اليوم المغلق في daily_reports وتُحدَّث العدادات والنوافذ فوراً —
    # وكلها دوال جديدة مستقلة لا تُلمس أي دالة قائمة إطلاقاً
    # ════════════════════════
    def show_past_days_station(self):
        """★ إضافة (الإصدار 23 — المطلوب 2): نافذة «حركات الأيام السابقة»
        محطة مشاهدة وتعديل كاملة — للأدمن والمدير فقط ولا يراها البائع
        نهائياً: صف اليوم التجاري الحالي أعلى القائمة بعنوان «اليوم الحالي
        (لم يُغلق بعد)»، وتحته الأيام المغلقة من daily_reports من الأحدث
        للأقدم (التاريخ وعدد الحركات والنقد والشبكة والمرتجعات والصافي
        ووقت الإغلاق بنظام 24)، واختيار أي يوم (حالي أو سابق) يعرض كل
        حركات ذلك اليوم من operations (الوقت بنظام 24 والصنف والكمية
        والسعر والإجمالي والنوع والعميل والبائع) مع صف إجماليات أسفل
        الجدول، والربط بالآلية القائمة نفسها (تاريخ الحركة المسجل =
        يومها التجاري)، وفيها للأدمن والمدير ثلاثة أزرار (إضافة حركة
        لهذا اليوم / تعديل الحركة المحددة / حذف الحركة المحددة)،
        وللأدمن وحده زر «إعادة احتساب وتوزيع حركات هذا اليوم» كما هو
        بلا أي تغيير — والنافذة القديمة show_past_days (قراءة فقط)
        باقية كما هي لم تُحذف"""
        if not manager_level(self.role):
            messagebox.showwarning("صلاحية", "حركات الأيام السابقة خاصة بالإدارة فقط (أدمن/مدير)")
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("حركات الأيام السابقة (محطة مشاهدة وتعديل كاملة)")
        win.configure(bg=BG)
        # القاعدة الذهبية: شريط الأزرار السفلي يُحزم أولاً فلا يُقص أبداً
        bar = tk.Frame(win, bg=BG)
        bar.pack(side="bottom", fill="x", padx=20, pady=(0, 12))
        lbl_totals = tk.Label(win, text="اختر يوماً من الجدول أعلاه لعرض حركاته",
                              bg=BG, fg=GRAY, font=("Segoe UI", 10, "bold"),
                              anchor="e", wraplength=940, justify="right")
        lbl_totals.pack(side="bottom", fill="x", padx=20)
        tk.Label(win, text="🧭 حركات الأيام السابقة", bg=BG, fg=DARK,
                 font=FT).pack(pady=(12, 2))
        tk.Label(win, text="محطة مشاهدة وتعديل كاملة — اليوم الحالي أعلى القائمة ثم "
                           "الأيام المغلقة (الأحدث أولاً)، والاختيار يعرض حركاته "
                           "كاملة بأوقاتها، والإضافة والتعديل والحذف للأدمن والمدير",
                 bg=BG, fg=GRAY, font=("Segoe UI", 10)).pack()
        frm_days, tv_days = self.mk_tree(win,
            ["وقت الإغلاق / الحالة", "الصافي", "المرتجعات", "الشبكة", "النقد", "عدد الحركات", "التاريخ"],
            [185, 110, 110, 105, 105, 95, 100])
        frm_days.pack(fill="x", padx=20, pady=(6, 2))
        tv_days.configure(height=8)
        config_tree_stripes(tv_days)
        # ★ إضافة (الإصدار 23 — المطلوب 2-1): تمييز صف اليوم الحالي بلون
        # أخضر فاتح ثابت كي يظهر أعلى القائمة بعنوانه للوهلة الأولى
        tv_days.tag_configure("cur", background="#dcfce7")
        frm_det, tv_det = self.mk_tree(win,
            ["النوع", "الإجمالي", "السعر", "الكمية", "اسم الصنف", "العميل", "البائع",
             "اليوم التجاري المسجل", "التاريخ والوقت الكاملان"],
            [80, 110, 100, 80, 180, 130, 100, 120, 170])
        frm_det.pack(fill="both", expand=True, padx=20, pady=(2, 4))
        tv_det.tag_configure("ret", foreground=RED)
        config_tree_stripes(tv_det)
        state = {"sel": None, "op": None}

        def fill_days():
            tv_days.delete(*tv_days.get_children())
            with connect() as conn:
                rows = conn.execute("SELECT * FROM daily_reports "
                                    "ORDER BY report_date DESC").fetchall()
            # ★ إضافة (الإصدار 23 — المطلوب 2-1): صف اليوم التجاري الحالي
            # أعلى القائمة بعنوان «اليوم الحالي (لم يُغلق بعد)» بمجاميع حية
            # من عملياته نفسها، وتحته الأيام المغلقة من الأحدث للأقدم كما
            # كانت في النافذة القديمة تماماً (اليوم المفتوح لا يظهر إن كان
            # مغلقاً بالأرشيف — التاريخ لا يتكرر في القائمة أبداً)
            open_d = business_day_open()
            if open_d and not is_closed(open_d):
                n, cash, netw, rets, net = day_totals(open_d)
                tv_days.insert("", "end", iid=open_d, tags=("cur",),
                    values=("اليوم الحالي (لم يُغلق بعد)", money(net),
                            money(rets), money(netw), money(cash), n, open_d))
            for i, r in enumerate(rows):
                tv_days.insert("", "end", iid=r["report_date"], tags=stripe_tags(i),
                    values=(r["closed_at"] or "—", money(r["net_total"]),
                            money(r["total_returns"]), money(r["total_network"] or 0),
                            money(r["total_cash"] or 0), r["ops_count"], r["report_date"]))
            return rows

        def fill_details(dd):
            state["sel"] = dd
            state["op"] = None
            tv_det.delete(*tv_det.get_children())
            with connect() as conn:
                rep = conn.execute("SELECT * FROM daily_reports WHERE report_date=?",
                                   (dd,)).fetchone()
                rows = conn.execute("SELECT * FROM operations WHERE date=? "
                                    "ORDER BY id", (dd,)).fetchall()
            # ★ إضافة (الإصدار 23): وقت الحركة — من سجل التدقيق حيثما تُطابق
            # (الآلية القائمة نفسها)، وإلا من أحداث add_operation للحركات
            # المضافة من المحطة (12:00 ظهراً من يومها / وقت إضافتها الفعلي)
            matched = match_op_times_from_audit()
            added = station_added_op_times()
            for i, r in enumerate(rows):
                ts = matched.get(r["id"]) or added.get(r["id"])
                tv_det.insert("", "end", iid=str(r["id"]),
                    tags=stripe_tags(i, r["type"] == "مرتجع"),
                    values=(r["type"], money(r["total"]), money(r["price"]),
                            f'{r["quantity"]:g}',
                            r["item_name"] + ret_ref_mark(r["type"] == "مرتجع",
                                                          r["original_op_id"]),
                            (r["customer_name"] or ""),
                            (r["seller_name"] or "—"), r["date"], ts or "—"))
            if rep is not None:
                # صف الإجماليات أسفل الجدول — مطابق لما في daily_reports حرفياً
                lbl_totals.config(fg="#1d4ed8", text=(
                    f"صف الإجماليات المطابق لـ daily_reports — يوم {dd} — عدد الحركات: {rep['ops_count']}"
                    f" | النقد: {money(rep['total_cash'] or 0)}"
                    f" | الشبكة: {money(rep['total_network'] or 0)}"
                    f" | المرتجعات: {money(rep['total_returns'])}"
                    f" | الصافي: {money(rep['net_total'])}"
                    f" | وقت الإغلاق: {rep['closed_at'] or '—'} (بنظام 24)"))
            elif dd == business_day_open():
                # ★ إضافة (الإصدار 23): إجماليات حية لليوم الحالي (لم يُغلق بعد)
                n, cash, netw, rets, net = day_totals(dd)
                lbl_totals.config(fg="#15803d", text=(
                    f"صف الإجماليات الحي لليوم الحالي (لم يُغلق بعد) — يوم {dd} — "
                    f"عدد الحركات: {n}"
                    f" | النقد: {money(cash)}"
                    f" | الشبكة: {money(netw)}"
                    f" | المرتجعات: {money(rets)}"
                    f" | الصافي: {money(net)} — يُحفظ التقرير عند إغلاق اليوم"))
            else:
                lbl_totals.config(fg=RED, text="لا صف لهذا اليوم في daily_reports")

        def on_pick_day(_e=None):
            sel = tv_days.selection()
            if sel:
                fill_details(sel[0])

        def on_pick_op(_e=None):
            sel = tv_det.selection()
            state["op"] = int(sel[0]) if sel else None

        tv_days.bind("<<TreeviewSelect>>", on_pick_day)
        tv_days.bind("<Double-1>", on_pick_day)
        tv_det.bind("<<TreeviewSelect>>", on_pick_op)
        tv_det.bind("<Double-1>", on_pick_op)
        # ربط دوال التعبئة بالحالة ليستخدمها المعالج المركزي وزر الأدمن بعد
        # كل تغيير — تحديث صف اليوم وجدول التفاصيل داخل النافذة فوراً
        state["refill_days"] = fill_days
        state["refill_details"] = fill_details
        # الأزرار: إغلاق يميناً — وأزرار المحطة الثلاثة يساراً للأدمن
        # والمدير (النافذة نفسها محروسة بالدور فلا يراها البائع نهائياً)،
        # وزر الإصلاح للأدمن وحده كما هو ولا يظهر للمدير أبداً
        self.mk_btn(bar, "إغلاق", win.destroy, "#475569").pack(side="right", padx=6)
        b_del = self.mk_btn(bar, "🗑️ حذف الحركة المحددة",
                            lambda: self._station_delete_op(state), "#dc2626")
        b_del.pack(side="left", padx=6)
        add_tip(b_del, "حذف الحركة المختارة من جدول التفاصيل — رسالة تأكيد تعرض "
                       "تفاصيلها كاملة، ثم تُنقل إلى سلة المحذوفات بنفس آلية الحذف "
                       "القائمة (وليست مسحاً نهائياً) مع الاحتفاظ بمرجع يومها الأصلي")
        b_edit = self.mk_btn(bar, "✏️ تعديل الحركة المحددة",
                             lambda: self._station_edit_op(state), "#1d4ed8")
        b_edit.pack(side="left", padx=6)
        add_tip(b_edit, "تعديل الحركة المختارة من جدول التفاصيل — نفس حقول الإضافة "
                        "معبأة بالقيم الحالية، والإجمالي يُعاد احتسابه تلقائيًا، وقبل "
                        "الحفظ تأكيد يعرض القيمة القديمة والجديدة لكل حقل معدّل")
        b_add = self.mk_btn(bar, "➕ إضافة حركة لهذا اليوم",
                            lambda: self._station_add_op(state), GREEN)
        b_add.pack(side="left", padx=6)
        add_tip(b_add, "إضافة حركة جديدة على اليوم المختار — إن كان اليوم الحالي "
                       "سُجلت بوقت الآن، وإلا بساعة 12:00 ظهراً من يومه حتى تُنسب "
                       "لليوم الصحيح، والإجمالي تلقائي = الكمية × السعر")
        if self.role == ADMIN_ROLE:
            b_fix = self.mk_btn(bar, "🛠️ إعادة احتساب وتوزيع حركات هذا اليوم",
                                lambda: self.rebuild_selected_day_reports(
                                    state["sel"], state["refill_days"],
                                    state["refill_details"]),
                                "#b45309")
            b_fix.pack(side="left", padx=6)
            add_tip(b_fix, "للأدمن وحده: يشتق اليوم التجاري الصحيح لكل حركة من وقتها "
                           "بحد 05:00 وينقلها إليه ثم يعيد بناء صفوف daily_reports "
                           "للأيام المتأثرة — إصلاح اليومين المدموجين معاً")
        tk.Label(bar, text="اختر اليوم من الجدول أعلاه ثم اعرض حركاته وعدّلها",
                 bg=BG, fg=GRAY, font=("Segoe UI", 9)).pack(side="right", padx=8)
        fill_days()
        place_window(win, 1120, 720, 960, 580, can_resize=True)

    def _station_after_change(self, dd, kind, state, op_id=None):
        """★ إضافة (الإصدار 23 — المطلوب 2-4): المعالج المركزي الموحد بعد كل
        إضافة أو تعديل أو حذف من المحطة — إن كان اليوم مغلقًا أُعيد احتساب
        صفه في daily_reports من عملياته فوراً (ops_count وtotal_cash
        وtotal_network وtotal_returns وnet_total) فيبقى التقرير مطابقاً
        للحركات دائماً، وإن كان هو اليوم التجاري الحالي حُدّثت العدادات
        والمجاميع المعروضة على الشاشة الرئيسية فورًا، ثم يُحدَّث صف اليوم
        وجدول التفاصيل داخل النافذة فوراً مع إشعار نجاح عربي قصير — ولا
        يُسجل هنا أي تدقيق (كل زر يسجل حدثه الخاص كاملاً قبل الوصول هنا)"""
        closed = is_closed(dd)
        if closed:
            recalc_closed_day_report(dd)
        if dd == business_day_open():
            try:
                self.refresh_today(); self.refresh_stats(); self.update_closed_banner()
            except Exception:
                pass
        try:
            self.refresh_archive()
        except Exception:
            pass
        rf_days = (state or {}).get("refill_days")
        rf_det = (state or {}).get("refill_details")
        if rf_days:
            try:
                rf_days()
            except Exception:
                pass
        if rf_det:
            try:
                rf_det(dd)
            except Exception:
                pass
        tail = " وأُعيد احتساب تقريره في الأرشيف فورًا" if closed else ""
        notices = {
            "add":    f"✔ أُضيفت حركة رقم {op_id or '—'} إلى يوم {dd}{tail}",
            "edit":   f"✏️ تم تعديل حركة رقم {op_id or '—'} من يوم {dd}{tail}",
            "delete": f"🗑 حُذفت حركة رقم {op_id or '—'} من يوم {dd} (في سلة المحذوفات){tail}",
        }
        try:
            self.lbl_status.config(text=notices.get(kind, "✔ تم"), fg=GREEN)
        except Exception:
            pass

    def _station_add_op(self, state):
        """★ إضافة (الإصدار 23 — المطلوب 2-3ا): زر «إضافة حركة لهذا اليوم» —
        نموذج عربي فيه اسم الصنف والكمية والسعر والنوع (نقداً/شبكة/مرتجع)
        واسم العميل واسم البائع، والإجمالي يُحسب تلقائيًا = الكمية × السعر
        (المرتجع يُخزَّن سالباً كما يُخزَّن دائماً)، ووقت الحركة الجديدة:
        الوقت الحالي إن كان اليوم المختار هو اليوم التجاري الحالي، وإلا
        ساعة 12:00 ظهراً بتاريخ ذلك اليوم — مع رسالة تأكيد قبل الحفظ ثم
        تدقيق add_operation باليوم المتأثر والدور والقيم كاملة"""
        dd = state.get("sel")
        if not dd:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً")
            return
        open_d = business_day_open()
        # ★ إضافة (الإصدار 23 — المطلوب 2-3ا): قاعدة وقت الحركة الجديدة —
        # اليوم الحالي بوقت الآن، وأي يوم سابق بساعة 12:00 ظهراً من يومه
        is_current = bool(open_d) and dd == open_d and not is_closed(dd)
        op_ts = (datetime.now().strftime("%Y-%m-%d %H:%M:%S") if is_current
                 else f"{dd} 12:00:00")
        win = self.register_window(tk.Toplevel(self))
        win.title(f"➕ إضافة حركة ليوم {dd}"
                  + (" — اليوم الحالي (وقت الآن)" if is_current
                     else " — يوم سابق (12:00 ظهراً)"))
        win.configure(bg=BG)
        # القاعدة الذهبية: شريط الأزرار السفلي يُحزم أولاً فلا يُقص أبداً
        bar = tk.Frame(win, bg=BG)
        bar.pack(side="bottom", fill="x", padx=18, pady=(0, 14))
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        card.pack(fill="both", expand=True, padx=18, pady=(12, 6))
        tk.Label(card, text=f"➕ إضافة حركة جديدة على اليوم التجاري {dd}",
                 bg=CARD, fg=DARK, font=FT).pack(pady=(10, 4))
        tk.Label(card, text=(f"وقت الحركة: {op_ts}"
                             + (" (الوقت الحالي)" if is_current
                                else " (12:00 ظهراً من يومه حتى تُنسب لليوم الصحيح)")),
                 bg=CARD, fg=GRAY, font=("Segoe UI", 10)).pack(pady=(0, 6))
        grid = tk.Frame(card, bg=CARD)
        grid.pack(fill="both", expand=True, padx=10, pady=8)

        def _row(lbl_txt, widget, row_i):
            tk.Label(grid, text=lbl_txt, bg=CARD, fg=GRAY,
                     font=("Segoe UI", 10, "bold")).grid(
                row=row_i, column=0, sticky="e", padx=8, pady=6)
            widget.grid(row=row_i, column=1, sticky="w", padx=8, pady=6)
            return widget

        e_item = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        _row("اسم الصنف:", e_item, 0)
        e_qty = tk.Entry(grid, font=F, justify="center", relief="solid", bd=1, width=12)
        _row("الكمية:", e_qty, 1)
        e_price = tk.Entry(grid, font=F, justify="center", relief="solid", bd=1, width=12)
        _row("السعر:", e_price, 2)
        cb_type = ttk.Combobox(grid, font=F, width=10, state="readonly",
                               values=["نقداً", "شبكة", "مرتجع"])
        cb_type.set("نقداً")
        _row("النوع:", cb_type, 3)
        e_cust = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        _row("اسم العميل:", e_cust, 4)
        e_seller = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        e_seller.insert(0, CURRENT_USER["name"])
        _row("اسم البائع:", e_seller, 5)
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع): السبب الإلزامي
        # والملاحظة الاختيارية عند إضافة حركة مرتجع من محطة الأيام —
        # يظهران عند اختيار «مرتجع» فقط ويختفيان معه
        fr_ret4 = tk.Frame(grid, bg=CARD)
        rr4 = tk.Frame(fr_ret4, bg=CARD); rr4.grid(row=0, column=0, sticky="ew", pady=2)
        tk.Label(rr4, text="سبب المرتجع:", bg=CARD, fg=RED,
                 font=("Segoe UI", 10, "bold")).pack(side="right", padx=(0, 8))
        cb_reason4 = ttk.Combobox(rr4, font=F, width=22, state="readonly",
                                  values=list(RETURN_REASONS))
        cb_reason4.pack(side="right")
        nn4 = tk.Frame(fr_ret4, bg=CARD); nn4.grid(row=1, column=0, sticky="ew", pady=2)
        tk.Label(nn4, text="ملاحظة (اختياري):", bg=CARD, fg=GRAY,
                 font=("Segoe UI", 10, "bold")).pack(side="right", padx=(0, 8))
        e_note4 = tk.Entry(nn4, font=F, justify="center", relief="solid", bd=1, width=24)
        e_note4.pack(side="right")
        fr_ret4.grid(row=6, column=0, columnspan=2, sticky="ew")
        def _sync_ret4(_e=None):
            try:
                if cb_type.get() == "مرتجع":
                    fr_ret4.grid()
                else:
                    fr_ret4.grid_remove()
                    cb_reason4.set("")
            except Exception:
                pass
        cb_type.bind("<<ComboboxSelected>>", _sync_ret4)
        _sync_ret4()
        lbl_tot = tk.Label(grid, text="", bg=CARD, fg=DARK,
                           font=("Segoe UI", 11, "bold"), justify="center")
        # ★ تعديل مصرح به (المرحلة الرابعة): الإجمالي نزل صفين لصفوف السبب
        lbl_tot.grid(row=8, column=0, columnspan=2, pady=(10, 4))

        def _recalc(_e=None):
            q, pr = to_num(e_qty.get()), to_num(e_price.get())
            t = cb_type.get()
            if q is None or pr is None or q <= 0 or pr < 0:
                lbl_tot.config(text="الإجمالي (تلقائي): — أكمل الكمية والسعر أولًا", fg=RED)
                return None
            tot = q * pr
            if t == "مرتجع":
                tot = -tot
                lbl_tot.config(text=f"الإجمالي (تلقائي) = {q:g} × {pr:g} = {tot:g} "
                                    "(مرتجع بقيمة سالبة كما يُخزَّن دائماً)", fg=RED)
            else:
                lbl_tot.config(text=f"الإجمالي (تلقائي) = {q:g} × {pr:g} = {tot:g}", fg=GREEN)
            return tot

        for w in (e_qty, e_price):
            w.bind("<KeyRelease>", _recalc)
        cb_type.bind("<<ComboboxSelected>>", _recalc)

        def do_save():
            item = e_item.get().strip()
            q, pr = to_num(e_qty.get()), to_num(e_price.get())
            t = cb_type.get()
            cust = e_cust.get().strip()
            seller = e_seller.get().strip()
            if not item:
                messagebox.showwarning("تنبيه", "اكتب اسم الصنف أولاً", parent=win)
                return
            if q is None or q <= 0:
                messagebox.showwarning("تنبيه", f"الكمية غير صحيحة: «{e_qty.get()}»\n"
                                     "أدخل رقماً أكبر من صفر", parent=win)
                return
            if pr is None or pr < 0:
                messagebox.showwarning("تنبيه", f"السعر غير صحيح: «{e_price.get()}»\n"
                                     "أدخل رقماً صحيحاً", parent=win)
                return
            total = q * pr
            if t == "مرتجع":
                total = -total
            # ★★★ إضافة (المرحلة الرابعة): سبب المرتجع إلزامي من المحطة
            # أيضاً — أي مرتجع مهما كان مصدره لا يتم دون سبب
            _reason4 = ""
            _note4 = ""
            if t == "مرتجع":
                _reason4 = cb_reason4.get().strip()
                if not _reason4:
                    messagebox.showwarning("سبب المرتجع إلزامي",
                        "اختر سبب المرتجع من القائمة أولاً —\n"
                        "لا تُسجَّل عملية مرتجع دون سبب.", parent=win)
                    return
                _note4 = e_note4.get().strip()
            if not messagebox.askyesno("تأكيد الإضافة",
                    f"إضافة حركة جديدة على اليوم التجاري {dd}:\n\n"
                    f"الصنف: {item}\nالكمية: {q:g}\nالسعر: {pr:g}\nالنوع: {t}\n"
                    f"الإجمالي (تلقائي): {total:g}\n"
                    f"العميل: {cust or '—'}\nالبائع: {seller or '—'}\n"
                    f"وقت الحركة: {op_ts}\n\n"
                    + ("اليوم مغلق — سيُعاد احتساب صف تقريره فوراً بعد الحفظ"
                       if is_closed(dd) else
                       "هذا هو اليوم التجاري الحالي — تُحدَّث عدادات الشاشة الرئيسية فوراً")
                    + "\n\nهل تريد الحفظ؟", parent=win):
                return
            # ★★★ إضافة (المرحلة الرابعة): رقم فاتورة متسلسل لا يتكرر —
            # يُجلب قبل فتح معاملة الحفظ (كاتب ثانٍ داخل معاملة مفتوحة
            # يقفل القاعدة)، ثم يُسند للعملية بعد إدراجها مباشرة مع سبب
            # المرتجع وملاحظته
            _inv4s = None
            try:
                _inv4s = get_next_invoice_number()
            except Exception as e:
                log_error(e, sys.exc_info()[2])
            with connect() as conn:
                cur = conn.execute(
                    "INSERT INTO operations(date,item_name,quantity,price,total,"
                    "type,customer_name,seller_name,original_op_id)"
                    " VALUES(?,?,?,?,?,?,?,?,?)",
                    (dd, item, q, pr, total, t, cust, seller, None))
                nid = cur.lastrowid
                # ★★★ إضافة (المرحلة الرابعة): وسم حركة المحطة برقم الفاتورة
                # وسبب المرتجع وملاحظته بعد إدراجها مباشرة
                try:
                    conn.execute("UPDATE operations SET invoice_number=?, "
                                 "return_reason=?, return_note=? WHERE id=?",
                                 (_inv4s, _reason4 or None, _note4 or None, nid))
                except Exception as e:
                    log_error(e, sys.exc_info()[2])
            audit("add_operation",
                  f"رقم {nid} يوم {dd} — {t}: {item} — {q:g} × {pr:g} = {total:g}"
                  f" | عميل: {cust or '—'} | بائع: {seller or '—'}"
                  f" | الدور: {self.role} | وقت الحركة: {op_ts}"
                  f" | أُضيفت من محطة حركات الأيام")
            win.destroy()
            self._station_after_change(dd, "add", state, op_id=nid)

        def do_cancel():
            win.destroy()

        self.mk_btn(bar, "💾 حفظ الحركة", do_save, GREEN).pack(side="right", padx=6)
        self.mk_btn(bar, "إلغاء", do_cancel, "#475569").pack(side="right", padx=6)
        e_item.bind("<Return>", lambda _e: do_save())
        place_window(win, 580, 620)

    def _edit_op_dialog_v23(self, r, dd, on_saved=None):
        """★ إضافة (الإصدار 23 — المطلوب 2-3ب + المطلوب 3): نافذة التعديل
        المركزية الوحيدة لأي حركة — تُفتح من محطة حركات الأيام أو من زر
        «✏️ تعديل الحركة» بجانب جدول اليوم في الشاشة الرئيسية: نفس النافذة
        ونفس المنطق بلا أي تكرار كود. تعرض بيانات الحركة الحالية معبأة
        وتسمح بتعديل اسم الصنف والكمية والسعر والنوع (نقداً/شبكة/مرتجع)
        واسم العميل واسم البائع، والإجمالي يُعاد احتسابه تلقائيًا = الكمية
        × السعر (المرتجع يُخزَّن سالباً كما يُخزَّن دائماً)، وقبل الحفظ رسالة
        تأكيد تعرض القيمة القديمة والجديدة لكل حقل معدّل، وبعده: تحديث صف
        الحركة فورًا + تدقيق edit_operation بالقيم القديمة والجديدة كاملة
        والدور، ثم on_saved إن أُعطي (محطة الأيام تعيد احتساب صف اليوم
        المغلق وتحدّث النافذة) وإلا تحديث مجاميع اليوم والعدادات كالمعتاد
        — والدالة القديمة _edit_op_dialog_v21 باقية كما هي لم تُحذف"""
        win = self.register_window(tk.Toplevel(self))
        win.title(f"✏️ تعديل الحركة رقم {r['id']} — يوم {dd}")
        win.configure(bg=BG)
        # القاعدة الذهبية: شريط الأزرار السفلي يُحزم أولاً فلا يُقص أبداً
        bar = tk.Frame(win, bg=BG)
        bar.pack(side="bottom", fill="x", padx=18, pady=(0, 14))
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        card.pack(fill="both", expand=True, padx=18, pady=(12, 6))
        tk.Label(card, text=f"✏️ تعديل الحركة رقم {r['id']} — {r['item_name']}",
                 bg=CARD, fg=DARK, font=FT).pack(pady=(10, 4))
        tk.Label(card, text=(f"البيانات الحالية: النوع {r['type']} | الكمية {r['quantity']:g} | "
                             f"السعر {r['price']:g} | الإجمالي {r['total']:g}\n"
                             + ("هذا اليوم مغلق — يُعاد احتساب صف تقريره في الأرشيف فورًا بعد الحفظ"
                                if is_closed(dd) else
                                "هذا هو اليوم التجاري الحالي — لم يُغلق بعد")),
                 bg=CARD, fg=GRAY, font=("Segoe UI", 10), justify="center").pack(pady=(0, 6))
        grid = tk.Frame(card, bg=CARD)
        grid.pack(fill="both", expand=True, padx=10, pady=8)

        def _row(lbl_txt, widget, row_i):
            tk.Label(grid, text=lbl_txt, bg=CARD, fg=GRAY,
                     font=("Segoe UI", 10, "bold")).grid(
                row=row_i, column=0, sticky="e", padx=8, pady=6)
            widget.grid(row=row_i, column=1, sticky="w", padx=8, pady=6)
            return widget

        e_item = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        e_item.insert(0, r["item_name"])
        _row("اسم الصنف:", e_item, 0)
        e_qty = tk.Entry(grid, font=F, justify="center", relief="solid", bd=1, width=12)
        e_qty.insert(0, f'{r["quantity"]:g}')
        _row("الكمية:", e_qty, 1)
        e_price = tk.Entry(grid, font=F, justify="center", relief="solid", bd=1, width=12)
        e_price.insert(0, f'{r["price"]:g}')
        _row("السعر:", e_price, 2)
        cb_type = ttk.Combobox(grid, font=F, width=10, state="readonly",
                               values=["نقداً", "شبكة", "مرتجع"])
        cb_type.set(r["type"])
        _row("النوع:", cb_type, 3)
        e_cust = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        e_cust.insert(0, r["customer_name"] or "")
        _row("اسم العميل:", e_cust, 4)
        e_seller = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        e_seller.insert(0, r["seller_name"] or "")
        _row("اسم البائع:", e_seller, 5)
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع): عرض/تعديل سبب المرتجع
        # وملاحظته — إلزامي للمرتجع عند الحفظ (القديمة بلا سبب تعبأ فارغة
        # ويُطلب السبب عند تعديلها)، وتُخزن القيم في العمودين الجديدين
        _old_reason4 = row_val4(r, "return_reason")
        _old_note4 = row_val4(r, "return_note")
        cb_reason4 = ttk.Combobox(grid, font=F, width=24, state="readonly",
                                  values=list(RETURN_REASONS))
        cb_reason4.set(_old_reason4)
        _row("سبب المرتجع:", cb_reason4, 6)
        e_note4 = tk.Entry(grid, font=F, justify="center", relief="solid", bd=1, width=26)
        e_note4.insert(0, _old_note4)
        _row("ملاحظة المرتجع:", e_note4, 7)
        lbl_tot = tk.Label(grid, text="", bg=CARD, fg=DARK,
                           font=("Segoe UI", 11, "bold"), justify="center")
        # ★ تعديل مصرح به (المرحلة الرابعة): الإجمالي نزل صفين لصفوف السبب
        lbl_tot.grid(row=8, column=0, columnspan=2, pady=(10, 4))

        def _recalc(_e=None):
            q, pr = to_num(e_qty.get()), to_num(e_price.get())
            t = cb_type.get()
            if q is None or pr is None or q <= 0 or pr < 0:
                lbl_tot.config(text="الإجمالي (تلقائي): — أكمل الكمية والسعر أولًا", fg=RED)
                return None
            tot = q * pr
            if t == "مرتجع":
                tot = -tot
                lbl_tot.config(text=f"الإجمالي (تلقائي) = {q:g} × {pr:g} = {tot:g} "
                                    "(مرتجع بقيمة سالبة كما يُخزَّن دائماً)", fg=RED)
            else:
                lbl_tot.config(text=f"الإجمالي (تلقائي) = {q:g} × {pr:g} = {tot:g}", fg=GREEN)
            return tot

        for w in (e_qty, e_price):
            w.bind("<KeyRelease>", _recalc)
        cb_type.bind("<<ComboboxSelected>>", _recalc)
        _recalc()

        def do_save():
            item = e_item.get().strip()
            q, pr = to_num(e_qty.get()), to_num(e_price.get())
            t = cb_type.get()
            cust = e_cust.get().strip()
            seller = e_seller.get().strip()
            if not item:
                messagebox.showwarning("تنبيه", "اكتب اسم الصنف أولاً", parent=win)
                return
            if q is None or q <= 0:
                messagebox.showwarning("تنبيه", f"الكمية غير صحيحة: «{e_qty.get()}»\n"
                                     "أدخل رقماً أكبر من صفر", parent=win)
                return
            if pr is None or pr < 0:
                messagebox.showwarning("تنبيه", f"السعر غير صحيح: «{e_price.get()}»\n"
                                     "أدخل رقماً صحيحاً", parent=win)
                return
            total = q * pr
            if t == "مرتجع":
                total = -total
            # ★★★ إضافة (المرحلة الرابعة): سبب المرتجع إلزامي عند تعديل أي
            # حركة مرتجع (والملاحظة اختيارية)
            if t == "مرتجع" and not cb_reason4.get().strip():
                messagebox.showwarning("سبب المرتجع إلزامي",
                    "اختر سبب المرتجع من القائمة أولاً —\n"
                    "لا يُحفظ تعديل مرتجع دون سبب.", parent=win)
                return
            changed = []
            # ★★★ إضافة (المرحلة الرابعة): سبب وملاحظة المرتجع في قائمة
            # التغييرات المعروضة للتأكيد
            if t == "مرتجع" and cb_reason4.get().strip() != _old_reason4:
                changed.append(("سبب المرتجع", _old_reason4 or "—", cb_reason4.get().strip()))
            if (e_note4.get().strip() or "") != (_old_note4 or ""):
                changed.append(("ملاحظة المرتجع", _old_note4 or "—",
                                e_note4.get().strip() or "—"))
            if item != r["item_name"]:
                changed.append(("اسم الصنف", r["item_name"], item))
            if q != (r["quantity"] or 0):
                changed.append(("الكمية", f'{r["quantity"]:g}', f"{q:g}"))
            if pr != (r["price"] or 0):
                changed.append(("السعر", f'{r["price"]:g}', f"{pr:g}"))
            if t != r["type"]:
                changed.append(("النوع", r["type"], t))
            if cust != (r["customer_name"] or ""):
                changed.append(("اسم العميل", r["customer_name"] or "—", cust or "—"))
            if seller != (r["seller_name"] or ""):
                changed.append(("اسم البائع", r["seller_name"] or "—", seller or "—"))
            if total != (r["total"] or 0):
                changed.append(("الإجمالي", f'{r["total"]:g}', f"{total:g}"))
            if not changed:
                messagebox.showinfo("تنبيه", "لم تتغير أي قيمة — لا شيء يحتاج التعديل",
                                    parent=win)
                return
            lines = "\n".join(f"• {f}: {old} ← {new}" for f, old, new in changed)
            if not messagebox.askyesno("تأكيد التعديل",
                    f"تعديل الحركة رقم {r['id']} (يوم {dd}):\n\n{lines}\n\n"
                    + ("اليوم مغلق — سيُعاد احتساب صف تقريره فوراً بعد الحفظ"
                       if is_closed(dd) else
                       "هذا هو اليوم التجاري الحالي — تُحدَّث العدادات فوراً")
                    + "\n\nهل تريد حفظ التعديل؟", parent=win):
                return
            with connect() as conn:
                # ★ تعديل مصرح به (المرحلة الرابعة): حفظ سبب المرتجع وملاحظته
                # مع التعديل (NULL عند غير المرتجع)
                conn.execute("""UPDATE operations SET item_name=?,quantity=?,price=?,
                                total=?,type=?,customer_name=?,seller_name=?,
                                return_reason=?,return_note=?
                                WHERE id=?""",
                             (item, q, pr, total, t, cust, seller,
                              (cb_reason4.get().strip() if t == "مرتجع" else None),
                              (e_note4.get().strip() if t == "مرتجع" else None),
                              r["id"]))
            audit("edit_operation",
                  f"رقم {r['id']} يوم {dd} — " +
                  "؛ ".join(f"{f}: {old} ← {new}" for f, old, new in changed)
                  + f" | الدور: {self.role}")
            win.destroy()
            if on_saved:
                try:
                    on_saved()
                except Exception:
                    pass
            else:
                self.refresh_today(); self.refresh_stats()
                try:
                    self.lbl_status.config(text=f"✏️ تم تعديل الحركة رقم {r['id']}", fg=GREEN)
                except Exception:
                    pass

        def do_cancel():
            win.destroy()

        self.mk_btn(bar, "💾 حفظ التعديل", do_save, GREEN).pack(side="right", padx=6)
        self.mk_btn(bar, "إلغاء", do_cancel, "#475569").pack(side="right", padx=6)
        e_item.bind("<Return>", lambda _e: do_save())
        place_window(win, 580, 620)

    def _station_edit_op(self, state):
        """★ إضافة (الإصدار 23 — المطلوب 2-3ب): زر «تعديل الحركة المحددة» من
        المحطة — يعمل على حركة أي يوم (حالي أو سابق) بعد اختيارها من جدول
        التفاصيل، ويفتح نافذة التعديل المركزية نفسها المستخدمة من الشاشة
        الرئيسية بلا أي تكرار كود — والتعديل على اليوم المغلق يعيد احتساب
        صف تقريره في الأرشيف فوراً بعد الحفظ"""
        dd = state.get("sel")
        op_id = state.get("op")
        if not dd:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً")
            return
        if not op_id:
            messagebox.showinfo("تنبيه", "اختر حركة من جدول التفاصيل أولاً")
            return
        with connect() as conn:
            r = conn.execute("SELECT * FROM operations WHERE id=?", (op_id,)).fetchone()
        if r is None:
            messagebox.showwarning("تنبيه", "هذه الحركة لم تعد موجودة")
            return
        if r["date"] != dd:
            messagebox.showwarning("تنبيه", "هذه الحركة ليست من اليوم المختار")
            return
        self._edit_op_dialog_v23(
            r, dd, on_saved=lambda: self._station_after_change(
                dd, "edit", state, op_id=r["id"]))

    def _quick_edit_today_v23(self):
        """★ إضافة (الإصدار 23 — المطلوب 3): زر «✏️ تعديل الحركة» بجانب جدول
        عمليات اليوم في الشاشة الرئيسية — للأدمن والمدير فقط حصراً بالدور
        (لا يظهر للبائع نهائياً حتى لو كان هو من سجل الحركة)، وبعد اختيار
        حركة من جدول اليوم التجاري الحالي فقط، ويفتح نفس نافذة التعديل
        المركزية ونفس المنطق المستخدم في المطلوب 2 بلا أي تكرار كود —
        والدالة القديمة edit_selected_op_v21 باقية كما هي لم تُحذف"""
        if not manager_level(self.role):
            messagebox.showwarning("صلاحية", "تعديل الحركات خاص بالإدارة فقط (أدمن/مدير)")
            return
        sel = self.tv_today.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر حركة من الجدول أولاً")
            return
        d = business_day_open()
        if not d or is_closed(d):
            messagebox.showwarning("اليوم مغلق", "التعديل على حركات اليوم التجاري المفتوح فقط")
            return
        op_id = int(sel[0])
        with connect() as conn:
            r = conn.execute("SELECT * FROM operations WHERE id=?", (op_id,)).fetchone()
        if r is None:
            return
        if r["date"] != d:
            messagebox.showwarning("اليوم مغلق",
                "هذه الحركة ليست من اليوم التجاري الحالي — لا تُعدَّل")
            return
        self._edit_op_dialog_v23(r, d)

    def _station_delete_op(self, state):
        """★ إضافة (الإصدار 23 — المطلوب 2-3ج): زر «حذف الحركة المحددة» —
        رسالة تأكيد تعرض تفاصيل الحركة كاملة (الرقم واليوم والوقت والصنف
        والكمية والسعر والإجمالي والنوع والعميل والبائع)، ثم تُنقل إلى
        جدول سلة المحذوفات deleted_operations بنفس آلية الحذف القائمة
        تماماً (recycle_add — وليست مسحاً نهائياً) مع الاحتفاظ بمرجع يومها
        الأصلي، ثم تدقيق delete_operation وإعادة احتساب تقرير اليوم فوراً"""
        dd = state.get("sel")
        op_id = state.get("op")
        if not dd:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً")
            return
        if not op_id:
            messagebox.showinfo("تنبيه", "اختر حركة من جدول التفاصيل أولاً")
            return
        with connect() as conn:
            r = conn.execute("SELECT * FROM operations WHERE id=?", (op_id,)).fetchone()
        if r is None:
            messagebox.showwarning("تنبيه", "هذه الحركة لم تعد موجودة")
            return
        if r["date"] != dd:
            messagebox.showwarning("تنبيه", "هذه الحركة ليست من اليوم المختار")
            return
        # وقت الحركة للعرض — من سجل التدقيق حيثما تُطابق، وإلا من أحداث
        # add_operation للمضافة من المحطة (آلية العرض نفسها في الجدول)
        matched = match_op_times_from_audit()
        added = station_added_op_times()
        ts = matched.get(op_id) or added.get(op_id) or "—"
        if not messagebox.askyesno("تأكيد الحذف",
                f"حذف الحركة رقم {r['id']} من يوم {dd}:\n\n"
                f"الصنف: {r['item_name']}\nالكمية: {r['quantity']:g}\n"
                f"السعر: {r['price']:g}\nالإجمالي: {r['total']:g}\n"
                f"النوع: {r['type']}\nالعميل: {r['customer_name'] or '—'}\n"
                f"البائع: {r['seller_name'] or '—'}\nوقت الحركة: {ts}\n\n"
                "ستُنقل إلى سلة المحذوفات بنفس آلية الحذف القائمة (وليست مسحاً "
                "نهائياً) مع الاحتفاظ بمرجع يومها الأصلي، ويُعاد احتساب تقرير "
                "اليوم فوراً.\n\nهل تريد المتابعة؟"):
            return
        recycle_add(r, CURRENT_USER["name"])   # الآلية القائمة نفسها بلا أي تغيير
        with connect() as conn:
            conn.execute("DELETE FROM operations WHERE id=?", (op_id,))
        audit("delete_operation",
              f"رقم {r['id']} يوم {dd} — {r['type']}: {r['item_name']} — "
              f"{r['quantity']:g} × {r['price']:g} = {r['total']:g}"
              f" | عميل: {r['customer_name'] or '—'} | بائع: {r['seller_name'] or '—'}"
              f" | الدور: {self.role} | وقت الحركة: {ts}"
              f" | نُقلت إلى سلة المحذوفات بمرجع يومها الأصلي {dd}")
        self._station_after_change(dd, "delete", state, op_id=r["id"])

    # ═════════════════════════════════════════════════════
    # ★★★ إضافات (الإصدار 21): تعديل حركات اليوم التجاري الحالي ✏️ ★★★
    # للأدمن والمدير فقط حصراً بالدور — بجانب ميزة التصحيح القائمة دون أي
    # مساس بها أو بسلة المحذوفات (المطلوب إضافة التعديل فقط بجانبها)
    # ═════════════════════════════════════════════════════
    def edit_selected_op_v21(self):
        """★ إضافة (الإصدار 21 — المطلوب 3): تعديل حركات اليوم التجاري الحالي —
        للأدمن والمدير فقط حصراً بالدور (البائع لا يعدّل أي حركة نهائياً حتى
        لو كان هو من سجلها — وصلاحية «تصحيح عملية» القائمة شيء منفصل بجانب
        هذا)، وعلى حركات اليوم المفتوح فقط (حركات الأيام المغلقة لا تُعدَّل
        إطلاقاً ولا يظهر لها أي زر تعديل في نافذة حركات الأيام السابقة)"""
        if not manager_level(self.role):
            messagebox.showwarning("صلاحية", "تعديل الحركات خاص بالإدارة فقط (أدمن/مدير)")
            return
        sel = self.tv_today.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر حركة من الجدول أولاً")
            return
        d = business_day_open()
        if not d or is_closed(d):
            messagebox.showwarning("اليوم مغلق", "التعديل على حركات اليوم التجاري المفتوح فقط")
            return
        op_id = int(sel[0])
        with connect() as conn:
            r = conn.execute("SELECT * FROM operations WHERE id=?", (op_id,)).fetchone()
        if r is None:
            return
        if r["date"] != d:
            messagebox.showwarning("اليوم مغلق",
                "هذه الحركة ليست من اليوم التجاري الحالي — لا تُعدَّل")
            return
        self._edit_op_dialog_v21(r, d)

    def _edit_op_dialog_v21(self, r, d):
        """★ إضافة (الإصدار 21 — المطلوب 3): نافذة تعديل عربية RTL تعرض بيانات
        الحركة الحالية وتسمح بتعديل: اسم الصنف والكمية والسعر والنوع
        (نقداً/شبكة/مرتجع) واسم العميل واسم البائع — والإجمالي يُعاد احتسابه
        تلقائيًا = الكمية × السعر ولا يُدخل يدويًا (والمرتجع يُخزَّن سالباً كما
        تُخزَّن دائماً)، وقبل الحفظ رسالة تأكيد تعرض القيمة القديمة والجديدة
        لكل حقل معدّل، وبعده: تحديث صف الحركة فورًا + تدقيق edit_operation
        بالقيم القديمة والجديدة كاملة + تحديث مجاميع اليوم والعدادات فورًا،
        ولا يُمس daily_reports للأيام السابقة إطلاقاً (تقرير اليوم الحالي
        يتأثر تلقائيًا لأن الإغلاق يحتسب من operations)"""
        win = self.register_window(tk.Toplevel(self))
        win.title(f"✏️ تعديل الحركة رقم {r['id']} — يوم {d}")
        win.configure(bg=BG)
        # القاعدة الذهبية: شريط الأزرار السفلي يُحزم أولاً فلا يُقص أبداً
        bar = tk.Frame(win, bg=BG)
        bar.pack(side="bottom", fill="x", padx=18, pady=(0, 14))
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        card.pack(fill="both", expand=True, padx=18, pady=(12, 6))
        tk.Label(card, text=f"✏️ تعديل الحركة رقم {r['id']} — {r['item_name']}",
                 bg=CARD, fg=DARK, font=FT).pack(pady=(10, 4))
        tk.Label(card, text=f"البيانات الحالية: النوع {r['type']} | الكمية {r['quantity']:g} | "
                            f"السعر {r['price']:g} | الإجمالي {r['total']:g}",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 10)).pack(pady=(0, 6))
        grid = tk.Frame(card, bg=CARD)
        grid.pack(fill="both", expand=True, padx=10, pady=8)

        def _row(lbl_txt, widget, row_i):
            tk.Label(grid, text=lbl_txt, bg=CARD, fg=GRAY,
                     font=("Segoe UI", 10, "bold")).grid(
                row=row_i, column=0, sticky="e", padx=8, pady=6)
            widget.grid(row=row_i, column=1, sticky="w", padx=8, pady=6)
            return widget

        e_item = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        e_item.insert(0, r["item_name"])
        _row("اسم الصنف:", e_item, 0)
        e_qty = tk.Entry(grid, font=F, justify="center", relief="solid", bd=1, width=12)
        e_qty.insert(0, f'{r["quantity"]:g}')
        _row("الكمية:", e_qty, 1)
        e_price = tk.Entry(grid, font=F, justify="center", relief="solid", bd=1, width=12)
        e_price.insert(0, f'{r["price"]:g}')
        _row("السعر:", e_price, 2)
        cb_type = ttk.Combobox(grid, font=F, width=10, state="readonly",
                               values=["نقداً", "شبكة", "مرتجع"])
        cb_type.set(r["type"])
        _row("النوع:", cb_type, 3)
        e_cust = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        e_cust.insert(0, r["customer_name"] or "")
        _row("اسم العميل:", e_cust, 4)
        e_seller = tk.Entry(grid, font=F, justify="right", relief="solid", bd=1, width=26)
        e_seller.insert(0, r["seller_name"] or "")
        _row("اسم البائع:", e_seller, 5)
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع): نفس صف السبب والملاحظة
        # في المحرر القديم الباقي بلا حذف — إلزامي للمرتجع عند الحفظ
        _old_reason4 = row_val4(r, "return_reason")
        _old_note4 = row_val4(r, "return_note")
        cb_reason4 = ttk.Combobox(grid, font=F, width=24, state="readonly",
                                  values=list(RETURN_REASONS))
        cb_reason4.set(_old_reason4)
        _row("سبب المرتجع:", cb_reason4, 6)
        e_note4 = tk.Entry(grid, font=F, justify="center", relief="solid", bd=1, width=26)
        e_note4.insert(0, _old_note4)
        _row("ملاحظة المرتجع:", e_note4, 7)
        lbl_tot = tk.Label(grid, text="", bg=CARD, fg=DARK,
                           font=("Segoe UI", 11, "bold"), justify="center")
        # ★ تعديل مصرح به (المرحلة الرابعة): الإجمالي نزل صفين لصفوف السبب
        lbl_tot.grid(row=8, column=0, columnspan=2, pady=(10, 4))

        def _recalc(_e=None):
            q, pr = to_num(e_qty.get()), to_num(e_price.get())
            t = cb_type.get()
            if q is None or pr is None or q <= 0 or pr < 0:
                lbl_tot.config(text="الإجمالي (تلقائي): — أكمل الكمية والسعر أولًا", fg=RED)
                return None
            tot = q * pr
            if t == "مرتجع":
                tot = -tot
                lbl_tot.config(text=f"الإجمالي (تلقائي) = {q:g} × {pr:g} = {tot:g} "
                                    "(مرتجع بقيمة سالبة كما يُخزَّن دائماً)", fg=RED)
            else:
                lbl_tot.config(text=f"الإجمالي (تلقائي) = {q:g} × {pr:g} = {tot:g}", fg=GREEN)
            return tot

        for w in (e_qty, e_price):
            w.bind("<KeyRelease>", _recalc)
        cb_type.bind("<<ComboboxSelected>>", _recalc)
        _recalc()

        def do_save():
            item = e_item.get().strip()
            q, pr = to_num(e_qty.get()), to_num(e_price.get())
            t = cb_type.get()
            cust = e_cust.get().strip()
            seller = e_seller.get().strip()
            if not item:
                messagebox.showwarning("تنبيه", "اكتب اسم الصنف أولاً", parent=win)
                return
            if q is None or q <= 0:
                messagebox.showwarning("تنبيه", f"الكمية غير صحيحة: «{e_qty.get()}»\n"
                                     "أدخل رقماً أكبر من صفر", parent=win)
                return
            if pr is None or pr < 0:
                messagebox.showwarning("تنبيه", f"السعر غير صحيح: «{e_price.get()}»\n"
                                     "أدخل رقماً صحيحاً", parent=win)
                return
            total = q * pr
            if t == "مرتجع":
                total = -total
            # ★★★ إضافة (المرحلة الرابعة): سبب المرتجع إلزامي عند تعديل أي
            # حركة مرتجع (والملاحظة اختيارية)
            if t == "مرتجع" and not cb_reason4.get().strip():
                messagebox.showwarning("سبب المرتجع إلزامي",
                    "اختر سبب المرتجع من القائمة أولاً —\n"
                    "لا يُحفظ تعديل مرتجع دون سبب.", parent=win)
                return
            changed = []
            # ★★★ إضافة (المرحلة الرابعة): سبب وملاحظة المرتجع في قائمة
            # التغييرات المعروضة للتأكيد
            if t == "مرتجع" and cb_reason4.get().strip() != _old_reason4:
                changed.append(("سبب المرتجع", _old_reason4 or "—", cb_reason4.get().strip()))
            if (e_note4.get().strip() or "") != (_old_note4 or ""):
                changed.append(("ملاحظة المرتجع", _old_note4 or "—",
                                e_note4.get().strip() or "—"))
            if item != r["item_name"]:
                changed.append(("اسم الصنف", r["item_name"], item))
            if q != (r["quantity"] or 0):
                changed.append(("الكمية", f'{r["quantity"]:g}', f"{q:g}"))
            if pr != (r["price"] or 0):
                changed.append(("السعر", f'{r["price"]:g}', f"{pr:g}"))
            if t != r["type"]:
                changed.append(("النوع", r["type"], t))
            if cust != (r["customer_name"] or ""):
                changed.append(("اسم العميل", r["customer_name"] or "—", cust or "—"))
            if seller != (r["seller_name"] or ""):
                changed.append(("اسم البائع", r["seller_name"] or "—", seller or "—"))
            if total != (r["total"] or 0):
                changed.append(("الإجمالي", f'{r["total"]:g}', f"{total:g}"))
            if not changed:
                messagebox.showinfo("تنبيه", "لم تتغير أي قيمة — لا شيء يحتاج التعديل",
                                    parent=win)
                return
            lines = "\n".join(f"• {f}: {old} ← {new}" for f, old, new in changed)
            if not messagebox.askyesno("تأكيد التعديل",
                    f"تعديل الحركة رقم {r['id']} (يوم {d}):\n\n{lines}\n\n"
                    "هل تريد حفظ التعديل؟", parent=win):
                return
            with connect() as conn:
                # ★ تعديل مصرح به (المرحلة الرابعة): حفظ سبب المرتجع وملاحظته
                # مع التعديل (NULL عند غير المرتجع)
                conn.execute("""UPDATE operations SET item_name=?,quantity=?,price=?,
                                total=?,type=?,customer_name=?,seller_name=?,
                                return_reason=?,return_note=?
                                WHERE id=?""",
                             (item, q, pr, total, t, cust, seller,
                              (cb_reason4.get().strip() if t == "مرتجع" else None),
                              (e_note4.get().strip() if t == "مرتجع" else None),
                              r["id"]))
            audit("edit_operation",
                  f"رقم {r['id']} يوم {d} — " +
                  "؛ ".join(f"{f}: {old} ← {new}" for f, old, new in changed))
            win.destroy()
            self.refresh_today(); self.refresh_stats()
            try:
                self.lbl_status.config(text=f"✏️ تم تعديل الحركة رقم {r['id']}", fg=GREEN)
            except Exception:
                pass

        def do_cancel():
            win.destroy()

        self.mk_btn(bar, "💾 حفظ التعديل", do_save, GREEN).pack(side="right", padx=6)
        self.mk_btn(bar, "إلغاء", do_cancel, "#475569").pack(side="right", padx=6)
        e_item.bind("<Return>", lambda _e: do_save())
        place_window(win, 580, 580)

    # ★ إضافة (الإصدار 17 — التعديل 4): الملاحظة اللطيفة عند التشغيل قبل 05:00
    def _show_pre_dawn_note(self, d):
        """★ إضافة (الإصدار 17 — التعديل 4): ملاحظة لطيفة أعلى الشاشة عند
        بدء التشغيل قبل 05:00 فجراً — «🌙 نحن قبل 05:00 — العمليات تُسجَّل
        على يوم [التاريخ]» تختفي وحدها بعد دقيقة (بلا أي زر ولا انتباه)"""
        try:
            fr_note = tk.Frame(self.container, bg="#e0f2fe",
                               highlightbackground="#7dd3fc", highlightthickness=1)
            fr_note.pack(fill="x", padx=25, pady=(10, 0),
                         before=self.stats_bar_frame)
            tk.Label(fr_note,
                     text=f"🌙 نحن قبل 05:00 — العمليات تُسجَّل على يوم {d} ({day_name(d)})",
                     bg="#e0f2fe", fg="#075985", font=("Segoe UI", 10, "bold")).pack(pady=5)

            def _hide():
                try:
                    fr_note.destroy()
                except Exception:
                    pass
            self.after(60 * 1000, _hide)     # تختفي بعد دقيقة كاملة
        except Exception:
            pass

    # ---------- الأرشيف ----------
    def build_archive_page(self, p):
        head = self.page_head(p, "🗂️ الأرشيف والتقارير", "كل التقارير اليومية المحفوظة في قاعدة البيانات")
        self.mk_btn(head, "🔄 تحديث", self.refresh_archive, "#475569").pack(side="left", pady=6)

        # ★ إضافة (ميزة 4): بطاقة تصفية الأرشيف بمدى تاريخ — تقبل عدة صيغ للتاريخ
        frow = tk.Frame(p, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        frow.pack(fill="x", padx=25, pady=6)
        def date_cell(label):
            c = tk.Frame(frow, bg=CARD); c.pack(side="right", padx=10, pady=10)
            tk.Label(c, text=label, bg=CARD, fg=DARK, font=FB).pack(side="right")
            e = tk.Entry(c, font=F, justify="center", relief="solid", bd=1, width=13)
            e.pack(side="right", padx=(6, 0), ipady=4)
            return e
        self.e_from = date_cell("من تاريخ:")
        self.e_to   = date_cell("إلى تاريخ:")
        tk.Label(frow, text="الصيغ المقبولة: 2025-01-10 أو 10-01-2025 أو 10/01/2025",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(side="right", padx=10)
        self.mk_btn(frow, "🔍 تصفية", self.filter_archive, ACCENT).pack(side="left", padx=10)
        self.mk_btn(frow, "↩ عرض الكل", self.show_all_archive, "#475569").pack(side="left", padx=6)

        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): جدول الأرشيف يعرض
        # التاريخ | عدد العمليات | نقداً | شبكة | المرتجعات | الإجمالي | وقت الإغلاق
        frm, self.tv_arch = self.mk_tree(p,
            ["وقت الإغلاق", "الإجمالي", "المرتجعات", "شبكة", "نقداً", "عدد العمليات", "التاريخ"],
            [130, 110, 110, 105, 105, 95, 100])
        frm.pack(fill="both", expand=True, padx=25, pady=8)
        self.tv_arch.bind("<Double-1>", lambda e: self.open_selected_day())
        # ★ إضافة (الإصدار 14 — الجزء الثاني): فرز أعمدة الأرشيف + صفوف متناوبة
        enable_tree_sorting(self.tv_arch)
        config_tree_stripes(self.tv_arch)

        # ★ إضافة (ميزة 4): سطر الإجمالي التراكمي للأيام المعروضة
        self.lbl_arch_summary = tk.Label(p, text="", bg=BG, fg=ACCENT, font=FB)
        self.lbl_arch_summary.pack(fill="x", padx=25)

        bar = tk.Frame(p, bg=BG); bar.pack(fill="x", padx=25, pady=(0, 18))
        self.mk_btn(bar, "🔓 إعادة فتح اليوم", self.reopen_day, "#7c3aed").pack(side="left", padx=6)
        # ★ إضافة (ميزة 3): زر تصدير الأرشيف كاملاً إلى Excel حقيقي
        self.mk_btn(bar, "📊 تصدير الأرشيف كاملاً Excel", self.export_archive_xlsx, "#0d9488").pack(side="right", padx=6)
        self.mk_btn(bar, "📥 تصدير اليوم إلى CSV", self.export_selected_day, GREEN).pack(side="right", padx=6)
        self.mk_btn(bar, "📄 عرض تفاصيل اليوم", self.open_selected_day).pack(side="right", padx=6)
        # ★ إضافة (إصدار 6): زر طباعة تقرير اليوم المحدد من شريط الأرشيف —
        # إعادة طباعة تقرير الإغلاق من بيانات daily_reports المحفوظة
        b_arch_prn = self.mk_btn(bar, "🖨 طباعة التقرير", self.print_selected_day, "#334155")
        b_arch_prn.pack(side="right", padx=6)
        add_tip(b_arch_prn, "طباعة تقرير اليوم المحدد على الطابعة الحرارية (إعادة طباعة)")
        # ★ إضافة (إصدار 7 — الميزة 8): زر «🖨 طباعة/معاينة A4» لتقرير اليوم
        # المحدد (بجانب زر الطباعة الحرارية الموجود) + زر «📄 تقرير الفترة A4»
        # للملخص الإجمالي بعد فلترة مدى التاريخ — كلاهما يفتح نافذة المعاينة
        # أولاً ولا طباعة مباشرة بدونها
        b_arch_a4 = self.mk_btn(bar, "🖨 طباعة/معاينة A4", self.print_selected_day_a4, "#1d4ed8")
        b_arch_a4.pack(side="right", padx=6)
        add_tip(b_arch_a4, "معاينة تقرير اليوم المحدد ثم طباعته على A4 عبر ملف PDF قياسي")
        b_arch_prd = self.mk_btn(bar, "📄 تقرير الفترة A4", self.print_period_report, "#0f766e")
        b_arch_prd.pack(side="right", padx=6)
        add_tip(b_arch_prd, "تقرير A4 دوري لكل الأيام ضمن مدى التاريخ المُصفّى أعلاه مع جدول الأيام والإجمالي التراكمي")

        # ★ إضافة (إصدار 8 — الميزة 4): دمج أزرار شريط الأرشيف كلها في زر
        # «⚙️ الإجراءات» واحد يفتح قائمة منسدلة — تعديل ضروري محدود في تخطيط
        # شريط الأرشيف فقط صرّحت به المواصفة: الأزرار الموجودة تُخفى من الشريط
        # وتُفتح كلها من القائمة بنفس الدوال ونفس المنطق تماماً
        self.arch_action_btns = [w for w in bar.winfo_children() if isinstance(w, tk.Button)]
        for w in self.arch_action_btns:
            w.pack_forget()
        self.arch_menu_btn = self.mk_btn(bar, "⚙️ الإجراءات", self.show_archive_menu, "#334155")
        self.arch_menu_btn.pack(side="right", padx=6)
        add_tip(self.arch_menu_btn,
                "كل إجراءات اليوم المحدد: عرض التفاصيل • طباعة/معاينة A4 • طباعة حرارية • "
                "تصدير CSV/Excel • تقرير الفترة A4 • إعادة فتح اليوم")
        tk.Label(bar, text="اختر اليوم من الجدول ثم اضغط زر الإجراءات",
                 bg=BG, fg=GRAY, font=("Segoe UI", 9)).pack(side="right", padx=8)
        self.refresh_archive()

    def refresh_archive(self):
        self.tv_arch.delete(*self.tv_arch.get_children())
        with connect() as conn:
            rows = conn.execute("SELECT * FROM daily_reports ORDER BY report_date DESC").fetchall()
        for i, r in enumerate(rows):
            # ★ تعديل (إصدار 5): القيم تشمل نقداً وشبكة منفصلين
            # ★ إضافة (الإصدار 14 — البند 6): شارة الصف المتناوب
            self.tv_arch.insert("", "end", iid=r["report_date"], tags=stripe_tags(i),
                values=(r["closed_at"], money(r["net_total"]), money(r["total_returns"]),
                        money(r["total_network"] or 0), money(r["total_cash"] or 0),
                        r["ops_count"], r["report_date"]))
        self.update_arch_summary(rows)   # ★ إضافة (ميزة 4): تحديث الإجمالي التراكمي

    def open_selected_day(self):
        sel = self.tv_arch.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً"); return
        self.open_day_details(sel[0])

    def open_day_details(self, d):
        with connect() as conn:
            rep = conn.execute("SELECT * FROM daily_reports WHERE report_date=?", (d,)).fetchone()
            # ★ تعديل ضروري معلن (إصدار 3 — ميزة 4): البائع يرى عملياته فقط في تفاصيل اليوم
            # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الأدمن كالمدير — يرى كل
            # العمليات (كان الفحص «مدير» وحده فكان الأدمن يرى عملياته فقط)
            q = "SELECT * FROM operations WHERE date=?"
            params = [d]
            if not manager_level(self.role):
                q += " AND seller_name=?"
                params.append(self.user_name)
            q += " ORDER BY id"
            rows = conn.execute(q, params).fetchall()
        if rep is None:
            return
        # ★ إضافة (إصدار 8 — الميزة 3): تسجيل النافذة في التتبع المركزي
        # (تُغلق تلقائياً عند تبديل المستخدم)
        win = self.register_window(tk.Toplevel(self))
        win.title(f"تقرير يوم {d}")
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول — القاعدة الذهبية): شريط
        # أزرار الإجراءات السفلي يُحزم أولاً side="bottom" قبل أي شيء آخر فلا
        # يُقص أبداً مهما طال الجدول — والأزرار تُنشأ فيه لاحقاً كالمعتاد،
        # والعنوان فوقه ثم البطاقات ثم الجدول يتمدد fill="both" expand=True
        bar = tk.Frame(win, bg=BG)
        bar.pack(side="bottom", fill="x", padx=20, pady=(0, 15))
        win.configure(bg=BG)   # ★ (إصدار 3): توسعة بسيطة لاستيعاب عمود البائع
        tk.Label(win, text=f"📄 تقرير يوم {d}  ({day_name(d)})", bg=BG, fg=DARK, font=FT).pack(pady=12)
        # ★ إضافة (إصدار 3 — ميزة 4): ملاحظة للبائع أنه يرى عملياته فقط
        # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الملاحظة للبائع فقط —
        # المدير والأدمن كلاهما يرى كل العمليات
        if not manager_level(self.role):
            tk.Label(win, text="تُعرض عملياتك فقط", bg=BG, fg=GRAY,
                     font=("Segoe UI", 10, "bold")).pack()

        cards = tk.Frame(win, bg=BG); cards.pack(fill="x", padx=20)
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): بطاقات تفاصيل اليوم
        # تعرض نقداً وشبكة منفصلين — الترقية عبّأت التقارير القديمة تلقائياً
        # (total_cash = total_sales و total_network = 0)
        for title, val, color in [("العمليات", rep["ops_count"], "#334155"),
                                  ("نقداً", money(rep["total_cash"] or 0), GREEN),
                                  ("شبكة", money(rep["total_network"] or 0), ACCENT),
                                  ("المرتجعات", money(rep["total_returns"]), RED),
                                  ("الإجمالي", money(rep["net_total"]),
                                   GREEN if rep["net_total"] >= 0 else RED)]:
            fr, v = self.mk_card(cards, title, color)
            fr.pack(side="right", expand=True, fill="x", padx=4)
            v.config(text=str(val))

        # ★ تعديل ضروري معلن (إصدار 3 — ميزة 3): عمود البائع في تفاصيل الأرشيف
        frm, tv = self.mk_tree(win,
            ["النوع", "المبيع", "السعر", "الكمية", "اسم الصنف", "العميل", "البائع", "التاريخ"],
            [80, 110, 100, 80, 190, 130, 100, 100])
        frm.pack(fill="both", expand=True, padx=20, pady=10)
        tv.tag_configure("ret", foreground=RED)
        for r in rows:
            tv.insert("", "end", tags=(("ret",) if r["type"] == "مرتجع" else ()),
                # ★ إضافة (الإصدار 16 — القسم 1-1): «↩ مرجع: [رقم الأصل]» بجانب
                # المرتجع — والقديمة بلا رابط تعرض «—»
                values=(r["type"], money(r["total"]), money(r["price"]),
                        f'{r["quantity"]:g}',
                        r["item_name"] + ret_ref_mark(r["type"] == "مرتجع", r["original_op_id"]),
                        (r["customer_name"] or ""),
                        (r["seller_name"] or "—"), r["date"]))   # ★ ميزة 3+5 (إصدار 3): عمودا العميل والبائع

        self.mk_btn(bar, "📥 تصدير CSV", lambda: self.export_ops_csv(d, rows, rep), GREEN).pack(side="right", padx=6)
        # ★ إضافة (ميزة 3): زر تصدير هذا اليوم إلى Excel حقيقي
        self.mk_btn(bar, "📊 تصدير Excel", lambda: self.export_day_xlsx(d, rows, rep), "#0d9488").pack(side="right", padx=6)
        # ★ إضافة (إصدار 6): زر طباعة تقرير هذا اليوم على الطابعة الحرارية —
        # إعادة طباعة تقرير الإغلاق من بيانات daily_reports المحفوظة ليومه
        b_det_prn = self.mk_btn(bar, "🖨 طباعة التقرير",
                                lambda: self.print_day_report(d, reprint=True), "#334155")
        b_det_prn.pack(side="right", padx=6)
        add_tip(b_det_prn, "طباعة تقرير إغلاق هذا اليوم على الطابعة الحرارية (إعادة طباعة)")
        # ★ إضافة (إصدار 7 — الميزة 8): زر «🖨 طباعة/معاينة A4» بجانب الأزرار
        # الموجودة في نافذة تفاصيل اليوم — يفتح نافذة المعاينة أولاً (تقرير
        # إغلاق اليوم بمسار A4/PDF الجديد بنفس محتوى التقرير الحراري)
        b_det_a4 = self.mk_btn(bar, "🖨 طباعة/معاينة A4",
                               lambda: self.open_print_preview("day", d), "#1d4ed8")
        b_det_a4.pack(side="right", padx=6)
        add_tip(b_det_a4, "معاينة تقرير هذا اليوم ثم طباعته على A4 عبر ملف PDF قياسي (أو حرارية 80mm من نفس النافذة)")

        # ★ إضافة (إصدار 8 — الميزة 4): نفس المبدأ في نافذة تفاصيل اليوم —
        # أزرار الإجراءات تُجمع في زر «⚙️ إجراءات» واحد (زر «إغلاق» النافذة
        # يُنشأ بعد هذا السطر فيبقى ظاهراً كما هو) بنفس الدوال ونفس المنطق
        # تماماً — تعديل ضروري محدود في التخطيط صرّحت به المواصفة
        det_action_btns = [w for w in bar.winfo_children() if isinstance(w, tk.Button)]
        for w in det_action_btns:
            w.pack_forget()
        b_det_menu = self.mk_btn(bar, "⚙️ إجراءات",
                                 lambda: self.show_day_details_menu(d, rows, rep, b_det_menu),
                                 "#334155")
        b_det_menu.pack(side="right", padx=6)
        add_tip(b_det_menu, "كل إجراءات هذا اليوم: تصدير CSV • تصدير Excel • طباعة حرارية • طباعة/معاينة A4")
        self.mk_btn(bar, "إغلاق", win.destroy, "#475569").pack(side="right", padx=6)
        # ★ إضافة (إصدار 4 — ميزة 5): تلميحات أزرار التصدير في نافذة التفاصيل
        for w in bar.winfo_children():
            if isinstance(w, tk.Button):
                t = w.cget("text")
                if t == "📥 تصدير CSV":
                    add_tip(w, "تصدير عمليات هذا اليوم إلى ملف CSV")
                elif t == "📊 تصدير Excel":
                    add_tip(w, "تصدير تفاصيل هذا اليوم إلى Excel")
                elif t == "إغلاق":
                    add_tip(w, "إغلاق نافذة التفاصيل")
        # ★ إضافة (الإصدار 15 — الجزء الأول): نافذة طويلة 1010×660 + minsize
        # + تمدد كامل + تمركز وسط الشاشة مع احترام الشاشات الصغيرة
        place_window(win, 1010, 660, 880, 560, can_resize=True)

    def show_day_details_menu(self, d, rows, rep, btn):
        """★ إضافة (إصدار 8 — الميزة 4): قائمة إجراءات نافذة تفاصيل اليوم —
        نفس الخيارات الموجودة سابقاً كأزرار بنفس الدوال ونفس المنطق تماماً"""
        m = tk.Menu(self, tearoff=0, bg=CARD, fg=DARK, font=("Segoe UI", 10),
                    activebackground=ACCENT, activeforeground="white", bd=0, relief="flat")
        if self.has_permission("export_reports"):
            m.add_command(label="📥 تصدير CSV", command=lambda: self.export_ops_csv(d, rows, rep))
            m.add_command(label="📊 تصدير Excel", command=lambda: self.export_day_xlsx(d, rows, rep))
        m.add_command(label="🖨 طباعة التقرير (حرارية)",
                      command=lambda: self.print_day_report(d, reprint=True))
        m.add_command(label="🖨 طباعة/معاينة A4",
                      command=lambda: self.open_print_preview("day", d))
        try:
            m.tk_popup(btn.winfo_rootx(), btn.winfo_rooty() + btn.winfo_height())
        finally:
            m.grab_release()

    def export_selected_day(self):
        sel = self.tv_arch.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً"); return
        d = sel[0]
        with connect() as conn:
            rep = conn.execute("SELECT * FROM daily_reports WHERE report_date=?", (d,)).fetchone()
            # ★ تعديل ضروري معلن (إصدار 3 — ميزة 4): البائع يصدّر عملياته فقط من تفاصيل اليوم
            # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الأدمن كالمدير — يصدّر
            # كل عمليات اليوم (كان الفحص «مدير» وحده)
            q = "SELECT * FROM operations WHERE date=?"
            params = [d]
            if not manager_level(self.role):
                q += " AND seller_name=?"
                params.append(self.user_name)
            q += " ORDER BY id"
            rows = conn.execute(q, params).fetchall()
        self.export_ops_csv(d, rows, rep)

    def reopen_day(self):
        # ★ تعديل مصرح به (إصدار 8 — الميزة 5): صلاحية «إعادة فتح يوم مغلق» بدل «المدير فقط»
        if not self.require_admin("reopen_day"):
            return
        sel = self.tv_arch.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً"); return
        d = sel[0]
        # ★ إضافة (الإصدار 14 — الجزء الأول): يوم آخر مفتوح حالياً؟ — يُمنع
        # الاستبدال حماية لأعماله غير المُغلقة (يُغلق أولاً ثم يُعاد فتح هذا
        # اليوم)، والفحص قبل حذف التقرير كي لا يُترك يوماً بلا تقرير بلا داعٍ
        cur = business_day_open()
        if cur and cur != d:
            messagebox.showwarning("لا يمكن إعادة الفتح",
                f"يوم عمل آخر مفتوح حالياً ({cur}) ولم تُغلق أعماله بعد.\n"
                f"أغلقه أولاً ثم أعد فتح يوم {d}.")
            return
        if not messagebox.askyesno("تأكيد", f"إعادة فتح يوم {d} سيحذف تقريره النهائي (تبقى العمليات).\nهل تريد المتابعة؟"):
            return
        with connect() as conn:
            conn.execute("DELETE FROM daily_reports WHERE report_date=?", (d,))
        audit("إعادة فتح يوم", d)               # ★ إضافة (ميزة 2): تسجيل إعادة الفتح
        # ★ إضافة (الإصدار 14 — الجزء الأول): اليوم المُعاد فتحه يصبح يوم العمل
        # المفتوح من جديد — بدونه كان الحفظ يبقى معطلاً بعد إعادة الفتح رغم
        # حذف التقرير، ووعد «يمكنك إضافة عمليات عليه ثم إغلاقه مرة أخرى»
        # يتحقق الآن فعلاً
        set_business_day(d)
        self.refresh_archive(); self.refresh_today(); self.update_closed_banner()
        self.refresh_stats(); self.refresh_business_day_ui()
        messagebox.showinfo("تم", f"أصبح يوم {d} مفتوحاً من جديد.\nيمكنك إضافة عمليات عليه ثم إغلاقه مرة أخرى.")

    def show_archive_menu(self):
        """★ إضافة (إصدار 8 — الميزة 4): قائمة إجراءات الأرشيف المنسدلة — كل
        الخيارات الموجودة سابقاً كأزرار، بنفس الدوال ونفس المنطق تماماً؛
        خيارات التصدير وإعادة الفتح تظهر بحسب الصلاحيات الفعلية"""
        m = tk.Menu(self, tearoff=0, bg=CARD, fg=DARK, font=("Segoe UI", 10),
                    activebackground=ACCENT, activeforeground="white", bd=0, relief="flat")
        m.add_command(label="📄 عرض تفاصيل اليوم", command=self.open_selected_day)
        if self.has_permission("export_reports"):
            m.add_command(label="🖨 طباعة/معاينة A4", command=self.print_selected_day_a4)
            m.add_command(label="📥 تصدير اليوم إلى CSV", command=self.export_selected_day)
            m.add_command(label="📊 تصدير الأرشيف كاملاً Excel", command=self.export_archive_xlsx)
            m.add_command(label="📄 تقرير الفترة A4", command=self.print_period_report)
        m.add_command(label="🖨 طباعة التقرير (حرارية)", command=self.print_selected_day)
        m.add_separator()
        if self.has_permission("reopen_day"):
            m.add_command(label="🔓 إعادة فتح اليوم", command=self.reopen_day)
        try:
            btn = self.arch_menu_btn
            m.tk_popup(btn.winfo_rootx(), btn.winfo_rooty() + btn.winfo_height())
        finally:
            m.grab_release()

    def export_ops_csv(self, d, rows, rep=None):
        # ★ إضافة (إصدار 8 — الميزة 5): صلاحية «تصدير التقارير (CSV/Excel/PDF)»
        if not self.has_permission("export_reports"):
            messagebox.showwarning("صلاحية", "ليست لديك صلاحية «تصدير التقارير»")
            return
        path = filedialog.asksaveasfilename(title="حفظ التقرير", defaultextension=".csv",
                                            initialfile=f"تقرير_{d}.csv", filetypes=[("ملف CSV", "*.csv")])
        if not path:
            return
        with open(path, "w", newline="", encoding="utf-8-sig") as f:
            w = csv.writer(f)
            # ★ تعديل ضروري معلن (ميزة 5): رأس الجدول وصفوفه أصبحا يشملان عمود العميل
            # ★ تعديل ضروري معلن (إصدار 3 — ميزة 3): أصبحا يشملان عمود البائع أيضاً
            w.writerow(["التاريخ", "اسم الصنف", "العميل", "البائع", "الكمية", "السعر", "المبيع", "النوع"])
            for r in rows:
                w.writerow([r["date"], r["item_name"], (r["customer_name"] or ""),
                            (r["seller_name"] or "—"),
                            r["quantity"], r["price"], r["total"], r["type"]])
            if rep:
                w.writerow([])
                w.writerow(["عدد العمليات", rep["ops_count"]])
                # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): ملخص التصدير يعرض
                # نقداً وشبكة منفصلين مع إجمالي المبيعات المجمع
                w.writerow(["نقداً", rep["total_cash"] or 0.0])
                w.writerow(["شبكة", rep["total_network"] or 0.0])
                w.writerow(["المبيعات (نقداً + شبكة)", rep["total_sales"]])
                w.writerow(["المرتجعات", rep["total_returns"]])
                w.writerow(["الإجمالي", rep["net_total"]])
        audit("تصدير CSV", f"{os.path.basename(path)} — {len(rows)} صف")   # ★ إضافة (ميزة 2)
        messagebox.showinfo("تم", "تم تصدير التقرير ✅\nيمكن فتحه مباشرة في Excel")

    # ---------- البحث ----------
    def build_search_page(self, p):
        self.page_head(p, "🔎 بحث", "ابحث عن صنف في كل العمليات منذ بداية الاستخدام")
        bar = tk.Frame(p, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        bar.pack(fill="x", padx=25, pady=8)
        self.e_search = tk.Entry(bar, font=F, justify="center", relief="solid", bd=1)
        self.e_search.pack(side="right", fill="x", expand=True, ipady=7, padx=12, pady=12)
        self.e_search.bind("<Return>", lambda e: self.do_search())
        self.mk_btn(bar, "بحث", self.do_search).pack(side="left", padx=12)

        # ★ تعديل ضروري معلن (إصدار 4 — ميزة 1): الملاحظة تُنشأ دائماً وتُخفى للمدير —
        # لتتكيف الشاشة عند تبديل المستخدم دون إعادة بنائها
        # ★ إضافة (إصدار 3 — ميزة 4): البائع يبحث في عملياته فقط
        self.lbl_search_only = tk.Label(p, text="تُعرض عملياتك فقط", bg=BG, fg=GRAY,
                                        font=("Segoe UI", 10, "bold"))
        # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الملاحظة للبائع فقط —
        # المدير والأدمن كلاهما يبحث في كل العمليات
        if not manager_level(self.role):
            self.lbl_search_only.pack(fill="x", padx=25, anchor="e")

        self.lbl_search = tk.Label(p, text="", bg=BG, fg=ACCENT, font=FB)
        self.lbl_search.pack(fill="x", padx=25)

        # ★ تعديل ضروري معلن (إصدار 3 — ميزة 3): عمود البائع في نتائج البحث
        frm, self.tv_search = self.mk_tree(p,
            ["النوع", "المبيع", "السعر", "الكمية", "اسم الصنف", "العميل", "البائع", "التاريخ"],
            [80, 110, 100, 80, 190, 130, 100, 100])
        frm.pack(fill="both", expand=True, padx=25, pady=8)
        self.tv_search.tag_configure("ret", foreground=RED)
        # ★ إضافة (الإصدار 14 — البندان 5+6): فرز الرؤوس + الصفوف المتناوبة
        enable_tree_sorting(self.tv_search)
        config_tree_stripes(self.tv_search)

    def do_search(self):
        q = self.e_search.get().strip()
        if not q:
            return
        self.tv_search.delete(*self.tv_search.get_children())
        # ★ تعديل ضروري معلن (إصدار 3 — ميزة 4): البائع يجد في عملياته فقط
        # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الأدمن كالمدير — يجد في
        # كل العمليات (كان الفحص «مدير» وحده فكان الأدمن يجد عملياته فقط)
        sql = "SELECT * FROM operations WHERE item_name LIKE ?"
        params = [f"%{q}%"]
        if not manager_level(self.role):
            sql += " AND seller_name=?"
            params.append(self.user_name)
        sql += " ORDER BY date DESC, id DESC"
        with connect() as conn:
            rows = conn.execute(sql, params).fetchall()
        total = 0
        for i, r in enumerate(rows):
            total += r["total"]
            # ★ إضافة (الإصدار 14 — البندان 5+6): شارة الصف المتناوب مع بقاء المرتجع أحمر
            self.tv_search.insert("", "end", tags=stripe_tags(i, r["type"] == "مرتجع"),
                # ★ إضافة (الإصدار 16 — القسم 1-1): «↩ مرجع: [رقم الأصل]» بجانب
                # المرتجع — والقديمة بلا رابط تعرض «—»
                values=(r["type"], money(r["total"]), money(r["price"]),
                        f'{r["quantity"]:g}',
                        r["item_name"] + ret_ref_mark(r["type"] == "مرتجع", r["original_op_id"]),
                        (r["customer_name"] or ""),
                        (r["seller_name"] or "—"), r["date"]))   # ★ ميزة 3+5 (إصدار 3): عمودا العميل والبائع
        self.lbl_search.config(text=f"نتائج «{q}»: {len(rows)} عملية — الإجمالي الكلي: {money(total)}")

    # ---------- الخروج والنسخ الاحتياطي ----------
    def backup_now(self):
        try:
            # ★ إضافة (الإصدار 16 — القسم 2-4): توحيد الملف قبل النسخ المباشر —
            # دمج سجلات WAL داخل shop.db فتكون النسخة عن الملف كاملة دائماً
            wal_checkpoint()
            shutil.copy2(DB, BACKUP)
            audit("نسخة احتياطية", BACKUP)      # ★ إضافة (ميزة 2): تسجيل النسخ الاحتياطي
            messagebox.showinfo("تم", f"تم إنشاء نسخة احتياطية:\n{BACKUP}")
        except Exception as e:
            messagebox.showerror("خطأ", f"تعذر إنشاء النسخة:\n{e}")

    def exit_app(self):
        try:
            # ★ إضافة (الإصدار 16 — القسم 2-4): نفس توحيد WAL قبل نسخة الخروج
            # المباشرة — بلا هذه الخطوة كانت نسخة الخروج تنقصها آخر الكتابات
            wal_checkpoint()
            shutil.copy2(DB, BACKUP)
        except Exception:
            pass
        self.destroy()

    # ═══════════════════════════════════════════════════════════
    # ★★★ إضافات الإصدار 2 — دوال جديدة داخل الكلاس ★★★
    # ═══════════════════════════════════════════════════════════

    # ---------- (ميزة 1) بوابة الصلاحيات ----------
    # ★ إضافة (إصدار 8 — الميزة 5): دالة الفحص الدقيق للصلاحيات — بديل فحوصات
    # «المدير فقط» السابقة (هذا هو الاستبدال المصرح به في قواعد هذه الجلسة
    # لأنه جوهر نظام الصلاحيات): المدير يملك كل الصلاحيات دائماً، والبائع
    # بحسب ما منحه المدير له (تُقرأ صلاحياته من قاعدة البيانات فتسري
    # التعديلات فوراً حتى أثناء الجلسة)، والصلاحية الخاصة «manager» معناها:
    # للمدير فقط (مثل شاشة إدارة المستخدمين)
    def has_permission(self, key):
        # ★ تعديل مصرح به (الإصدار 14 — الجزء صفر): الأدمن يملك كل صلاحيات
        # المدير تلقائياً — أضيف لدوره إلى شرط المدير (كان المدير وحده)
        if manager_level(self.role):
            return True
        if key == "manager":
            return False
        row = get_user_row(self.user_name)
        try:
            perms = json.loads(row["permissions"] or "[]") if row is not None else []
        except Exception:
            perms = []
        return key in perms

    def require_admin(self, perm="manager"):
        """★ تعديل مصرح به (إصدار 8 — الميزة 5): بوابة الصلاحيات الدقيقة —
        كانت تفحص «المدير فقط» والآن تفحص has_permission(الصلاحية) بدلاً منها
        (هذا هو الاستبدال المصرح به في قواعد هذه الجلسة لأنه جوهر نظام
        الصلاحيات) — والصلاحية الافتراضية «manager» تعني: للمدير فقط"""
        if self.has_permission(perm):
            return True
        messagebox.showwarning("صلاحية", "ليست لديك الصلاحية لهذا الإجراء")
        return False

    # ★ إضافة (إصدار 8 — الميزة 3): التتبع المركزي للنوافذ المفتوحة —
    # كل نافذة Toplevel تُفتح تُسجل هنا، وتُغلق كلها فوراً عند تبديل المستخدم
    def register_window(self, win):
        """تسجيل نافذة Toplevel في قائمة التتبع المركزية"""
        self.open_windows.append(win)
        win.bind("<Destroy>", lambda e: self._unregister_window(win), add="+")
        return win

    def _unregister_window(self, win):
        """إزالة نافذة من قائمة التتبع بعد إغلاقها"""
        try:
            if win in self.open_windows:
                self.open_windows.remove(win)
        except Exception:
            pass

    def close_all_windows(self):
        """إغلاق كل النوافذ المفتوحة فوراً (destroy) وإرجاع عددها —
        أول خطوة عند تبديل المستخدم قبل إظهار نافذة الدخول، فلا تبقى أي
        شاشة تعمل باسم المستخدم القديم بعد التبديل أبداً"""
        n = 0
        for w in list(getattr(self, "open_windows", [])):
            try:
                w.destroy()
                n += 1
            except Exception:
                pass
        self.open_windows = []
        return n

    # ---------- (ميزة 6) شاشة الفاتورة متعددة الأصناف ----------
    def show_invoice(self):
        """★ إضافة (ميزة 6): فتح شاشة الفاتورة وتحديث قائمة الأصناف"""
        self.show_page("invoice")
        self.refresh_items()

    def build_invoice_page(self, p):
        self.page_head(p, "🧾 فاتورة أصناف", "أدخل عدة أصناف ثم احفظ الفاتورة كاملة دفعة واحدة")

        # ★★★ إصلاح (الإصدار 18 — المشكلة 1): شريط إجراءات الفاتورة السفلي
        # يُحزم side="bottom" أولاً (قاعدة الأزرار المثبتة) قبل النموذج والجدول —
        # كان يُحزم آخر شيء بعد جدول السلة المتمدد، والمساحة المطلوبة للصفحة
        # أكبر من المتاح في النافذة، فلا يُخصص للشريط أي مساحة إطلاقاً فيختفي
        # زر الحفظ كلياً (سلة فخ) — الآن الزران مثبتان أسفل الصفحة دائماً مهما
        # طال الجدول أو صغرت الشاشة، وزر الحفظ الأخضر البارز أول الصف (يمين)
        bar = tk.Frame(p, bg=BG)
        bar.pack(side="bottom", fill="x", padx=25, pady=(6, 14))
        b_save_inv = self.mk_btn(bar, "💾 حفظ الفاتورة كاملة", self.save_invoice, GREEN)
        b_save_inv.pack(side="right", padx=6, ipadx=14)
        add_tip(b_save_inv, "حفظ كل أصناف السلة دفعة واحدة كعمليات على يوم العمل التجاري "
                            "باسمك — تأكيد بالعدد والإجمالي ثم تفريغ السلة وسؤال تصدير Excel")
        b_inv_rm = self.mk_btn(bar, "🗑 إزالة المحدد من السلة", self.remove_from_cart, RED)
        b_inv_rm.pack(side="right", padx=6)
        add_tip(b_inv_rm, "إزالة الصنف المحدد من السلة قبل الحفف")
        # ★★★ إضافة (المرحلة الرابعة — البيع بالدين): زر «بيع بالدين» بجانب
        # زر حفظ الفاتورة — لا يُبنى إلا لمن يملك sell_on_credit (والأدمن
        # دائماً)، ويُدار ظهوره وإخفاؤه مع تبديل المستخدم من
        # rebuild_ui_for_current_user (إخفاء كلي لا تعطيل)
        self._invbar_credit_host = bar
        self._inv_rm_btn_ref = b_inv_rm
        if user_has_permission(self.user_name, "sell_on_credit"):
            b_credit_inv4 = self.mk_btn(bar, "🧾 بيع بالدين",
                                        lambda: self._credit_sale_dialog("invoice"),
                                        ORANGE)
            b_credit_inv4.pack(side="right", padx=6, before=b_inv_rm)
            self.b_credit_inv = b_credit_inv4
            add_tip(b_credit_inv4, "بيع الفاتورة بالدين — اختيار العميل والدفعة الأولى "
                                   "ثم الحفظ بنفس دالة الفاتورة القائمة وتسجيل الباقي ديناً")
        else:
            self.b_credit_inv = None

        # ★ إضافة (آخر سعر بيع): زر «استعلام آخر الأسعار» في شريط
        # إجراءات الفاتورة — لا يُبنى إلا لمن يملك last_price_view
        # (والأدمن دائماً)، ويُدار ظهوره وإخفاؤه مع تبديل المستخدم من
        # rebuild_ui_for_current_user (إخفاء كلي لا تعطيل) بنفس نمط
        # زر «بيع بالدين» أعلاه حرفياً
        self._invbar_lastprice_host = bar
        self.b_inv_lastprice = None
        if user_has_permission(self.user_name, "last_price_view"):
            b_lp4 = self.mk_btn(bar, "🔍 استعلام آخر الأسعار",
                                self.show_last_prices_window, ACCENT)
            b_lp4.pack(side="right", padx=6, before=b_inv_rm)
            self.b_inv_lastprice = b_lp4
            add_tip(b_lp4, "نافذة استعلام صغيرة: آخر 5 عمليات بيع مطابقة "
                           "لاسم الصنف (تاريخها وسعر وحدتها وكميتها والعميل "
                           "والبائع ورقم الفاتورة) — لتوحيد التسعير بين البائعين")

        form = tk.Frame(p, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        form.pack(fill="x", padx=25, pady=8)

        def frow(label, width=18):
            fr = tk.Frame(form, bg=CARD); fr.pack(fill="x", padx=22, pady=6)
            tk.Label(fr, text=label, bg=CARD, fg=DARK, font=FB, width=width, anchor="e").pack(side="right")
            inner = tk.Frame(fr, bg=CARD)
            inner.pack(side="right", padx=(0, 10))
            return inner

        i_c = frow("اسم العميل (اختياري):", 20)
        self.e_inv_customer = tk.Entry(i_c, font=F, justify="center", relief="solid", bd=1, width=30)
        self.e_inv_customer.pack(side="right", ipady=4)

        i_i = frow("اسم الصنف:")
        self.cb_inv_item = ttk.Combobox(i_i, font=F, width=30)
        self.cb_inv_item.pack(side="right", ipady=4)

        # ★ إضافة (آخر سعر بيع): مضيف سطر التلميح تحت حقل اسم الصنف —
        # إطار فارغ بارتفاع صفري لمن لا يملك last_price_view (طبقة
        # الإخفاء: سطر التلميح لا يُبنى أصلاً له)، ويُبنى داخله سطر
        # التلميح لمن يملكه — وموقعه هنا يضمن ظهوره تحت الحقل مباشرة
        # قبل صف الكمية، ويُدار بناؤه وهدمه مع تبديل المستخدم من
        # rebuild_ui_for_current_user بنفس منطق زر «بيع بالدين»
        self._inv_lp_hint_host = tk.Frame(form, bg=CARD)
        self._inv_lp_hint_host.pack(fill="x", padx=22, pady=0)
        self.lbl_inv_last_price = None
        self._lp_last_query = None
        if user_has_permission(self.user_name, "last_price_view"):
            self._lp_build_hint_label()

        i_q = frow("الكمية:")
        self.e_inv_qty = tk.Entry(i_q, font=F, justify="center", relief="solid", bd=1, width=30)
        self.e_inv_qty.pack(side="right", ipady=4)

        i_p = frow("السعر:")
        self.e_inv_price = tk.Entry(i_p, font=F, justify="center", relief="solid", bd=1, width=30)
        self.e_inv_price.pack(side="right", ipady=4)
        # ★ إضافة (الإصدار 14 — البند 13): فلترة إدخال الكمية/السعر في شاشة
        # الفاتورة — أرقام فقط (عربية/إنجليزية وفاصلة الكسر) كحقلي شاشة
        # «عملية جديدة» نفسها — أي حرف آخر لا يُكتب أصلاً
        digits_only_filter(self.e_inv_qty)
        digits_only_filter(self.e_inv_price)

        # ★★★ إضافة (المرحلة الرابعة — سقف الخصم): خصم % على كامل الفاتورة
        # — 0 أو فراغ = بلا خصم (نفس السلوك القديم)، يوزَّع نسبياً على أصناف
        # البيع فقط عند الحفظ (المرتجعات بسعر أصلها دائماً)، وسطر لحظي يعرض
        # الإجمالي بعد الخصم وسقف خصم المستخدم توضيحياً
        i_d4 = frow("خصم % على الفاتورة (اختياري):", 20)
        self.e_inv_disc = tk.Entry(i_d4, font=F, justify="center", relief="solid",
                                   bd=1, width=30)
        self.e_inv_disc.pack(side="right", ipady=4)
        self.e_inv_disc.insert(0, "0")
        digits_only_filter(self.e_inv_disc)
        self.lbl_inv_after_disc = tk.Label(i_d4, text="", bg=CARD, fg=GRAY,
                                           font=("Segoe UI", 9, "bold"))
        self.lbl_inv_after_disc.pack(side="right", padx=(6, 0))
        add_tip(self.e_inv_disc, "نسبة خصم 0-100 على أصناف البيع في السلة — 0 = بلا "
                                 "خصم. تُفحص عند الحفظ ضد سقف الخصم المسموح لك")
        self.e_inv_disc.bind("<KeyRelease>", lambda e: self._inv_disc_recalc())

        trow = tk.Frame(form, bg=CARD); trow.pack(fill="x", padx=22, pady=8)
        tk.Label(trow, text="النوع:", bg=CARD, fg=DARK, font=FB).pack(side="right")
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): ثلاثة أنواع في صفحة الفاتورة أيضاً —
        # نقداً (أخضر) / شبكة (أزرق) بقيمة موجبة، ومرتجع (أحمر) بقيمة سالبة كما هو
        self.inv_type_var = tk.StringVar(value="نقداً")
        for txt, col in [("نقداً", GREEN), ("شبكة", ACCENT), ("مرتجع", RED)]:
            tk.Radiobutton(trow, text=txt, variable=self.inv_type_var, value=txt, font=FB,
                           fg=col, bg=CARD, selectcolor="#dbeafe", activebackground=CARD,
                           activeforeground=col, indicatoron=0, width=10, bd=1,
                           relief="solid", cursor="hand2").pack(side="right", padx=10)

        # ★★★ إضافة (الإصدار 16 — القسم 1-1): نفس ربط المرتجع بالأصل في شاشة
        # الفاتورة — صف «العملية المُرجَعة» يظهر عند «مرتجع» فقط، والمتاح
        # للإرجاع يخصم أيضاً ما أُضيف للسلة على نفس الأصل في هذه الفاتورة
        self._inv_orig_map = {}
        self._trow_inv_ref = trow
        self.fr_inv_orig = tk.Frame(form, bg=CARD)
        iorow = tk.Frame(self.fr_inv_orig, bg=CARD); iorow.pack(fill="x", pady=4)
        tk.Label(iorow, text="العملية المُرجَعة:", bg=CARD, fg=RED, font=FB,
                 width=17, anchor="e").pack(side="right")
        inner_io = tk.Frame(iorow, bg=CARD)
        inner_io.pack(side="right", padx=(0, 10))
        self.cb_inv_orig = ttk.Combobox(inner_io, font=F, width=42, state="readonly")
        self.cb_inv_orig.pack(side="right", ipady=4)
        self.lbl_inv_orig_info = tk.Label(iorow, text="", bg=CARD, fg=GRAY,
                                          font=("Segoe UI", 9, "bold"))
        self.lbl_inv_orig_info.pack(side="right", padx=8)
        add_tip(self.cb_inv_orig,
                "اختر عملية البيع الأصلية لهذا الصنف المرتجع — الكمية المعروضة هي المتبقي "
                "الصالح للإرجاع (بعد خصم المرتجعات السابقة وما أُضيف للسلة)، والسعر بسعر الأصل")
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع): السبب الإلزامي
        # والملاحظة الاختيارية لكل صنف مرتجع يُضاف إلى السلة — يظهران
        # ويختفيان مع صف «العملية المُرجَعة» عند اختيار «مرتجع» فقط
        irr4 = tk.Frame(self.fr_inv_orig, bg=CARD); irr4.pack(fill="x", pady=4)
        tk.Label(irr4, text="سبب المرتجع:", bg=CARD, fg=RED, font=FB,
                 width=17, anchor="e").pack(side="right")
        inner_ir4 = tk.Frame(irr4, bg=CARD)
        inner_ir4.pack(side="right", padx=(0, 10))
        self.cb_inv_ret_reason = ttk.Combobox(inner_ir4, font=F, width=30,
                                              state="readonly",
                                              values=list(RETURN_REASONS))
        self.cb_inv_ret_reason.pack(side="right", ipady=4)
        add_tip(self.cb_inv_ret_reason, "إلزامي — لا يُضاف مرتجع إلى السلة دون سبب")
        inr4 = tk.Frame(self.fr_inv_orig, bg=CARD); inr4.pack(fill="x", pady=4)
        tk.Label(inr4, text="ملاحظة (اختياري):", bg=CARD, fg=GRAY, font=FB,
                 width=17, anchor="e").pack(side="right")
        inner_in4 = tk.Frame(inr4, bg=CARD)
        inner_in4.pack(side="right", padx=(0, 10))
        self.e_inv_ret_note = tk.Entry(inner_in4, font=F, justify="center",
                                       relief="solid", bd=1, width=32)
        self.e_inv_ret_note.pack(side="right", ipady=4)
        self.cb_inv_orig.bind("<<ComboboxSelected>>", lambda e: self._inv_orig_selected())
        self.inv_type_var.trace_add("write", lambda *_: self._sync_inv_return_ui())
        self.cb_inv_item.bind("<KeyRelease>", lambda e: self._refresh_inv_orig_list())
        self.cb_inv_item.bind("<<ComboboxSelected>>", lambda e: self._refresh_inv_orig_list())
        self._sync_inv_return_ui()

        crow = tk.Frame(form, bg=CARD); crow.pack(fill="x", padx=22, pady=(2, 12))
        self.mk_btn(crow, "➕ إضافة إلى السلة", self.add_to_cart, GREEN).pack(side="right")
        self.lbl_inv_status = tk.Label(crow, text="", bg=CARD, font=FB)
        self.lbl_inv_status.pack(side="right", padx=14)

        frm, self.tv_cart = self.mk_tree(p,
            ["النوع", "المبيع", "السعر", "الكمية", "الصنف"],
            [90, 120, 110, 90, 240])
        frm.pack(fill="both", expand=True, padx=25, pady=8)
        self.tv_cart.tag_configure("ret", foreground=RED)

        # ★ إجمالي السلة لحظياً — يتحدث مع كل إضافة/إزالة
        self.lbl_inv_total = tk.Label(p, text="إجمالي السلة: 0.00", bg=BG, fg=ACCENT, font=FV)
        self.lbl_inv_total.pack(fill="x", padx=25)

        # ★★★ إضافة (الإصدار 17 — الإضافة 2): شريط التعديل السريع أسفل السلة —
        # الكمية والسعر قابلان للتعديل مباشرة: أزرار +/- للكمية وحقلا كمية/سعر
        # وزر «🔄 تحديث المحدد» يعيد حساب الصف المحدد — والنقر المزدوج على أي
        # صف يفتح نافذة التعديل الكاملة (Enter في حقلي الإضافة يبقى للجديد كما هو)
        qbar = tk.Frame(p, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        qbar.pack(fill="x", padx=25, pady=(4, 2))
        b_minus = self.mk_btn(qbar, "➖", lambda: self.cart_qty_step(-1), "#475569")
        b_minus.pack(side="right", padx=(6, 2))
        add_tip(b_minus, "إنقاص كمية الصف المحدد من السلة بواحد (بحدود تحققات الإضافة كاملة)")
        b_plus = self.mk_btn(qbar, "➕", lambda: self.cart_qty_step(1), "#475569")
        b_plus.pack(side="right", padx=2)
        add_tip(b_plus, "زيادة كمية الصف المحدد من السلة بواحد (المرتجع لا يتجاوز متاح أصله)")
        tk.Label(qbar, text="الكمية:", bg=CARD, fg=DARK, font=FB).pack(side="right", padx=(14, 2))
        self.e_cart_qty = tk.Entry(qbar, font=F, justify="center", relief="solid", bd=1, width=10)
        self.e_cart_qty.pack(side="right", ipady=4)
        digits_only_filter(self.e_cart_qty)
        add_tip(self.e_cart_qty, "اكتب كمية جديدة ثم اضغط «🔄 تحديث المحدد» (أو Enter) لتطبيقها على الصف المحدد")
        tk.Label(qbar, text="السعر:", bg=CARD, fg=DARK, font=FB).pack(side="right", padx=(14, 2))
        self.e_cart_price = tk.Entry(qbar, font=F, justify="center", relief="solid", bd=1, width=10)
        self.e_cart_price.pack(side="right", ipady=4)
        digits_only_filter(self.e_cart_price)
        add_tip(self.e_cart_price, "اكتب سعراً جديداً ثم اضغط «🔄 تحديث المحدد» — سعر المرتجع مقفل بسعر أصله دائماً")
        b_upd = self.mk_btn(qbar, "🔄 تحديث المحدد", self.update_selected_cart_row, ACCENT)
        b_upd.pack(side="left", padx=6)
        add_tip(b_upd, "تطبيق قيم حقلي الكمية والسعر على الصف المحدد وإعادة حسابه — بلا حذف وإعادة إدخال")
        tk.Label(qbar, text="نقر مزدوج على أي صف لتعديله بالكامل ✏️", bg=CARD, fg=GRAY,
                 font=("Segoe UI", 9)).pack(side="left", padx=8)
        # (شريط إجراءات الفاتورة — حفظ/إزالة — انتقل لأعلى الدالة ليُحزم
        # side="bottom" أولاً فوق كل شيء: إصلاح الإصدار 18 — المشكلة 1)

        self.cart = []   # السلة: قائمة الأصناف قبل الحفظ
        for w in (self.e_inv_qty, self.e_inv_price):
            w.bind("<Return>", lambda e: self.add_to_cart())
        self.cb_inv_item.bind("<Return>", lambda e: self.add_to_cart())
        # ★ إضافة (آخر سعر بيع): روابط تحديث تلميح آخر سعر — البحث عند
        # خروج المؤشر من حقل اسم الصنف أو ضغط Enter (بعد معالج الإضافة
        # القائم نفسه بترتيب التسجيل: إن أُضيف الصنف للسلة صار الحقل
        # فارغاً فيخفي التلميح) أو اختيار صنف من القائمة فقط، ولا بحث
        # مع كل حرف إطلاقاً: الكتابة تخفي التلميح القديم فور تغيّر
        # الاسم فقط (بلا أي استعلام)
        self.cb_inv_item.bind("<FocusOut>", lambda e: self._lp_hint_update())
        self.cb_inv_item.bind("<Return>", lambda e: self._lp_hint_update(), add="+")
        self.cb_inv_item.bind("<<ComboboxSelected>>", lambda e: self._lp_hint_update(), add="+")
        self.cb_inv_item.bind("<KeyRelease>", lambda e: self._lp_hint_on_change(), add="+")

        # ★ إضافة (الإصدار 17 — الإضافة 2): النقر المزدوج على صف السلة يفتح
        # نافذة تعديله الكاملة — واختيار صف يعبّئ حقلي الكمية والسعر بقيمه
        # (السعر يقفل للمرتجع)، وEnter في حقلي التعديل السريع يطبّق على المحدد
        self.tv_cart.bind("<Double-1>", lambda e: self.edit_cart_row())
        self.tv_cart.bind("<<TreeviewSelect>>", lambda e: self._cart_sel_fill())
        for w in (self.e_cart_qty, self.e_cart_price):
            w.bind("<Return>", lambda e: self.update_selected_cart_row())

    # ═══════════════════════════════════════════════════════
    # ★★★ إضافة (آخر سعر بيع): تلميح آخر سعر تحت حقل الصنف + نافذة ★★★
    # الاستعلام — ميزة قراءة فقط فوق جدول operations القائم بلا أي
    # تعديل على أي سلوك قائم: التلميح يعرض سعر الوحدة لأحدث عملية بيع
    # زمنياً (بالأوقات الحقيقية من monitor_op_times القائمة قراءةً فقط)
    # ونافذة الاستعلام تعرض آخر 5 عمليات مطابقة، وكل بحث بفحص صلاحية
    # داخلي ثانٍ (last_price_view) قبل أي قراءة، وأي فشل يُسجَّل في
    # error_log.txt ولا يعيق إكمال الفاتورة أبداً
    # ═══════════════════════════════════════════════════════
    def _lp_build_hint_label(self):
        """★ إضافة (آخر سعر بيع): بناء سطر التلميح داخل مضيفه تحت حقل
        اسم الصنف — يُستدعى عند بناء شاشة الفاتورة وعند إعادة بناء
        الواجهة بعد تبديل المستخدم لمن يملك المفتاح فقط"""
        if getattr(self, "_inv_lp_hint_host", None) is None:
            return
        self.lbl_inv_last_price = tk.Label(
            self._inv_lp_hint_host, text="", bg=CARD, fg=GRAY,
            font=("Segoe UI", 10, "bold"), anchor="e", justify="right")
        self.lbl_inv_last_price.pack(fill="x", padx=(60, 10), pady=(0, 6))

    def _lp_hint_hide(self):
        """★ إضافة (آخر سعر بيع): إخفاء سطر التلميح بهدوء — بلا أي بحث
        وبلا أي خطأ مهما كانت الحالة (فشل التلميح لا يعيق الفاتورة
        أبداً) وآمنة تماماً إن لم يكن التلميح مبنياً أصلاً"""
        try:
            lbl = getattr(self, "lbl_inv_last_price", None)
            if lbl is not None and lbl.winfo_exists():
                lbl.config(text="", fg=GRAY)
        except Exception:
            pass

    def _lp_hint_on_change(self):
        """★ إضافة (آخر سعر بيع): عند كتابة أي حرف — لا بحث إطلاقاً؛
        فقط إخفاء التلميح فور تغيّر الاسم عن آخر ما بُحث عنه كي لا يبقى
        سطر قديم مضلل (البحث عند Enter أو اختيار من القائمة أو خروج
        المؤشر من الحقل فقط)"""
        try:
            if not user_has_permission(CURRENT_USER["name"], "last_price_view"):
                return
            cur = _lp_norm(self.cb_inv_item.get())
            if cur != getattr(self, "_lp_last_query", None):
                self._lp_hint_hide()
        except Exception:
            pass

    def _lp_hint_update(self):
        """★ إضافة (آخر سعر بيع): البحث عن آخر سعر بيع للصنف المكتوب
        وتحديث سطر التلميح — يُستدعى عند خروج المؤشر من حقل اسم الصنف
        أو ضغط Enter (بعد معالج الإضافة القائم) أو اختيار صنف من
        القائمة. الطبقة الثانية من الصلاحية أول كل شيء: من لا يملك
        last_price_view يخفي التلميح ويعود فوراً دون أي بحث"""
        try:
            if not user_has_permission(CURRENT_USER["name"], "last_price_view"):
                self._lp_hint_hide()
                return
            lbl = getattr(self, "lbl_inv_last_price", None)
            if lbl is None or not lbl.winfo_exists():
                return
            text = self.cb_inv_item.get().strip()
            if not text:          # حقل فارغ: لا يتم أي بحث
                self._lp_hint_hide()
                return
            res = last_price_find(CURRENT_USER["name"], text)
            if res["status"] == "found":
                row = res["row"]
                cust = row["customer"] or "بدون اسم"
                lbl.config(text=f"آخر سعر بيع: {money(row['price'])} — "
                                f"بتاريخ {row['when']} — العميل: {cust}",
                           fg=ACCENT)
            elif res["status"] == "notfound":
                lbl.config(text="لا يوجد سجل بيع سابق لهذا الصنف", fg=GRAY)
            else:
                lbl.config(text="تعذر جلب آخر سعر بيع الآن — سُجّل الخطأ في "
                                "error_log.txt", fg=ORANGE)
            self._lp_last_query = _lp_norm(text)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            try:
                lbl = getattr(self, "lbl_inv_last_price", None)
                if lbl is not None and lbl.winfo_exists():
                    lbl.config(text="تعذر جلب آخر سعر بيع الآن — سُجّل الخطأ "
                                    "في error_log.txt", fg=ORANGE)
            except Exception:
                pass

    def show_last_prices_window(self):
        """★ إضافة (آخر سعر بيع): نافذة استعلام صغيرة — حقل بحث وقائمة
        آخر 5 عمليات بيع مطابقة (التاريخ/الصنف/سعر الوحدة/الكمية/العميل/
        البائع/رقم الفاتورة)، المطابقة التامة بعد التطبيع أولًا فإن لم
        توجد فمطابقة جزئية مع الإشارة لذلك، والبحث عند Enter أو ضغط زر
        البحث فقط (لا بحث تلقائي مع كل حرف إطلاقاً)"""
        # الطبقة الثانية (دفاع مزدوج مع إخفاء الزر): لا فتح بلا صلاحية
        if not user_has_permission(CURRENT_USER["name"], "last_price_view"):
            messagebox.showwarning("لا تملك صلاحية",
                "استعلام آخر الأسعار يتطلب صلاحية «آخر سعر بيع (شاشة "
                "الفاتورة)» — راجع الأدمن")
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("استعلام آخر الأسعار")
        win.configure(bg=BG)
        win.resizable(False, False)
        try:
            win.transient(self)
        except Exception:
            pass
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER,
                        highlightthickness=1)
        card.pack(fill="both", expand=True, padx=16, pady=14)
        tk.Label(card, text="🔍 استعلام آخر الأسعار", bg=CARD, fg=DARK,
                 font=FT).pack(pady=(12, 2))
        tk.Label(card, text="اكتب اسم صنف ثم اضغط Enter أو زر البحث — آخر 5 عمليات بيع مطابقة",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(pady=(0, 6))
        srow = tk.Frame(card, bg=CARD)
        srow.pack(fill="x", padx=14, pady=4)
        tk.Label(srow, text="اسم الصنف:", bg=CARD, fg=DARK,
                 font=FB).pack(side="right", padx=(0, 8))
        e_q = tk.Entry(srow, font=F, justify="center", relief="solid",
                       bd=1, width=28)
        e_q.pack(side="right", ipady=4)
        lbl_mode = tk.Label(card, text="", bg=CARD, fg=GRAY,
                            font=("Segoe UI", 10, "bold"), anchor="e",
                            justify="right")
        lbl_mode.pack(fill="x", padx=14, pady=(4, 2))
        frm, tv = self.mk_tree(card,
            ["رقم الفاتورة", "البائع", "العميل", "الكمية", "سعر الوحدة",
             "الصنف", "التاريخ"],
            [85, 100, 125, 65, 95, 180, 135])
        frm.pack(fill="both", expand=True, padx=14, pady=(2, 8))
        try:
            tv.configure(height=6)
        except Exception:
            pass

        def do_search():
            """★ البحث عند Enter أو الزر فقط — محدود بآخر 5 عمليات
            ولا يجمد الواجهة (لا بحث مع كل حرف إطلاقاً)"""
            try:
                text = e_q.get().strip()
                tv.delete(*tv.get_children())
                if not text:      # حقل فارغ: لا يتم أي بحث
                    lbl_mode.config(text="اكتب اسم صنف للبحث أولًا", fg=ORANGE)
                    return
                res = last_price_search(CURRENT_USER["name"], text, 5)
                if res["status"] == "found":
                    for row in res["rows"]:
                        tv.insert("", "end", values=(
                            (row["invoice"] or "—"),
                            (row["seller"] or "—"),
                            (row["customer"] or "—"),
                            f'{row["qty"]:g}',
                            money(row["price"]),
                            row["item"],
                            row["when"]))
                    lbl_mode.config(
                        text=f"نتائج {res['mode']} — عدد النتائج: {len(res['rows'])}",
                        fg=(ORANGE if res["mode"] == "مطابقة جزئية" else ACCENT))
                elif res["status"] == "notfound":
                    lbl_mode.config(text="لا توجد نتائج مطابقة لـ«" + text + "»",
                                    fg=GRAY)
                else:
                    lbl_mode.config(text="", fg=GRAY)
                    messagebox.showwarning("خطأ في البحث",
                        "تعذر تنفيذ البحث الآن — سُجّل الخطأ في error_log.txt\n"
                        "حاول مرة أخرى", parent=win)
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                messagebox.showwarning("خطأ في البحث",
                    "تعذر تنفيذ البحث الآن — سُجّل الخطأ في error_log.txt",
                    parent=win)

        b_go = self.mk_btn(srow, "🔍 بحث", do_search, ACCENT)
        b_go.pack(side="right", padx=8)
        add_tip(b_go, "عرض آخر 5 عمليات بيع مطابقة لاسم الصنف — مطابقة تامة "
                      "أولًا فإن لم توجد فمطابقة جزئية")
        e_q.bind("<Return>", lambda e: do_search())
        e_q.focus_set()

    def add_to_cart(self):
        """★ إضافة (ميزة 6): التحقق ثم إضافة الصنف الحالي إلى السلة"""
        item = self.cb_inv_item.get().strip()
        if not item:
            messagebox.showwarning("تنبيه", "اكتب اسم الصنف أولاً"); return
        q  = to_num(self.e_inv_qty.get())
        pr = to_num(self.e_inv_price.get())
        if q is None or q <= 0:
            messagebox.showwarning("تنبيه",
                f"الكمية غير صحيحة: «{self.e_inv_qty.get()}»\nأدخل رقماً أكبر من صفر"); return
        if pr is None or pr < 0:
            messagebox.showwarning("تنبيه",
                f"السعر غير صحيح: «{self.e_inv_price.get()}»\nأدخل رقماً صحيحاً"); return
        t = self.inv_type_var.get()
        # ★ إضافة (الإصدار 16 — القسم 1-1): المرتجع في السلة يُربط بالأصل —
        # لا إضافة بلا أصل، ولا كمية فوق المتبقي (بعد خصم ما بالسلة)،
        # والسعر بسعر الأصل دائماً
        orig_id = None
        if t == "مرتجع":
            orig = self._inv_orig_map.get(self.cb_inv_orig.get())
            if orig is None:
                messagebox.showwarning("مرتجع بلا أصل",
                    "اختر «العملية المُرجَعة» من القائمة أولاً —\n"
                    "ممنوع إضافة مرتجع بلا عملية بيع أصلية.")
                return
            if q > orig["qty"] + RET_EPS:      # orig["qty"] = المتاح بعد خصم السلة
                messagebox.showwarning("كمية المرتجع أكبر من المتاح",
                    f"الكمية المتاحة للإرجاع من العملية رقم {orig['id']}: {orig['qty']:g}\n"
                    "(كمية الأصل ناقصاً المرتجعات السابقة وما أُضيف للسلة)")
                return
            pr = orig["price"]          # السعر يعود تلقائياً بسعر الأصل
            orig_id = orig["id"]
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع): لا يُضاف أي مرتجع إلى
        # السلة دون سبب من القائمة الثابتة (والملاحظة اختيارية) — يُخزنان
        # مع صف السلة حتى حفظ الفاتورة في عمودي return_reason وreturn_note
        _reason4 = ""
        _note4 = ""
        if t == "مرتجع":
            _reason4 = (self.cb_inv_ret_reason.get().strip()
                        if hasattr(self, "cb_inv_ret_reason") else "")
            if not _reason4:
                messagebox.showwarning("سبب المرتجع إلزامي",
                    "اختر سبب المرتجع من القائمة أولاً —\n"
                    "لا يُضاف مرتجع إلى السلة دون سبب.")
                return
            _note4 = (self.e_inv_ret_note.get().strip()
                      if hasattr(self, "e_inv_ret_note") else "")
        total = q * pr
        if t == "مرتجع":
            total = -total          # المرتجع في السلة أيضاً بقيمة سالبة
        # ★ تعديل ضروري معلن (الإصدار 16 — القسم 1-1): صف السلة يحمل رابط الأصل
        # ★ تعديل مصرح به (المرحلة الرابعة): وصف السلة يحمل سبب المرتجع وملاحظته
        self.cart.append({"item": item, "qty": q, "price": pr, "total": total, "type": t,
                          "orig_id": orig_id, "reason": _reason4, "note": _note4})
        self.e_inv_qty.delete(0, "end"); self.e_inv_price.delete(0, "end")
        self.cb_inv_item.set("")
        # ★ إضافة (الإصدار 16): تحديث قائمة الأصول — المتاح تغيّر بما أُضيف
        # ★ إضافة (آخر سعر بيع): إخفاء تلميح آخر سعر بعد تفريغ حقل الصنف
        # — التلميح يتحدث أو يختفي عند تغيّر الاسم (وتفريغ الحقل تغيير
        # له)، والدالة آمنة تماماً لمن لا يملك المفتاح (لا تلميح له
        # أصلاً) ولا تعيق إضافة السلة إطلاقاً
        self._lp_hint_hide()
        self._refresh_inv_orig_list()
        self.update_cart_view()
        self.lbl_inv_status.config(text=f"✔ أُضيف إلى السلة ({t}: {item})", fg=GREEN)

    def remove_from_cart(self):
        """★ إضافة (ميزة 6): إزالة صنف محدد من السلة قبل الحفظ"""
        sel = self.tv_cart.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر صنفاً من السلة أولاً"); return
        removed = self.cart.pop(int(sel[0]))
        self.update_cart_view()
        self.lbl_inv_status.config(text=f"🗑 أُزيل من السلة: {removed['item']}", fg=RED)

    def update_cart_view(self):
        """★ إضافة (ميزة 6): إعادة رسم جدول السلة والإجمالي اللحظي"""
        self.tv_cart.delete(*self.tv_cart.get_children())
        for i, it in enumerate(self.cart):
            self.tv_cart.insert("", "end", iid=str(i),
                tags=(("ret",) if it["type"] == "مرتجع" else ()),
                # ★ إضافة (الإصدار 16 — القسم 1-1): «↩ مرجع: [رقم الأصل]» بجانب
                # صنف المرتجع داخل السلة
                values=(it["type"], money(it["total"]), money(it["price"]),
                        f'{it["qty"]:g}',
                        it["item"] + ret_ref_mark(it["type"] == "مرتجع", it.get("orig_id"))))
        tot = sum(it["total"] for it in self.cart)
        self.lbl_inv_total.config(text=f"إجمالي السلة: {money(tot)}",
                                  fg=(ACCENT if tot >= 0 else RED))
        # ★★★ إضافة (المرحلة الرابعة): سطر الإجمالي بعد الخصم يتحدث مع كل
        # تغيّر في السلة
        try:
            self._inv_disc_recalc()
        except Exception:
            pass

    # ═══════════════════════════════════════════════════════
    # ★★★ إضافة (الإصدار 17 — الإضافة 2): تعديل صنف داخل السلة ✏️ ★★★
    # نقر مزدوج على صف السلة يفتح نافذة تعديل كاملة، وشريط التعديل السريع
    # (أزرار +/- للكمية وحقلا كمية/سعر وزر «تحديث المحدد») يعدّل مباشرة —
    # بلا حذف وإعادة إدخال، وبنفس تحققات الإضافة كاملة، والمرتجع داخل السلة
    # يظل مربوطاً بأصله (كمية محدودة بالمتبقي وسعر مقفل) — والسلة بالذاكرة
    # حتى الحفظ النهائي فلا تُلمس قاعدة البيانات إطلاقاً
    # ═══════════════════════════════════════════════════════
    def _cart_orig_available(self, orig_id, exclude_idx):
        """★ إضافة (الإصدار 17 — الإضافة 2): المتاح للإرجاع من أصل ما بخصم
        مطالبات السلة عليه (عدا الصف المُعدَّل نفسه) — return_remaining_of
        يعرف المرتجعات المحفوظة فقط فتُخصم منها مطالبات السلة الحالية"""
        rem = return_remaining_of(orig_id)
        for j, o in enumerate(self.cart):
            if j != exclude_idx and o.get("type") == "مرتجع" and o.get("orig_id") == orig_id:
                rem -= o["qty"]
        return rem

    def _cart_sel_fill(self):
        """★ إضافة (الإصدار 17 — الإضافة 2): اختيار صف من السلة يعبّئ حقلي
        الكمية والسعر بقيمه — والسعر يقفل للمرتجع (تعديل سعر المرتجع ممنوع:
        سعره بسعر أصله دائماً)"""
        try:
            sel = self.tv_cart.selection()
            if not sel:
                self.e_cart_qty.delete(0, "end")
                if str(self.e_cart_price.cget("state")) == "disabled":
                    self.e_cart_price.config(state="normal")
                self.e_cart_price.delete(0, "end")
                return
            it = self.cart[int(sel[0])]
            self.e_cart_qty.delete(0, "end")
            self.e_cart_qty.insert(0, f'{it["qty"]:g}')
            if str(self.e_cart_price.cget("state")) == "disabled":
                self.e_cart_price.config(state="normal")
            self.e_cart_price.delete(0, "end")
            self.e_cart_price.insert(0, f'{it["price"]:g}')
            if it["type"] == "مرتجع":
                self.e_cart_price.config(state="disabled", disabledforeground=GRAY)
        except Exception:
            pass

    def cart_qty_step(self, delta):
        """★ إضافة (الإصدار 17 — الإضافة 2): أزرار +/- للكمية — زيادة أو
        إنقاص 1 من الصف المحدد فوراً وإعادة حساب الصف والإجمالي، بحدود نفس
        تحققات الإضافة (لا صفر، والمرتجع لا يتجاوز متاح أصله)"""
        sel = self.tv_cart.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر صنفاً من السلة أولاً"); return
        idx = int(sel[0])
        it = self.cart[idx]
        new_q = it["qty"] + delta
        if new_q <= 0:
            messagebox.showwarning("تنبيه",
                "الكمية يجب أن تبقى أكبر من صفر — للإزالة استخدم زر "
                "«🗑 إزالة المحدد من السلة»")
            return
        if it["type"] == "مرتجع":
            avail = self._cart_orig_available(it["orig_id"], idx)
            if new_q > avail + RET_EPS:
                messagebox.showwarning("كمية المرتجع أكبر من المتاح",
                    f"الكمية المتاحة للإرجاع من العملية رقم {it['orig_id']}: {avail:g}\n"
                    "(كمية الأصل ناقصاً المرتجعات السابقة وباقي السلة)")
                return
        old_q = it["qty"]
        it["qty"] = new_q
        it["total"] = (-new_q if it["type"] == "مرتجع" else new_q) * it["price"]
        self.update_cart_view()
        self.tv_cart.selection_set(str(idx))
        self._refresh_inv_orig_list()
        self.lbl_inv_status.config(
            text=f"✏️ كمية «{it['item']}»: {old_q:g} ← {new_q:g}", fg=GREEN)
        audit("تعديل صف سلة",
              f"{it['type']}: {it['item']} — الكمية {old_q:g} ← {new_q:g} "
              + (f"(زر {'+' if delta > 0 else '-'})"))

    def update_selected_cart_row(self):
        """★ إضافة (الإصدار 17 — الإضافة 2): زر «🔄 تحديث المحدد» — يطبق قيم
        حقلي الكمية والسعر على الصف المحدد ويعيد حساب الصف والإجمالي — بنفس
        تحققات الإضافة كاملة (وسعر المرتجع مقفل بسعر أصله)"""
        sel = self.tv_cart.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر صنفاً من السلة أولاً"); return
        idx = int(sel[0])
        it = self.cart[idx]
        q = to_num(self.e_cart_qty.get())
        if q is None or q <= 0:
            messagebox.showwarning("تنبيه",
                f"الكمية غير صحيحة: «{self.e_cart_qty.get()}»\nأدخل رقماً أكبر من صفر"); return
        if it["type"] == "مرتجع":
            avail = self._cart_orig_available(it["orig_id"], idx)
            if q > avail + RET_EPS:
                messagebox.showwarning("كمية المرتجع أكبر من المتاح",
                    f"الكمية المتاحة للإرجاع من العملية رقم {it['orig_id']}: {avail:g}\n"
                    "(كمية الأصل ناقصاً المرتجعات السابقة وباقي السلة)")
                return
            pr = it["price"]          # سعر المرتجع مقفل بسعر أصله دائماً
        else:
            pr = to_num(self.e_cart_price.get())
            if pr is None or pr < 0:
                messagebox.showwarning("تنبيه",
                    f"السعر غير صحيح: «{self.e_cart_price.get()}»\nأدخل رقماً صحيحاً"); return
        old_q, old_pr = it["qty"], it["price"]
        it["qty"], it["price"] = q, pr
        it["total"] = (-q if it["type"] == "مرتجع" else q) * pr
        self.update_cart_view()
        self.tv_cart.selection_set(str(idx))
        self._refresh_inv_orig_list()
        self.lbl_inv_status.config(
            text=f"✏️ حُدِّث «{it['item']}»: {old_q:g} × {old_pr:g} ← {q:g} × {pr:g}",
            fg=GREEN)
        audit("تعديل صف سلة",
              f"{it['type']}: {it['item']} — {old_q:g} × {old_pr:g} ← {q:g} × {pr:g} (تحديث المحدد)")

    def edit_cart_row(self):
        """★ إضافة (الإصدار 17 — الإضافة 2): النقر المزدوج على صف السلة —
        نافذة تعديل صغيرة بحقول الصنف معبأة بقيمه (الاسم/الكمية/السعر/النوع/
        العميل) وزرا حفظ وإلغاء — الحفظ بنفس تحققات الإضافة كاملة ثم تحديث
        الصف وإعادة رسم الجدول والإجمالي بلا حذف وإعادة إدخال، والمرتجع يظل
        مربوطاً بأصله (كمية محدودة بالمتبقي وسعر مقفل بسعر الأصل)"""
        sel = self.tv_cart.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر صنفاً من السلة أولاً"); return
        idx = int(sel[0])
        it = self.cart[idx]
        win = self.register_window(tk.Toplevel(self))
        win.title("✏️ تعديل صنف السلة")
        win.configure(bg=BG); win.resizable(False, False)
        win.transient(self)
        try:
            win.grab_set()
        except Exception:
            pass
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        card.pack(fill="both", expand=True, padx=18, pady=14)
        # القاعدة الذهبية: زرا الحفظ/الإلغاء يُحزمان side="bottom" أولاً
        fr_btns = tk.Frame(card, bg=CARD)
        fr_btns.pack(side="bottom", fill="x", pady=(8, 12))
        tk.Label(card, text="✏️ تعديل صنف السلة", bg=CARD, fg=DARK, font=FT).pack(pady=(12, 2))
        tk.Label(card, text=f"الصف {idx + 1} من {len(self.cart)} — التعديل بالذاكرة حتى حفظ الفاتورة",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(pady=(0, 6))

        def frow(label, width=16):
            fr = tk.Frame(card, bg=CARD); fr.pack(fill="x", padx=16, pady=4)
            tk.Label(fr, text=label, bg=CARD, fg=DARK, font=FB, width=width,
                     anchor="e").pack(side="right")
            inner = tk.Frame(fr, bg=CARD)
            inner.pack(side="right", padx=(0, 8))
            return inner

        i_item = frow("اسم الصنف:")
        cb_item = ttk.Combobox(i_item, font=F, width=24)
        cb_item.pack(side="right", ipady=4)
        cb_item.set(it["item"])
        try:
            cb_item["values"] = self.cb_inv_item["values"]   # نفس قائمة الأصناف القائمة
        except Exception:
            pass

        i_qty = frow("الكمية:")
        e_qty = tk.Entry(i_qty, font=F, justify="center", relief="solid", bd=1, width=24)
        e_qty.pack(side="right", ipady=4)
        e_qty.insert(0, f'{it["qty"]:g}')
        digits_only_filter(e_qty)

        i_price = frow("السعر:")
        e_price = tk.Entry(i_price, font=F, justify="center", relief="solid", bd=1, width=24)
        e_price.pack(side="right", ipady=4)
        e_price.insert(0, f'{it["price"]:g}')
        digits_only_filter(e_price)

        trow = tk.Frame(card, bg=CARD); trow.pack(fill="x", padx=16, pady=(6, 2))
        tk.Label(trow, text="النوع:", bg=CARD, fg=DARK, font=FB).pack(side="right", padx=(0, 10))
        type_var = tk.StringVar(value=it["type"])
        for txt, col in [("نقداً", GREEN), ("شبكة", ACCENT), ("مرتجع", RED)]:
            tk.Radiobutton(trow, text=txt, variable=type_var, value=txt, font=FB,
                           fg=col, bg=CARD, selectcolor="#dbeafe", activebackground=CARD,
                           activeforeground=col, indicatoron=0, width=8, bd=1,
                           relief="solid", cursor="hand2").pack(side="right", padx=5)

        # صف «العملية المُرجَعة» — يظهر عند اختيار «مرتجع» فقط (نفس نمط الفاتورة)
        fr_orig = tk.Frame(card, bg=CARD)
        orow = tk.Frame(fr_orig, bg=CARD); orow.pack(fill="x", pady=3)
        tk.Label(orow, text="العملية المُرجَعة:", bg=CARD, fg=RED, font=FB,
                 width=16, anchor="e").pack(side="right")
        inner_o = tk.Frame(orow, bg=CARD)
        inner_o.pack(side="right", padx=(0, 8))
        cb_orig = ttk.Combobox(inner_o, font=F, width=24, state="readonly")
        cb_orig.pack(side="right", ipady=4)
        lbl_orig = tk.Label(orow, text="", bg=CARD, fg=GRAY,
                            font=("Segoe UI", 9, "bold"))
        lbl_orig.pack(side="right", padx=8)
        add_tip(cb_orig, "اختر عملية البيع الأصلية — المتاح يخصم المرتجعات السابقة وباقي السلة")
        orig_map = {}
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع): تعديل سبب المرتجع
        # وملاحظته من نافذة تعديل الصف — إلزامي ما دام النوع مرتجعاً
        # (يُعبأ بما خُزن مع صف السلة سابقاً)
        fr_ret4 = tk.Frame(card, bg=CARD)
        rr4 = tk.Frame(fr_ret4, bg=CARD); rr4.pack(fill="x", pady=3)
        tk.Label(rr4, text="سبب المرتجع:", bg=CARD, fg=RED, font=FB,
                 width=16, anchor="e").pack(side="right")
        inner_rr4 = tk.Frame(rr4, bg=CARD)
        inner_rr4.pack(side="right", padx=(0, 8))
        cb_reason4 = ttk.Combobox(inner_rr4, font=F, width=24, state="readonly",
                                  values=list(RETURN_REASONS))
        cb_reason4.pack(side="right", ipady=4)
        cb_reason4.set(it.get("reason") or "")
        nn4 = tk.Frame(fr_ret4, bg=CARD); nn4.pack(fill="x", pady=3)
        tk.Label(nn4, text="ملاحظة (اختياري):", bg=CARD, fg=GRAY, font=FB,
                 width=16, anchor="e").pack(side="right")
        inner_nn4 = tk.Frame(nn4, bg=CARD)
        inner_nn4.pack(side="right", padx=(0, 8))
        e_note4 = tk.Entry(inner_nn4, font=F, justify="center",
                           relief="solid", bd=1, width=26)
        e_note4.pack(side="right", ipady=4)
        e_note4.insert(0, it.get("note") or "")

        i_cust = frow("العميل:")
        e_cust = tk.Entry(i_cust, font=F, justify="center", relief="solid", bd=1, width=24)
        e_cust.pack(side="right", ipady=4)
        e_cust.insert(0, self.e_inv_customer.get())
        tk.Label(i_cust, text="(لكامل الفاتورة)", bg=CARD, fg=GRAY,
                 font=("Segoe UI", 9)).pack(side="right", padx=(4, 0))

        lbl_err = tk.Label(card, text="", bg=CARD, fg=RED,
                           font=("Segoe UI", 9, "bold"), wraplength=330, justify="center")
        lbl_err.pack(pady=(2, 0))

        def _unlock_price():
            if str(e_price.cget("state")) == "disabled":
                e_price.config(state="normal")
                e_price.delete(0, "end")

        def refresh_orig_list():
            try:
                cb_orig.set("")
                orig_map.clear()
                lbl_orig.config(text="", fg=GRAY)
                _unlock_price()
                item = cb_item.get().strip()
                if not item:
                    cb_orig["values"] = []
                    lbl_orig.config(text="اكتب اسم الصنف لعرض عمليات بيعه", fg=ORANGE)
                    return
                labels = []
                for o in return_eligible_originals(item):
                    avail = self._cart_orig_available(o["id"], idx)
                    if avail <= RET_EPS:
                        continue          # استُهلك متاحه داخل هذه الفاتورة
                    o = dict(o)
                    o["qty"] = avail
                    lbl = (f'[{o["id"]}] — [{o["date"]}] — كمية [{avail:g}] — '
                           f'بـ [{o["price"]:g}] — [{o["type"]}]')
                    labels.append(lbl)
                    orig_map[lbl] = o
                cb_orig["values"] = labels
                if not labels:
                    lbl_orig.config(text="لا عمليات بيع صالحة للمرتجع لهذا الصنف", fg=RED)
            except Exception:
                pass

        def orig_selected():
            try:
                s = orig_map.get(cb_orig.get())
                if not s:
                    return
                _unlock_price()
                e_price.insert(0, f'{s["price"]:g}')
                e_price.config(state="disabled", disabledforeground=DARK)
                lbl_orig.config(text=f'المتاح للإرجاع: {s["qty"]:g}', fg="#0d9488")
            except Exception:
                pass

        def sync_return_ui():
            try:
                if type_var.get() == "مرتجع":
                    fr_orig.pack(fill="x", padx=16, pady=2, after=trow)
                    # ★★★ إضافة (المرحلة الرابعة): صفا السبب والملاحظة
                    # يظهران مع صف الأصل للمرتجع فقط
                    fr_ret4.pack(fill="x", padx=16, pady=2, after=fr_orig)
                    refresh_orig_list()
                else:
                    fr_orig.pack_forget()
                    fr_ret4.pack_forget()
                    cb_orig.set("")
                    orig_map.clear()
                    lbl_orig.config(text="", fg=GRAY)
                    _unlock_price()
            except Exception:
                pass

        def _item_changed():
            if type_var.get() == "مرتجع":
                refresh_orig_list()

        cb_orig.bind("<<ComboboxSelected>>", lambda e: orig_selected())
        type_var.trace_add("write", lambda *_: sync_return_ui())
        cb_item.bind("<KeyRelease>", lambda e: _item_changed())
        cb_item.bind("<<ComboboxSelected>>", lambda e: _item_changed())
        sync_return_ui()
        # تعبئة أصل المرتجع الحالي إن كان الصف المُعدَّل مرتجعاً مربوطاً
        if it["type"] == "مرتجع" and it.get("orig_id"):
            for lbl, o in orig_map.items():
                if o["id"] == it["orig_id"]:
                    cb_orig.set(lbl)
                    orig_selected()
                    break

        def do_save():
            item = cb_item.get().strip()
            if not item:
                lbl_err.config(text="اكتب اسم الصنف أولاً")
                shake_widget(card); return
            q = to_num(e_qty.get())
            if q is None or q <= 0:
                lbl_err.config(text=f"الكمية غير صحيحة: «{e_qty.get()}» — أدخل رقماً أكبر من صفر")
                shake_widget(card); return
            t = type_var.get()
            orig_id = None
            _reason4 = ""
            _note4 = ""
            if t == "مرتجع":
                s = orig_map.get(cb_orig.get())
                if s is None:
                    lbl_err.config(text="اختر «العملية المُرجَعة» أولاً — ممنوع مرتجع بلا أصل")
                    shake_widget(card); return
                if q > s["qty"] + RET_EPS:
                    lbl_err.config(text=f"المتاح للإرجاع من العملية رقم {s['id']}: {s['qty']:g}")
                    shake_widget(card); return
                pr = s["price"]          # سعر المرتجع دائماً بسعر أصله
                orig_id = s["id"]
                # ★★★ إضافة (المرحلة الرابعة): السبب إلزامي للمرتجع داخل
                # نافذة التعديل أيضاً
                _reason4 = cb_reason4.get().strip()
                if not _reason4:
                    lbl_err.config(text="اختر سبب المرتجع من القائمة أولاً — إلزامي")
                    shake_widget(card); return
                _note4 = e_note4.get().strip()
            else:
                pr = to_num(e_price.get())
                if pr is None or pr < 0:
                    lbl_err.config(text=f"السعر غير صحيح: «{e_price.get()}» — أدخل رقماً صحيحاً")
                    shake_widget(card); return
            total = (-q * pr) if t == "مرتجع" else (q * pr)
            old = dict(it)
            it["item"], it["qty"], it["price"], it["total"] = item, q, pr, total
            it["type"], it["orig_id"] = t, orig_id
            # ★★★ إضافة (المرحلة الرابعة): حفظ السبب والملاحظة مع صف السلة
            it["reason"], it["note"] = _reason4, _note4
            # حقل العميل يخص الفاتورة كلها — يُحدَّث حقل الفاتورة نفسه
            new_cust = e_cust.get().strip()
            self.e_inv_customer.delete(0, "end")
            if new_cust:
                self.e_inv_customer.insert(0, new_cust)
            self.update_cart_view()
            self.tv_cart.selection_set(str(idx))
            self._refresh_inv_orig_list()
            audit("تعديل صف سلة",
                  f"{old['type']}: {old['item']} — {old['qty']:g} × {old['price']:g} = {old['total']:g}"
                  f"  ←  {t}: {item} — {q:g} × {pr:g} = {total:g}"
                  + (f" | مربوط بالعملية رقم {orig_id}" if orig_id else ""))
            self.lbl_inv_status.config(text=f"✏️ تم تعديل «{item}» داخل السلة", fg=GREEN)
            win.destroy()

        self.mk_btn(fr_btns, "💾 حفظ", do_save, GREEN).pack(side="right", padx=6)
        self.mk_btn(fr_btns, "إلغاء", win.destroy, "#475569").pack(side="right", padx=6)
        e_qty.bind("<Return>", lambda _e: do_save())
        e_price.bind("<Return>", lambda _e: do_save())
        place_window(win, 470)

    # ★★★ إضافات (الإصدار 16 — القسم 1-1): دوال ربط المرتجع بالأصل في الفاتورة ↩ ★★★
    def _sync_inv_return_ui(self):
        """إظهار/إخفاء صف «العملية المُرجَعة» في الفاتورة حسب النوع (يستدعيه
        تتبع inv_type_var تلقائياً) — عند غير المرتجع يُفتح قفل السعر ويُمسح"""
        try:
            if self.inv_type_var.get() == "مرتجع":
                self.fr_inv_orig.pack(fill="x", padx=22, pady=6, after=self._trow_inv_ref)
                self._refresh_inv_orig_list()
            else:
                self.fr_inv_orig.pack_forget()
                self.cb_inv_orig.set("")
                self._inv_orig_map = {}
                self.lbl_inv_orig_info.config(text="", fg=GRAY)
                if str(self.e_inv_price.cget("state")) == "disabled":
                    self.e_inv_price.config(state="normal")
                    self.e_inv_price.delete(0, "end")
        except Exception:
            pass

    def _refresh_inv_orig_list(self):
        """تحديث قائمة الأصول الصالحة حسب الصنف المكتوب — المتاح يخصم المرتجعات
        السابقة وما أُضيف للسلة على نفس الأصل في هذه الفاتورة"""
        try:
            self.cb_inv_orig.set("")
            self._inv_orig_map = {}
            self.lbl_inv_orig_info.config(text="", fg=GRAY)
            if str(self.e_inv_price.cget("state")) == "disabled":
                self.e_inv_price.config(state="normal")
                self.e_inv_price.delete(0, "end")
            if self.inv_type_var.get() != "مرتجع":
                self.cb_inv_orig["values"] = []
                return
            item = self.cb_inv_item.get().strip()
            if not item:
                self.cb_inv_orig["values"] = []
                self.lbl_inv_orig_info.config(text="اكتب اسم الصنف لعرض عمليات بيعه", fg=ORANGE)
                return
            claims = {}     # ما CLAIMه السلة على كل أصل في هذه الفاتورة
            for it in self.cart:
                if it.get("type") == "مرتجع" and it.get("orig_id"):
                    claims[it["orig_id"]] = claims.get(it["orig_id"], 0) + it["qty"]
            labels = []
            for o in return_eligible_originals(item):
                avail = o["qty"] - claims.get(o["id"], 0)
                if avail <= RET_EPS:
                    continue      # استُهلك متاحه داخل هذه الفاتورة
                o = dict(o)
                o["qty"] = avail
                lbl = (f'[{o["id"]}] — [{o["date"]}] — كمية [{avail:g}] — '
                       f'بـ [{o["price"]:g}] — [{o["type"]}]')
                labels.append(lbl)
                self._inv_orig_map[lbl] = o
            self.cb_inv_orig["values"] = labels
            if not labels:
                self.lbl_inv_orig_info.config(text="لا عمليات بيع صالحة للمرتجع لهذا الصنف", fg=RED)
        except Exception:
            pass

    def _inv_orig_selected(self):
        """تعبئة سعر الفاتورة بسعر الأصل وقفله + عرض المتاح للإرجاع"""
        try:
            sel = self._inv_orig_map.get(self.cb_inv_orig.get())
            if not sel:
                return
            self.e_inv_price.config(state="normal")
            self.e_inv_price.delete(0, "end")
            self.e_inv_price.insert(0, f'{sel["price"]:g}')
            self.e_inv_price.config(state="disabled", disabledforeground=DARK)
            self.lbl_inv_orig_info.config(text=f'المتاح للإرجاع: {sel["qty"]:g}', fg="#0d9488")
        except Exception:
            pass

    def save_invoice(self):
        """★ إضافة (ميزة 6): تأكيد بالمجموع ثم حفظ كل الأصناف دفعة واحدة كعمليات اليوم"""
        # ★ إضافة (إصدار 8 — الميزة 5): صلاحية «إضافة عمليات وفواتير» — الفحص
        # الدقيق الجديد (المدير يملك كل الصلاحيات دائماً ولا يلاحظ الفرق)
        if not self.has_permission("add_ops"):
            messagebox.showwarning("صلاحية", "ليست لديك صلاحية «إضافة عمليات وفواتير»")
            return
        # ★★★ إضافة (المرحلة الرابعة — البيع بالدين): التقاط سياق البيع
        # بالدين مرة واحدة في البداية وتصفيره فوراً — لا دين إلا بعد نجاح
        # حفظ الفاتورة كاملة بنفس دالتها القائمة
        _credit4 = self._pending_credit
        self._pending_credit = None
        # ★ إضافة (عروض الأسعار): التقاط سياق تحويل العرض المعلق (دون
        # تصفير) — لا يُعلَّم العرض إلا بعد نجاح حفظ الفاتورة فعليًا في
        # خطاف النجاح أدناه، وإن فشل الحفظ أو أُلغي بقي السياق معلقًا
        # فيُعلَّم العرض عند المحاولة الناجحة التالية
        _quote9 = self._pending_quote
        # ★★★ إضافة (الإصدار 21 — المطلوب 1-3/ج — الاستثناء ب): نقطة التفتيش
        # قبل حفظ الفاتورة (بيع أو مرتجع) مباشرة — نفس الدالة المركزية الوحيدة:
        # يستحيل بعدها تسجيل حركة على يوم تجاري قديم
        try:
            self.ensure_business_day_current()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        # ★ إصلاح (الإصدار 18 — المشكلة 1): الحفظ على يوم العمل التجاري المفتوح
        # بتاريخه لا بتاريخ الجهاز — مطابقةً تامة لسلوك حفظ عملية جديدة save_op
        # القائم (كانت الفاتورة تُحفظ بتاريخ اليوم فتنقسم عمليات ما قبل حد
        # 05:00 فجراً على تاريخ غير تاريخ يوم عملها، وتُحفظ بلا يوم مفتوح أصلاً)
        d = business_day_open()
        if not d:
            messagebox.showwarning("لا يوم عمل مفتوح",
                "لا يمكن حفظ الفاتورة — لا يوم عمل مفتوح.\n"
                "اضغط «▶️ بدء يوم جديد» في شاشة عمليات يوم العمل.")
            return
        if is_closed(d):
            messagebox.showwarning("اليوم مغلق",
                "تم إغلاق اليوم وحفظ تقريره.\nلا يمكن حفظ فاتورة على يوم مغلق.\n"
                "➡ يمكنك إعادة فتح اليوم من شاشة الأرشيف.")
            return
        if not self.cart:
            messagebox.showwarning("السلة فارغة", "أضف صنفاً واحداً على الأقل إلى السلة أولاً"); return
        cust = self.e_inv_customer.get().strip()
        # ★ إضافة (الإصدار 16 — القسم 1-1): تحقق نهائي قبل الحفظ — كل مرتجع
        # في السلة مربوط بأصل، ومجموع كميات السلة لكل أصل لا يتجاوز المتبقي
        # (حماية من تغيّر البيانات بين الإضافة والحفظ)
        for it in self.cart:
            if it["type"] == "مرتجع" and not it.get("orig_id"):
                messagebox.showwarning("مرتجع بلا أصل",
                    f"الصنف «{it['item']}» في السلة مرتجع بلا عملية أصلية —\n"
                    "أزله وأعد إضافته باختيار «العملية المُرجَعة» أولاً.")
                return
        _claims16 = {}
        for it in self.cart:
            if it["type"] == "مرتجع":
                _claims16[it["orig_id"]] = _claims16.get(it["orig_id"], 0) + it["qty"]
        for _oid, _qsum in _claims16.items():
            _rem = return_remaining_of(_oid)
            if _qsum > _rem + RET_EPS:
                messagebox.showwarning("كمية المرتجع أكبر من المتاح",
                    f"مجموع مرتجعات السلة على العملية رقم {_oid} ({_qsum:g})\n"
                    f"يتجاوز الكمية المتاحة للإرجاع ({_rem:g})")
                return
        # ★★★ إضافة (المرحلة الرابعة — سبب المرتجع): خط الدفاع الأخير —
        # كل صنف مرتجع في السلة له سبب (أُلزم عند الإضافة والتعديل)
        for it in self.cart:
            if it["type"] == "مرتجع" and not (it.get("reason") or "").strip():
                messagebox.showwarning("سبب المرتجع إلزامي",
                    f"الصنف «{it['item']}» مرتجع بلا سبب —\n"
                    "أزله وأعد إضافته باختيار سبب من القائمة أولاً.")
                return
        # ★★★ إضافة (المرحلة الرابعة — سقف الخصم): قراءة خصم الفاتورة —
        # 0 أو فراغ = بلا خصم (نفس السلوك القديم)، يوزَّع نسبياً على أصناف
        # البيع فقط (المرتجعات بسعر أصلها)، ثم الطبقتان ضد سقف المستخدم
        _disc4 = 0.0
        if hasattr(self, "e_inv_disc"):
            dv4 = to_num(self.e_inv_disc.get())
            if dv4 is None or dv4 < 0 or dv4 > 100:
                messagebox.showwarning("خصم غير صحيح",
                    f"نسبة الخصم غير صحيحة: «{self.e_inv_disc.get()}»\n"
                    "أدخل رقماً بين 0 و100")
                return
            _disc4 = dv4
        _sale_part4 = sum(it["total"] for it in self.cart if it["type"] != "مرتجع")
        if _disc4 > 0 and _sale_part4 > 0:
            cap4 = user_discount_cap(CURRENT_USER["name"])
            if cap4 is not None and _disc4 > cap4 + 1e-9:
                messagebox.showwarning("سقف الخصم",
                    f"سقف الخصم المسموح لك {cap4:g}% فقط\n"
                    f"خفّض نسبة الخصم ({_disc4:g}%) ثم أعد الحفظ")
                return
            # الطبقة الثانية: إعادة حساب النسبة الفعلية (مبلغ الخصم ÷
            # إجمالي أصناف البيع قبل الخصم × 100) ورفض الحفظ إن تجاوزت السقف
            _amt4 = _sale_part4 * (_disc4 / 100.0)
            _eff4 = _amt4 / _sale_part4 * 100.0
            if cap4 is not None and _eff4 > cap4 + 1e-9:
                messagebox.showwarning("سقف الخصم",
                    f"سقف الخصم المسموح لك {cap4:g}% فقط\n"
                    f"النسبة الفعلية للخصم {_eff4:g}% — عدّلها ثم أعد الحفظ")
                return
        total = sum(it["total"] for it in self.cart)
        # ★★★ إضافة (المرحلة الرابعة): إجمالي الفاتورة بعد الخصم (أصناف
        # البيع تُخَصَّم نسبياً والمرتجعات تبقى بقيمها) — وهو المبلغ المعروض
        # في التأكيد والمُوافَق عليه والمُسجَّل الدين به
        if _disc4 > 0 and _sale_part4 > 0:
            total = _sale_part4 * (1.0 - _disc4 / 100.0) + \
                    sum(it["total"] for it in self.cart if it["type"] == "مرتجع")
        if not messagebox.askyesno("تأكيد حفظ الفاتورة",
                f"عدد الأصناف: {len(self.cart)}\nالمجموع: {money(total)}\n"
                + (f"العميل: {cust}\n" if cust else "")
                    + f"\nسيُحفظ كل صنف كعملية على يوم {d}.\nهل تريد المتابعة؟"):
            return
        # ★★★ إضافة (المرحلة الرابعة — العمليات الكبيرة): الموافقة المسبقة
        # إذا بلغ إجمالي الفاتورة (بيعاً أو ديناً) حد التنبيه أو تجاوزه —
        # صاحب الصلاحية يمر مباشرة وغيره نافذة موافقة مستخدم آخر
        _approver4 = None
        if abs(total) >= stage4_large_op_threshold() - 1e-9:
            _ok4, _approver4 = self._require_large_op_approval(abs(total))
            if not _ok4:
                messagebox.showwarning("عملية كبيرة",
                    "توقفت العملية ولم يُسجل شيء — الفواتير بهذا المبلغ "
                    "تتطلب موافقة مستخدم يملك صلاحية "
                    "«الموافقة على العمليات الكبيرة»")
                return
        snapshot = list(self.cart)   # نسخة للتصدير بعد تفريغ السلة
        # ★★★ إضافة (المرحلة الرابعة — رقم فاتورة متسلسل): رقم واحد متسلسل
        # لا يتكرر للفاتورة كلها يشاركه كل أصنافها + إجمالي كل صف بعد توزيع
        # الخصم نسبياً على أصناف البيع فقط (المرتجعات بقيمها الأصلية)
        _inv4 = None
        try:
            _inv4 = get_next_invoice_number()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        _rows4 = []
        _ids4 = []
        for it in snapshot:
            _rt4 = it["total"]
            if _disc4 > 0 and it["type"] != "مرتجع" and _sale_part4 > 0:
                _rt4 = it["total"] * (1.0 - _disc4 / 100.0)
            _rows4.append((it, _rt4))
        try:
            with connect() as conn:   # ★ معاملة واحدة: كل الأصناف تُحفظ وتُلتزم دفعة واحدة
                for it, _rt4 in _rows4:
                    # ★ تعديل ضروري معلن (إصدار 3 — ميزة 3): كل صنف يُسجل باسم البائع الحالي
                    # ★ تعديل ضروري معلن (الإصدار 16 — القسم 1-1): كل صنف يحمل رابط
                    # أصله إن كان مرتجعاً (NULL لغير المرتجعات كما كانت)
                    # ★ تعديل مصرح به (المرحلة الرابعة): قيمة الصف بعد الخصم
                    cur4 = conn.execute("INSERT INTO operations(date,item_name,quantity,price,total,type,customer_name,seller_name,original_op_id)"
                                 " VALUES(?,?,?,?,?,?,?,?,?)",
                                 (d, it["item"], it["qty"], it["price"], _rt4, it["type"],
                                  cust, CURRENT_USER["name"], it.get("orig_id")))
                    # ★★★ إضافة (المرحلة الرابعة): وسم كل صف برقم الفاتورة
                    # المتسلسل ووسم «دين» وربط العميل وسبب المرتجع وملاحظته
                    # ونسبة الخصم — بعد إدراجه مباشرة وبلا تغيير شكل الإدراج
                    try:
                        conn.execute(
                            "UPDATE operations SET invoice_number=?, payment_kind=?, "
                            "customer_id=?, return_reason=?, return_note=?, discount_percent=? "
                            "WHERE id=?",
                            (_inv4,
                             ("دين" if _credit4 else None),
                             (_credit4["customer_id"] if _credit4 else None),
                             ((it.get("reason") or None) if it["type"] == "مرتجع" else None),
                             ((it.get("note") or None) if it["type"] == "مرتجع" else None),
                             (_disc4 if (_disc4 > 0 and it["type"] != "مرتجع") else None),
                             cur4.lastrowid))
                    except Exception as e:
                        log_error(e, sys.exc_info()[2])
                    _ids4.append(cur4.lastrowid)
        except Exception as e:
            messagebox.showerror("خطأ في الحفظ", f"تعذر حفظ الفاتورة:\n{e}")
            return
        # ★ إضافة (إصدار 5 — نظام الأنواع الثلاثة): تفاصيل التدقيق تذكر الأنواع
        # (مثل: حفظ فاتورة — 3 صنف — المجموع 1,500.00 — الأنواع: نقداً 2، شبكة 1)
        tset = {}
        for it in snapshot:
            tset[it["type"]] = tset.get(it["type"], 0) + 1
        # ★ إضافة (الإصدار 16 — القسم 1-1): توثيق عدد المرتجعات المربوطة بالأصل
        _nlinked16 = sum(1 for it in snapshot
                         if it["type"] == "مرتجع" and it.get("orig_id"))
        audit("حفظ فاتورة", f"{len(snapshot)} صنف — المجموع {money(total)} — الأنواع: "
              + "، ".join(f"{k} {v}" for k, v in tset.items())
              + (f" | عميل: {cust}" if cust else "")
              + (f" | مرتجعات مربوطة بالأصل: {_nlinked16}" if _nlinked16 else "")
              # ★ إضافة (المرحلة الرابعة): رقم الفاتورة والخصم والدين
              + (f" | فاتورة رقم {_inv4}" if _inv4 else "")
              + (f" | خصم {_disc4:g}%" if _disc4 > 0 else "")
              + (" | بيع بالدين" if _credit4 else ""))   # ★ إضافة (ميزة 2)
        # ★★★ إضافة (المرحلة الرابعة — البيع بالدين): بعد نجاح حفظ الفاتورة —
        # تسجيل الدين بالباقي على العميل المختار + سطر تدقيق مستقل
        # credit_sale_recorded بنفس أسلوب الكاتب الحالي
        if _credit4:
            try:
                _down4 = float(_credit4.get("down") or 0)
                _remain4 = total - _down4
                if _remain4 > 1e-9:
                    _ensure_stage4_tables()
                    # ★★★ إضافة (موعد التحصيل): الترحيل الآمن أولًا — إن نجح
                    # أُدرج موعد التحصيل مع الدين في العمود الجديد، وإن فشل
                    # الترحيل يُدرج الدين بالعبارة القديمة نفسها حرفيًا بلا
                    # الموعد (البرنامج يعمل بدون الميزة ولا يتوقف شيء)
                    try:
                        _ensure_collection_date_column()
                    except Exception as e:
                        log_error(e, sys.exc_info()[2])
                    _cdate_ins4 = (str(_credit4.get("collection_date"))
                                   if (_COLL_READY["done"]
                                       and _credit4.get("collection_date"))
                                   else None)
                    with connect() as conn:
                        if _COLL_READY["done"]:
                            conn.execute(
                                "INSERT INTO debts(customer_id, invoice_number, "
                                "sale_id, total_amount, paid_amount, status, "
                                "created_at, collection_date) VALUES(?,?,?,?,?,?,?,?)",
                                (_credit4["customer_id"], _inv4,
                                 (_ids4[0] if _ids4 else None), _remain4, 0.0,
                                 "مفتوح",
                                 datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                                 _cdate_ins4))
                        else:
                            # عبارة الإدراج القديمة نفسها حرفيًا (بلا الموعد)
                            conn.execute(
                                "INSERT INTO debts(customer_id, invoice_number, sale_id, "
                                "total_amount, paid_amount, status, created_at) "
                                "VALUES(?,?,?,?,?,?,?)",
                                (_credit4["customer_id"], _inv4,
                                 (_ids4[0] if _ids4 else None), _remain4, 0.0, "مفتوح",
                                 datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
                audit("credit_sale_recorded",
                      f"فاتورة رقم {_inv4 or '—'} | العميل: {_credit4['customer_name']} | "
                      f"الإجمالي: {money(total)} | الدفعة الأولى: {money(_down4)} | "
                      f"الدين المسجل: {money(max(_remain4, 0.0))}"
                      # ★ إضافة (موعد التحصيل): الموعد إن وُجد في سطر التدقيق
                      + (f" | موعد التحصيل: {_credit4['collection_date']}"
                         if _credit4.get("collection_date") else ""))
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                messagebox.showwarning("بيع بالدين",
                    "حُفظت الفاتورة لكن تعذر تسجيل الدين — سُجّل الخطأ في "
                    "error_log.txt (راجع تبويب الديون والتحصيل)")
        # ★★★ إضافة (المرحلة الرابعة): تدقيق موافقة العملية الكبيرة
        if _approver4:
            try:
                audit("large_op_approved",
                      f"الموافق: {_approver4} | فاتورة رقم {_inv4 or '—'} | "
                      f"المبلغ: {money(abs(total))} | فاتورة {len(snapshot)} صنف")
            except Exception:
                pass
        # ★★★ إضافة (عروض الأسعار): بعد نجاح حفظ الفاتورة فعليًا — تعليم
        # العرض المحوَّل «محول لفاتورة» برقم الفاتورة نفسه وتصفير سياق
        # التحويل المعلق (ولا يُلمس العرض مطلقًا إن فشل الحفظ أو أُلغي:
        # يبقى مفتوحًا كما كان وسياقه باقٍ للمحاولة التالية) — الطبقة
        # الثانية داخل quotation_mark_converted نفسها ثم التحديث مشروط
        # بالحالة داخل عبارة SQL
        if _quote9:
            try:
                self._pending_quote = None
                _qok9, _qmsg9 = quotation_mark_converted(_quote9["id"], _inv4)
                if _qok9:
                    try:
                        audit("quotation_converted",
                              f"عرض رقم {_quote9['quote_no']} ← فاتورة رقم "
                              f"{_inv4 or '—'} | المبلغ: {money(total)}")
                    except Exception:
                        pass
                    for _qcb9 in list(getattr(self, "_quot_refresh_cbs", [])):
                        try:
                            _qcb9()
                        except Exception:
                            pass
            except Exception as e:
                log_error(e, sys.exc_info()[2])
        self.cart = []                          # السلة تُفرغ بعد الحفظ
        self.e_inv_customer.delete(0, "end")
        # ★ إضافة (إصدار 5): عودة الاختيار تلقائياً إلى «نقداً» بعد حفظ الفاتورة
        self.inv_type_var.set("نقداً")
        # ★★★ إضافة (المرحلة الرابعة): تصفير خصم الفاتورة وسبب المرتجع وملاحظته
        if hasattr(self, "e_inv_disc"):
            self.e_inv_disc.delete(0, "end"); self.e_inv_disc.insert(0, "0")
        if hasattr(self, "cb_inv_ret_reason"):
            self.cb_inv_ret_reason.set("")
        if hasattr(self, "e_inv_ret_note"):
            self.e_inv_ret_note.delete(0, "end")
        self.update_cart_view()
        self.refresh_items(); self.refresh_today(); self.refresh_stats()
        # ★ تعديل مصرح به (المرحلة الرابعة): رسالة الحالة تذكر رقم الفاتورة
        self.lbl_inv_status.config(text=f"✔ تم حفظ الفاتورة ({len(snapshot)} صنف)"
                               + (f" — فاتورة رقم {_inv4}" if _inv4 else "")
                               + (" — بالدين" if _credit4 else ""), fg=GREEN)
        # ★ تعديل مصرح به (المرحلة الرابعة): التصدير بقيم الصفوف بعد الخصم
        _export4 = [dict(it, total=_rt4) for it, _rt4 in _rows4]
        if messagebox.askyesno("تم", "تم حفظ الفاتورة كاملة ✅\nهل تريد تصديرها إلى Excel الآن؟"):
            self.export_invoice_xlsx(_export4, cust)

    def export_invoice_xlsx(self, items, cust=""):
        """★ إضافة (ميزة 3+6): تصدير الفاتورة الحالية إلى Excel حقيقي"""
        path = filedialog.asksaveasfilename(title="حفظ الفاتورة", defaultextension=".xlsx",
                                            initialfile=f"فاتورة_{today_str()}.xlsx",
                                            filetypes=[("ملف Excel", "*.xlsx")])
        if not path:
            return
        d = today_str()
        # ★ تعديل ضروري معلن (إصدار 3 — ميزة 3): عمود البائع في تصدير الفاتورة
        headers = ["التاريخ", "العميل", "الصنف", "الكمية", "السعر", "المبيع", "النوع", "البائع"]
        widths  = [12, 20, 26, 10, 10, 12, 10, 16]
        rows = [[d, cust or "", it["item"], it["qty"], it["price"], it["total"], it["type"],
                 CURRENT_USER["name"]] for it in items]
        export_xlsx(path, headers, rows, widths,
                    desc=f"فاتورة {len(items)} صنف — المجموع {money(sum(it['total'] for it in items))}")

    # ---------- (ميزة 2) شاشة سجل التدقيق ----------
    def show_audit(self):
        """★ إضافة (ميزة 2): فتح سجل التدقيق — للمدير فقط"""
        # ★ تعديل مصرح به (إصدار 8 — الميزة 5): صلاحية «عرض سجل التدقيق» بدل «المدير فقط»
        if not self.require_admin("view_audit"):
            return
        self.show_page("audit")
        self.refresh_audit()

    def build_audit_page(self, p):
        self.page_head(p, "📜 سجل التدقيق", "تسجيل تلقائي لكل الإجراءات — للمدير فقط")
        bar = tk.Frame(p, bg=BG); bar.pack(fill="x", padx=25)
        self.mk_btn(bar, "🔄 تحديث", self.refresh_audit, "#475569").pack(side="left", pady=6)

        # ★ إضافة (إصدار 8 — الميزة 1): السجل التفاعلي — قائمة «الإجراء» المنسدلة
        # تختصر الفلترة الشائعة بدون بحث، وزر «عرض الكل» يلغي الفلتر ويعيد
        # الجدول كاملاً (الفلترة عرضية في الذاكرة فقط ولا تمس قاعدة البيانات)
        self.audit_filter = None      # None أو ("user", اسم) أو ("action", إجراء)
        self.audit_all_rows = []      # كل السجلات في الذاكرة (يُفلتر العرض منها فقط)
        b_audit_all = self.mk_btn(bar, "👁 عرض الكل", self.clear_audit_filter, "#0d9488")
        b_audit_all.pack(side="left", padx=6, pady=6)
        add_tip(b_audit_all, "إعادة الجدول كاملاً وإلغاء الفلتر النشط")
        # ★ إضافة (الإصدار 16 — القسم 1-3): زر فحص سلامة سلسلة سجل التدقيق —
        # مدير/أدمن فقط (يُخفى عن البائع عند تبديل المستخدم من apply_role_ui)
        self.btn_audit_integrity = self.mk_btn(bar, "🧪 فحص سلامة السجل",
                                               self.audit_integrity_check, "#7c3aed")
        add_tip(self.btn_audit_integrity,
                "إعادة حساب سلسلة التوثيق المتسلسلة لكل السجلات — أي حذف أو تعديل يدوي "
                "خارج البرنامج يكسر السلسلة ويُعرض بالأحمر فوراً")
        if manager_level(self.role):
            self.btn_audit_integrity.pack(side="left", padx=6, pady=6)
        fr_act = tk.Frame(bar, bg=BG); fr_act.pack(side="right", padx=6)
        tk.Label(fr_act, text="الإجراء:", bg=BG, fg=DARK, font=FB).pack(side="right", padx=4)
        self.cb_audit_action = ttk.Combobox(fr_act, font=F, width=22, state="readonly",
                                            values=["كل الإجراءات"])
        self.cb_audit_action.current(0)
        self.cb_audit_action.pack(side="right", ipady=3)
        self.cb_audit_action.bind("<<ComboboxSelected>>",
                                  lambda e: self.apply_audit_action_filter())
        add_tip(self.cb_audit_action, "فلترة سريعة حسب نوع الإجراء — والنقر على أي صف يفلتر أيضاً")

        # ★ سطر الفلتر النشط الملون فوق الجدول: «🔍 سجلات: [الاسم/الإجراء] (عدد)»
        self.lbl_audit_filter = tk.Label(p, text="", bg=BG, fg=GRAY, font=FB, anchor="e")
        self.lbl_audit_filter.pack(fill="x", padx=25)
        # ★ إضافة (الإصدار 16 — القسم 1-3): سطر نتيجة فحص سلامة السلسلة —
        # أخضر عند السلامة وأحمر عند اكتشاف عبث، تحت سطر الفلتر فوق الجدول
        self.lbl_audit_integrity = tk.Label(p, text="", bg=BG, fg=GREEN, font=FB,
                                            anchor="e", wraplength=860)
        self.lbl_audit_integrity.pack(fill="x", padx=25)

        frm, self.tv_audit = self.mk_tree(p,
            ["التفاصيل", "الإجراء", "المستخدم", "التاريخ والوقت"],
            [380, 150, 100, 160])
        frm.pack(fill="both", expand=True, padx=25, pady=8)
        # ★ النقر على صف: عمود «المستخدم» (أو أي مكان بالصف) يعرض سجلات هذا
        # المستخدم فقط، والنقر على عمود «الإجراء» يعرض هذا الإجراء فقط
        # (كل من حفظ فاتورة مثلاً) — فلترة عرضية في الذاكرة فقط
        self.tv_audit.bind("<ButtonRelease-1>", self.on_audit_click)
        add_tip(self.tv_audit, "انقر أي صف للفلترة حسب المستخدم — وانقر عمود «الإجراء» للفلترة حسب الإجراء")
        # ★ إضافة (الإصدار 14 — البندان 5+6): فرز الرؤوس + الصفوف المتناوبة
        enable_tree_sorting(self.tv_audit)
        config_tree_stripes(self.tv_audit)
        self.refresh_audit()

    def refresh_audit(self):
        """★ إضافة (ميزة 2): عرض أحدث الإجراءات أولاً"""
        # ★ تعديل مصرح به (إصدار 8 — الميزة 5): فحص الصلاحية الدقيقة بدل «المدير فقط»
        if not self.has_permission("view_audit"):
            return
        self.tv_audit.delete(*self.tv_audit.get_children())
        with connect() as conn:
            rows = conn.execute("SELECT * FROM audit_log ORDER BY id DESC").fetchall()
        # ★ إضافة (إصدار 8 — الميزة 1): السجلات كلها تُحفظ في الذاكرة أولاً —
        # الفلترة التفاعلية عرضية فقط (في الذاكرة) ولا تمس قاعدة البيانات،
        # وقائمة «الإجراء» المنسدلة تتحدث بأنواع الإجراءات المتاحة
        self.audit_all_rows = rows
        self.update_audit_action_values(rows)
        for i, r in enumerate(rows):
            self.tv_audit.insert("", "end", tags=stripe_tags(i),
                values=(r["details"], r["action"], r["username"], r["ts"]))
        # ★ إضافة (إصدار 8 — الميزة 1): العرض يمر بالفلتر النشط (إن وُجد)
        self.render_audit()

    # ★ إضافة (إصدار 8 — الميزة 1): دوال السجل التفاعلي — فلترة عرضية بالنقر
    def update_audit_action_values(self, rows):
        """تحديث قائمة «الإجراء» المنسدلة من السجلات المعروضة (بدون تكرار)"""
        acts = sorted({r["action"] for r in rows})
        self.cb_audit_action["values"] = ["كل الإجراءات"] + acts
        if self.cb_audit_action.get() not in self.cb_audit_action["values"]:
            self.cb_audit_action.set("كل الإجراءات")

    def render_audit(self):
        """عرض السجلات مع الفلتر النشط — سطر ملون فوق الجدول يوضح الفلتر
        وعدد السجلات المعروضة (الفلترة في الذاكرة فقط ولا تمس القاعدة)"""
        f = self.audit_filter
        rows = self.audit_all_rows
        if f is not None:
            key, val = f
            if key == "multi":
                # ★ إضافة (الإصدار 16 — القسم 1-2): فلتر أنواع النشاط الحساس —
                # يفتحه زر «عرض التفاصيل» من بطاقة تنبيه الإدارة
                rows = [r for r in rows if r["action"] in val]
                self.lbl_audit_filter.config(
                    text=f"⚠ سجلات النشاط الحساس   ({len(rows)} سجلاً) — اضغط «👁 عرض الكل» لإلغاء الفلتر",
                    bg="#fee2e2", fg="#991b1b")
            else:
                rows = [r for r in rows if (r["username"] == val if key == "user"
                                            else r["action"] == val)]
                kind = "المستخدم" if key == "user" else "الإجراء"
                self.lbl_audit_filter.config(
                    text=f"🔍 سجلات: {kind} = {val}   ({len(rows)} سجلاً) — اضغط «👁 عرض الكل» لإلغاء الفلتر",
                    bg="#dbeafe", fg="#1e3a8a")
        else:
            self.lbl_audit_filter.config(
                text=f"🔍 السجلات: الكل   ({len(rows)} سجلاً)", bg=BG, fg=GRAY)
        self.tv_audit.delete(*self.tv_audit.get_children())
        for i, r in enumerate(rows):
            self.tv_audit.insert("", "end", tags=stripe_tags(i),
                                  values=(r["details"], r["action"],
                                          r["username"], r["ts"]))

    def on_audit_click(self, event):
        """النقر على صف: فلترة حسب المستخدم — والنقر على عمود «الإجراء»:
        فلترة بهذا الإجراء فقط (كل من حفظ فاتورة مثلاً)"""
        row_id = self.tv_audit.identify_row(event.y)
        if not row_id:
            return
        col = self.tv_audit.identify_column(event.x)   # #1 التفاصيل، #2 الإجراء، #3 المستخدم
        vals = self.tv_audit.item(row_id, "values")
        if col == "#2":                    # عمود «الإجراء»
            self.audit_filter = ("action", vals[1])
        else:                              # أي مكان آخر بالصف → فلترة بالمستخدم
            self.audit_filter = ("user", vals[2])
        self.render_audit()

    def apply_audit_action_filter(self):
        """تطبيق الفلتر السريع من قائمة «الإجراء» المنسدلة"""
        val = self.cb_audit_action.get()
        self.audit_filter = None if val in ("كل الإجراءات", "") else ("action", val)
        self.render_audit()

    def clear_audit_filter(self):
        """«عرض الكل»: إعادة الجدول كاملاً وإلغاء الفلتر"""
        self.audit_filter = None
        self.cb_audit_action.set("كل الإجراءات")
        self.render_audit()

    # ★★★ إضافة (الإصدار 16 — القسم 1-3): فحص سلامة سلسلة سجل التدقيق 🧪 ★★★
    def audit_integrity_check(self):
        """زر «🧪 فحص سلامة السجل» — مدير/أدمن فقط: يعيد حساب بصمات السلسلة
        كاملة ويقارنها بالمخزنة؛ السلسلة السليمة «✅ سجل التدقيق سليم وغير
        معدل» بالأخضر، وأي حذف أو تعديل يدوي خارج البرنامج يكسر السلسلة
        فيُعرض «⚠ عبث بالسجل عند: [السجل]!» بالأحمر مع تحديد السجلات
        المكسورة داخل الجدول نفسه — وكل فحص يُسجل في سجل التدقيق"""
        if not manager_level(self.role):
            messagebox.showwarning("صلاحية", "فحص سلامة السجل للمدير/الأدمن فقط")
            return
        ok, msg, broken = audit_chain_verify()
        try:
            self.lbl_audit_integrity.config(text=msg, fg=(GREEN if ok else RED))
        except Exception:
            pass
        # تحديد السجلات المكسورة بالأحمر داخل الجدول إن كانت ظاهرة الآن
        try:
            self.tv_audit.tag_configure("tampered", background="#fecaca",
                                        foreground="#991b1b")
            bset = {(b["action"], b["ts"], b["username"], b["details"]) for b in broken}
            for iid in self.tv_audit.get_children(""):
                v = self.tv_audit.item(iid, "values")
                if (v[1], v[3], v[2], v[0]) in bset:
                    tags = list(self.tv_audit.item(iid, "tags") or [])
                    if "tampered" not in tags:
                        tags.append("tampered")
                    self.tv_audit.item(iid, tags=tags)
        except Exception:
            pass
        audit("فحص سلامة سجل التدقيق", ("السلسلة سليمة" if ok else "عبث مكتشف: " + msg))

    # ---------- (ميزة 1) تغيير كلمة المرور ----------
    def change_password_dialog(self):
        """★ تعديل ضروري معلن (إصدار 3 — ميزة 7): تغيير كلمة المرور لأي مستخدم —
        يغيّر كلمة مروره هو في جدول users
        (وإعادة تعيين كلمات البائعين تكون من شاشة إدارة المستخدمين)"""
        # ★ إضافة (إصدار 8 — الميزة 3): تسجيل النافذة في التتبع المركزي
        win = self.register_window(tk.Toplevel(self))
        win.title("تغيير كلمة المرور")
        win.configure(bg=BG); win.resizable(False, False)
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        card.pack(fill="both", expand=True, padx=20, pady=16)
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول — القاعدة الذهبية): زر
        # الحفظ يُحزم side="bottom" أولاً داخل البطاقة فلا يُقص أبداً مهما
        # طال المحتوى — وبقية الحقول فوقه، والارتفاع من المحتوى ذاتياً
        fr_save = tk.Frame(card, bg=CARD)
        fr_save.pack(side="bottom", fill="x", pady=(8, 12))
        tk.Label(card, text="🔑 تغيير كلمة المرور", bg=CARD, fg=DARK, font=FT).pack(pady=(14, 4))
        # ★ إضافة (إصدار 3 — ميزة 7): إظهار الحساب الحالي الذي ستُغيّر كلمة مروره
        tk.Label(card, text=f"الحساب الحالي: {self.user_name}", bg=CARD, fg=GRAY,
                 font=("Segoe UI", 10)).pack(pady=(0, 8))

        def row(label):
            fr = tk.Frame(card, bg=CARD); fr.pack(fill="x", padx=18, pady=5)
            tk.Label(fr, text=label, bg=CARD, fg=DARK, font=FB, width=18, anchor="e").pack(side="right")
            e = tk.Entry(fr, font=F, justify="center", show="•", relief="solid", bd=1, width=22)
            e.pack(side="right", padx=(0, 8), ipady=4)
            return e

        e_cur = row("كلمة المرور الحالية:")
        e_new = row("كلمة المرور الجديدة:")
        # ★ إضافة (إصدار 9 — الميزة 4): شريط قوة كلمة المرور الجديدة تحت حقلها
        # مباشرة — يتحدث مع كل ضغطة مفتاح (أحمر/برتقالي/أخضر + النص الإرشادي)
        strength_update = make_strength_bar(card, self.role)   # ★ (الميزة 4) الشريط حسب دور الحساب
        e_new.bind("<KeyRelease>", lambda _e: strength_update(e_new.get()))
        e_con = row("تأكيد الجديدة:")
        # ★ إضافة (إصدار 9 — الميزة 1): زر عين 👁 داخل كل حقل كلمة مرور (على
        # يساره) — 👁 عند الإخفاء و🙈 عند الإظهار، ويعود للإخفاء تلقائياً بعد 5 ثوانٍ
        for _e in (e_cur, e_new, e_con):
            add_eye_to_entry(_e)

        def do_change():
            cur, new, con = e_cur.get(), e_new.get(), e_con.get()
            urow = get_user_row(self.user_name)
            if urow is None or not verify_user_password(urow, cur):
                messagebox.showerror("خطأ", "كلمة المرور الحالية غير صحيحة", parent=win); return
            # ★ تعديل مصرح به (الإصدار 14 — البند 11): منع الحفظ إذا كانت دون حد
            # دور هذا الحساب (مدير/أدمن: 6 أحرف وفيها رقم / بائع: 4 أحرف)
            if pw_is_weak(new, self.role):
                messagebox.showwarning("تنبيه", pw_role_message(self.role), parent=win); return
            if new != con:
                messagebox.showwarning("تنبيه", "التأكيد لا يطابق كلمة المرور الجديدة", parent=win); return
            salt = secrets.token_hex(16)
            with connect() as conn:
                conn.execute("UPDATE users SET password_hash=? WHERE username=?",
                             (salt + "$" + hash_pwd(salt, new), self.user_name))
            audit("تغيير كلمة المرور", self.user_name)   # ★ إضافة (ميزة 2)
            messagebox.showinfo("تم", "تم تغيير كلمة المرور بنجاح", parent=win)
            win.destroy()

        self.mk_btn(fr_save, "💾 حفظ", do_change, ACCENT).pack()
        # ★ إضافة (الإصدار 15 — الجزء الأول): تمركز وسط الشاشة + ارتفاع من
        # المحتوى (فحص ذاتي) + احترام الشاشات الصغيرة — لا قصّ للأزرار أبداً
        place_window(win, 420)

    # ---------- (ميزة 4) التصفية بالمدى ----------
    def filter_archive(self):
        """★ إضافة (ميزة 4): عرض التقارير ضمن المدى + الإجمالي التراكمي"""
        f, t = parse_date_multi(self.e_from.get()), parse_date_multi(self.e_to.get())
        bad = [lbl for lbl, v in (("من تاريخ", f), ("إلى تاريخ", t)) if v is None]
        if bad:
            messagebox.showwarning("تاريخ خاطئ",
                "صيغة غير صحيحة لـ " + " و ".join(bad) +
                "\nالصيغ المقبولة: 2025-01-10 أو 10-01-2025 أو 10/01/2025")
            return
        sql, params, cond = "SELECT * FROM daily_reports", [], []
        if f:
            cond.append("report_date >= ?"); params.append(f)
        if t:
            cond.append("report_date <= ?"); params.append(t)
        if cond:
            sql += " WHERE " + " AND ".join(cond)
        sql += " ORDER BY report_date DESC"
        with connect() as conn:
            rows = conn.execute(sql, params).fetchall()
        self.tv_arch.delete(*self.tv_arch.get_children())
        for i, r in enumerate(rows):
            # ★ تعديل (إصدار 5): القيم تشمل نقداً وشبكة منفصلين
            # ★ إضافة (الإصدار 14 — البند 6): شارة الصف المتناوب
            self.tv_arch.insert("", "end", iid=r["report_date"], tags=stripe_tags(i),
                values=(r["closed_at"], money(r["net_total"]), money(r["total_returns"]),
                        money(r["total_network"] or 0), money(r["total_cash"] or 0),
                        r["ops_count"], r["report_date"]))
        self.update_arch_summary(rows)

    def show_all_archive(self):
        """★ إضافة (ميزة 4): مسح التصفية والعودة لعرض كل التقارير"""
        self.e_from.delete(0, "end")
        self.e_to.delete(0, "end")
        self.refresh_archive()

    def update_arch_summary(self, rows):
        """★ إضافة (ميزة 4): صف الإجمالي التراكمي لكل الأيام المعروضة حالياً
        ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): يعرض نقداً وشبكة منفصلين
        ★ تعديل مصرح به (الإصدار 14 — البند 8): صيغة العداد الدائم أُضيفت
        لأول السطر — «اعرض [عدد] صفوف — المجموع الكلي: [الإجمالي]» مع كل تعبئة"""
        n   = len(rows)
        ca  = sum((r["total_cash"] or 0) for r in rows)
        nw  = sum((r["total_network"] or 0) for r in rows)
        rt  = sum((r["total_returns"] or 0) for r in rows)
        net = sum((r["net_total"] or 0) for r in rows)
        self.lbl_arch_summary.config(
            text=(f"اعرض {n} صفوف — المجموع الكلي: {money(net)} — نقداً: {money(ca)} — شبكة: {money(nw)} — "
                  f"المرتجعات: {money(rt)}" if n else ""),
            fg=(GREEN if net >= 0 else RED))

    # ---------- (ميزة 3) تصدير Excel ----------
    def export_archive_xlsx(self):
        """★ إضافة (ميزة 3): تصدير كل تقارير الأرشيف إلى Excel حقيقي"""
        # ★ إضافة (إصدار 8 — الميزة 5): صلاحية «تصدير التقارير (CSV/Excel/PDF)»
        if not self.has_permission("export_reports"):
            messagebox.showwarning("صلاحية", "ليست لديك صلاحية «تصدير التقارير»")
            return
        with connect() as conn:
            rows = conn.execute("SELECT * FROM daily_reports ORDER BY report_date DESC").fetchall()
        if not rows:
            messagebox.showinfo("تنبيه", "لا توجد تقارير محفوظة بعد"); return
        path = filedialog.asksaveasfilename(title="حفظ تقرير الأرشيف", defaultextension=".xlsx",
                                            initialfile=f"الأرشيف_كاملاً_{today_str()}.xlsx",
                                            filetypes=[("ملف Excel", "*.xlsx")])
        if not path:
            return
        # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): أعمدة نقداً وشبكة منفصلين
        headers = ["التاريخ", "عدد العمليات", "نقداً", "شبكة", "المرتجعات", "الإجمالي", "وقت الإغلاق"]
        widths  = [12, 12, 14, 14, 14, 14, 18]
        xrows = [[r["report_date"], r["ops_count"], r["total_cash"] or 0.0,
                  r["total_network"] or 0.0, r["total_returns"], r["net_total"],
                  r["closed_at"]] for r in rows]
        export_xlsx(path, headers, xrows, widths, desc=f"الأرشيف كاملاً — {len(rows)} تقريراً")
        messagebox.showinfo("تم", "تم تصدير الأرشيف إلى Excel ✅")

    def export_day_xlsx(self, d, rows, rep=None):
        """★ إضافة (ميزة 3): تصدير تفاصيل يوم واحد إلى Excel حقيقي مع الملخص"""
        # ★ إضافة (إصدار 8 — الميزة 5): صلاحية «تصدير التقارير (CSV/Excel/PDF)»
        if not self.has_permission("export_reports"):
            messagebox.showwarning("صلاحية", "ليست لديك صلاحية «تصدير التقارير»")
            return
        path = filedialog.asksaveasfilename(title="حفظ التقرير", defaultextension=".xlsx",
                                            initialfile=f"تقرير_{d}.xlsx",
                                            filetypes=[("ملف Excel", "*.xlsx")])
        if not path:
            return
        # ★ تعديل ضروري معلن (إصدار 3 — ميزة 3): رأس الجدول وصفوفه أصبحا يشملان عمود البائع
        headers = ["التاريخ", "اسم الصنف", "العميل", "البائع", "الكمية", "السعر", "المبيع", "النوع"]
        widths  = [12, 26, 20, 16, 10, 10, 12, 10]
        xrows = [[r["date"], r["item_name"], (r["customer_name"] or ""), (r["seller_name"] or "—"),
                  r["quantity"], r["price"], r["total"], r["type"]] for r in rows]
        extra = None
        if rep:
            # ★ تعديل (إصدار 5 — نظام الأنواع الثلاثة): ملخص Excel يعرض
            # نقداً وشبكة منفصلين مع إجمالي المبيعات المجمع
            extra = [("عدد العمليات", rep["ops_count"]), ("نقداً", rep["total_cash"] or 0.0),
                     ("شبكة", rep["total_network"] or 0.0),
                     ("المبيعات (نقداً + شبكة)", rep["total_sales"]),
                     ("المرتجعات", rep["total_returns"]), ("الإجمالي", rep["net_total"])]
        export_xlsx(path, headers, xrows, widths, desc=f"تقرير يوم {d} — {len(rows)} عملية", extra=extra)
        messagebox.showinfo("تم", "تم تصدير التقرير إلى Excel ✅")

    # ═════════════════════════════════════════════════════════
    # ★★★ إضافات الإصدار 3 — إدارة المستخدمين وتقرير أداء البائعين ★★★
