    # ---------- (ميزة 1) تبديل المستخدم دون إغلاق البرنامج ----------
    def login_dialog(self):
        """★ إضافة (إصدار 4 — ميزة 1): شاشة تسجيل الدخول الحالية بتصميمها وسلوكها
        نفسه تماماً (نفس الرسائل الثلاث ونفس سجل التدقيق ونمط الحقول والأزرار)
        — تُعرض كنافذة Toplevel فوق النافذة الرئيسية المخفية عند تبديل المستخدم.
        سبب عدم استدعاء login_flow نفسها: هي تنشئ نافذة Tk ثانية وتشغّل mainloop
        خاصاً بها، وحلقة الأحداث المتداخلة لنافذة Tk ثانية لا تعود أبداً بعد
        تدميرها ما دامت النافذة الرئيسية حية (تُعلّق البرنامج كلياً)، بينما
        wait_window لنافذة Toplevel هي الطريقة القياسية الآمنة للحواريات.
        ★ تعديل مصرح به (إصدار 9): نفس إعادة بناء نافذة الدخول المصرح بها في
        login_flow — البناء كله انتقل لـ _screen_login_build المشتركة بنفس
        المنطق حرفياً وبنفس الميزات الثماني (التعديل المصرح به الوحيد)"""
        result = {"name": None, "role": None}
        win = tk.Toplevel(self)
        _screen_login_build(win, result)
        # ★ تعديل مصرح به (الإصدار 17 — الإضافة 3): بروتوكول الإغلاق (Alt+F4)
        # يديره _screen_login_build نفسها — تحذير «أكمل تسجيل الدخول» بدل
        # الإغلاق، والخروج الوحيد زر ✕ (كإلغاء الدخول القائم) أو دخول ناجح
        win.wait_window(win)          # حلقة أحداث محلية آمنة — تعود فور إغلاق النافذة
        return result if result["role"] else None

    def session_lock(self):
        """★ إضافة (الإصدار 14 — البند 10): قفل الجلسة — يخفي البرنامج كاملاً
        (النافذة الرئيسية وكل النوافذ المفتوحة) خلف نافذة كلمة مرور الحساب
        الحالي (الاسم معروض ثابتاً ولا يُكتب شيء غير كلمة المرور)، والعودة
        بكلمة المرور الصحيحة تُعيد كل شيء كما كان بالضبط (الصفحة والسلة
        والنوافذ) دون إغلاق أي شيء — إغلاق نافذة القفل يطلب تأكيد الخروج"""
        audit("قفل جلسة", f"قفل جهاز — الجلسة باسم {self.user_name}")
        # إخفاء كل النوافذ المفتوحة أولاً ثم الرئيسية — تُعاد كلها كما كانت
        hidden = []
        for w in list(getattr(self, "open_windows", [])):
            try:
                if w.winfo_exists():
                    w.withdraw()
                    hidden.append(w)
            except Exception:
                pass
        self.withdraw()

        lock = tk.Toplevel(self)
        lock.title("🔒 جلسة مقفلة")
        lock.geometry("400x310")
        lock.configure(bg=CARD)
        lock.resizable(False, False)
        try:      # تُعرض في مكان النافذة الرئيسية نفسه
            lock.geometry(f"+{self.winfo_x()}+{self.winfo_y()}")
        except Exception:
            pass
        lock.protocol("WM_DELETE_WINDOW", lambda: on_close())

        tk.Label(lock, text="🔒", bg=CARD, fg=DARK, font=("Segoe UI", 30)).pack(pady=(18, 2))
        tk.Label(lock, text="الجلسة مقفلة", bg=CARD, fg=DARK, font=FT).pack()
        tk.Label(lock, text=f"الحساب: {self.user_name} ({self.role})", bg=CARD, fg=GRAY,
                 font=("Segoe UI", 10)).pack(pady=(0, 10))
        fr = tk.Frame(lock, bg=CARD)
        fr.pack(fill="x", padx=30)
        tk.Label(fr, text="كلمة المرور:", bg=CARD, fg=DARK, font=FB, width=14,
                 anchor="e").pack(side="right")
        e_pwd = tk.Entry(fr, font=F, justify="center", show="•", relief="solid", bd=1, width=18)
        e_pwd.pack(side="right", padx=(0, 8), ipady=4)
        add_eye_to_entry(e_pwd)               # زر العين داخل الحقل ككل حقول كلمات المرور
        err = tk.Label(lock, text="", bg=CARD, fg=RED, font=("Segoe UI", 9, "bold"),
                       wraplength=330, justify="center")
        err.pack(fill="x", padx=30, pady=(4, 0))
        e_pwd.focus_set()

        def unlock():
            urow = get_user_row(self.user_name)
            if urow is None or not verify_user_password(urow, e_pwd.get()):
                err.config(text="كلمة المرور غير صحيحة — حاول من جديد")
                shake_widget(lock)
                flash_entry_red(e_pwd)
                e_pwd.delete(0, "end")
                e_pwd.focus_set()
                return
            audit("فتح جلسة", f"عودة {self.user_name} بعد القفل")
            lock.destroy()
            # إعادة كل شيء كما كان بالضبط — النوافذ المخفية ثم الرئيسية
            for w in hidden:
                try:
                    if w.winfo_exists():
                        w.deiconify()
                except Exception:
                    pass
            self.deiconify()

        def on_close():
            if messagebox.askyesno("خروج", "الخروج من البرنامج بالكامل؟", parent=lock):
                lock.destroy()
                self.exit_app()

        e_pwd.bind("<Return>", lambda _e: unlock())
        fr_btns = tk.Frame(lock, bg=CARD)
        fr_btns.pack(pady=(8, 16))
        b_open = self.mk_btn(fr_btns, "🔓 فتح الجلسة", unlock, GREEN)
        b_open.pack(side="right", padx=6)
        add_tip(b_open, "العودة إلى البرنامج بكلمة مرور الحساب الحالي — كل شيء يعود كما كان")
        b_exit = self.mk_btn(fr_btns, "⏻ خروج", on_close, RED)
        b_exit.pack(side="right", padx=6)
        add_tip(b_exit, "إغلاق البرنامج بالكامل (مع نسخة احتياطية تلقائية كما هو قائم)")

    # ═══════════════════════════════════════════════════════════
    # ★★★ إضافات (قفل الخمول): حماية الجلسة عند ترك الجهاز مفتوحًا ★★★
    # إذا بقي البرنامج دون أي تفاعل (ماوس أو كيبورد) للمدة المحددة في
    # الإعدادات (idle_lock_minutes — افتراضيًا 5 دقائق و0 = إيقاف القفل)
    # تُفتح شاشة قفل بملء الشاشة فوق كل النوافذ تعرض اسم المستخدم الحالي
    # وتطلب الرقم السري لعودة نفس الجلسة ونفس الشاشات كما كانت (بلا أي
    # rebuild)، مع زر «تبديل المستخدم» للدخول بحساب آخر من شاشة الدخول
    # القائمة نفسها — القفل للجميع بلا استثناء (حماية لا ميزة ممنوحة)
    # ═══════════════════════════════════════════════════════════

    def _idle_on_activity(self, _e=None):
        """★ إضافة (قفل الخمول): كل حدث نشاط (لوحة مفاتيح أو أزرار أو حركة
        مؤشر أو عجلة فأرة) يحدّث طابع آخر نشاط فقط — متغير بسيط بلا أي عمل
        ثقيل — والربط تم بـ add='+' عند الإنشاء فلا كُسرت أي ربطة قائمة"""
        self._idle_last_activity = time.monotonic()

    def _idle_lock_tick(self):
        """★ إضافة (قفل الخمول): فحص كل ثانية عبر after متجددة — جدولة واحدة
        تتكرر ولا تتراكم النداءات أبدًا؛ عند انقضاء المدة المحددة دون نشاط
        مع وجود مستخدم مسجَّل دخوله ولا شاشة قفل مفتوحة تُفتح شاشة القفل،
        وأي استثناء يُسجَّل في error_log.txt ولا ينهار البرنامج — فشل فتح
        الشاشة يعني محاولة جديدة في الدورة التالية تلقائيًا"""
        try:
            self.after(1000, self._idle_lock_tick)   # الجدولة المتجددة الوحيدة
        except Exception:
            return                                   # النافذة تُغلق — انتهى الفحص
        try:
            # (1) لا جلسة نشطة؟ — النافذة الرئيسية مخفية (withdrawn) تعني
            # شاشة الدخول أثناء تبديل المستخدم أو القفل اليدوي القائم: لا
            # قفل خمول قبل تسجيل الدخول أصلًا، وطابع النشاط يُصفَّر كي لا
            # يقفل مستخدم الجلسة الجديدة فور دخوله بطابع قديم
            try:
                if self.state() == "withdrawn":
                    self._idle_last_activity = time.monotonic()
                    return
            except Exception:
                return
            # (2) شاشة قفل الخمول مفتوحة؟ — لا شيء (الفتح الصحيح يصفّر الطابع)
            w = self._idle_lock_win
            if w is not None:
                try:
                    if w.winfo_exists():
                        return
                except Exception:
                    pass
                self._idle_lock_win = None
            # (3) المدة المحددة من جدول الإعدادات — بكاش يتجدد كل 30 ثانية
            # (والحفظ من شاشة الإعدادات يحدّثه فورًا) فلا تُفتح القاعدة كل
            # ثانية، والقيمة 0 = إيقاف القفل
            self._idle_cache_tick += 1
            if self._idle_lock_minutes_cache is None or self._idle_cache_tick >= 30:
                self._idle_lock_minutes_cache = get_idle_lock_minutes()
                self._idle_cache_tick = 0
            minutes = self._idle_lock_minutes_cache
            if minutes is None or minutes <= 0:
                return
            # (4) انقضت المدة دون أي نشاط؟ — فتح شاشة القفل
            if time.monotonic() - self._idle_last_activity >= minutes * 60:
                self._idle_open_lock()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            # أي فشل (بما فيه فتح الشاشة): البرنامج يعمل والمحاولة تتكرر
            # في الدورة التالية — لا انهيار أبدًا

    def _idle_open_lock(self):
        """★ إضافة (قفل الخمول): فتح شاشة القفل — نافذة Toplevel بملء الشاشة
        فوق كل النوافذ (-topmost) بخلفية داكنة: «الجلسة مقفلة» واسم المستخدم
        وصلاحيته ووقت القفل وحقل الرقم السري (مخفي الأحرف ويستقبل التركيز
        تلقائيًا) وزرا «فتح» و«تبديل المستخدم»، مع grab_set لمنع أي تفاعل مع
        البرنامج خلفها — وإغلاق البرنامج من زر ✕ (أو Alt+F4) يبقى ممكنًا؛
        أي فشل في البناء يُنظَّف ويُعاد المحاولة في الدورة التالية"""
        if self._idle_lock_win is not None:
            return
        lock_time = datetime.now()
        lock = tk.Toplevel(self)
        lock.bind("<Destroy>",
                  lambda _e: setattr(self, "_idle_lock_win", None), add="+")
        try:
            lock.title("🔒 جلسة مقفلة")
            lock.configure(bg=DARK)
            sw, sh = lock.winfo_screenwidth(), lock.winfo_screenheight()
            # ملء الشاشة بنفس أسلوب شاشة الدخول القائمة حرفيًا: بلا إطار
            # ويندوز ثم zoomed مع خطة بديلة بأبعاد الشاشة والفشل الهادئ
            # بحجم معقول — والشاشة دائمًا فوق كل النوافذ (-topmost)
            try:
                lock.overrideredirect(True)
            except Exception:
                pass
            fs_ok = False
            try:
                lock.state("zoomed")
                fs_ok = True
            except Exception:
                fs_ok = False
            if not fs_ok:
                try:
                    lock.geometry(f"{sw}x{sh}+0+0")
                    fs_ok = True
                except Exception:
                    fs_ok = False
            if not fs_ok:
                lock.geometry("520x430+200+120")
            try:
                lock.resizable(False, False)
            except Exception:
                pass
            try:
                lock.attributes("-topmost", True)
            except Exception:
                pass

            # ── الدوال قبل العناصر التي تستخدمها ──
            def _destroy_lock():
                """إغلاق شاشة قفل الخمول وتحرير القبضة — بأقصى جهد بلا أخطاء"""
                self._idle_lock_win = None
                try:
                    lock.grab_release()
                except Exception:
                    pass
                try:
                    lock.destroy()
                except Exception:
                    pass

            def _ensure_grab(tries=0):
                """grab_set لمنع أي تفاعل مع البرنامج خلف الشاشة — إن كانت
                قبضة أخرى نشطة (رسالة مفتوحة لحظة القفل) أو الشاشة لم تُعرض
                بعد تُعاد المحاولة كل نصف ثانية، وبعد دقيقتين يكتفي بالتغطية
                والتوبموس (الشاشة نفسها تبقى عاملة بالرقم السري)"""
                try:
                    if not lock.winfo_exists():
                        return
                except Exception:
                    return
                try:
                    lock.grab_set()
                    return
                except Exception:
                    pass
                if tries >= 240:
                    return
                try:
                    lock.after(500, lambda: _ensure_grab(tries + 1))
                except Exception:
                    pass

            def _unlock():
                """فتح القفل بالرقم السري — بنفس آلية التحقق القائمة نفسها
                (get_user_row + verify_user_password دون أي تعديل عليهما)؛
                الصحيح يغلق الشاشة ويعيد نفس الجلسة ونفس الشاشات المفتوحة
                كما كانت دون أي rebuild، والخاطئ رسالة عربية واضحة والقفل
                باقٍ والمحاولة مسجلة في error_log.txt"""
                pwd = e_pwd.get()
                if not pwd:
                    err.config(text="أدخل الرقم السري")
                    try:
                        e_pwd.focus_set()
                    except Exception:
                        pass
                    return
                urow = get_user_row(self.user_name)
                if urow is None or not verify_user_password(urow, pwd):
                    log_error("قفل الخمول — _unlock: محاولة فتح برقم سري "
                              f"خاطئ للمستخدم: {self.user_name}")
                    err.config(text="الرقم السري غير صحيح — حاول من جديد")
                    try:
                        shake_widget(card)
                        flash_entry_red(e_pwd)
                    except Exception:
                        pass
                    e_pwd.delete(0, "end")
                    try:
                        e_pwd.focus_set()
                    except Exception:
                        pass
                    return
                self._idle_last_activity = time.monotonic()   # عدّاد نشاط جديد
                audit("فتح بعد قفل الخمول", "عودة " + self.user_name +
                      " — كانت مقفلة منذ " + lock_time.strftime("%H:%M:%S"))
                _destroy_lock()

            def _switch_user():
                """تبديل المستخدم من شاشة القفل — إغلاق شاشة قفل الخمول ثم
                نفس خطوات التبديل القائمة حرفيًا: تحذير السلة وإغلاق كل
                النوافذ وخروج الجلسة في سجل التدقيق وشاشة الدخول القائمة،
                وبعد الدخول يعمل rebuild_ui_for_current_user كما هو"""
                _destroy_lock()
                self._idle_last_activity = time.monotonic()
                self.switch_user()

            def _on_close():
                """✕ / Alt+F4 — الخروج من البرنامج بالكامل يبقى ممكنًا من
                شاشة القفل (بتأكيد عربي كنمط شاشة القفل اليدوي القائمة)"""
                try:
                    lock.grab_release()
                except Exception:
                    pass
                if messagebox.askyesno("خروج", "الخروج من البرنامج بالكامل؟",
                                       parent=lock):
                    _destroy_lock()
                    self.exit_app()
                else:
                    _ensure_grab()

            def _refocus():
                """تركيز إضافي بعد لحظة — بعض الأنظمة تحتاج عرض الشاشة أولًا"""
                try:
                    if lock.winfo_exists():
                        e_pwd.focus_set()
                except Exception:
                    pass

            # ── العناصر: عربية RTL بخلفية داكنة وبطاقة وسطية كشاشة الدخول ──
            tk.Button(lock, text="✕", command=_on_close, bg=SIDEBAR, fg=BORDER,
                      activebackground=RED, activeforeground="white",
                      font=("Segoe UI", 9, "bold"), bd=0, relief="flat",
                      cursor="hand2", takefocus=0).place(x=8, y=8, width=30,
                                                        height=26)
            card = tk.Frame(lock, bg=SIDEBAR, highlightbackground=BORDER,
                            highlightthickness=1)
            card.place(in_=lock, relx=0.5, rely=0.5, anchor="c", width=430)
            tk.Label(card, text="🔒", bg=SIDEBAR, fg="#f1f5f9",
                     font=("Segoe UI", 42)).pack(pady=(24, 2))
            tk.Label(card, text="الجلسة مقفلة", bg=SIDEBAR, fg="#f1f5f9",
                     font=("Segoe UI", 24, "bold")).pack(pady=(0, 2))
            tk.Label(card, text=f"المستخدم: {self.user_name} ({self.role})",
                     bg=SIDEBAR, fg="#94a3b8",
                     font=("Segoe UI", 12, "bold")).pack(pady=(2, 0))
            tk.Label(card, text="وقت القفل: " + lock_time.strftime("%H:%M:%S")
                     + " — " + lock_time.strftime("%Y-%m-%d"), bg=SIDEBAR,
                     fg="#64748b", font=("Segoe UI", 10, "bold")).pack(pady=(2, 12))
            fr = tk.Frame(card, bg=SIDEBAR)
            fr.pack()
            tk.Label(fr, text="الرقم السري:", bg=SIDEBAR, fg="#e2e8f0", font=FB,
                     width=12, anchor="e").pack(side="right", padx=(0, 8))
            e_pwd = tk.Entry(fr, font=("Segoe UI", 13), justify="center",
                             show="•", relief="solid", bd=1, width=20)
            e_pwd.pack(side="right", ipady=6)
            add_eye_to_entry(e_pwd)     # زر العين ككل حقول كلمات المرور
            err = tk.Label(card, text="", bg=SIDEBAR, fg=RED,
                           font=("Segoe UI", 10, "bold"), wraplength=380,
                           justify="center")
            err.pack(pady=(8, 0))
            fr_btns = tk.Frame(card, bg=SIDEBAR)
            fr_btns.pack(pady=(10, 4))
            b_open = self.mk_btn(fr_btns, "🔓 فتح", _unlock, GREEN)
            b_open.pack(side="right", padx=6)
            add_tip(b_open, "الرقم السري الصحيح (أو Enter) يعيد نفس الجلسة "
                           "وكل الشاشات المفتوحة كما كانت تمامًا")
            b_sw = self.mk_btn(fr_btns, "👥 تبديل المستخدم", _switch_user, "#475569")
            b_sw.pack(side="right", padx=6)
            add_tip(b_sw, "إنهاء جلسة المستخدم الحالي والدخول بحساب آخر من "
                         "شاشة الدخول القائمة")
            tk.Label(card, text="⏱️ قفل تلقائي بعد خمول المدة المحددة من شاشة الإعدادات",
                     bg=SIDEBAR, fg="#64748b", font=("Segoe UI", 9)).pack(pady=(2, 18))
            e_pwd.bind("<Return>", lambda _e: _unlock())
            e_pwd.focus_set()          # التركيز تلقائيًا في حقل الرقم السري
            lock.protocol("WM_DELETE_WINDOW", _on_close)
            lock.after(150, _ensure_grab)
            lock.after(250, _refocus)
            # نجح البناء كاملًا: تسجيل الشاشة ثم حدث القفل في سجل التدقيق
            self._idle_lock_win = lock
            audit("قفل خمول", "قفل تلقائي لعدم النشاط — الجلسة باسم "
                  f"{self.user_name} ({self.role})")
        except Exception as e:
            # فشل بناء شاشة القفل: تنظيف أي نافذة نصف مبنية والبرنامج يعمل
            # وتُعاد المحاولة في الدورة التالية (شرط الخمول ما زال قائمًا)
            log_error(e, sys.exc_info()[2])
            try:
                lock.destroy()
            except Exception:
                pass
            self._idle_lock_win = None

    def save_idle_lock_setting(self):
        """★ إضافة (قفل الخمول): حفظ مدة قفل الخمول من شاشة الإعدادات
        القائمة — تحقق عربي كامل: عدد صحيح من 0 إلى 120 فقط (والأرقام
        العربية مقبولة كعادتها في البرنامج كله)، ورسالة عربية واضحة عند
        أي إدخال غير صالح ولا يُحفظ شيء، والقيمة تُخزَّن في settings
        بمفتاح idle_lock_minutes وتسري فورًا (تحديث الكاش مباشرة)"""
        try:
            raw = self.e_idle_lock.get().strip().translate(AR_DIGITS)
            if not raw:
                messagebox.showwarning("قفل الخمول",
                    "أدخل مدة قفل الخمول بالدقائق — عدد صحيح من 0 إلى 120 "
                    "(0 = إيقاف القفل)")
                return
            try:
                n = int(raw)
            except ValueError:
                messagebox.showwarning("قفل الخمول",
                    "القيمة غير صالحة — أدخل عددًا صحيحًا من 0 إلى 120 "
                    "(0 = إيقاف القفل)")
                return
            if n < 0 or n > 120:
                messagebox.showwarning("قفل الخمول",
                    "المدة يجب أن تكون من 0 إلى 120 دقيقة (0 = إيقاف القفل)")
                return
            set_setting(IDLE_LOCK_KEY, str(n))
            self._idle_lock_minutes_cache = n     # تسري فورًا دون انتظار الكاش
            self._idle_cache_tick = 0
            audit("ضبط قفل الخمول",
                  ("إيقاف قفل الخمول" if n == 0
                   else f"مدة قفل الخمول: {n} دقيقة"))
            self.lbl_idle_lock_status.config(
                text=("✔ تم الحفظ — قفل الخمول مُوقف" if n == 0
                      else f"✔ تم الحفظ — القفل بعد {n} دقيقة خمول"),
                fg=GREEN)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", "تعذر حفظ إعدادات قفل الخمول")

    def switch_user(self):
        """★ إضافة (إصدار 4 — ميزة 1): تبديل المستخدم دون إغلاق البرنامج —
        تحذير إذا كانت السلة فيها أصناف، تسجيل الخروج في سجل التدقيق، إخفاء
        النافذة الرئيسية وإظهار نافذة تسجيل الدخول الحالية من جديد، وعند نجاح
        الدخول تُصفَّر الجلسة وتتكيف كل الشاشات مع صلاحيات المستخدم الجديد.
        إلغاء الدخول يغلق البرنامج بأمان (كما عند بدء التشغيل)"""
        # تحذير: السلة فيها أصناف ستُفقد عند التبديل
        if getattr(self, "cart", None):
            if not messagebox.askyesno("تبديل المستخدم",
                    "السلة فيها أصناف ستُفقد عند التبديل — متابعة؟"):
                return
        # ★ إضافة (إصدار 8 — الميزة 3): أول خطوة قبل إظهار نافذة الدخول — إغلاق
        # كل النوافذ المفتوحة فوراً (تفاصيل اليوم، المعاينة، إدارة المستخدمين،
        # تغيير كلمة المرور...) مع إفراغ السلة (تحذير السلة الحالي أعلاه باقٍ
        # كما هو) — فلا تبقى أي شاشة تعمل باسم المستخدم القديم بعد التبديل أبداً
        closed_count = self.close_all_windows()
        audit(f"تبديل مستخدم — إغلاق {closed_count} نافذة مفتوحة")
        audit("تبديل مستخدم — خروج " + self.user_name)   # تسجيل الخروج في سجل التدقيق
        self.withdraw()                    # إخفاء النافذة الرئيسية
        try:
            # ★ تعديل ضروري معلن (إصدار 4 — ميزة 1): شاشة الدخول نفسها تُعرض عبر
            # login_dialog (Toplevel + wait_window) بدل استدعاء login_flow مباشرة —
            # لأن login_flow تنشئ نافذة Tk ثانية بـ mainloop خاص لا يعود أبداً بعد
            # تدميرها ما دامت النافذة الرئيسية حية (يُعلّق البرنامج كلياً)،
            # والبديل يعطي نفس الشاشة ونفس السلوك ونفس سجل التدقيق تماماً
            session = self.login_dialog()  # شاشة تسجيل الدخول من جديد
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            session = None
        if session is None:
            self.exit_app()                # أُلغي الدخول: إغلاق آمن كما عند بدء التشغيل
            return
        # نجاح الدخول: تصفير الجلسة للمستخدم الجديد
        CURRENT_USER["name"] = session["name"]
        self.user_name = session["name"]
        self.role = session["role"]
        self.user_role = session["role"]
        # ★ إضافة (إصلاح 1 — بعد تبديل المستخدم): الجلسة الجديدة تبدأ بلا
        # إخفاء سابق للشريط (حتى يظهر للمستخدم الجديد إن وُجد تحديث)، مع
        # فحص صامت واحد بعد الدخول بنفس دالة الفحص القائمة نفسها — كما
        # بعد الدخول عند بدء التشغيل تماماً
        self.update_bar_dismissed = False
        self.update_bar_dismissed_version = None
        self.after(1200, lambda: update_check_silent(self))
        # ★ إضافة (الإصدار 16 — القسم 1-2): تصفير تنبيه الإدارة للمستخدم
        # الجديد وإعادة الفحص الصامت إن كان في مستوى الإدارة — والإخفاء
        # السابق كان لهذه الجلسة فقط فانتهى بخروج صاحبه
        self.alert_data = None
        self.alert_dismissed = False
        if manager_level(self.role):
            self.after(700, self._alert_scan)
        else:
            self._render_alert_card()
        self.cart = []                     # السلة تُفرغ
        if hasattr(self, "e_inv_customer"):
            self.e_inv_customer.delete(0, "end")
        if hasattr(self, "lbl_inv_status"):
            self.lbl_inv_status.config(text="")
        self.update_cart_view()
        if hasattr(self, "cb_today_filter"):      # تصفير فلاتر عمليات اليوم
            self.cb_today_filter.set("الكل")
        if getattr(self, "today_type_var", None) is not None:
            self.today_type_var.set("الكل")
        if hasattr(self, "e_search"):             # مسح نتائج بحث المستخدم السابق
            self.e_search.delete(0, "end")
        if hasattr(self, "tv_search"):
            self.tv_search.delete(*self.tv_search.get_children())
            self.lbl_search.config(text="")
        for attr in ("tv_audit", "tv_users", "tv_sellers"):   # مسح شاشات المدير
            tv = getattr(self, attr, None)
            if tv is not None:
                tv.delete(*tv.get_children())
        if hasattr(self, "lbl_perf_total"):
            self.lbl_perf_total.config(text="")
            self.sellers_report_rows = []
            self.sellers_report_total = []
        for v in getattr(self, "dash_cards", {}).values():     # مسح لوحة المعلومات
            v.config(text="—")
        if hasattr(self, "tv_dash_items"):
            self.tv_dash_items.delete(*self.tv_dash_items.get_children())
        if hasattr(self, "lbl_dash_range"):
            self.lbl_dash_range.config(text="")
        if hasattr(self, "lbl_chart_info"):
            self.lbl_chart_info.config(
                text="📈 صافي آخر 30 يوم عمل — مرّر المؤشر فوق أي عمود لعرض قيمته", fg=GRAY)
        self.apply_role_ui()               # تكييف الشريط الجانبي والشاشات مع الدور
        self.show_page("new")              # العودة لصفحة «عملية جديدة» (تحدّث الشريط العلوي)
        self.refresh_today()               # تحديث عمليات اليوم
        self.refresh_archive()             # تحديث الأرشيف
        self.deiconify()                   # إعادة إظهار النافذة الرئيسية
        # ★ الاستثناء ج المصرح به (المرحلة الرابعة — القسم 4): سطر واحد في
        # نهاية معالج تبديل المستخدم يستدعي إعادة بناء الواجهة — بدونه تبقى
        # أزرار الجلسة السابقة ظاهرة حتى إغلاق البرنامج (كمدخل «الصلاحيات
        # الدقيقة» بعد التبديل من أدمن إلى غيره) ولا تظهر أزرار صلاحيات
        # المستخدم الجديدة أبدًا (الشرح الكامل داخل الدالة نفسها)
        self.rebuild_ui_for_current_user()

    def apply_role_ui(self):
        """★ إضافة (إصدار 4 — ميزة 1): تكييف الواجهة مع دور المستخدم الحالي بعد
        التبديل — إظهار/إخفاء أزرار المدير وملاحظات البائع وفلتر البائع وتحديث
        اسم المستخدم تحت الشعار (الشريط العلوي والأرشيف الإجمالي يبقيان عامين كما هما)"""
        self.lbl_user.config(text=f"👤 {self.user_name} ({self.role})")
        if self.role == "مدير":
            for b in self.manager_btns:       # أزرار المدير تظهر
                b.pack(fill="x", padx=10, pady=3)
            self.lbl_today_only.pack_forget()
            self.fr_today_filter.pack(side="left", padx=12)
            if hasattr(self, "lbl_search_only"):
                self.lbl_search_only.pack_forget()
        else:
            for b in self.manager_btns:       # أزرار المدير تختفي عن البائع
                b.pack_forget()
            self.fr_today_filter.pack_forget()
            self.lbl_today_only.pack(side="left", padx=12)
            if hasattr(self, "lbl_search_only"):
                self.lbl_search_only.pack(fill="x", padx=25, anchor="e")

        # ★ إضافة (إصدار 8 — الميزة 5+6+7): إعادة بناء ظهور أزرار الشريط
        # الجانبي حسب صلاحيات المستخدم الجديد الفعلية عند كل دخول/تبديل
        # (المدير يملك كل الصلاحيات دائماً — والبائع بحسب ما مُنح له) +
        # تحديث نص زر قائمة المستخدم أسفل الشريط
        self.refresh_sidebar_permissions()
        # ★ إضافة (إصدار 10): مواءمة شريط إشعار التحديث مع دور المستخدم بعد
        # التبديل — البائع يرى «راجع المدير» والمدير يرى زر «تحديث الآن»
        self.refresh_update_bar()
        # ★ إضافة (الإصدار 16 — القسم 1-3): زر فحص سلامة السجل للمدير/الأدمن
        # فقط — يتكيف مع تبديل المستخدم (يُخفى عن البائع ويعود للمدير)
        try:
            if getattr(self, "btn_audit_integrity", None) is not None:
                if manager_level(self.role):
                    self.btn_audit_integrity.pack(side="left", padx=6, pady=6)
                else:
                    self.btn_audit_integrity.pack_forget()
        except Exception:
            pass
        # ★ إضافة (الإصدار 18 — المشكلة 2): زر تصحيح العملية يتكيف مع صلاحيات
        # المستخدم الجديد بعد التبديل — يظهر لمن يملك «✏️ تصحيح عملية» فقط
        # (تعديل ضروري محدود: بدون هذا الكتلة يبقى الزر بحالة مستخدمه السابق)
        try:
            if getattr(self, "btn_correct_op", None) is not None:
                if self.has_permission("edit_op"):
                    self.btn_correct_op.pack(side="right", padx=6)
                else:
                    self.btn_correct_op.pack_forget()
        except Exception:
            pass
        # ★ إضافة (الإصدار 21 — المطلوب 3): زر «✏️ تعديل الحركة» يتكيف مع الدور
        # بعد التبديل — للأدمن والمدير فقط (البائع لا يراه نهائياً)، وزر الإغلاق
        # اليدوي نفسه يتكيف مع الدور من بوابة refresh_business_day_ui (نقطة
        # التجمع التي تُستدعى مع كل تحديث) فلا يحتاج كتلة هنا
        try:
            if getattr(self, "btn_edit_op21", None) is not None:
                if manager_level(self.role):
                    self.btn_edit_op21.pack(side="left", padx=6)
                else:
                    self.btn_edit_op21.pack_forget()
        except Exception:
            pass

