        self.lbl_login_bg_preview = tk.Label(card3, bg=CARD)
        self.lbl_login_bg_preview.pack(pady=(2, 12))
        self.refresh_login_bg_controls()

        # ★ إضافة (قفل الخمول): بطاقة ضبط مدة قفل الخمول — من شاشة الإعدادات
