    def refresh_printer_list(self):
        """★ إضافة (إصدار 6): جلب قائمة الطابعات من ويندوز وعرضها في القائمة
        المنسدلة — والطابعة المحفوظة في الإعدادات تُحدد تلقائياً إن وُجدت
        ★ تعديل مصرح به (الإصدار 20 — القسم 1): منطق اكتشاف الطابعات المثبتة
        في النظام كما هو حرفياً بلا أي تغيير — المصدر الوحيد المتغير هو
        الطابعة المحفوظة: صارت من مفتاح هذا الجهاز printer_device_<اسم
        الجهاز> (مع توافق المفاتيح العامة القديمة) بدل المفتاح العام"""
        try:
            printers = get_windows_printers()
            self.cb_printer["values"] = printers
            cur = self.cb_printer.get().strip()
            saved = get_device_printer()
            pick = cur if cur in printers else (saved if saved in printers else "")
            self.cb_printer.set(pick)
            if printers:
                self.lbl_print_status.config(
                    text=f"✔ تم العثور على {len(printers)} طابعة مثبتة", fg=GREEN)
            else:
                self.lbl_print_status.config(
                    text="لم يتم العثور على طابعات مثبتة على هذا الجهاز", fg=RED)
        except Exception as e:
            log_error(e)
            self.lbl_print_status.config(text="تعذر جلب قائمة الطابعات", fg=RED)

    def on_printer_selected(self):
        """★ إضافة (إصدار 6): اختيار الطابعة يُحفظ فوراً في جدول settings
        الموجود — كما تنص المواصفة تماماً
        ★ تعديل مصرح به (الإصدار 20 — القسم 1): الحفظ صار على مفتاح هذا
        الجهاز printer_device_<اسم الجهاز> بدل المفتاح العام printer_name —
        فكل جهاز طابعته الخاصة وتغيير طابعة جهاز لا يؤثر على باقي الأجهزة،
        ويُحدَّث شريط الحالة السفلي فوراً بعد الحفظ (البند 4)"""
        try:
            name = self.cb_printer.get().strip()
            if name:
                set_device_printer(name)
                self.lbl_print_status.config(text=f"✔ تم اختيار الطابعة: {name}", fg=GREEN)
                self.refresh_printer_status_bar()
        except Exception as e:
            log_error(e)

    def test_print(self):
        """★ إضافة (إصدار 6): طباعة صفحة اختبار قصيرة (اسم النظام + سطر تجريبي
        عربي + التاريخ + الوقت) للتأكد أن كل شيء يعمل قبل الاعتماد على الطباعة"""
        try:
            # ★ تعديل مصرح به (الإصدار 20 — القسم 1): المصدر مفتاح الجهاز
            # (مع توافق المفاتيح العامة القديمة) والحفظ على مفتاح هذا الجهاز
            name = self.cb_printer.get().strip() or get_device_printer()
            if not name:
                messagebox.showwarning("تنبيه", "اختر الطابعة أولاً من القائمة")
                return
            set_device_printer(name)   # حفظ المختار إن كان جديداً — على مفتاح هذا الجهاز
            self.refresh_printer_status_bar()   # ★ إضافة (الإصدار 20 — البند 4)
            if print_report_lines(name, build_test_page_lines(), job_title="طباعة تجريبية"):
                audit("طباعة تجريبية", name)   # ★ تسجيل الطباعة التجريبية في سجل التدقيق
                messagebox.showinfo("تم", "أُرسلت صفحة الاختبار إلى الطابعة ✅")
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    def save_print_settings(self):
        """★ إضافة (إصدار 6): حفظ اسم المحل وخيار الطباعة التلقائية والطابعة
        المختارة في جدول settings الموجود — مع تسجيل الحفظ في سجل التدقيق"""
        try:
            name = self.cb_printer.get().strip()
            if name:
                # ★ تعديل مصرح به (الإصدار 20 — القسم 1): الحفظ على مفتاح
                # هذا الجهاز printer_device_<اسم الجهاز> — لا المفتاح العام
                set_device_printer(name)
            set_setting("store_name", self.e_store.get().strip())
            set_setting("auto_print_daily", "1" if self.var_auto_print.get() else "0")
            audit("حفظ إعدادات الطباعة",
                  f"الطابعة: {name or 'غير محددة'} — الطباعة التلقائية: "
                  + ("مفعلة" if self.var_auto_print.get() else "معطلة"))
            self.lbl_print_status.config(text="✔ تم حفظ إعدادات الطباعة", fg=GREEN)
            # ★ إضافة (الإصدار 20 — البند 4): تحديث فوري لشريط الحالة السفلي
            # بعد تغيير المدير للطابعة (أو حفظ الإعدادات دون تغيير)
            self.refresh_printer_status_bar()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", "تعذر حفظ إعدادات الطباعة")

    # ---------- ★ إضافات الإصدار 9 (الميزة 8): خلفية شاشة الدخول ----------
    def choose_login_bg_image(self):
        """★ إضافة (إصدار 9 — الميزة 8): اختيار صورة خلفية شاشة الدخول —
        filedialog تقبل png/jpg وتُحوّل png عبر pillow (المثبتة أصلاً) وتُحفظ
        باسم ثابت في مجلد البيانات، ومسارها في settings (المفتاح login_bg)
        مع تسجيل التعيين في سجل التدقيق"""
        if not LOGIN_BG_PIL_OK:
            messagebox.showwarning("تحتاج pillow", "اختيار صورة الخلفية يحتاج مكتبة pillow:\n"
                                    "pip install pillow")
            return
        p = filedialog.askopenfilename(title="اختيار صورة خلفية شاشة الدخول", parent=self,
                                       filetypes=[("صور", "*.png *.jpg *.jpeg *.bmp"),
                                                  ("كل الملفات", "*.*")])
        if not p:
            return
        try:
            img = _BGImage.open(p).convert("RGB")
            img.save(login_bg_file(), "PNG")       # تحويل موحّد إلى png باسم ثابت
            set_setting("login_bg", login_bg_file())
            audit("تعيين صورة خلفية الدخول", os.path.basename(p))
            self.refresh_login_bg_controls()
            messagebox.showinfo("تم", "تم تعيين صورة الخلفية — ستظهر خلف شاشة الدخول القادمة")
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", f"تعذر تحميل الصورة:\n{e}")

    def remove_login_bg_image(self):
        """★ إضافة (إصدار 9 — الميزة 8): إزالة الصورة والعودة للخلفية المتدرجة
        الافتراضية — مع تسجيل الإزالة في سجل التدقيق"""
        try:
            set_setting("login_bg", "")
            try:
                if os.path.exists(login_bg_file()):
                    os.remove(login_bg_file())
            except Exception:
                pass
            audit("إزالة صورة خلفية الدخول")
            self.refresh_login_bg_controls()
            messagebox.showinfo("تم", "أُزيلت الصورة — عادت الخلفية المتدرجة الافتراضية")
        except Exception as e:
            log_error(e)
            messagebox.showerror("خطأ", "تعذرت الإزالة")

    def refresh_login_bg_controls(self):
        """★ إضافة (إصدار 9 — الميزة 8): تحديث حالة ومعاينة مصغرة لخلفية الدخول
        في شاشة إعدادات الطباعة — وأي فشل يُعرض بهدوء دون رسائل مزعجة"""
        try:
            if not hasattr(self, "lbl_login_bg_state"):
                return
            path = get_setting("login_bg")
            on = bool(path) and os.path.exists(path) and LOGIN_BG_PIL_OK
            self.lbl_login_bg_state.config(
                text=("✔ معيّنة — ستظهر خلف شاشة الدخول" if on
                      else "غير معيّنة — الخلفية المتدرجة الافتراضية"),
                fg=(GREEN if on else GRAY))
            self.lbl_login_bg_preview.config(image="", text="")
            self.lbl_login_bg_preview.image = None
            if on:
                try:
                    img = _BGImage.open(path)
                    img.thumbnail((240, 130))
                    ph = _BGImageTk.PhotoImage(img)
                    self.lbl_login_bg_preview.config(image=ph)
                    self.lbl_login_bg_preview.image = ph   # مرجع حي يمنع محو الصورة
                except Exception:
                    self.lbl_login_bg_preview.config(text="(تعذر عرض المعاينة)")
        except Exception as e:
            log_error(e)

    # ---------- (6) إعادة طباعة أي يوم من الأرشيف ----------
    def print_selected_day(self):
        """★ إضافة (إصدار 6): طباعة تقرير اليوم المحدد من شريط الأرشيف"""
        sel = self.tv_arch.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً"); return
        self.print_day_report(sel[0], reprint=True)

    def print_day_report(self, d, reprint=False, closer=None, when=""):
        """★ إضافة (إصدار 6): طباعة تقرير إغلاق يوم من بيانات daily_reports
        المحفوظة (نقداً/شبكة/مرتجعات/الإجمالي/عدد العمليات/وقت الإغلاق) — عند
        الإعادة يظهر سطر «إعادة طباعة» بالوقت الحالي، وكل طباعة ناجحة تُسجل
        في سجل التدقيق باسم من طبع. أي فشل يعرض رسالة عربية ويسجل في
        error_log ولا يوقف البرنامج أبداً"""
        try:
            with connect() as conn:
                rep = conn.execute("SELECT * FROM daily_reports WHERE report_date=?",
                                   (d,)).fetchone()
            if rep is None:
                messagebox.showinfo("تنبيه", f"لا يوجد تقرير محفوظ ليوم {d}")
                return
            # من أغلق اليوم: من سجل التدقيق إن لم يُمرر مباشرة (إعادة الطباعة)
            who = closer or get_day_closer(d) or CURRENT_USER["name"]
            lines = build_day_report_lines(
                store_name=get_setting("store_name") or "",
                d=d, ops_count=rep["ops_count"] or 0,
                cash=rep["total_cash"] or 0, netw=rep["total_network"] or 0,
                rets=rep["total_returns"] or 0, net=rep["net_total"] or 0,
                closed_at=rep["closed_at"], closed_by=who, reprint=reprint)
            # ★ تعديل مصرح به (الإصدار 20 — القسم ٣): مصدر اسم الطابعة صار
            # مفتاح هذا الجهاز printer_device_<اسم الجهاز> (مع توافق المفاتيح
            # العامة القديمة) — المنطق والتنسيق كما هما تماماً
            if print_report_lines(get_device_printer(), lines,
                                  job_title=f"تقرير يوم {d}"):
                audit("طباعة تقرير يوم",
                      d + (" — إعادة طباعة" if reprint else (" — " + when if when else "")))
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    # ═══════════════════════════════════════════════════════════
    # ★★★ إضافات الإصدار 7 — شاشة النسخ والاستعادة + المعاينة قبل الطباعة ★★★
    # ═══════════════════════════════════════════════════════════

    # ---------- (الطبقة 4) شاشة النسخ والاستعادة — للمدير فقط ----------
    def show_backups(self):
        """★ إضافة (إصدار 7): فتح شاشة النسخ والاستعادة — للمدير فقط"""
        # ★ تعديل مصرح به (إصدار 8 — الميزة 5): صلاحية «النسخ والاستعادة» بدل «المدير فقط»
        if not self.require_admin("backup"):
            return
        self.show_page("backups")
        self.refresh_backups_list()

    def build_backups_page(self, p):
        """★ إضافة (إصدار 7 — الطبقة 4): شاشة «🗄️ النسخ والاستعادة» — جدول
        بكل النسخ (النوع/الاسم/التاريخ/المكان/الحجم بالكيلوبايت/عدد العمليات
        داخل النسخة) + نسخة فورية الآن + استعادة نسخة مختارة + اختيار مجلد
        النسخ الخارجي + فتح مجلد النسخ + تصدير كل البيانات (طوارئ)"""
        self.page_head(p, "🗄️ النسخ والاستعادة",
                       "حماية البيانات — نسخ يومية وشهرية وفورية واستعادة آمنة — للمدير فقط")

        # بطاقة معلومات مجلدات النسخ: الداخلي والخارجي
        info = tk.Frame(p, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        info.pack(fill="x", padx=25, pady=6)
        tk.Label(info, text="مجلد النسخ الداخلي (بجانب البرنامج):", bg=CARD, fg=DARK,
                 font=FB).pack(pady=(12, 2))
        tk.Label(info, text=BACKUP_ROOT, bg=CARD, fg=GRAY, font=("Consolas", 9)).pack(pady=(0, 6))
        self.lbl_bk_external = tk.Label(info, text="", bg=CARD, fg=GRAY,
                                        font=("Segoe UI", 10, "bold"), wraplength=860)
        self.lbl_bk_external.pack(pady=(0, 12))

        # صف الأزرار: نسخة فورية / استعادة / مجلد خارجي / فتح المجلد / تصدير طوارئ / تحديث
        bar = tk.Frame(p, bg=BG); bar.pack(fill="x", padx=25, pady=6)
        b_now = self.mk_btn(bar, "📋 نسخة فورية الآن", self.make_instant_now, GREEN)
        b_now.pack(side="right", padx=5)
        add_tip(b_now, "نسخة يدوية فورية من قاعدة البيانات باسم instant_التاريخ_الوقت (يُحتفظ بآخر 10)")
        b_rest = self.mk_btn(bar, "♻️ استعادة نسخة مختارة", self.restore_selected_backup, ORANGE)
        b_rest.pack(side="right", padx=5)
        add_tip(b_rest, "استبدال القاعدة الحالية بنسخة مختارة — بعد فحص صحتها وأخذ نسخة أمان تلقائياً")
        b_ext = self.mk_btn(bar, "📂 اختيار مجلد النسخ الخارجي", self.choose_external_dir, "#0369a1")
        b_ext.pack(side="right", padx=5)
        add_tip(b_ext, "اختيار مجلد خارجي (فلاش/قرص آخر) تُنسخ إليه النسخ اليومية والشهرية إضافة للداخلي")
        b_open = self.mk_btn(bar, "🖥 فتح مجلد النسخ", self.open_backups_folder, "#475569")
        b_open.pack(side="right", padx=5)
        add_tip(b_open, "فتح مجلد النسخ الاحتياطي في مستكشف ويندوز")
        b_emg = self.mk_btn(bar, "📤 تصدير كل البيانات (طوارئ)", self.export_emergency, RED)
        b_emg.pack(side="right", padx=5)
        add_tip(b_emg, "ملف Excel شامل بكل البيانات (العمليات/التقارير/المستخدمون/سجل التدقيق)")
        b_ref = self.mk_btn(bar, "🔄 تحديث", self.refresh_backups_list, "#475569")
        b_ref.pack(side="right", padx=5)
        add_tip(b_ref, "إعادة تحميل جدول النسخ من مجلدات النسخ الداخلية والخارجية")
        # ★ إضافة (الإصدار 16 — القسم 2-8): زر فحص سلامة قاعدة البيانات —
        # PRAGMA integrity_check بالعربية (سليمة ✅ / تالفة ⚠ مع التفاصيل)
        b_dbchk = self.mk_btn(bar, "🧪 فحص سلامة قاعدة البيانات",
                              self.db_integrity_check, "#7c3aed")
        b_dbchk.pack(side="right", padx=5)
        add_tip(b_dbchk, "فحص شامل لسلامة ملف قاعدة البيانات (integrity_check) — "
                         "سليمة ✅ أو تالفة ⚠ مع التفاصيل ونصيحة الاستعادة")

        # جدول النسخ: النوع | اسم النسخة | التاريخ | المكان | الحجم | عدد العمليات
        frm, self.tv_backups = self.mk_tree(p,
            ["عدد العمليات", "الحجم (KB)", "المكان", "التاريخ", "اسم النسخة", "النوع"],
            [100, 100, 90, 105, 250, 115])
        frm.pack(fill="both", expand=True, padx=25, pady=8)
        self.tv_backups.tag_configure("monthly", background="#dcfce7")   # شهرية: خلفية خضراء فاتحة
        self.tv_backups.tag_configure("instant", background="#e0f2fe")   # فورية: خلفية زرقاء فاتحة
        self.tv_backups.tag_configure("safety", background="#fef3c7")    # أمان استعادة: برتقالية فاتحة

        # سياسة الاحتفاظ — سطر توضيحي أسفل الشاشة
        self.lbl_bk_policy = tk.Label(p, text="", bg=BG, fg=GRAY,
                                      font=("Segoe UI", 10, "bold"), wraplength=900, justify="right")
        self.lbl_bk_policy.pack(fill="x", padx=25, pady=(0, 16))
        self.backups_list = []     # بيانات الجدول الحالية (تُستخدم عند الاستعادة)

    def refresh_backups_list(self):
        """★ إضافة (إصدار 7 — الطبقة 4): تحميل كل النسخ في الجدول — الداخلية
        والخارجية معاً، مع عدد العمليات داخل كل نسخة وبتحديث حالة المجلد الخارجي"""
        # ★ تعديل مصرح به (إصدار 8 — الميزة 5): فحص الصلاحية الدقيقة بدل «المدير فقط»
        if not self.has_permission("backup"):
            return
        self.backups_list = list_all_backups()
        self.tv_backups.delete(*self.tv_backups.get_children())
        for i, b in enumerate(self.backups_list):
            tag = ("monthly" if b["type"] == "شهرية" else
                   "instant" if b["type"] == "فورية" else
                   "safety" if b["type"] == "أمان استعادة" else "")
            self.tv_backups.insert("", "end", iid=str(i), tags=(tag,) if tag else (),
                values=((str(b["ops"]) if b["ops"] >= 0 else "—"), b["size"], b["place"],
                        b["date"], b["name"], b["type"]))
        ext = get_setting("external_backup_dir")
        self.lbl_bk_external.config(
            text=("مجلد النسخ الخارجي: " + ext if ext
                  else "⚠ لم يتم اختيار مجلد نسخ خارجي بعد — يُنصح باختيار فلاش/قرص خارجي للنسخ في مكانين"),
            fg=(GRAY if ext else ORANGE))
        n_daily = sum(1 for b in self.backups_list if b["type"] == "يومية")
        n_month = sum(1 for b in self.backups_list if b["type"] == "شهرية")
        n_inst = sum(1 for b in self.backups_list if b["type"] == "فورية")
        self.lbl_bk_policy.config(
            text=(f"النسخ: {n_daily} يومية (آخر 30 تلقائياً) — {n_month} شهرية (دائمة لا تُحذف) — "
                  f"{n_inst} فورية (آخر 10) — تُنشأ نسخة يومية تلقائياً عند كل إغلاق يوم ناجح "
                  "وفشل النسخ لا يلغي الإغلاق أبداً"))

    def make_instant_now(self):
        """★ إضافة (إصدار 7 — الطبقة 4): زر «📋 نسخة فورية الآن» — نسخة يدوية
        فورية تُسجل في سجل التدقيق ويُحدَّث الجدول بعدها مباشرة"""
        try:
            path = make_instant_backup()
            self.refresh_backups_list()
            messagebox.showinfo("تم", "تم إنشاء النسخة الفورية بنجاح ✅\n"
                                        + os.path.basename(path))
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", f"تعذر إنشاء النسخة الفورية:\n{e}")

    # ★★★ إضافة (الإصدار 16 — القسم 2-8): فحص سلامة قاعدة البيانات 🧪 ★★★
    def db_integrity_check(self):
        """زر «🧪 فحص سلامة قاعدة البيانات» — يشغّل PRAGMA integrity_check
        ويعرض النتيجة بالعربية: سليمة ✅ أو تالفة ⚠ مع تفاصيل الأخطاء
        ونصيحة أخذ نسخة فورية واستعادة آخر نسخة سليمة، وكل فحص يُسجل
        في سجل التدقيق"""
        try:
            with connect() as conn:
                res = conn.execute("PRAGMA integrity_check").fetchall()
            lines = [str(r[0]) for r in res]
            if lines and lines[0] == "ok":
                audit("فحص سلامة قاعدة البيانات", "سليمة")
                messagebox.showinfo("فحص سلامة القاعدة",
                                    "✅ قاعدة البيانات سليمة — لا يوجد أي تلف")
            else:
                audit("فحص سلامة قاعدة البيانات", "تحذير تلف: " + " | ".join(lines[:3]))
                messagebox.showwarning("تحذير — قاعدة البيانات تالفة ⚠",
                    "⚠ نتائج الفحص تشير إلى تلف في قاعدة البيانات:\n\n"
                    + "\n".join(lines[:10]) +
                    "\n\nخُذ «📋 نسخة فورية الآن» ثم استعد آخر نسخة سليمة من الجدول.")
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", f"تعذر فحص قاعدة البيانات:\n{e}")

    def choose_external_dir(self):
        """★ إضافة (إصدار 7 — الطبقة 3): زر «اختيار مجلد النسخ الخارجي» —
        filedialog يختار مجلداً خارجياً يُحفظ مكانه في settings
        (external_backup_dir) وتُنسخ إليه كل نسخة يومية وشهرية قادمة إضافة
        للمجلد الداخلي، وكل تغيير يُسجل في سجل التدقيق"""
        d = filedialog.askdirectory(title="اختيار مجلد النسخ الخارجي (فلاش / قرص خارجي)")
        if not d:
            return
        set_setting("external_backup_dir", d)
        audit("تغيير مجلد النسخ الخارجي", d)
        self.refresh_backups_list()
        messagebox.showinfo("تم",
            "تم تعيين مجلد النسخ الخارجي ✅\n" + d +
            "\n\nكل نسخة يومية وشهرية قادمة ستُنسخ في المكانين معاً (داخلي + خارجي)،"
            "\nوإن فشل الخارجي تستمر النسخة الداخلية مع رسالة تحذير.")

    def open_backups_folder(self):
        """★ إضافة (إصدار 7 — الطبقة 3): زر «فتح مجلد النسخ» — يفتح مجلد
        backups في مستكشف ملفات ويندوز"""
        try:
            ensure_backup_dirs()
            if os.name == "nt":
                os.startfile(BACKUP_ROOT)
            else:
                messagebox.showinfo("مجلد النسخ", BACKUP_ROOT)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", f"تعذر فتح مجلد النسخ:\n{e}")

    def restore_selected_backup(self):
        """★ إضافة (إصدار 7 — الطبقة 4): زر «♻️ استعادة نسخة مختارة» — فحص
        صحة النسخة أولاً (فتحها بـ sqlite3 وقراءة جدول) ثم تحذير قوي بالعربية
        يوضح أن الاستعادة تستبدل القاعدة الحالية، ثم نسخة أمان تلقائية من
        الوضع الحالي (pre_restore_...) ثم الاستبدال الذري ثم رسالة إعادة
        تشغيل البرنامج — والنسخة التالفة تُرفض برسالة واضحة"""
        sel = self.tv_backups.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر نسخة من الجدول أولاً"); return
        rec = self.backups_list[int(sel[0])]
        path = rec["path"]
        # 1) فحص صحة ملف النسخة قبل أي شيء
        ok, msg = check_backup_health(path)
        if not ok:
            messagebox.showerror("نسخة تالفة — رُفضت الاستعادة",
                "فشل فحص صحة هذه النسخة ولن تُستخدم:\n\n" + msg)
            return
        # 2) تحذير قوي بالعربية (تأكيد مزدوج)
        warn = ("⚠️ تحذير هام ⚠️\n\n"
                "الاستعادة ستستبدل قاعدة البيانات الحالية بالكامل ببيانات النسخة:\n"
                f"{rec['name']}  ({rec['type']} — {rec['date']})\n"
                f"النتيجة: {msg}\n\n"
                "كل العمليات التي تمت بعد هذه النسخة ستُفقد.\n"
                "سيُنشئ البرنامج تلقائياً نسخة أمان من الوضع الحالي قبل الاستعادة.\n\n"
                "هل أنت متأكد من المتابعة؟")
        if not messagebox.askyesno("تأكيد الاستعادة (1 من 2)", warn):
            return
        if not messagebox.askyesno("تأكيد الاستعادة (2 من 2)",
                "تأكيد أخير:\nهل تريد فعلاً استبدال القاعدة الحالية بهذه النسخة الآن؟"):
            return
        # 3) نسخة الأمان ثم الاستبدال الذري ثم رسالة إعادة التشغيل
        try:
            safety_name = restore_backup_file(path)
            audit("استعادة نسخة", f"{rec['name']} — نسخة الأمان: {safety_name}")
            messagebox.showinfo("تمت الاستعادة ✅",
                "استُبدلت قاعدة البيانات ببيانات النسخة بنجاح.\n"
                "نُشئت نسخة أمان من الوضع السابق باسم:\n" + safety_name +
                "\n\n⚠ أغلق البرنامج الآن وافتحه من جديد لتفعيل البيانات المستعادة.")
            self.exit_app()          # إغلاق البرنامج — يجب إعادة تشغيله بعد الاستعادة
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("فشلت الاستعادة",
                "تعذر استعادة النسخة:\n" + str(e) +
                "\n\nلم تتغير قاعدة البيانات الحالية (راجع error_log.txt).")

    def export_emergency(self):
        """★ إضافة (إصدار 7 — الطبقة 5): زر «📤 تصدير كل البيانات (طوارئ)» —
        ملف xlsx متعدد الأوراق (العمليات/التقارير اليومية/المستخدمون/سجل
        التدقيق) عبر export_xlsx_multi الجديدة بنفس منطق zip الموجود"""
        path = filedialog.asksaveasfilename(title="تصدير كل البيانات (طوارئ)",
                                            defaultextension=".xlsx",
                                            initialfile=f"تصدير_شامل_طوارئ_{today_str()}.xlsx",
                                            filetypes=[("ملف Excel", "*.xlsx")])
        if not path:
            return
        try:
            with connect() as conn:
                ops = conn.execute("SELECT date, item_name, customer_name, seller_name,"
                                   " quantity, price, total, type FROM operations"
                                   " ORDER BY date, id").fetchall()
                reps = conn.execute("SELECT report_date, ops_count, total_cash, total_network,"
                                    " total_sales, total_returns, net_total, closed_at"
                                    " FROM daily_reports ORDER BY report_date").fetchall()
                usrs = conn.execute("SELECT username, role,"
                                    " CASE WHEN active=1 THEN 'مفعل' ELSE 'موقوف' END, created_at"
                                    " FROM users ORDER BY id").fetchall()
                aud = conn.execute("SELECT ts, username, action, details FROM audit_log"
                                   " ORDER BY id").fetchall()
            export_xlsx_multi(path, [
                ("العمليات",
                 ["التاريخ", "اسم الصنف", "العميل", "البائع", "الكمية", "السعر", "المبيع", "النوع"],
                 [tuple(r) for r in ops],
                 [12, 26, 20, 16, 10, 10, 12, 10]),
                ("التقارير اليومية",
                 ["التاريخ", "عدد العمليات", "نقداً", "شبكة", "المبيعات", "المرتجعات", "الإجمالي", "وقت الإغلاق"],
                 [tuple(r) for r in reps],
                 [12, 12, 14, 14, 14, 14, 14, 18]),
                ("المستخدمون",
                 ["اسم المستخدم", "الدور", "الحالة", "تاريخ الإضافة"],
                 [tuple(r) for r in usrs],       # ★ بلا كلمات المرور أبداً — أمان
                 [20, 12, 12, 18]),
                ("سجل التدقيق",
                 ["التاريخ والوقت", "المستخدم", "الإجراء", "التفاصيل"],
                 [tuple(r) for r in aud],
                 [18, 16, 20, 40]),
            ], desc="تصدير طوارئ شامل — كل البيانات")
            messagebox.showinfo("تم", "تم تصدير كل البيانات بنجاح ✅\n" + path)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", f"تعذر التصدير:\n{e}")

    # ---------- (الميزة 7+8) المعاينة قبل الطباعة ومسار A4 ----------
    def print_selected_day_a4(self):
        """★ إضافة (إصدار 7 — الميزة 8): زر «🖨 طباعة/معاينة A4» في شريط
        الأرشيف — يفتح نافذة المعاينة لتقرير اليوم المحدد قبل أي طباعة"""
        sel = self.tv_arch.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر يوماً من الجدول أولاً"); return
        self.open_print_preview("day", sel[0])

    def print_period_report(self):
        """★ إضافة (إصدار 7 — الميزة 8): زر «📄 تقرير الفترة A4» — تقرير دوري
        لكل الأيام ضمن مدى التاريخ المُصفّى في الأرشيف، بعنوان «تقرير فترة من
        [تاريخ] إلى [تاريخ]» مع جدول الأيام والإجمالي التراكمي — عبر المعاينة"""
        f, t = parse_date_multi(self.e_from.get()), parse_date_multi(self.e_to.get())
        bad = [lbl for lbl, v in (("من تاريخ", f), ("إلى تاريخ", t)) if v is None]
        if bad:
            messagebox.showwarning("تاريخ خاطئ",
                "صيغة غير صحيحة لـ " + " و ".join(bad) +
                "\nالصيغ المقبولة: 2025-01-10 أو 10-01-2025 أو 10/01/2025")
            return
        if not f and not t:
            messagebox.showinfo("تنبيه",
                "أدخل مدى التاريخ أولاً في حقلي «من تاريخ» و«إلى تاريخ» بالأعلى ثم اضغط «🔍 تصفية»")
            return
        sql, params, cond = "SELECT * FROM daily_reports", [], []
        if f:
            cond.append("report_date >= ?"); params.append(f)
        if t:
            cond.append("report_date <= ?"); params.append(t)
        if cond:
            sql += " WHERE " + " AND ".join(cond)
        sql += " ORDER BY report_date"
        with connect() as conn:
            rows = conn.execute(sql, params).fetchall()
        if not rows:
            messagebox.showinfo("تنبيه", "لا توجد أيام مغلقة ضمن هذا المدى"); return
        dates = [r["report_date"] for r in rows]
        self.open_print_preview("period", (f or min(dates), t or max(dates), rows))

    def open_print_preview(self, kind, arg):
        """★ إضافة (إصدار 7 — الميزة 7): نافذة «👁️ معاينة قبل الطباعة» الكبيرة
        (900×700) — تعرض المحتوى المراد طباعته كما سيُطبع تماماً (الترويسة
        والتواريخ والصفوف والإجماليات) وأسفلها ثلاثة أزرار: «طباعة A4 (PDF)»
        تفتح حوار الطباعة القياسي في ويندوز (تختار طابعة A4 منه فتختفي مشكلة
        الصفحات البيضاء نهائياً) و«طباعة حرارية 80mm» على الطابعة المختارة في
        الإعدادات بنفس نظام ESC/POS الموجود و«إلغاء» — المعاينة مطلوبة دائماً
        قبل أي طباعة A4 ولا طباعة مباشرة بدونها"""
        store = get_setting("store_name") or "نظام المبيعات والمُرتجعات"
        if kind == "day":
            d = arg
            with connect() as conn:
                rep = conn.execute("SELECT * FROM daily_reports WHERE report_date=?",
                                   (d,)).fetchone()
            if rep is None:
                messagebox.showinfo("تنبيه", f"لا يوجد تقرير محفوظ ليوم {d}")
                return
            title = f"تقرير إغلاق اليوم — {day_name(d)} {d}"
            sub = f"وقت الإغلاق: {rep['closed_at'] or '—'}"
            data = {"d": d, "rep": rep}
        else:
            f, t, rows = arg
            title = f"تقرير فترة من {f} إلى {t}"
            sub = f"عدد الأيام: {len(rows)}"
            data = {"f": f, "t": t, "rows": rows}
        # ★ إضافة (إصدار 8 — الميزة 3): تسجيل نافذة المعاينة في التتبع المركزي
        win = self.register_window(tk.Toplevel(self))
        win.title("👁️ معاينة قبل الطباعة")
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول — القاعدة الذهبية): شريط
        # أزرار الطباعة السفلي يُحزم أولاً side="bottom" قبل الترويسة والمحتوى
        # فلا يُقص أبداً — والأزرار تُنشأ فيه في نهاية الدالة كالمعتاد
        bar = tk.Frame(win, bg=BG)
        bar.pack(side="bottom", fill="x", padx=22, pady=(4, 16))
        win.configure(bg=BG)

        # ترويسة المعاينة — كما ستُطبع تماماً: اسم المحل والعنوان والتاريخ
        head = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        head.pack(fill="x", padx=22, pady=(16, 6))
        tk.Label(head, text=store, bg=CARD, fg=DARK, font=FT).pack(pady=(12, 2))
        tk.Label(head, text=title, bg=CARD, fg=ACCENT,
                 font=("Segoe UI", 13, "bold")).pack(pady=2)
        tk.Label(head, text=sub, bg=CARD, fg=GRAY,
                 font=("Segoe UI", 10)).pack(pady=(0, 12))

        # محتوى المعاينة — نفس الصفوف والإجماليات التي ستُطبع
        body = tk.Frame(win, bg=BG)
        body.pack(fill="both", expand=True, padx=22, pady=4)
        if kind == "day":
            rep = data["rep"]
            closer = get_day_closer(d) or CURRENT_USER["name"]
            frm, tv = self.mk_tree(body, ["القيمة", "البند"], [300, 280])
            frm.pack(fill="both", expand=True, pady=(0, 4))
            tv.tag_configure("total", background="#dbeafe")
            rows = [("عدد العمليات", str(rep["ops_count"] or 0)),
                    ("مبيعات نقداً", money(rep["total_cash"] or 0)),
                    ("مبيعات شبكة", money(rep["total_network"] or 0)),
                    ("المرتجعات", money(rep["total_returns"] or 0)),
                    ("إجمالي اليوم", money(rep["net_total"] or 0)),
                    ("أغلق بواسطة", closer)]
            for i, (k, v) in enumerate(rows):
                tv.insert("", "end", tags=("total",) if k == "إجمالي اليوم" else (),
                          iid=str(i), values=(v, k))
            tk.Label(body, text="شكراً لزيارتكم", bg=BG, fg=GRAY,
                     font=("Segoe UI", 10, "bold")).pack(pady=(0, 4))
        else:
            rows = data["rows"]
            frm, tv = self.mk_tree(body,
                ["الإجمالي", "المرتجعات", "شبكة", "نقداً", "عدد العمليات", "التاريخ"],
                [110, 105, 100, 100, 95, 105])
            frm.pack(fill="both", expand=True, pady=(0, 4))
            tv.tag_configure("total", background="#dbeafe")
            t_cash = t_netw = t_rets = t_net = 0.0; t_ops = 0
            for r in rows:
                cash, netw = r["total_cash"] or 0, r["total_network"] or 0
                rets, net = r["total_returns"] or 0, r["net_total"] or 0
                t_cash += cash; t_netw += netw; t_rets += rets; t_net += net
                t_ops += r["ops_count"] or 0
                tv.insert("", "end", values=(money(net), money(rets), money(netw),
                                             money(cash), r["ops_count"], r["report_date"]))
            tv.insert("", "end", tags=("total",),
                      values=(money(t_net), money(t_rets), money(t_netw),
                              money(t_cash), t_ops, "الإجمالي التراكمي"))
            tk.Label(body, text=f"نقداً: {money(t_cash)} — شبكة: {money(t_netw)} — "
                                f"المرتجعات: {money(t_rets)} — عدد العمليات: {t_ops}",
                     bg=BG, fg=GRAY, font=("Segoe UI", 10, "bold")).pack(pady=(0, 4))

        # أزرار الطباعة الثلاثة أسفل المعاينة (شريطها محزوم أسفل النافذة أولاً)
        b_a4 = self.mk_btn(bar, "🖨 طباعة A4 (PDF)",
                           lambda: self._preview_print_a4(kind, data), "#1d4ed8")
        b_a4.pack(side="right", padx=6)
        add_tip(b_a4, "يُنشأ ملف PDF قياسي ويُفتح حوار الطباعة في ويندوز — اختر طابعة A4 منه")
        b_th = self.mk_btn(bar, "🖨 طباعة حرارية 80mm",
                           lambda: self._preview_print_thermal(kind, data), "#334155")
        b_th.pack(side="right", padx=6)
        add_tip(b_th, "طباعة على الطابعة الحرارية المختارة في إعدادات الطباعة (نظام ESC/POS الموجود)")
        b_cancel = self.mk_btn(bar, "❌ إلغاء", win.destroy, "#475569")
        b_cancel.pack(side="right", padx=6)
        add_tip(b_cancel, "إغلاق نافذة المعاينة دون طباعة")
        # ★ إضافة (الإصدار 15 — الجزء الأول): نفس الحجم 900×700 + minsize
        # + تمدد صريح + تمركز وسط الشاشة مع احترام الشاشات الصغيرة
        place_window(win, 900, 700, 760, 560, can_resize=True)

    def _preview_print_a4(self, kind, data):
        """★ إضافة (إصدار 7 — الميزة 6+7): تنفيذ طباعة A4 من المعاينة — ملف
        PDF قياسي يُحفظ مؤقتاً (مجلد pdf_reports بجانب البرنامج) ثم يُرسل
        للطباعة عبر حوار الطباعة القياسي، وكل طباعة تُسجل في سجل التدقيق
        بصيغة «طباعة A4 — [نوع التقرير]»"""
        # ★ إضافة (إصدار 8 — الميزة 5): صلاحية «تصدير التقارير (CSV/Excel/PDF)» —
        # طباعة A4 عبر ملف PDF هي أحد أنواع التصدير في النظام الدقيق
        if not self.has_permission("export_reports"):
            messagebox.showwarning("صلاحية", "ليست لديك صلاحية «تصدير التقارير»")
            return
        if not PDF_LIBS_OK:
            messagebox.showerror("طباعة A4 غير متاحة", PDF_LIBS_MSG)
            return
        try:
            store = get_setting("store_name") or ""
            folder = os.path.join(data_dir(), "pdf_reports")
            os.makedirs(folder, exist_ok=True)
            stamp = datetime.now().strftime("%H%M")
            if kind == "day":
                d, rep = data["d"], data["rep"]
                path = os.path.join(folder, f"تقرير_اليوم_{d}_{stamp}.pdf")
                build_day_report_pdf(path, store, d, rep["ops_count"] or 0,
                                     rep["total_cash"] or 0, rep["total_network"] or 0,
                                     rep["total_returns"] or 0, rep["net_total"] or 0,
                                     rep["closed_at"],
                                     get_day_closer(d) or CURRENT_USER["name"])
                label = f"تقرير إغلاق يوم {d}"
            else:
                f, t, rows = data["f"], data["t"], data["rows"]
                path = os.path.join(folder, f"تقرير_الفترة_{f}_{t}_{stamp}.pdf")
                build_period_report_pdf(path, store, f, t, rows)
                label = f"تقرير فترة من {f} إلى {t}"
            ok, err = send_pdf_to_printer(path)
            audit("طباعة A4 — " + label, os.path.basename(path))
            if ok:
                messagebox.showinfo("تم الإرسال للطباعة",
                    "أُرسل التقرير إلى حوار الطباعة ✅\n"
                    "اختر طابعة A4 من نافذة الطباعة التي ظهرت في ويندوز.\n\n"
                    "ملف PDF محفوظ في:\n" + path)
            else:
                messagebox.showwarning("افتح الملف واطبعه",
                    "تعذر فتح حوار الطباعة تلقائياً — فُتح ملف PDF بدلاً منه.\n"
                    "اطبع منه مباشرة (Ctrl+P) واختر طابعة A4.\n\n" + err + "\n\nالملف:\n" + path)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ في طباعة A4",
                                 "حدث خطأ أثناء توليد ملف PDF:\n\n" + str(e))

    def _preview_print_thermal(self, kind, data):
        """★ إضافة (إصدار 7 — الميزة 7): زر «الطباعة الحرارية 80mm» من
        المعاينة — لنفس نظام ESC/POS الموجود: تقرير اليوم عبر الدالة الموجودة
        نفسها (print_day_report) وتقرير الفترة عبر أسطر حرارية جديدة"""
        try:
            if kind == "day":
                self.print_day_report(data["d"], reprint=True)
            else:
                f, t, rows = data["f"], data["t"], data["rows"]
                # ★ تعديل مصرح به (الإصدار 20 — القسم ٣): مصدر اسم الطابعة مفتاح الجهاز
                if print_report_lines(get_device_printer(),
                                      build_period_report_lines(get_setting("store_name") or "",
                                                                f, t, rows),
                                      job_title=f"تقرير فترة {f} — {t}"):
                    audit("طباعة تقرير فترة", f"من {f} إلى {t} — {len(rows)} يوماً (حرارية)")
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    # ═══════════════════════════════════════════════════════
    # ★★★ إضافة (الإصدار 17 — الإضافة 1): تقرير البائعين الشامل للطباعة 🖨️ ★★★
    # متاح للجميع (البائع والمدير): معاينة أولاً (قاعدة المعاينة قبل الطباعة
    # القائمة) ثم طباعة حرارية 80mm أو A4 عبر PDF أو تصدير Excel — للعرض
    # والطباعة فقط بلا أي تعديل، وكل طباعة/تصدير في سجل التدقيق
    # ═══════════════════════════════════════════════════════
    def _sellers_report_rows(self, d_from, d_to):
        """★ إضافة (الإصدار 17 — الإضافة 1): جمع أداء كل البائعين ضمن الفترة
        من جدول العمليات (استعلام جديد فقط) — يرجع (صفوف البائعين، صف إجمالي
        المحل) بنفس أعمدة تقرير أداء البائعين القائم: عدد العمليات ونقداً
        وشبكة والمرتجعات والصافي"""
        cond, params = [], []
        if d_from:
            cond.append("date >= ?"); params.append(d_from)
        if d_to:
            cond.append("date <= ?"); params.append(d_to)
        where = (" WHERE " + " AND ".join(cond)) if cond else ""
        sql = ("SELECT seller_name, type, COUNT(*), SUM(total) FROM operations"
               + where + " GROUP BY seller_name, type")
        agg = {}
        with connect() as conn:
            for seller, typ, cnt, sm in conn.execute(sql, params):
                a = agg.setdefault(seller or "غير محدد",
                                   {"n": 0, "cash": 0.0, "netw": 0.0, "rv": 0.0})
                a["n"] += cnt
                if typ == "مرتجع":
                    a["rv"] += -(sm or 0)
                elif typ == "شبكة":
                    a["netw"] += (sm or 0)
                else:              # نقداً (وقيم المبيع القديمة بعد الترقية)
                    a["cash"] += (sm or 0)
        rows = []
        for seller, a in sorted(agg.items(),
                                key=lambda kv: (kv[1]["cash"] + kv[1]["netw"] - kv[1]["rv"]),
                                reverse=True):
            rows.append({"seller": seller, "n": a["n"], "cash": a["cash"],
                         "netw": a["netw"], "rets": a["rv"],
                         "net": a["cash"] + a["netw"] - a["rv"]})
        tot = {"seller": "إجمالي المحل", "n": sum(r["n"] for r in rows),
               "cash": sum(r["cash"] for r in rows), "netw": sum(r["netw"] for r in rows),
               "rets": sum(r["rets"] for r in rows), "net": sum(r["net"] for r in rows)}
        return rows, tot

    def open_sellers_report(self):
        """★ إضافة (الإصدار 17 — الإضافة 1): زر «🖨️ تقرير البائعين» — نافذة
        معاينة قبل الطباعة متاحة للجميع: جدول أداء كل البائعين للفترة
        (افتراضياً يوم العمل التجاري الحالي مع حقلي من/إلى تاريخ بنفس دالة
        التاريخ المرنة لفترة أوسع) + صف إجمالي المحل بخلفية مميزة، وأسفل
        التقرير التاريخ والوقت واسم من يطبع — وثلاثة مسارات من نفس المعاينة:
        طباعة حرارية 80mm / طباعة A4 عبر PDF / تصدير Excel (نفس export_xlsx)
        — التقرير للعرض والطباعة فقط ولا يتيح أي تعديل"""
        win = self.register_window(tk.Toplevel(self))
        win.title("👁️ معاينة قبل الطباعة — تقرير البائعين")
        win.configure(bg=BG)
        # القاعدة الذهبية: شريط الأزرار السفلي يُحزم أولاً side="bottom"
        # قبل أي شيء آخر فلا يُقص أبداً — والأزرار تُنشأ فيه بعد تعريف دوالها
        bar = tk.Frame(win, bg=BG)
        bar.pack(side="bottom", fill="x", padx=22, pady=(4, 16))
        # صف الفترة أعلى النافذة: حقلا من/إلى (نفس دالة التاريخ المرنة القائمة)
        frow = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        frow.pack(fill="x", padx=22, pady=(16, 4))

        def date_cell(label):
            c = tk.Frame(frow, bg=CARD); c.pack(side="right", padx=10, pady=10)
            tk.Label(c, text=label, bg=CARD, fg=DARK, font=FB).pack(side="right")
            e = tk.Entry(c, font=F, justify="center", relief="solid", bd=1, width=13)
            e.pack(side="right", padx=(6, 0), ipady=4)
            return e

        e_from = date_cell("من تاريخ:")
        e_to   = date_cell("إلى تاريخ:")
        # افتراضياً يوم العمل التجاري الحالي — قابل للتوسيع لفترة أوسع
        bd = current_business_day()
        e_from.insert(0, bd)
        e_to.insert(0, bd)
        tk.Label(frow, text="الصيغ المقبولة: 2026-01-10 أو 10-01-2026 أو 10/01/2026 (بالأرقام العربية أيضاً)",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(side="right", padx=10)
        b_view = self.mk_btn(frow, "🔄 عرض", lambda: fill(), ACCENT)
        b_view.pack(side="left", padx=10)
        add_tip(b_view, "إعادة عرض التقرير بالفترة المُدخلة — افتراضياً يوم العمل التجاري الحالي")
        # ترويسة المعاينة — كما ستُطبع تماماً: اسم المحل والعنوان والفترة
        head = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        head.pack(fill="x", padx=22, pady=(4, 6))
        store = get_setting("store_name") or "نظام المبيعات والمُرتجعات"
        tk.Label(head, text=store, bg=CARD, fg=DARK, font=FT).pack(pady=(12, 2))
        tk.Label(head, text="تقرير البائعين — أداء جميع البائعين", bg=CARD, fg=ACCENT,
                 font=("Segoe UI", 13, "bold")).pack(pady=2)
        lbl_sub = tk.Label(head, text="", bg=CARD, fg=GRAY,
                           font=("Segoe UI", 10))
        lbl_sub.pack(pady=(0, 12))
        # جدول المعاينة — نفس أعمدة تقرير أداء البائعين القائم (للعرض فقط)
        frm, tv = self.mk_tree(win,
            ["الصافي", "المرتجعات", "شبكة", "نقداً", "عدد العمليات", "البائع"],
            [120, 120, 115, 115, 100, 170])
        frm.pack(fill="both", expand=True, padx=22, pady=4)
        tv.tag_configure("total", background="#dbeafe")
        add_tip(tv, "التقرير للعرض والطباعة فقط — لا يتيح أي تعديل")
        # أسفل التقرير: التاريخ والوقت + اسم من يطبع
        lbl_foot = tk.Label(win, text="", bg=BG, fg=GRAY,
                            font=("Segoe UI", 10, "bold"))
        lbl_foot.pack(side="bottom", fill="x", padx=22, pady=(2, 0))
        state = {"rows": [], "tot": None, "f": bd, "t": bd}

        def fill():
            f, t = parse_date_multi(e_from.get()), parse_date_multi(e_to.get())
            bad = [lbl for lbl, v in (("من تاريخ", f), ("إلى تاريخ", t)) if v is None]
            if bad:
                messagebox.showwarning("تاريخ خاطئ",
                    "صيغة غير صحيحة لـ " + " و ".join(bad) +
                    "\nالصيغ المقبولة: 2026-01-10 أو 10-01-2026 أو 10/01/2026",
                    parent=win)
                return
            rows, tot = self._sellers_report_rows(f, t)
            state["rows"], state["tot"], state["f"], state["t"] = rows, tot, f, t
            tv.delete(*tv.get_children())
            for i, r in enumerate(rows):
                tv.insert("", "end", tags=stripe_tags(i),
                          values=(money(r["net"]), money(r["rets"]), money(r["netw"]),
                                  money(r["cash"]), r["n"], r["seller"]))
            if rows:
                # صف الإجمالي النهائي بخلفية مميزة: إجمالي المحل ومجموع كل البائعين
                tv.insert("", "end", tags=("total",),
                          values=(money(tot["net"]), money(tot["rets"]), money(tot["netw"]),
                                  money(tot["cash"]), tot["n"],
                                  "إجمالي المحل — مجموع كل البائعين"))
                lbl_sub.config(text=f"الفترة: من {f or 'البداية'} إلى {t or 'اليوم'} — "
                                     f"{len(rows)} بائعاً عمل خلالها")
                lbl_foot.config(text=f"التاريخ والوقت: "
                                     + datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                                     + f" — طبعه بواسطة: {CURRENT_USER['name']}")
            else:
                lbl_sub.config(text=f"الفترة: من {f or 'البداية'} إلى {t or 'اليوم'}")
                lbl_foot.config(text="")
                messagebox.showinfo("تنبيه", "لا توجد عمليات لأي بائع ضمن هذه الفترة",
                                    parent=win)
        fill()

        def do_thermal():
            """🖨 حرارية 80mm: ترويسة وسطر لكل بائع وفاصل وإجمالي نهائي بخط أكبر"""
            if not state["rows"]:
                messagebox.showinfo("تنبيه", "لا توجد بيانات لطباعتها ضمن هذه الفترة",
                                    parent=win)
                return
            # ★ تعديل مصرح به (الإصدار 20 — القسم ٣): مصدر اسم الطابعة مفتاح الجهاز
            if print_report_lines(get_device_printer(),
                                  build_sellers_report_lines(get_setting("store_name") or "",
                                                             state["f"], state["t"],
                                                             state["rows"], state["tot"],
                                                             CURRENT_USER["name"]),
                                  job_title="تقرير البائعين"):
                audit("طباعة تقرير البائعين",
                      f"بواسطة {CURRENT_USER['name']} — للفترة من "
                      f"{state['f'] or 'البداية'} إلى {state['t'] or 'اليوم'} (حرارية 80mm)")

        def do_a4():
            """🖨 A4 عبر PDF: ملف قياسي ثم حوار الطباعة في ويندوز (كما هو قائم)"""
            if not state["rows"]:
                messagebox.showinfo("تنبيه", "لا توجد بيانات لطباعتها ضمن هذه الفترة",
                                    parent=win)
                return
            if not PDF_LIBS_OK:
                messagebox.showerror("طباعة A4 غير متاحة", PDF_LIBS_MSG, parent=win)
                return
            try:
                folder = os.path.join(data_dir(), "pdf_reports")
                os.makedirs(folder, exist_ok=True)
                stamp = datetime.now().strftime("%H%M")
                path = os.path.join(folder,
                                    f"تقرير_البائعين_{state['f'] or 'الكل'}_{stamp}.pdf")
                build_sellers_report_pdf(path, get_setting("store_name") or "",
                                         state["f"], state["t"], state["rows"],
                                         state["tot"], CURRENT_USER["name"])
                ok, err = send_pdf_to_printer(path)
                audit("طباعة تقرير البائعين",
                      f"بواسطة {CURRENT_USER['name']} — للفترة من "
                      f"{state['f'] or 'البداية'} إلى {state['t'] or 'اليوم'} (A4 عبر PDF)")
                if ok:
                    messagebox.showinfo("تم الإرسال للطباعة",
                        "أُرسل تقرير البائعين إلى حوار الطباعة ✅\n"
                        "اختر طابعة A4 من نافذة الطباعة التي ظهرت في ويندوز.\n\n"
                        "ملف PDF محفوظ في:\n" + path, parent=win)
                else:
                    messagebox.showwarning("افتح الملف واطبعه",
                        "تعذر فتح حوار الطباعة تلقائياً — فُتح ملف PDF بدلاً منه.\n"
                        "اطبع منه مباشرة (Ctrl+P) واختر طابعة A4.\n\n" + err +
                        "\n\nالملف:\n" + path, parent=win)
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                messagebox.showerror("خطأ في طباعة A4",
                                     "حدث خطأ أثناء توليد ملف PDF:\n\n" + str(e),
                                     parent=win)

        def do_xlsx():
            """📥 تصدير Excel بنفس export_xlsx القائمة + صف إجمالي المحل"""
            if not state["rows"]:
                messagebox.showinfo("تنبيه", "لا توجد بيانات لتصديرها ضمن هذه الفترة",
                                    parent=win)
                return
            path = filedialog.asksaveasfilename(title="حفظ تقرير البائعين",
                                                defaultextension=".xlsx",
                                                initialfile=f"تقرير_البائعين_{today_str()}.xlsx",
                                                filetypes=[("ملف Excel", "*.xlsx")],
                                                parent=win)
            if not path:
                return
            headers = ["البائع", "عدد العمليات", "نقداً", "شبكة", "المرتجعات", "الصافي"]
            widths  = [22, 12, 14, 14, 14, 14]
            rows = [[r["seller"], r["n"], r["cash"], r["netw"], r["rets"], r["net"]]
                    for r in state["rows"]]
            tot = state["tot"]
            rows.append([tot["seller"], tot["n"], tot["cash"], tot["netw"],
                         tot["rets"], tot["net"]])
            export_xlsx(path, headers, rows, widths,
                        desc=f"تقرير البائعين — {len(state['rows'])} بائعاً — الفترة من "
                             f"{state['f'] or 'البداية'} إلى {state['t'] or 'اليوم'}")
            audit("تصدير تقرير البائعين",
                  f"بواسطة {CURRENT_USER['name']} — للفترة من "
                  f"{state['f'] or 'البداية'} إلى {state['t'] or 'اليوم'} (Excel)")
            messagebox.showinfo("تم", "تم تصدير تقرير البائعين إلى Excel ✅",
                                parent=win)

        b_th = self.mk_btn(bar, "🖨 طباعة حرارية 80mm", do_thermal, "#334155")
        b_th.pack(side="right", padx=6)
        add_tip(b_th, "طباعة تقرير البائعين على الطابعة الحرارية المختارة في إعدادات الطباعة (نظام ESC/POS الموجود)")
        b_a4 = self.mk_btn(bar, "🖨 طباعة A4 (PDF)", do_a4, "#1d4ed8")
        b_a4.pack(side="right", padx=6)
        add_tip(b_a4, "يُنشأ ملف PDF قياسي ويُفتح حوار الطباعة في ويندوز — اختر طابعة A4 منه")
        b_xl = self.mk_btn(bar, "📥 تصدير Excel", do_xlsx, "#0d9488")
        b_xl.pack(side="right", padx=6)
        add_tip(b_xl, "تصدير جدول البائعين المعروض إلى ملف Excel حقيقي (نفس نظام التصدير القائم)")
        b_close = self.mk_btn(bar, "❌ إغلاق", win.destroy, "#475569")
        b_close.pack(side="right", padx=6)
        add_tip(b_close, "إغلاق نافذة المعاينة دون طباعة")
        place_window(win, 900, 640, 760, 540, can_resize=True)

    # ═══════════════════════════════════════════════════════
    # ★★★ إضافة (إصدار 10 — نظام التحديث التلقائي الصامت) ★★★
    # شريط الإشعار الأصفر + نافذة التحديث للمدير — لا شيء تقني يظهر
    # للمستخدمين: البائع يرى الشريط و«راجع المدير» فقط
    # ═══════════════════════════════════════════════════════

    def refresh_update_bar(self):
        """(2) شريط الإشعار الأصفر الرفيع أعلى الشريط الإحصائي — الوحيد الذي
        يراه المستخدمون من نظام التحديث: بلا أي كلمة تقنية إطلاقاً — البائع
        يرى «راجع المدير» فقط، والمدير يرى زر «⬇️ تحديث الآن» وزر ✕ لإخفاء
        الشريط لهذه الجلسة فقط
        ★ إصلاح (11 — البندان ب+ج): (ب) زر «⬇️ التحديث» الجانبي يُدار من
        هنا أيضاً — مخفي بلا تحديث مؤكد وظهره الوحيد نتيجة مقارنة ناجحة
        (ج) نص الشريط يعرض رقم الإصدار الجديد: «🔔 يتوفر تحديث جديد —
        الإصدار [رقم]»، فإن غاب الرقم اكتمل النص بدونه"""
        # (ب) زر الشريط الجانبي أولاً: يظهر للمدير فقط عند تحديث مؤكد فعلياً —
        # وإلا يُخفى صراحة (هذه هي النقطة الوحيدة التي تُظهره بعد الإقلاع)
        b_side = self.nav_buttons.get("update")
        if b_side is not None:
            try:
                if (getattr(self, "update_available_version", None)
                        and self.role == "مدير" and self.has_permission("manager")):
                    try:
                        b_side.pack_info()      # محزوم أصلاً؟ لا تعد حزمه (يبقى موضعه)
                    except Exception:
                        b_side.pack(fill="x", padx=10, pady=3)
                else:
                    b_side.pack_forget()
            except Exception:
                pass
        if getattr(self, "update_bar", None) is not None:
            try:
                self.update_bar.destroy()
            except Exception:
                pass
            self.update_bar = None
        ver = getattr(self, "update_available_version", None)
        if not ver:
            return            # لا تحديث معروف
        # ★ إصلاح (1): الشريط الذي أُخفي بـ✕ لا يعود في نفس الجلسة إلا إذا
        # اكتشف الفحص رقماً أحدث فعلياً من رقم الشريط المخفي — رقم أحدث
        # واحد يعيده ويجدّد حالة الإخفاء للجلسة من جديد
        if getattr(self, "update_bar_dismissed", False):
            dver = getattr(self, "update_bar_dismissed_version", None)
            if dver and update_is_newer(ver, dver):
                self.update_bar_dismissed = False
                self.update_bar_dismissed_version = None
            else:
                return        # نفس الرقم المخفي أو أقدم منه — يبقى مخفياً
        upd_bg, upd_fg = "#fef9c3", "#854d0e"
        bar = tk.Frame(self.container, bg=upd_bg, highlightbackground="#fde047",
                       highlightthickness=1)
        try:                  # فوق الشريط الإحصائي مباشرة
            bar.pack(fill="x", padx=25, pady=(10, 0), before=self.stats_bar_frame)
        except Exception:
            bar.pack(fill="x", padx=25, pady=(10, 0))
        # (ج) النص مع رقم الإصدار الجديد — وبدونه إن غاب
        tk.Label(bar, text=(f"🔔 يتوفر تحديث جديد — الإصدار {ver}" if ver
                            else "🔔 يتوفر تحديث جديد"),
                 bg=upd_bg, fg=upd_fg,
                 font=("Segoe UI", 10, "bold")).pack(side="right", padx=(4, 12), pady=4)
        if self.role == "مدير":
            b_now = tk.Button(bar, text="⬇️ تحديث الآن", command=self.update_now_dialog,
                              bg=ORANGE, fg="white", activebackground=ORANGE,
                              activeforeground="white", font=("Segoe UI", 9, "bold"),
                              bd=0, cursor="hand2", padx=12, pady=2, highlightthickness=0)
            b_now.pack(side="left", padx=(12, 6), pady=3)
            add_tip(b_now, "عرض تفاصيل التحديث والموافقة الصريحة على تثبيته — إعادة التشغيل تلقائية بعد التثبيت")
            # ★ إضافة (إصلاح 3 — البند أ): زر «فحص التحديثات الآن» داخل
            # الشريط الأصفر بجانب «تحديث الآن» — فحص فوري بنص الزر «جارٍ
            # الفحص...» أثناءه ثم رسالة نتيجة عربية دائماً
            b_chk = tk.Button(bar, text="🔄 فحص التحديثات الآن",
                              command=lambda: self.update_check_manual(b_chk),
                              bg="#0369a1", fg="white", activebackground="#0369a1",
                              activeforeground="white", font=("Segoe UI", 9, "bold"),
                              bd=0, cursor="hand2", padx=10, pady=2, highlightthickness=0)
            b_chk.pack(side="left", padx=(0, 6), pady=3)
            add_tip(b_chk, "فحص فوري جديد الآن برسالة نتيجة — يظهر الشريط فور توفر إصدار أحدث")
            b_x = tk.Button(bar, text="✕", command=self.dismiss_update_bar,
                            bg=upd_bg, fg=upd_fg, activebackground="#fde047",
                            activeforeground=upd_fg, font=("Segoe UI", 8, "bold"),
                            bd=0, relief="flat", cursor="hand2", padx=6, pady=1,
                            highlightthickness=0, takefocus=0)
            b_x.pack(side="left", pady=3)
            add_tip(b_x, "إخفاء شريط التحديث لهذه الجلسة فقط")
        else:
            tk.Label(bar, text="راجع المدير", bg=upd_bg, fg="#a16207",
                     font=("Segoe UI", 9, "bold")).pack(side="left", padx=(12, 4))
        self.update_bar = bar

    def dismiss_update_bar(self):
        """(2) زر ✕: إخفاء شريط الإشعار لهذه الجلسة فقط (يعود مع تشغيل جديد)"""
        self.update_bar_dismissed = True
        # ★ إضافة (إصلاح 1): تذكر رقم إصدار الشريط المخفي — لا يعود الشريط
        # في نفس الجلسة إلا إذا اكتشف الفحص رقماً أحدث منه فعلياً
        self.update_bar_dismissed_version = getattr(
            self, "update_available_version", None)
        if getattr(self, "update_bar", None) is not None:
            try:
                self.update_bar.destroy()
            except Exception:
                pass
            self.update_bar = None

    def update_now_dialog(self):
        """(3) ★ تعديل مصرح به (الإصدار 15 — الجزء الثاني): نافذة الموافقة
        الصريحة على التحديث — للمدير فقط: تعرض «الإصدار الحالي [VERSION] ←
        الجديد [رقم]» وزر «📄 ما الجديد؟» (ملاحظات الإصدار إن وُجدت) وسطر
        الطمأنة أن التحديث لا يلمس البيانات والتقارير، ولا يبدأ التنزيل
        والتثبيت إلا بضغط «✅ نعم، ثبّت التحديث الآن» الصريح — و«❌ لا،
        لاحقاً» أو إغلاق النافذة لا يفعلان شيئاً ويبقى شريط الإشعار للموافقة
        لاحقاً. وإن كانت السلة فيها أصناف غير محفوظة يُعطَّل زر التثبيت حتى
        تأكيد تحذير فقدانها (نفس منطق تبديل المستخدم). زرا «🔄 فحص
        التحديثات الآن» و«ℹ️ عن البرنامج» كما كانا تماماً، وعند الموافقة
        تُنفّذ خطوات التثبيت الصارمة بالترتيب مع إلغاء آمن عند أي فشل"""
        if not self.require_admin("manager"):
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("تحديث البرنامج")
        win.configure(bg=CARD)
        win.transient(self)
        try:
            win.grab_set()
        except Exception:
            pass
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول — القاعدة الذهبية): شريط
        # أزرار الموافقة السفلي يُحزم أولاً side="bottom" فلا يُقص أبداً
        fr_btns = tk.Frame(win, bg=CARD)
        fr_btns.pack(side="bottom", fill="x", pady=(8, 14))
        # ★ إضافة (الإصدار 15 — الجزء الثاني): تحذير السلة داخل نافذة
        # الموافقة — يُحزم side="bottom" فوق شريط الأزرار مباشرة
        cart_n = len(getattr(self, "cart", None) or [])
        lbl_cart = tk.Label(win, text="", bg=CARD, fg=RED,
                            font=("Segoe UI", 10, "bold"),
                            wraplength=430, justify="center")
        if cart_n:
            lbl_cart.config(text=f"⚠ السلة فيها {cart_n} أصناف غير محفوظة — "
                                 "ستُفقد بعد التحديث وإعادة التشغيل")
            lbl_cart.pack(side="bottom", fill="x", padx=14, pady=(0, 4))
        # الرأس ثم المحتوى — كل شيء فوق الشريط السفلي الثابت
        tk.Label(win, text="⬇️", bg=CARD, fg=DARK, font=("Segoe UI", 26)).pack(pady=(14, 0))
        lbl = tk.Label(win, text="", bg=CARD, fg=DARK, font=FT,
                       wraplength=430, justify="center")
        lbl.pack(pady=(4, 2), fill="x")
        # ★ إضافة (الإصدار 15 — الجزء الثاني): سطر الإصدارين — الحالي ← الجديد
        lbl_vers = tk.Label(win, text="", bg=CARD, fg=DARK,
                            font=("Segoe UI", 11, "bold"),
                            wraplength=430, justify="center")
        lbl_vers.pack(pady=(0, 4), fill="x")
        # ★ إضافة (الإصدار 15 — الجزء الثاني): زر «📄 ما الجديد؟» — ملاحظات
        # الإصدار من ملف الملاحظات إن وُجد (جلب نص فقط بلا أي تنزيل للبرنامج)
        b_news = self.mk_btn(win, "📄 ما الجديد؟",
                             lambda: self.update_show_changelog(win, b_news), "#0369a1")
        b_news.pack(ipadx=8)
        add_tip(b_news, "عرض ملاحظات الإصدار الجديدة إن نُشرت — بلا أي تنزيل للبرنامج")
        # ★ إضافة (الإصدار 15 — الجزء الثاني): سطر الطمأنة — لا مساس بالبيانات
        # وسيلزم تسجيل دخول من جديد بعد إعادة التشغيل التلقائية
        tk.Label(win, text="التحديث لا يلمس بياناتك والتقارير — وسيلزم تسجيل "
                           "دخول من جديد بعد إعادة التشغيل",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 10),
                 wraplength=430, justify="center").pack(pady=(6, 2), fill="x")
        b_recheck = self.mk_btn(win, "🔄 فحص التحديثات الآن",
                                lambda: self.update_check_now(win, lbl, b_install, b_close, lbl_vers), "#0369a1")
        b_recheck.pack(pady=(8, 0))
        add_tip(b_recheck, "إعادة فحص التحديثات الآن بغض النظر عن الفحص التلقائي الصامت")
        # ★ إضافة (نافذة «عن البرنامج»): زر داخل نافذة التحديث بجانب زر الفحص —
        # يفتح نبذة مختصرة عن البرنامج (قراءة فقط من المتغيرات والجداول
        # القائمة بلا أي فحص شبكي عند الفتح)
        b_about = self.mk_btn(win, "ℹ️ عن البرنامج", self.about_dialog, "#475569")
        b_about.pack(pady=(4, 0))
        add_tip(b_about, "نبذة عن البرنامج: الإصدار وآخر تحديث ومجلد البيانات — بلا أي اتصال")

        # ---------- أزرار الموافقة الصريحة (الشريط السفلي المحزوم أولاً) ----------
        def _install():
            """بوابة الموافقة الصريحة — لا تنزيل ولا تثبيت إلا من هنا"""
            v = getattr(self, "update_available_version", None)
            if not v:
                return          # لا تثبيت بلا إصدار مؤكد فعلياً
            cart = getattr(self, "cart", None) or []
            extra = (f" — مع فقدان سلة فيها {len(cart)} أصناف" if cart else "")
            audit("موافقة على التحديث",
                  f"من {VERSION} إلى {v} — بواسطة {self.user_name}{extra}")
            self.update_install(win, b_install, lbl)

        def _later():
            """«❌ لا، لاحقاً» — لا يحدث شيء: الشريط يبقى للموافقة لاحقاً"""
            audit("رفض التحديث",
                  f"الإصدار {getattr(self, 'update_available_version', None) or '—'}"
                  f" — بواسطة {self.user_name}: طلب التأجيل، الشريط يبقى للموافقة لاحقاً")
            win.destroy()

        b_install = self.mk_btn(fr_btns, "✅ نعم، ثبّت التحديث الآن", _install, GREEN)
        b_install.pack(side="right", padx=6)
        add_tip(b_install, "الموافقة الصريحة: تنزيل الإصدار الجديد وتثبيته ثم إعادة تشغيل "
                           "تلقائية — لا يلمس البيانات والتقارير نهائياً")
        b_close = self.mk_btn(fr_btns, "❌ لا، لاحقاً", _later, "#475569")
        b_close.pack(side="right", padx=6)
        add_tip(b_close, "لا يحدث شيء الآن — يبقى شريط الإشعار للموافقة لاحقاً")

        # ★ إضافة (الإصدار 15 — الجزء الثاني): السلة فيها أصناف غير محفوظة —
        # زر التثبيت معطل حتى تأكيد التحذير بنفس منطق تبديل المستخدم
        if cart_n:
            b_install.config(state="disabled",
                             text=f"⛔ أكّد المتابعة أولاً (السلة فيها {cart_n} أصناف)")

            def _confirm_cart():
                if messagebox.askyesno("تحديث وسلة غير محفوظة",
                        f"السلة فيها {cart_n} أصناف — ستُفقد. متابعة؟", parent=win):
                    b_install.config(state="normal", text="✅ نعم، ثبّت التحديث الآن")
                    lbl_cart.config(text="تم تأكيد فقدان السلة — يمكن التثبيت الآن",
                                    fg="#a16207")
                # «لا» = لا شيء يحدث — يبقى زر التثبيت معطلاً

            b_cart = self.mk_btn(win, "⚠️ متابعة رغم فقدان السلة؟", _confirm_cart, ORANGE)
            b_cart.pack(ipadx=8, pady=(4, 2))
            add_tip(b_cart, "تأكيد صريح بفقدان أصناف السلة غير المحفوظة قبل تمكين زر "
                           "التثبيت — نفس منطق تبديل المستخدم")

        # الحالة الابتدائية: إصدار معروف من الفحص الصامت، أو فحص فوري عند الفتح
        ver = getattr(self, "update_available_version", None)
        if ver:
            lbl.config(text=f"يتوفر تحديث جديد (الإصدار {ver})", fg=ORANGE)
            lbl_vers.config(text=f"الإصدار الحالي {VERSION} ← الجديد {ver}")
        else:
            # ★ إصلاح (11 — البند د): بلا إصدار مؤكد يبدأ الفحص فوراً وزر
            # التثبيت مخفي حتى تثبت نتيجة المقارنة وجود إصدار أحدث فعلياً
            self.update_check_now(win, lbl, b_install, b_close, lbl_vers)
        # ★ إضافة (الإصدار 15 — الجزء الأول): الحجم + الفحص الذاتي + التمركز
        place_window(win, 520, 560)

    def update_check_now(self, win, lbl, install_btn=None, anchor_btn=None, vers_lbl=None):
        """(4) زر «🔄 فحص التحديثات الآن»: فحص فوري بنفس مهلة الفحص الصامت —
        يحدّث حالة نافذة التحديث وشريط الإشعار الأصفر معاً وبهدوء عند الفشل
        ★ تعديل مصرح به (الإصدار 15 — الجزء الثاني): معامل اختياري vers_lbl
        وحده — سطر «الإصدار الحالي ← الجديد» في نافذة الموافقة يُحدَّث مع كل
        نتيجة (الافتراضي None = كما كان حرفياً لأي نداء آخر)
        ★ إصلاح (11 — البند د): عند عدم وجود إصدار أحدث فعلياً تظهر رسالة
        «✅ أنت على أحدث إصدار — الإصدار الحالي [VERSION]» ولا يظهر أي زر
        تثبيت في هذه الحالة — فزر «تثبيت الآن» يُخفى فور بدء الفحص ولا
        يُعاد إظهاره إلا من داخل نتيجة مقارنة ناجحة تثبت إصداراً أحدث"""
        def _hide_install():
            if install_btn is not None:
                try:
                    install_btn.pack_forget()
                except Exception:
                    pass
        def _show_install():
            if install_btn is not None:
                try:
                    install_btn.pack(side="right", padx=6, before=anchor_btn)
                except Exception:
                    install_btn.pack(side="right", padx=6)
        try:
            lbl.config(text="جارٍ الفحص...", fg=GRAY)
        except Exception:
            pass
        _hide_install()      # مخفي أثناء الفحص وفي كل نتيجة ليست «إصداراً أحدث»
        box = update_fetch_async(UPDATE_VERSION_URL, UPDATE_CHECK_TIMEOUT)
        def _poll():
            if box["state"] != "done":
                try:
                    win.after(250, _poll)
                except Exception:
                    pass
                return
            remote = update_parse_version(box["data"] or b"")
            try:
                if remote is None:
                    lbl.config(text="تعذر فحص التحديثات الآن", fg=RED)
                    if vers_lbl is not None:
                        vers_lbl.config(text="")
                    return
                if not update_is_newer(remote, VERSION):
                    self.update_available_version = None  # لا تحديث مؤكد الآن
                    self.refresh_update_bar()             # إخفاء الشريط والزر إن بقيا من تأكيد سابق
                    lbl.config(text=f"✅ أنت على أحدث إصدار — الإصدار الحالي {VERSION}",
                               fg=GREEN)
                    if vers_lbl is not None:
                        vers_lbl.config(text="")
                    return
                self.update_available_version = remote
                audit("فحص تحديث يدوي", f"يتوفر إصدار جديد: {remote}")
                lbl.config(text=f"يتوفر تحديث جديد (الإصدار {remote})", fg=ORANGE)
                if vers_lbl is not None:
                    vers_lbl.config(text=f"الإصدار الحالي {VERSION} ← الجديد {remote}")
                _show_install()
                self.refresh_update_bar()
            except Exception:
                pass
        try:
            win.after(250, _poll)
        except Exception:
            pass

    def update_show_changelog(self, parent, btn=None):
        """★ إضافة (الإصدار 15 — الجزء الثاني): زر «📄 ما الجديد؟» — يجلب
        ملاحظات الإصدار الجديد من ملف الملاحظات (جلب نص فقط بلا أي تنزيل
        لملف البرنامج أبداً) ويعرض قسم هذا الإصدار في نافذة قراءة أنيقة
        بأسلوب البرنامج؛ وعند غياب الملف أو غياب القسم رسالة لطيفة، وأي فشل
        صمت مهذب — زر الطلب يعرض «جارٍ الجلب...» معطلاً ثم يعود"""
        ver = getattr(self, "update_available_version", None) or VERSION
        old_text = None
        if btn is not None:
            try:
                old_text = btn.cget("text")
                btn.config(text="⏳ جارٍ جلب الملاحظات...", state="disabled",
                           cursor="watch")
            except Exception:
                btn = None
        box = update_fetch_async(UPDATE_CHANGELOG_URL, UPDATE_CHECK_TIMEOUT)

        def _restore():
            """إعادة زر الطلب لنصه وحالته (بأقصى جهد)"""
            if btn is not None and old_text:
                try:
                    btn.config(text=old_text, state="normal", cursor="hand2")
                except Exception:
                    pass

        def _poll():
            if box["state"] != "done":
                try:
                    self.after(250, _poll)
                except Exception:
                    _restore()
                return
            _restore()
            try:
                text = update_changelog_section(box["data"], ver)
                if not text:
                    messagebox.showinfo("ما الجديد؟",
                        "لا توجد ملاحظات منشورة لهذا الإصدار بعد.\n"
                        "يمكنك سؤال المالك عن تفاصيل التحديث.", parent=parent)
                    return
                win = self.register_window(tk.Toplevel(self))
                win.title(f"📄 ما الجديد؟ — الإصدار {ver}")
                win.configure(bg=CARD)
                # القاعدة الذهبية: زر الإغلاق أسفل أولاً ثم المحتوى يتمدد
                fr_btns = tk.Frame(win, bg=CARD)
                fr_btns.pack(side="bottom", fill="x", pady=(6, 12))
                b_close = self.mk_btn(fr_btns, "إغلاق", win.destroy, "#475569")
                b_close.pack()
                add_tip(b_close, "إغلاق نافذة ملاحظات التحديث")
                txt = tk.Text(win, font=("Segoe UI", 11), bg="white", fg=DARK,
                              wrap="word", relief="flat", padx=14, pady=12,
                              height=14, width=52)
                vsb = ttk.Scrollbar(win, orient="vertical", command=txt.yview)
                txt.configure(yscrollcommand=vsb.set)
                vsb.pack(side="left", fill="y")
                txt.pack(fill="both", expand=True, padx=(10, 16), pady=(12, 0))
                txt.insert("1.0", text)
                txt.tag_add("all", "1.0", "end")
                txt.tag_configure("all", justify="right")   # نص عربي من اليمين
                txt.configure(state="disabled")             # قراءة فقط
                place_window(win, 560, 460)
            except Exception:
                pass
        try:
            self.after(250, _poll)
        except Exception:
            _restore()

    def update_check_manual(self, btn=None):
        """★ إضافة (إصلاح 3 — البندان أ+ب): «🔄 فحص التحديثات الآن» من
        الشريط الأصفر أو من قائمة المستخدم — فحص يدوي فوري برسالة نتيجة
        عربية دائماً: «🔔 يتوفر تحديث جديد — الإصدار [رقم]» مع ظهور الشريط،
        أو «✅ أنت على أحدث إصدار — الإصدار الحالي [VERSION]»، أو «⚠ تعذر
        الاتصال — تحقق من الإنترنت وحاول لاحقاً» عند فشل الاتصال — ونص زر
        الفحص «جارٍ الفحص...» أثناء الفحص ثم يعود لسابقه، وكل فحص يدوي
        ونتيجته في سجل التدقيق"""
        if getattr(self, "_manual_check_busy", False):
            return                      # فحص جارٍ فعلاً — لا ضغط مزدوج
        self._manual_check_busy = True
        old_text = None
        if btn is not None:             # نص الزر «جارٍ الفحص...» ثم يعود
            try:
                old_text = btn.cget("text")
                btn.config(text="جارٍ الفحص...", state="disabled", cursor="watch")
            except Exception:
                btn = None

        def _restore():
            """إعادة زر الفحص لنصه وحالته (بأقصى جهد إن كان الشريط أعيد
            بناؤه أثناء الفحص) ثم السماح بفحص جديد"""
            if btn is not None and old_text:
                try:
                    btn.config(text=old_text, state="normal", cursor="hand2")
                except Exception:
                    pass
            self._manual_check_busy = False

        box = update_fetch_async(UPDATE_VERSION_URL, UPDATE_CHECK_TIMEOUT)

        def _poll():
            if box["state"] != "done":
                try:
                    self.after(250, _poll)
                except Exception:
                    _restore()
                return
            remote = update_parse_version(box["data"] or b"")
            _restore()                  # الزر يعود لسابقه قبل رسالة النتيجة
            if remote is None:          # فشل الاتصال
                audit("فحص تحديث يدوي", "تعذر الاتصال — فحص فاشل")
                messagebox.showwarning("فحص التحديثات",
                    "⚠ تعذر الاتصال — تحقق من الإنترنت وحاول لاحقاً", parent=self)
                return
            if not update_is_newer(remote, VERSION):
                self.update_available_version = None   # لا تحديث مؤكد الآن
                self.update_last_check_result = "latest"
                self.refresh_update_bar()   # إخفاء الشريط والزر إن بقيا من تأكيد سابق
                audit("فحص تحديث يدوي", f"أحدث إصدار ({VERSION})")
                messagebox.showinfo("فحص التحديثات",
                    f"✅ أنت على أحدث إصدار — الإصدار الحالي {VERSION}", parent=self)
                return
            self.update_available_version = remote     # تحديث مؤكد → الشريط فوراً
            self.update_last_check_result = "available"
            self.refresh_update_bar()
            audit("فحص تحديث يدوي", f"يتوفر إصدار جديد: {remote}")
            messagebox.showinfo("فحص التحديثات",
                f"🔔 يتوفر تحديث جديد — الإصدار {remote}", parent=self)

        try:
            self.after(250, _poll)
        except Exception:
            _restore()

    def _update_periodic_check(self):
        """★ إضافة (إصلاح 1 — الفحص الدوري): كل 30 دقيقة فحص صامت بنفس دالة
        الفحص القائمة — عند اكتشاف إصدار أحدث يظهر الشريط الأصفر فوراً دون
        إعادة تشغيل ولكل الأدوار، وبلا تحديث صمت تام (لا رسائل ولا أي أثر
        إطلاقاً)، ثم يُعيد جدولة نفسه ما دام البرنامج مفتوحاً"""
        try:
            update_check_silent(self, quiet=True)
        except Exception:
            pass
        try:
            self._update_periodic_after_id = self.after(
                30 * 60 * 1000, self._update_periodic_check)
        except Exception:
            pass          # البرنامج أُغلق — يتوقف المؤقت بهدوء

    def update_install(self, win, btn, lbl):
        """(3) خطوات التثبيت الصارمة بالترتيب: (أ) تنزيل إلى ملف مؤقت
        main_new.tmp وليس فوق القديم ← (ب) التحقق من السلامة: حجم أكبر من
        10 كيلوبايت + يحتوي VERSION + يبدأ بتعليق أو import ← (ج) حفظ
        النسخة القديمة في أرشيف الإصدارات versions_archive باسم منظم
        main_v[الإصدار]_[التاريخ].py — سجل تاريخي كامل لا يُحذف منه شيء
        (★ التعديل المصرح به الوحيد في خطوات التثبيت) ← (د)
        الاستبدال باسم مكتشف ديناميكياً من __file__ ← (هـ) حفظ
        last_update_date + سجل التدقيق ← (و) ★ تعديل مصرح به (الإصدار 15 —
        الجزء الثاني): رسالة النجاح بإعادة التشغيل التلقائية الآمنة بدل زر
        «إغلاق الآن» اليدوي القديم — ولو البرنامج EXE فالتحديث يدوي — وأي
        فشل في أي خطوة = إلغاء آمن برسالة «لم يتغير شيء»"""
        # نسخة EXE لا تُحدَّث تلقائياً: تنبيه صريح دون أي تنزيل
        if getattr(sys, "frozen", False):
            messagebox.showinfo("تحديث EXE",
                "التحديث التلقائي لنسخة Python — حدث EXE يدوياً", parent=win)
            return
        # اسم ملف البرنامج يُكتشف ديناميكياً من __file__ (وليس اسماً ثابتاً)
        try:
            target = os.path.abspath(__file__)
        except Exception:
            target = None
        if not target or not os.path.isfile(target):
            messagebox.showerror("فشل التحديث",
                "تعذر تحديد موقع ملف البرنامج — لم يتغير شيء، حاول لاحقاً", parent=win)
            return
        tmp = os.path.join(os.path.dirname(target), "main_new.tmp")   # (أ) بجانب البرنامج
        btn.config(text="⬇️ جارٍ التنزيل...", state="disabled", cursor="watch")
        try:
            lbl.config(text="جارٍ تنزيل التحديث...", fg=GRAY)
        except Exception:
            pass
        box = update_fetch_async(UPDATE_FILE_URL, UPDATE_DOWNLOAD_TIMEOUT)

        def _fail(msg):
            """إلغاء آمن: حذف الملف المؤقت إن وُجد وإعادة الزر — لم يتغير شيء
            (بأقصى جهد إن كانت النافذة أُغلقت أثناء التنزيل)"""
            try:
                os.remove(tmp)
            except Exception:
                pass
            try:
                btn.config(text="✅ نعم، ثبّت التحديث الآن", state="normal", cursor="hand2")
                lbl.config(text="يتوفر تحديث جديد (الإصدار "
                          + str(getattr(self, "update_available_version", "")) + ")",
                          fg=ORANGE)
            except Exception:
                pass
            try:
                messagebox.showerror("فشل التحديث", msg, parent=win)
            except Exception:
                pass

        def _poll():
            if box["state"] != "done":
                try:
                    win.after(250, _poll)
                except Exception:
                    pass
                return
            # (أ) التنزيل إلى الملف المؤقت — وليس فوق الملف القديم
            data = box["data"]
            if data is None:
                _fail("فشل التنزيل — لم يتغير شيء، حاول لاحقاً"); return
            try:
                with open(tmp, "wb") as f:
                    f.write(data)
            except Exception:
                _fail("فشل حفظ ملف التحديث — لم يتغير شيء، حاول لاحقاً"); return
            # (ب) التحقق من سلامة الملف المؤقت قبل أي مساس بالملف القديم:
            # حجم > 10 كيلوبايت + يحتوي VERSION + يبدأ بتعليق أو import
            ok = False
            try:
                with open(tmp, "rb") as f:
                    blob = f.read()
                first = next((ln.strip() for ln in blob.splitlines() if ln.strip()), b"")
                ok = (len(blob) > 10 * 1024 and b"VERSION" in blob
                      and (first.startswith(b"#") or first.startswith(b"import")
                           or first.startswith(b"from") or first.startswith(b'"""')))
            except Exception:
                ok = False
            if not ok:
                _fail("فشل التنزيل — لم يتغير شيء، حاول لاحقاً"); return
            # (ج) ★ تعديل مصرح به (أرشيف الإصدارات): حفظ النسخة القديمة في
            # مجلد أرشيف الإصدارات versions_archive باسم منظم
            # main_v[الإصدار]_[التاريخ].py بدل نسخ main_backup_* بجوار
            # البرنامج — الأرشيف سجل تاريخي كامل لا يُحذف منه أي ملف
            # تلقائياً أبداً (بدل قاعدة آخر 3)، وفشل الحفظ يلغي التحديث
            # بأمان كما كان تماماً، وبقية الخطوات (أ/ب/د/هـ/و) كما هي حرفياً
            saved_archive = archive_save_current()
            if saved_archive is None:
                _fail("تعذر إنشاء نسخة الأمان — لم يتغير شيء، حاول لاحقاً"); return
            audit("أرشيف الإصدارات",
                  f"حُفظ الإصدار {VERSION} في الأرشيف قبل التحديث إلى "
                  + str(getattr(self, "update_available_version", "إصدار جديد")))
            # (د) الاستبدال — بعد نجاح كل الفحوص أعلاه فقط
            try:
                os.replace(tmp, target)
            except Exception:
                _fail("فشل استبدال ملف البرنامج — لم يتغير شيء، حاول لاحقاً"); return
            # (هـ) حفظ last_update_date في الإعدادات + سجل التدقيق (بأقصى جهد)
            try:
                set_setting("last_update_date",
                            datetime.now().strftime("%Y-%m-%d %H:%M"))
                audit("تحديث البرنامج",
                      f"من {VERSION} إلى {getattr(self, 'update_available_version', 'إصدار جديد')}")
            except Exception:
                pass
            # ★ إضافة (الإصدار 16 — القسم 2-6): تحديث بصمة الكود تلقائياً بعد
            # الاستبدال وقبل إعادة التشغيل — إعادة حساب sha256 للملف الجديد
            # وحفظه في الإعدادات كي لا تظهر شاشة التحذير الحمراء بعد كل تحديث
            # عبر النظام (الخطوة الجديدة غير المساسة سابقاً — بأقصى جهد)
            try:
                _new_hash16 = code_file_hash(target)
                if _new_hash16:
                    set_setting(CODE_HASH_KEY, _new_hash16)
            except Exception:
                pass
            # (و) ★ تعديل مصرح به (الإصدار 15 — الجزء الثاني): رسالة النجاح
            # بإعادة التشغيل التلقائية الآمنة بدل زر «إغلاق الآن» اليدوي —
            # يُفقد تسجيل الدخول فقط، ولا تُمس البيانات والتقارير إطلاقاً
            new_ver = str(getattr(self, "update_available_version", "إصدار جديد"))
            try:
                for w in win.winfo_children():
                    w.destroy()
                tk.Label(win, text=f"تم التحديث إلى {new_ver} بنجاح ✅", bg=CARD,
                         fg=GREEN, font=FT, wraplength=420,
                         justify="center").pack(pady=(36, 6))
                tk.Label(win, text="جارٍ إعادة تشغيل البرنامج تلقائياً...\n"
                                  "(سيُطلب تسجيل الدخول من جديد)",
                         bg=CARD, fg=DARK, font=F,
                         justify="center").pack(pady=(0, 14))
            except Exception:
                pass
            try:
                messagebox.showinfo("تم التحديث",
                    f"✅ تم التحديث إلى {new_ver} بنجاح!\n"
                    "جارٍ إعادة تشغيل البرنامج تلقائياً...\n"
                    "(سيُطلب تسجيل الدخول من جديد)", parent=win)
            except Exception:
                pass
            # إعادة التشغيل التلقائية الآمنة — إطلاق الجديدة ثم خروج نظيف
            self._restart_after_update(new_ver)
        try:
            win.after(250, _poll)
        except Exception:
            pass

    def _restart_after_update(self, new_ver):
        """★ إضافة (الإصدار 15 — الجزء الثاني): إعادة التشغيل التلقائية
        الآمنة بعد نجاح التثبيت — الترتيب الصارم: (أ) اتصالات القاعدة قصيرة
        أصلاً فلا يوجد اتصال مفتوح يعلّق الخروج (ب) إطلاق العملية الجديدة
        أولاً كي لا تظهر لحظة «لا برنامج مفتوح» ولا تتضارب النسخ (ج) الخروج
        النظيف من القديمة بنفس مسار exit_app القائم حرفياً — النسخة
        الاحتياطية والتدقيق يأخذان حقهما ولا نتجاوزهما أبداً. لا تُمس القاعدة
        ولا النسخ الاحتياطية ولا الإعدادات ولا سجل التدقيق ولا الأرشيف
        إطلاقاً — يُفقد تسجيل الدخول فقط (عودة لشاشة الدخول). الحمايات:
        فشل إطلاق العملية الجديدة = رسالة «أعد فتح البرنامج يدوياً هذه المرة
        فقط» وخروج عادي بلا انهيار، ونسخة EXE تبقى على الرسالة اليدوية"""
        audit("إعادة تشغيل تلقائية بعد التحديث", f"إلى {new_ver}")
        # نسخة EXE لا تُعاد تشغيلها تلقائياً — رسالة يدوية وخروج عادي
        if getattr(sys, "frozen", False):
            messagebox.showinfo("أعد التشغيل يدوياً",
                "تم التحديث بنجاح — أغلق البرنامج وافتحه من جديد لتفعيل "
                "الإصدار الجديد.")
            self.exit_app()
            return
        try:
            # إطلاق العملية الجديدة أولاً — قبل الخروج النظيف من القديمة
            subprocess.Popen([sys.executable, os.path.abspath(__file__)])
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showwarning("تعذر التشغيل التلقائي",
                "أعد فتح البرنامج يدوياً هذه المرة فقط.")
            self.exit_app()      # خروج عادي نظيف — لا انهيار أبداً
            return
        self.exit_app()          # الخروج النظيف — النسخة الاحتياطية كاملة كما هي

    # ═══════════════════════════════════════════════════════════
    # ★★★ إضافات (الإصدار 19): خطاف بدء التشغيل + الشريط الأصفر ★★★
    # ═══════════════════════════════════════════════════════════
    def _print_setup_startup(self):
        """★ إضافة (الإصدار 19 — البندان أ+ب المصرح بهما): خطاف بدء التشغيل —
        فحص مكتبات الطباعة مرة واحدة صمتاً (النتيجة بالذاكرة) + كشف الطابعة
        تلقائياً + الشريط الأصفر الرفيع للمدير فقط إن كانت المكتبات ناقصة.
        السيناريو المستهدف (الربط بتوزيع التحديثات — البند 5): جهاز جديد →
        تحديث تلقائي → أول فتح → هذا الخطاف يجعل الطباعة جاهزة على ذلك
        الجهاز بلا أي خطوة يدوية إطلاقاً
        ★ تعديل مصرح به (الإصدار 20 — الاستثناء أ): كشف الطابعة التلقائي عند
        بدء التشغيل أُلغي — اختيار الطابعة صار صريحاً لكل جهاز على مفتاح
        printer_device_<اسم الجهاز> يختاره الأدمن/المدير من «⚙️ إعدادات
        الطباعة»، ولا يُملأ أي إعداد تلقائياً ولا يُستبدل بالطابعة الافتراضية:
        بدون اختيار صريح لا تحدث طباعة صامتة خاطئة أبداً، وعند أول محاولة
        طباعة تظهر رسالة «لم يتم اختيار طابعة لهذا الجهاز بعد…» للمستخدم"""
        global PRINT_APP
        PRINT_APP = self            # مرجع الوحدة لواجهات الطباعة الجديدة
        try:
            check_print_libs()      # صامت — تخزين النتيجة بالذاكرة فقط
        except Exception:
            pass
        # ★ تعديل مصرح به (الإصدار 20 — الاستثناء أ): استدعاء الكشف التلقائي
        # auto_detect_printer() هنا أُلغي — كان يملأ الإعداد تلقائياً (حرارية
        # مطابقة أو الطابعة الافتراضية في ويندوز) وهذا يخالف قاعدة الإصدار
        # 20 الصريحة: ممنوع الطابعة الافتراضية كبديل تلقائي، وبدون اختيار
        # صريح لا تحدث طباعة صامتة خاطئة (الدالة نفسها باقية بلا حذف بقسم
        # الإصدار 19 — انظر get_device_printer للقراءة الجديدة لكل جهاز)
        if not PRINT_LIBS_OK and manager_level(self.role):
            self._show_print_libs_bar()

    def _show_print_libs_bar(self):
        """★ إضافة (الإصدار 19 — القسم 1 — البند 3): الشريط الأصفر الرفيع
        أعلى الشاشة (كشريط التحديث) — يظهر للمدير فقط عند بدء التشغيل إن
        كانت مكتبات الطباعة ناقصة، وزره يفتح نافذة التثبيت التلقائي فيُثبَّت
        من البداية دون انتظار أول طباعة، ويختفي من تلقاء نفسه بعد التثبيت
        لأن إعادة التشغيل تفتح جلسة والمكتبات صارت موجودة"""
        if getattr(self, "print_libs_bar", None) is not None:
            try:
                self.print_libs_bar.destroy()
            except Exception:
                pass
            self.print_libs_bar = None
        bg, fg = "#fef9c3", "#854d0e"
        bar = tk.Frame(self.container, bg=bg, highlightbackground="#fde047",
                       highlightthickness=1)
        try:                  # فوق الشريط الإحصائي مباشرة — مثل شريط التحديث
            bar.pack(fill="x", padx=25, pady=(10, 0), before=self.stats_bar_frame)
        except Exception:
            bar.pack(fill="x", padx=25, pady=(10, 0))
        lbl = tk.Label(bar, text="🖨 مكتبات الطباعة غير مثبتة — انقر للتثبيت التلقائي",
                       bg=bg, fg=fg, font=("Segoe UI", 10, "bold"), cursor="hand2")
        lbl.pack(side="right", padx=(4, 12), pady=4)
        lbl.bind("<Button-1>", lambda e: open_print_libs_install_dialog())
        add_tip(lbl, "فتح نافذة التثبيت التلقائي لمكتبات الطباعة")
        b_ins = tk.Button(bar, text="⚙️ تثبيت تلقائي", command=open_print_libs_install_dialog,
                          bg=GREEN, fg="white", activebackground=GREEN,
                          activeforeground="white", font=("Segoe UI", 9, "bold"),
                          bd=0, cursor="hand2", padx=12, pady=2, highlightthickness=0)
        b_ins.pack(side="left", padx=(12, 6), pady=3)
        add_tip(b_ins, "تثبيت مكتبات الطباعة تلقائياً عبر الإنترنت (أقل من دقيقة) "
                       "ثم إعادة تشغيل تلقائية — تعمل الطباعة بعدها مباشرة")
        self.print_libs_bar = bar

    def _restart_after_print_install(self):
        """★ إضافة (الإصدار 19 — القسم 1 — البند 2د): إعادة التشغيل التلقائية
        الآمنة بعد نجاح التثبيت — بنفس آلية إعادة التشغيل القائمة بنظام
        التحديث حرفياً: إطلاق العملية الجديدة أولاً (subprocess.Popen) ثم
        الخروج النظيف عبر exit_app — لا تُمس القاعدة ولا النسخ الاحتياطية
        ولا الإعدادات ولا سجل التدقيق إطلاقاً، ويُفقد تسجيل الدخول فقط"""
        audit("إعادة تشغيل تلقائية بعد تثبيت مكتبات الطباعة",
              "نجح التثبيت والتحقق الفعلي — الطباعة تعمل مباشرة بعدها")
        if getattr(sys, "frozen", False):
            messagebox.showinfo("أعد التشغيل يدوياً",
                "تم تثبيت مكتبات الطباعة — أغلق البرنامج وافتحه من جديد "
                "لتعمل الطباعة.")
            self.exit_app()
            return
        try:
            # إطلاق العملية الجديدة أولاً — قبل الخروج النظيف من القديمة
            subprocess.Popen([sys.executable, os.path.abspath(__file__)])
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showwarning("تعذر التشغيل التلقائي",
                "أعد فتح البرنامج يدوياً هذه المرة فقط.")
            self.exit_app()      # خروج عادي نظيف — لا انهيار أبداً
            return
        self.exit_app()          # الخروج النظيف — النسخة الاحتياطية كاملة كما هي

    def about_dialog(self):
        """★ إضافة (نافذة «عن البرنامج»): نبذة مختصرة أنيقة عن البرنامج بأسلوب
        نافذة تسجيل الدخول القائمة (بطاقة فاتحة وسطية فوق خلفية داكنة) — قراءة
        فقط من المتغيرات والجداول القائمة بلا أي فحص شبكي عند الفتح: الإصدار
        الحالي، آخر تحديث ناجح من الإعدادات، حالة آخر فحص تحديث (ذاكرة الجلسة
        ثم سجل التدقيق القائم)، تاريخ اليوم وساعة حية تتحدث كل ثانية، مستخدم
        الجلسة، ومجلد البيانات بخط صغير قابل للتحديد مع زر نسخ 📋 للمحفظة"""
        win = self.register_window(tk.Toplevel(self))
        win.title("عن البرنامج")
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول): التمركز والفحص الذاتي
        # عبر place_window الموحدة (نفس الحجم القائم 420×560 — لا يرتفع إلا
        # إن طلب المحتوى أكثر) — عناصر الأسفل محزومة أولاً هنا منذ إنشائها
        # (القاعدة الذهبية كانت مطبقة في هذه النافذة أصلاً)
        win.resizable(False, False)
        win.configure(bg=SIDEBAR)
        win.transient(self)
        try:
            win.grab_set()
        except Exception:
            pass

        # ---------- عناصر الأسفل تُرصّ أولاً كي تثبت في مكانها ----------
        # زر «إغلاق» رمادي داكن أسفل النافذة (نفس رمادي أزرار الإغلاق القائمة)
        self.mk_btn(win, "إغلاق", win.destroy, "#475569").pack(side="bottom",
                                                                pady=(4, 16))
        # سطر صغير رمادي: البيانات محلية مع نسخ احتياطية تلقائية
        tk.Label(win, text="البيانات محفوظة محلياً مع نسخ احتياطية تلقائية 🔒",
                 bg=SIDEBAR, fg="#94a3b8",
                 font=("Segoe UI", 9)).pack(side="bottom", pady=(2, 2))
        # الفاصل الثاني (تحت البطاقة)
        tk.Frame(win, bg="#334155", height=1).pack(side="bottom", fill="x",
                                                   padx=46, pady=(6, 4))

        # ---------- الرأس: أيقونة كبيرة + اسم البرنامج + السطر الفرعي ----------
        tk.Label(win, text="🖥️", bg=SIDEBAR, fg="#e2e8f0",
                 font=("Segoe UI", 30)).pack(pady=(18, 2))
        tk.Label(win, text="نظام المبيعات والمرتجعات", bg=SIDEBAR, fg="#f1f5f9",
                 font=FT).pack(pady=(0, 2))
        tk.Label(win, text="برنامج إدارة محل الكمبيوتر", bg=SIDEBAR, fg="#94a3b8",
                 font=("Segoe UI", 10)).pack(pady=(0, 8))
        # الفاصل الأول اللطيف (بلون أهدأ من الخلفية الداكنة)
        tk.Frame(win, bg="#334155", height=1).pack(fill="x", padx=46, pady=(2, 4))

        # ---------- بطاقة المعلومات الفاتحة (CARD بإطار BORDER) ----------
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER,
                        highlightthickness=1)
        card.pack(fill="both", expand=True, padx=26, pady=(0, 6))

        def info_row(title, value="", value_fg=DARK, value_font=F):
            """صف معلومة داخل البطاقة: العنوان يميناً والقيمة يساراً بخط واضح"""
            fr = tk.Frame(card, bg=CARD)
            fr.pack(fill="x", padx=14, pady=6)
            tk.Label(fr, text=title, bg=CARD, fg=GRAY,
                     font=("Segoe UI", 10, "bold"), anchor="e").pack(side="right")
            lbl = tk.Label(fr, text=value, bg=CARD, fg=value_fg,
                           font=value_font, anchor="w")
            lbl.pack(side="left")
            return lbl

        # (1) الإصدار الحالي
        info_row("الإصدار الحالي:", str(VERSION), DARK, FB)

        # (2) آخر تحديث ناجح — من الإعدادات القائمة فقط (بلا أي اتصال)
        try:
            last_upd = get_setting("last_update_date") or "لم يتم تحديث بعد"
        except Exception:
            last_upd = "لم يتم تحديث بعد"
        info_row("آخر تحديث ناجح:", last_upd,
                 DARK if last_upd != "لم يتم تحديث بعد" else GRAY)

        # (3) حالة التحديث — من نتيجة آخر فحص فقط (بلا فحص شبكي جديد): إصدار
        # مؤكد بذاكرة الجلسة = «يتوفر تحديث جديد»، وإلا نتيجة آخر فحص مسجلة
        # في سجل التدقيق القائم («أحدث إصدار») — وإن لم يُجرَ فحص قط أو فشل
        # الفحص الأخير = «—»
        # ★ إصلاح (2): نتيجة آخر فحص من متغير الذاكرة أولاً (الفحص الدوري
        # لا يكتب في سجل التدقيق عند غياب تحديث — صمت تام) والنصان
        # الموحدان: «أحدث إصدار ✅» / «يتوفر تحديث جديد 🔔»
        if getattr(self, "update_available_version", None):
            state_txt, state_fg = "يتوفر تحديث جديد 🔔", ORANGE
        elif getattr(self, "update_last_check_result", None) == "latest":
            state_txt, state_fg = "أحدث إصدار ✅", GREEN
        else:
            state_txt, state_fg = "—", GRAY
            try:
                with connect() as conn:
                    r = conn.execute(
                        "SELECT details FROM audit_log WHERE action IN "
                        "('فحص تحديث تلقائي', 'فحص تحديث يدوي') "
                        "ORDER BY id DESC LIMIT 1").fetchone()
                if r and "أحدث إصدار" in str(r["details"]):
                    state_txt, state_fg = "أحدث إصدار ✅", GREEN
            except Exception:
                pass
        info_row("حالة التحديث:", state_txt, state_fg)

        # ★ إضافة (أرشيف الإصدارات — نقطة ربط): عدد الإصدارات المحفوظة
        # في الأرشيف — يُحسب من ملفات versions_archive فقط (بلا أي اتصال)
        try:
            arch_n = archive_count()
        except Exception:
            arch_n = 0
        info_row("الإصدارات المحفوظة بالأرشيف:", str(arch_n),
                 DARK if arch_n else GRAY)

        # (4) تاريخ اليوم والوقت — ساعة حية تتحدث كل ثانية بـ after
        lbl_clock = info_row("تاريخ اليوم والوقت:", "", DARK, ("Segoe UI", 10))

        def _tick():
            try:
                if not win.winfo_exists():
                    return
                now = datetime.now()
                d = now.strftime("%Y-%m-%d")
                lbl_clock.config(text=f"{day_name(d)} — {d} "
                                      + now.strftime("%H:%M:%S"))
                win.after(1000, _tick)
            except Exception:
                pass
        _tick()

        # (5) مستخدم الجلسة
        info_row("مستخدم الجلسة:",
                 f"{getattr(self, 'user_name', '—')} "
                 f"({getattr(self, 'role', '—')})")

        # (6) مجلد البيانات — عنوان يميناً ثم المسار بخط صغير قابل للتحديد
        fr_d = tk.Frame(card, bg=CARD)
        fr_d.pack(fill="x", padx=14, pady=(6, 0))
        tk.Label(fr_d, text="مجلد البيانات:", bg=CARD, fg=GRAY,
                 font=("Segoe UI", 10, "bold"), anchor="e").pack(side="right")
        fr_p = tk.Frame(card, bg=CARD)
        fr_p.pack(fill="x", padx=14, pady=(2, 8))
        e_path = tk.Entry(fr_p, font=("Segoe UI", 8), justify="center",
                          relief="solid", bd=1)
        e_path.insert(0, data_dir())
        e_path.configure(state="readonly")   # للقراءة فقط — قابل للتحديد والنسخ
        e_path.pack(side="right", fill="x", expand=True)

        def _copy_done():
            """إعادة زر النسخ لشكله بعد رسالة التأكيد القصيرة (بأقصى جهد)"""
            try:
                b_copy.config(text="📋", state="normal")
            except Exception:
                pass

        def _copy_path():
            """نسخ مسار مجلد البيانات إلى المحفظة مع رسالة تأكيد قصيرة"""
            try:
                win.clipboard_clear()
                win.clipboard_append(e_path.get())
                b_copy.config(text="✅ تم النسخ", state="disabled")
                win.after(1500, _copy_done)
            except Exception:
                pass
        b_copy = tk.Button(fr_p, text="📋", command=_copy_path, bg=CARD, fg=DARK,
                           font=("Segoe UI", 10), bd=1, relief="solid",
                           cursor="hand2", padx=6, pady=2)
        b_copy.pack(side="left", padx=(0, 6))
        # ★ إضافة (الإصدار 15 — الجزء الأول): 420×560 مع الفحص الذاتي
        # والتمركز وسط الشاشة بدل الحساب اليدوي السابق
        place_window(win, 420, 560)

    def archive_open_folder(self):
        """★ إضافة (أرشيف الإصدارات): زر «📂 فتح مجلد الأرشيف» — يفتح مجلد
        versions_archive في مستكشف ملفات ويندوز بنفس نمط زر «فتح مجلد
        النسخ» القائم تماماً"""
        try:
            folder = archive_dir()
            if os.name == "nt":
                os.startfile(folder)
            else:
                messagebox.showinfo("مجلد أرشيف الإصدارات", folder)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", f"تعذر فتح مجلد الأرشيف:\n{e}")

    def archive_versions_dialog(self):
        """★ إضافة (أرشيف الإصدارات): نافذة عرض أرشيف الإصدارات — للمدير
        فقط: جدول بكل ملفات الأرشيف مرتبة من الأحدث (الاسم | الإصدار |
        تاريخ الحفظ | الحجم بالكيلوبايت) + زر فتح مجلد الأرشيف في مستكشف
        ويندوز + زر استعادة أي إصدار بتحذير قوي (تُحفظ النسخة الحالية في
        الأرشيف أولاً بنفس التسمية قبل أي استبدال — لا فقدان في أي اتجاه)
        — وكل إجراء في سجل التدقيق"""
        if not self.require_admin("manager"):
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("أرشيف الإصدارات")
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول — إصلاح خاص): الحجم
        # 900×640 + minsize + تمدد كامل — كان 780×520 بلا تمدد فكانت الأزرار
        # السفلية تُقص، والآن شريط الأزرار يُحزم أولاً side="bottom" كامل
        # الظهور قبل أي شيء آخر (القاعدة الذهبية) فلا يُقص أبداً
        win.configure(bg=CARD)
        win.transient(self)
        try:
            win.grab_set()
        except Exception:
            pass
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول — القاعدة الذهبية): شريط
        # الأزرار السفلي (استعادة/فتح المجلد/تحديث القائمة/إغلاق) يُحزم أولاً
        # side="bottom" كامل الظهور، وعدّاد الإصدارات يُحزم side="bottom" فوقه
        # مباشرة، ثم الرأس، والجدول يتمدد fill="both" expand=True في الباقي —
        # والأزرار تُنشأ في الشريط لاحقاً بعد تعريف load_rows
        fr_btns = tk.Frame(win, bg=CARD)
        fr_btns.pack(side="bottom", fill="x", pady=(4, 12))
        # الرأس بنمط عناوين الشاشات القائم
        tk.Label(win, text="🗃️", bg=CARD, fg=DARK,
                 font=("Segoe UI", 24)).pack(pady=(12, 0))
        tk.Label(win, text="أرشيف الإصدارات", bg=CARD, fg=DARK, font=FT).pack()
        tk.Label(win, text="سجل تاريخي كامل لكل إصدارات البرنامج المحفوظة — لا يُحذف منه شيء تلقائياً",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 10)).pack(pady=(0, 4))
        # جدول الملفات مرتباً من الأحدث إلى الأقدم
        frm, tv = self.mk_tree(win, ["الاسم", "الإصدار", "تاريخ الحفظ", "الحجم (KB)"],
                               [340, 90, 150, 90])
        frm.pack(fill="both", expand=True, padx=18, pady=6)
        # ★ إضافة (الإصدار 14 — البندان 5+6): فرز الرؤوس + الصفوف المتناوبة
        enable_tree_sorting(tv)
        config_tree_stripes(tv)
        self._archive_rows = []          # مسارات ملفات الأرشيف بترتيب الصفوف
        # ★ تعديل مصرح به (الإصدار 15 — الجزء الأول): العدّاد فوق شريط
        # الأزرار مباشرة — ظاهر دائماً فوقه مهما تمدد الجدول
        lbl_count = tk.Label(win, text="", bg=CARD, fg=GRAY, font=("Segoe UI", 10))
        lbl_count.pack(side="bottom", pady=(2, 0))

        def load_rows():
            """قراءة ملفات الأرشيف من جديد وملء الجدول من الأحدث"""
            tv.delete(*tv.get_children())
            self._archive_rows = []
            rows = archive_list_files()          # مرتبة من الأحدث
            for i, r in enumerate(rows):
                tv.insert("", "end", tags=stripe_tags(i),
                          values=(r["name"], r["version"],
                                  r["saved"], r["size_kb"]))
                self._archive_rows.append(r["path"])
            lbl_count.config(text=f"عدد الإصدارات المحفوظة: {len(rows)}")
        load_rows()
        # الأزرار: الاستعادة (الأساسي) ثم فتح المجلد ثم التحديث ثم الإغلاق
        b_restore = self.mk_btn(fr_btns, "♻️ استعادة هذا الإصدار",
                                lambda: self.archive_restore_selected(tv, win, load_rows), ORANGE)
        b_restore.pack(side="right", padx=6)
        add_tip(b_restore, "استبدال كود البرنامج الحالي بالنسخة المختارة — "
                           "تُحفظ النسخة الحالية في الأرشيف أولاً ثم رسالة إعادة التشغيل")
        b_open = self.mk_btn(fr_btns, "📂 فتح مجلد الأرشيف",
                             self.archive_open_folder, "#0369a1")
        b_open.pack(side="right", padx=6)
        add_tip(b_open, "فتح مجلد أرشيف الإصدارات في مستكشف ملفات ويندوز")
        b_refresh = self.mk_btn(fr_btns, "🔄 تحديث", load_rows, "#475569")
        b_refresh.pack(side="right", padx=6)
        add_tip(b_refresh, "إعادة قراءة ملفات الأرشيف من جديد")
        b_close = self.mk_btn(fr_btns, "إغلاق", win.destroy, "#475569")
        b_close.pack(side="right", padx=6)
        add_tip(b_close, "إغلاق نافذة أرشيف الإصدارات")
        # ★ إضافة (الإصدار 15 — الجزء الأول): 900×640 + minsize لا يُصغَّر
        # تحته إلى إخفاء الأزرار + تمدد كامل + تمركز وسط الشاشة
        place_window(win, 900, 640, 820, 560, can_resize=True)

    def archive_restore_selected(self, tv, win, reload_rows):
        """★ إضافة (أرشيف الإصدارات): زر «♻️ استعادة هذا الإصدار» — تحذير
        قوي بالعربية أن الاستعادة تستبدل كود البرنامج الحالي، ثم تُحفظ
        النسخة الحالية في الأرشيف أولاً بنفس التسمية المنظمة (لا فقدان في
        أي اتجاه) قبل استبدال ملف البرنامج بنسخة من الأرشيف (نسخاً لا
        نقلاً — الأرشيف لا يفقد شيئاً) + رسالة إعادة التشغيل + تسجيل كامل
        في سجل التدقيق (من استعاد أي إصدار ومتى)"""
        sel = tv.selection()
        if not sel:
            messagebox.showinfo("تنبيه", "اختر إصداراً من الجدول أولاً", parent=win)
            return
        try:
            i = tv.index(sel[0])              # رقم الصف المختار في الجدول
            path = self._archive_rows[i]
        except Exception:
            return
        name = os.path.basename(path)
        ver = archive_file_version(path)
        # نسخة EXE لا تُستعاد تلقائياً: تنبيه يدوي دون أي مساس بالملف
        if getattr(sys, "frozen", False):
            messagebox.showinfo("استعادة EXE",
                "الاستعادة التلقائية لنسخة Python — حدّث EXE يدوياً", parent=win)
            return
        # تحذير قوي بالعربية (تأكيد مزدوج) — الاستعادة تستبدل الكود الحالي
        warn = ("⚠️ تحذير هام ⚠️\n\n"
                "الاستعادة ستستبدل كود البرنامج الحالي بالكامل بالنسخة المختارة:\n"
                f"{name}  (الإصدار {ver})\n\n"
                "ستفقد كل تحسينات الإصدارات الأحدث من هذا الإصدار.\n"
                "سيُحفظ الكود الحالي أولاً في الأرشيف تلقائياً قبل الاستبدال — "
                "لا فقدان في أي اتجاه.\n"
                "بياناتك وتقاريرك لا تُمس نهائياً (محفوظة في قاعدة بيانات منفصلة).\n\n"
                "هل أنت متأكد من المتابعة؟")
        if not messagebox.askyesno("تأكيد الاستعادة (1 من 2)", warn, parent=win):
            return
        if not messagebox.askyesno("تأكيد الاستعادة (2 من 2)",
                "تأكيد أخير:\nهل تريد فعلاً استبدال كود البرنامج الحالي بهذه النسخة الآن؟",
                parent=win):
            return
        # 1) حفظ الكود الحالي في الأرشيف أولاً — بنفس التسمية المنظمة
        saved = archive_save_current()
        if saved is None:
            messagebox.showerror("فشلت الاستعادة",
                "تعذر حفظ النسخة الحالية في الأرشيف قبل الاستعادة —\n"
                "لم يتغير شيء إطلاقاً، حاول لاحقاً.", parent=win)
            return
        # 2) الاستبدال بنسخة من ملف الأرشيف (نسخ لا نقل — الأرشيف لا يفقد شيئاً)
        try:
            target = os.path.abspath(__file__)
            if not os.path.isfile(target):
                raise Exception("تعذر تحديد موقع ملف البرنامج")
            shutil.copy2(path, target)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("فشلت الاستعادة",
                "تعذر استبدال ملف البرنامج:\n" + str(e) +
                "\n\nلم يتغير شيء (راجع error_log.txt).", parent=win)
            return
        # 3) تسجيل كامل في سجل التدقيق + رسالة إعادة التشغيل
        audit("أرشيف الإصدارات",
              f"استعادة إصدار {ver} ({name}) — حُفظ الكود الحالي أولاً باسم "
              + os.path.basename(saved))
        try:
            reload_rows()
        except Exception:
            pass
        messagebox.showinfo("تمت الاستعادة ✅",
            "استُبدل كود البرنامج بالنسخة المختارة بنجاح.\n"
            "حُفظ الكود السابق في الأرشيف باسم:\n" + os.path.basename(saved) +
            "\n\n⚠ أغلق البرنامج الآن وافتحه من جديد لتفعيل الإصدار المستعاد.",
            parent=win)
        self.exit_app()      # إغلاق البرنامج — يجب إعادة تشغيله بعد الاستعادة

    # ═══════════════════════════════════════════════════════════
    # ★★★ إعادة بناء (المرحلة الثالثة — الاستثناء ب المصرح به بالحرف):
    # محتوى نافذة «الصلاحيات الدقيقة» على المواصفة الكاملة ★★★
    # السبب المعلن: تنفيذها السابق كان ناقصًا ومعطوبًا — محتواها كان يُبنى
    # داخل Canvas بإحداثيات خاطئة (anchor=ne عند 0,0) فيُسحق عرض البطاقات
    # إلى بكسل واحد: لا تظهر المستخدمون ولا مربعات الكتالوج ولا خانة الخصم.
    # المواصفة الجديدة كاملة: أدمن حصريًا بفحص الدور عند الفتح (دفاع مزدوج
    # مع إخفاء الزر)، وسطر توضيحي ثابت بأعلى النافذة، وعرض كل المستخدمين
    # من جدول users (الأدمن أولًا مقفولًا بعلامة «كل الصلاحيات دائمًا» فلا
    # يقبل أي تعديل أبدًا)، ولكل مستخدم بطاقة واضحة بعنوان اسمه ودوره فيها
    # مربع اختيار لكل مفتاح من PERMISSIONS_CATALOG باسمه العربي الكامل
    # (قراءة ديناميكية فأي مفتاح يُضاف مستقبلًا يظهر تلقائيًا) + خانة رقمية
    # «أقصى نسبة خصم %»، والقراءة الابتدائية من حقل permissions عبر دوال
    # المحرك القائمة (read_user_permissions_safe) فتعكس المربعات الحالة
    # المحفوظة فعلًا. الحفظ = الدمج الإجباري حصرًا عبر الدالة القائمة
    # write_user_permissions_safe (لا كتابة فوق أبدًا): تُقرأ قائمة الحقل
    # كاملة كما كتبها محرر إدارة المستخدمين، ويُحدَّث فيها مفاتيح الكتالوج
    # وقيمة الخصم فقط، وكل مفتاح آخر خارج الكتالوج يبقى حرفيًا كما هو بنفس
    # صيغة قائمة JSON المعتمدة — ثم رسالة نجاح عربية وجلسة audit_log واحدة
    # بنوع permission_changed (من منح والمستخدم المستهدف والمفاتيح التي
    # فُعّلت وأُطفئت وقيمة الخصم إن تغيرت) باستدعاء دالة التسجيل القائمة
    # audit من داخل الدالة الجديدة فقط دون أي تغيير في بنية السلسلة.
    # نطاق النافذة الكتالوج الجديد حصرًا: لا تعرض ولا تعدل مفاتيح الميزات
    # الأصلية إطلاقًا، ومحتواها قابل للتمرير رأسيًا إذا زاد عدد المستخدمين
    # عن مساحة الشاشة
    # ═══════════════════════════════════════════════════════════
    def show_fine_permissions(self):
        """★ إعادة بناء (المرحلة الثالثة — الاستثناء ب): فتح شاشة الإدارة —
        الفحص الثاني عند الفتح (دفاع مزدوج مع إخفاء الزر في الشريط)"""
        if self.role != ADMIN_ROLE:
            b = getattr(self, "nav_buttons", {}).get("fine_perms")
            if b is not None:
                b.pack_forget()   # زر متقادم بعد تبديل المستخدم: يُخفى فورًا
            messagebox.showwarning("ممنوع",
                "شاشة «الصلاحيات الدقيقة» أدمن حصريًا إلى الأبد — "
                "ليست ضمن الكتالوج ولا تُمنح لأحد")
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("الصلاحيات الدقيقة")
        win.configure(bg=BG); win.resizable(False, False)
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        card.pack(fill="both", expand=True, padx=20, pady=16)
        # القاعدة الذهبية: زر الحفظ يُحزم side="bottom" أولاً فلا يُقص أبدًا
        fr_save = tk.Frame(card, bg=CARD)
        fr_save.pack(side="bottom", fill="x", pady=(8, 12))
        tk.Label(card, text="🛡️ الصلاحيات الدقيقة", bg=CARD, fg=DARK, font=FT).pack(pady=(14, 2))
        # السطر التوضيحي الثابت المطلوب بالحرف — أول سطر تحت العنوان
        tk.Label(card, text="هذه النافذة لإدارة صلاحيات الميزات الجديدة فقط — صلاحيات الميزات الأصلية تُدار من إدارة المستخدمين ثم تعديل الصلاحيات",
                 bg=CARD, fg="#7c3aed", font=("Segoe UI", 9)).pack(pady=(0, 4))
        tk.Label(card, text="طبقة إضافية فوق نظام الأدوار الحالي (أدمن/مدير/بائع) — ليست بديلًا عنه",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 10)).pack(pady=(0, 4))
        tk.Label(card, text="🔒 الشاشة نفسها أدمن حصريًا إلى الأبد — ليست ضمن الكتالوج ولا تُمنح لأحد",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(pady=(0, 8))
        # منطقة تمرير عمودية لبطاقات المستخدمين — كل المستخدمين من جدول
        # users (الأدمن أولًا ثم المديرون ثم البائعون، والنشط قبل المتوقف
        # داخل كل دور، وبالأسماء) — وبالإحداثيات الصحيحة: anchor=nw عند
        # 0,0 وربط <Configure> للـCanvas بضبط عرض الإطار الداخلي (هذه كانت
        # علة النسخة السابقة التي سحقتها إلى بكسل واحد)
        area = tk.Frame(card, bg=CARD)
        area.pack(fill="both", expand=True, padx=6)
        cvs = tk.Canvas(area, bg=CARD, height=420, highlightthickness=0)
        vsb = ttk.Scrollbar(area, orient="vertical", command=cvs.yview)
        cvs.configure(yscrollcommand=vsb.set)
        vsb.pack(side="left", fill="y")
        cvs.pack(side="right", fill="both", expand=True)
        inner = tk.Frame(cvs, bg=CARD)
        _wid = cvs.create_window(0, 0, window=inner, anchor="nw")
        # الاسم القديم نفسه _inner_conf باقٍ (قاعدة عدم حذف أي دالة) —
        # والسلوك المصحح: تحديث رقعة التمرير عند تغير حجم الإطار الداخلي
        def _inner_conf(e):
            cvs.configure(scrollregion=cvs.bbox("all"))
        cvs.bind("<Configure>", lambda e: cvs.itemconfigure(_wid, width=cvs.winfo_width()))
        inner.bind("<Configure>", _inner_conf)
        with connect() as conn:
            users = conn.execute("SELECT username, role, active FROM users "
                                 "ORDER BY (role='أدمن') DESC, (role='مدير') DESC, "
                                 "active DESC, username").fetchall()
        perm_vars, disc_entries = {}, {}
        for u in users:
            is_adm = (u["role"] == ADMIN_ROLE)
            old = read_user_permissions_safe(u["username"])
            state = "disabled" if is_adm else "normal"
            box = tk.Frame(inner, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
            box.pack(fill="x", padx=4, pady=6)
            head = tk.Frame(box, bg=CARD)
            head.pack(fill="x", padx=12, pady=(10, 2))
            # عنوان البطاقة: الاسم والدور (+ وسم «غير نشط» للحسابات المتوقفة
            # تمييزًا لها عن العاملة — عرض توضيحي فقط لا يؤثر في أي شيء)
            title = f"👤 {u['username']} ({u['role']}"
            if not u["active"]:
                title += " — غير نشط"
            title += ")"
            tk.Label(head, text=title, bg=CARD, fg=DARK,
                     font=("Segoe UI", 10, "bold"), anchor="e").pack(
                         side="right", fill="x", expand=True)
            if is_adm:
                tk.Label(head, text="🔒 كل الصلاحيات دائمًا", bg=CARD, fg="#7c3aed",
                         font=("Segoe UI", 9, "bold")).pack(side="right", padx=6)
            for key, label in PERMISSIONS_CATALOG.items():
                v = tk.BooleanVar(value=(is_adm or key in old["fine_keys"]))
                cb = tk.Checkbutton(box, text=label, variable=v, font=F, bg=CARD,
                                    fg=DARK, selectcolor="#dbeafe", activebackground=CARD,
                                    activeforeground=ACCENT, anchor="e", justify="right",
                                    onvalue=True, offvalue=False, state=state)
                cb.pack(fill="x", padx=30, pady=1)
                perm_vars[(u["username"], key)] = v
            fr_d = tk.Frame(box, bg=CARD)
            fr_d.pack(fill="x", padx=12, pady=(4, 10))
            tk.Label(fr_d, text="أقصى نسبة خصم % (0 = ممنوع من الخصم)", bg=CARD, fg=GRAY,
                     font=("Segoe UI", 9), anchor="e").pack(side="right", fill="x", expand=True)
            e_d = tk.Entry(fr_d, width=8, font=("Segoe UI", 10), justify="center",
                           state=state, disabledbackground="#e2e8f0", disabledforeground=GRAY)
            e_d.pack(side="right", padx=6)
            if not is_adm:
                e_d.insert(0, "%g" % old["max_discount"])
            disc_entries[u["username"]] = e_d

        # ربط عجلة الفأرة للـCanvas والإطار الداخلي وكل متحدرية (كل عناصر
        # هذه النافذة تُبنى دفعة واحدة قبل الربط فلا فجوة أبدًا) — بنفس
        # أسلوب التمرير القائم مع return "break" فلا يتكرر التمرير فوق
        # الـCanvas مع ربط صنفه القياسي
        def _wheel(e):
            try:
                cvs.yview_scroll(-1 * int(e.delta / 120), "units")
            except Exception:
                pass
            return "break"
        def _bind_wheel(w):
            w.bind("<MouseWheel>", _wheel)
            for c in w.winfo_children():
                _bind_wheel(c)
        _bind_wheel(cvs)
        _bind_wheel(inner)

        def do_save_fine_perms():
            granter = self.user_name
            planned, bad = [], []
            for u in users:
                if u["role"] == ADMIN_ROLE:
                    continue        # صف الأدمن مقفول دائمًا — لا يُحفظ ولا يُعدل
                name = u["username"]
                val = to_num(disc_entries[name].get().strip())
                if val is None or val < 0 or val > 100:
                    bad.append(f"«{name}»: أدخل قيمة صحيحة بين 0 و100 في «أقصى نسبة خصم %»")
                    continue
                old = read_user_permissions_safe(name)
                new_fine = sorted(k for k in PERMISSIONS_CATALOG
                                  if perm_vars[(name, k)].get())
                if new_fine == old["fine_keys"] and val == old["max_discount"]:
                    continue    # لا تغيير لهذا المستخدم: لا يُكتب ولا يُسجل
                planned.append((name, u["role"], new_fine, val, old))
            if bad:
                messagebox.showwarning("تعذر الحفظ", "\n".join(bad), parent=win)
                return
            if not planned:
                messagebox.showinfo("تنبيه", "لا توجد تغييرات جديدة لحفظها", parent=win)
                return
            changes, saved_names, failed = [], [], []
            lbls = dict(PERMISSIONS_CATALOG)
            for name, role, new_fine, val, old in planned:
                # الدمج الإجباري بالحرف: الكتابة عبر الدالة القائمة
                # write_user_permissions_safe فقط — هي التي تقرأ قائمة الحقل
                # كاملة كما كتبها محرر إدارة المستخدمين، وتحدّث فيها مفاتيح
                # الكتالوج وقيمة الخصم فقط، وتبقي كل مفتاح آخر خارج الكتالوج
                # حرفيًا كما هو بنفس صيغة قائمة JSON — لا يوجد أي مسار كتابة
                # آخر في هذه النافذة إطلاقًا
                if not write_user_permissions_safe(name, new_fine, val):
                    failed.append(name)
                    continue
                saved_names.append(name)
                old_fine, old_md = old["fine_keys"], old["max_discount"]
                seg = f"«{name}» ({role}):"
                on = [k for k in new_fine if k not in old_fine]
                off = [k for k in old_fine if k not in new_fine]
                if on:
                    seg += " فعّل " + " و".join(f"«{lbls[k]}»" for k in on) + "؛"
                if off:
                    seg += " أطفأ " + " و".join(f"«{lbls[k]}»" for k in off) + "؛"
                if val != old_md:
                    seg += f" أقصى خصم: {old_md:g}% ← {val:g}%؛"
                changes.append(seg.rstrip("؛"))
            # جلسة تدقيق واحدة لكل حفظ ناجح — بنوع permission_changed تتضمن
            # من منح (نصًا وفي عمود username بالسلسلة نفسها) والمستخدم
            # المستهدف ومفاتيح الكتالوج التي فُعّلت وأُطفئت وقيمة أقصى خصم
            # إن تغيرت — باستدعاء دالة التسجيل القائمة audit من داخل هذه
            # الدالة الجديدة فقط دون أي تغيير في بنية السلسلة
            if changes:
                audit("permission_changed",
                      "بواسطة: " + granter + " — " + " | ".join(changes))
            if failed:
                msg = "تعذر حفظ صلاحيات: " + "، ".join(f"«{n}»" for n in failed) + "."
                if saved_names:
                    msg = ("حُفظت صلاحيات: " + "، ".join(f"«{n}»" for n in saved_names)
                           + "\nلكن " + msg)
                messagebox.showwarning("تعذر الحفظ",
                    msg + "\nأعد فتح الشاشة وحفظ من تعذر حفظه.", parent=win)
                return
            messagebox.showinfo("تم", "تم حفظ الصلاحيات الدقيقة بنجاح", parent=win)
            win.destroy()

        self.mk_btn(fr_save, "💾 حفظ", do_save_fine_perms, "#0d9488").pack()
        place_window(win, 620)

    # ═══════════════════════════════════════════════════════════
    # ★★★ إضافات (المرحلة الثانية — مركز المتابعة والرقابة): النافذة ★★★
    # نافذة واحدة بتبويبين: «اللوحة الحية» (تتطلب live_dashboard) و«الأنشطة
    # غير الطبيعية» (تتطلب anomalies_report) — كل تبويب يُفحص عبر
    # user_has_permission القائم عند الفتح وعند كل تحديث (دفاع مزدوج مع
    # إخفاء الزر في الشريط الجانبي): بطاقات ملخص اليوم التجاري الحالي من
    # get_business_day() حصراً، وجدول البائعين، وآخر عملية، ومقارنة
    # الأسبوع الماضي حتى نفس الساعة، والمتصلون الآن من get_online_users،
    # وتنبيهات اليوم تُمسح وتُعاد من بيانات اليوم وحدها مع كل تحديث،
    # وحدود التنبيهات الست تحريراً وحفظاً للأدمن فقط وللقراءة لغيره، وزر
    # «تحديث الآن» وتحديث تلقائي كل 60 ثانية بمؤقت جديد مستقل تماماً —
    # وبنفس ألوان البرنامج وخطوطه واتجاه RTL وتعليقاته العربية
    # ═══════════════════════════════════════════════════════════
    def show_monitor_center(self):
        """★ إضافة (المرحلة الثانية): فتح «مركز المتابعة والرقابة» — الفحص
        الثاني عند الفتح (دفاع مزدوج مع إخفاء الزر في الشريط الجانبي)"""
        if not (user_has_permission(self.user_name, "live_dashboard")
                or user_has_permission(self.user_name, "anomalies_report")):
            b = getattr(self, "nav_buttons", {}).get("monitor_center")
            if b is not None:
                b.pack_forget()   # زر متقادم بعد تبديل المستخدم: يُخفى فورًا
            messagebox.showwarning("ممنوع",
                "مركز المتابعة والرقابة يتطلب صلاحية «لوحة المتابعة الحية»\n"
                "أو صلاحية «تقرير الأنشطة غير الطبيعية» — راجع الأدمن")
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("مركز المتابعة والرقابة")
        win.configure(bg=BG)
        st = {"tab": "live", "job": None}

        # ---------- الرأس + زر تحديث اللوحة الحية ----------
        head = tk.Frame(win, bg=BG)
        head.pack(fill="x", padx=18, pady=(12, 2))
        hr = tk.Frame(head, bg=BG); hr.pack(side="right")
        tk.Label(hr, text="🛰️ مركز المتابعة والرقابة", bg=BG, fg=DARK,
                 font=FT).pack(anchor="e")
        tk.Label(hr, text="اليوم التجاري من get_business_day — وكل التوقيتات بنظام 24 ساعة",
                 bg=BG, fg=GRAY, font=("Segoe UI", 10)).pack(anchor="e")

        # ---------- تبويبان بنفس نمط أزرار الشريط الجانبي ----------
        bar = tk.Frame(win, bg=BG)
        bar.pack(fill="x", padx=18, pady=(4, 4))
        fr_live = tk.Frame(win, bg=BG)
        fr_anom = tk.Frame(win, bg=BG)
        tabs = {}

        def _select_tab(key):
            st["tab"] = key
            for k, b in tabs.items():
                b.config(bg=(ACCENT if k == key else SIDEBAR),
                         fg=("white" if k == key else "#cbd5e1"))
            fr_live.pack_forget(); fr_anom.pack_forget()
            (fr_live if key == "live" else fr_anom).pack(
                fill="both", expand=True, padx=14, pady=(0, 10))
            if key == "live":
                refresh_live()
            else:
                refresh_anom()

        def _mk_tab(key, text, tip):
            b = tk.Button(bar, text=text, font=FB, bd=0, cursor="hand2", anchor="e",
                          bg=SIDEBAR, fg="#cbd5e1", activebackground=ACCENT,
                          activeforeground="white", padx=18, pady=9, highlightthickness=0,
                          command=lambda: _select_tab(key))
            b.pack(side="right", padx=(0, 6))
            add_tip(b, tip)
            tabs[key] = b

        # ★ تعديل مصرح به (المرحلة الرابعة — القسم 3-ب): كل تبويب يُنشأ فقط
        # لمن يملك صلاحيته الحرفية من الكتالوج — من يملك live_dashboard فقط
        # يرى تبويب «اللوحة الحية» فقط، ومن يملك anomalies_report فقط يرى
        # تبويب «الأنشطة غير الطبيعية» فقط (والأدمن يرى الاثنين بدوره عبر
        # المحرك)، فما لا يملكه المستخدم لا يُنشأ أصلًا — لا زر معطل البتة
        if user_has_permission(self.user_name, "live_dashboard"):
            _mk_tab("live", "📊  اللوحة الحية",
                    "بطاقات اليوم التجاري الحالي وجدول البائعين وآخر عملية ومقارنة "
                    "الأسبوع الماضي والمتصلون الآن وتنبيهات اليوم — تتطلب صلاحية "
                    "«لوحة المتابعة الحية والتنبيهات الفورية»")
        if user_has_permission(self.user_name, "anomalies_report"):
            _mk_tab("anom", "🚨  الأنشطة غير الطبيعية",
                    "قائمة موحدة من سجل التدقيق والبيانات القائمة فقط: الحذف "
                    "والاسترجاع والإغلاق المتأخر والمرتجع السريع والتأريخ السابق "
                    "والسعر المنخفض والدخول خارج الدوام — تتطلب صلاحية «تقرير "
                    "الأنشطة غير الطبيعية»")

        # ══════════════ تبويب «اللوحة الحية» (يتطلب live_dashboard) ══════════════
        # القاعدة الذهبية للترتيب: إعدادات الحدود أسفل أولاً ثم تنبيهات اليوم
        # فوقها ثم البطاقات والمعلومات أعلى، وجدول البائعين آخراً يتمدد فيما
        # تبقى (هو وحده يُقص على الشاشات القصيرة — لا الأزرار ولا الحدود أبداً)
        fr_set = tk.Frame(fr_live, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        is_adm = (self.role == ADMIN_ROLE)
        tk.Label(fr_set,
                 text=("⚙️ حدود التنبيهات — تحرير وحفظ للأدمن وحده" if is_adm
                       else "⚙️ حدود التنبيهات — للعرض فقط (التحرير والحفظ للأدمن وحده)"),
                 bg=CARD, fg=("#7c3aed" if is_adm else GRAY),
                 font=("Segoe UI", 10, "bold"), anchor="e").pack(fill="x", padx=10, pady=(8, 2))
        grid_set = tk.Frame(fr_set, bg=CARD)
        grid_set.pack(fill="x", padx=10, pady=2)
        ent_set = {}
        cur_vals = get_all_alert_settings()
        for i, k in enumerate(ALERT_SETTINGS_DEFAULTS):
            r_, c_ = divmod(i, 2)
            tk.Label(grid_set, text=ALERT_SETTINGS_LABELS[k] + ":", bg=CARD, fg=GRAY,
                     font=("Segoe UI", 10), anchor="e").grid(
                row=r_, column=c_ * 2, sticky="e", padx=10, pady=3)
            e = tk.Entry(grid_set, width=10, font=("Segoe UI", 10), justify="center",
                         relief="solid", bd=1)
            e.grid(row=r_, column=c_ * 2 + 1, sticky="w", padx=(0, 10), pady=3)
            e.insert(0, cur_vals[k])
            if not is_adm:
                e.config(state="disabled", disabledbackground="#e2e8f0", disabledforeground=DARK)
            ent_set[k] = e

        def do_save_alert_settings():
            """حفظ الحدود للأدمن فقط — تحقق كامل قبل أي كتابة ورفض كامل بلا
            كتابة عند أي خطأ، ثم جلسة تدقيق واحدة داخل save_alert_settings"""
            vals = {k: ent_set[k].get().strip() for k in ALERT_SETTINGS_DEFAULTS}
            problems = []
            v = to_num(vals["alert_large_op_amount"])
            if v is None or v < 0:
                problems.append("«الحد الأدنى لتنبيه عملية كبيرة»: أدخل رقماً صحيحاً 0 فما فوق")
            for k in ("alert_returns_limit", "alert_quick_return_minutes"):
                v = to_num(vals[k])
                if v is None or v < 1 or v != int(v):
                    problems.append(f"«{ALERT_SETTINGS_LABELS[k]}»: أدخل عدداً صحيحاً 1 فما فوق")
            v = to_num(vals["anomaly_price_deviation_pct"])
            if v is None or v < 1 or v > 100:
                problems.append("«نسبة انخفاض السعر المشكوك فيها %»: أدخل قيمة بين 1 و100")
            for k in ("shop_hours_start", "shop_hours_end"):
                if _parse_hhmm(vals[k]) is None:
                    problems.append(f"«{ALERT_SETTINGS_LABELS[k]}»: أدخل الوقت بصيغة HH:MM بنظام 24 ساعة")
            if problems:
                messagebox.showwarning("تعذر الحفظ", "\n".join(problems), parent=win)
                return
            ok, msg = save_alert_settings(vals)
            if not ok:
                messagebox.showwarning("تعذر الحفظ", msg, parent=win)
                return
            messagebox.showinfo("تم", "تم حفظ حدود التنبيهات بنجاح", parent=win)
            refresh_live()

        if is_adm:
            fr_sv = tk.Frame(fr_set, bg=CARD)
            fr_sv.pack(pady=(2, 8))
            b_sv = self.mk_btn(fr_sv, "💾 حفظ الحدود", do_save_alert_settings, "#0d9488")
            b_sv.pack()
            add_tip(b_sv, "كتابة الحدود الست في settings + جلسة تدقيق واحدة "
                          "بنوع alert_settings_changed")
        else:
            tk.Label(fr_set, text="", bg=CARD, font=("Segoe UI", 4)).pack(pady=4)
        fr_set.pack(side="bottom", fill="x", padx=2, pady=(2, 0))

        # منطقة تنبيهات اليوم — تُمسح كلياً وتُعاد بناءها من بيانات اليوم مع
        # كل تحديث (لا لمس لأي منطق حفظ إطلاقاً — قراءة فقط)
        al_card = tk.Frame(fr_live, bg=CARD, highlightbackground=BORDER, highlightthickness=1)
        tk.Label(al_card, text="⚠️ تنبيهات اليوم (تُمسح وتُعاد من بيانات اليوم مع كل تحديث)",
                 bg=CARD, fg=ORANGE, font=("Segoe UI", 10, "bold"),
                 anchor="e").pack(fill="x", padx=10, pady=(8, 2))
        frm_al, tv_al = self.mk_tree(al_card, ["التفاصيل", "التنبيه"], [700, 170])
        frm_al.pack(fill="x", padx=10, pady=(0, 8))
        tv_al.configure(height=4)
        config_tree_stripes(tv_al)
        al_card.pack(side="bottom", fill="x", padx=2, pady=(4, 2))

        # بطاقات ملخص اليوم التجاري الحالي حتى الآن
        cards_fr = tk.Frame(fr_live, bg=BG)
        cards_fr.pack(fill="x", pady=(4, 2))
        c_cash = self.mk_card(cards_fr, "مبيعات نقدية", GREEN)
        c_netw = self.mk_card(cards_fr, "مبيعات شبكة", ACCENT)
        c_rets = self.mk_card(cards_fr, "المرتجعات", RED)
        c_net = self.mk_card(cards_fr, "الصافي", DARK)
        for c in (c_cash, c_netw, c_rets, c_net):
            c[0].pack(side="right", fill="x", expand=True, padx=4)
        # ★★★ إضافة (حزمة الصندوق والرقابة المالية — الميزة 5): بطاقة
        # الديون المتعثرة — إضافة بحتة تحت صف البطاقات القائم لا تمس أي
        # عنصر قائم: تُبنى فقط لمن يملك debt_aging_view (والأدمن بدوره
        # دائماً)، وكل بنائها داخل try/except مستقل فلو فشل شيء بقيت
        # اللوحة الحية كاملة كما هي، وتُحدَّث من refresh_live بنفس
        # استقلالها (lbl_delinq = None يعني بطاقة غير موجودة لهذه الجلسة)
        lbl_delinq = None
        try:
            if user_has_permission(self.user_name, "debt_aging_view"):
                fr_dlq6 = tk.Frame(fr_live, bg=CARD,
                                   highlightbackground=BORDER,
                                   highlightthickness=1)
                fr_dlq6.pack(fill="x", padx=2, pady=(4, 2))
                tk.Label(fr_dlq6,
                         text="ديون متعثرة (تجاوزت 60 يومًا بلا سداد)",
                         bg=CARD, fg=GRAY,
                         font=("Segoe UI", 10)).pack(pady=(8, 0))
                lbl_delinq = tk.Label(fr_dlq6, text="—", bg=CARD, fg=RED,
                                      font=FV)
                lbl_delinq.pack(pady=(2, 8))
        except Exception as e:
            log_error(e, sys.exc_info()[2])

        # أسطر المعلومات: آخر عملية + المقارنة + المتصلون الآن
        info_fr = tk.Frame(fr_live, bg=BG)
        info_fr.pack(fill="x", pady=(2, 4))
        lbl_last = tk.Label(info_fr, text="آخر عملية: —", bg=BG, fg=DARK,
                            font=("Segoe UI", 10, "bold"), anchor="e",
                            justify="right", wraplength=920)
        lbl_last.pack(fill="x")
        lbl_cmp = tk.Label(info_fr, text="المقارنة مع الأسبوع الماضي: —", bg=BG, fg=GRAY,
                           font=("Segoe UI", 10), anchor="e", justify="right",
                           wraplength=920)
        lbl_cmp.pack(fill="x")
        lbl_online = tk.Label(info_fr, text="المتصلون الآن: —", bg=BG, fg="#0d9488",
                              font=("Segoe UI", 10), anchor="e", justify="right",
                              wraplength=920)
        lbl_online.pack(fill="x")

        # جدول صغير: عدد العمليات وإجماليها لكل بائع اليوم
        frm_sel, tv_sel = self.mk_tree(fr_live,
            ["الصافي", "المرتجعات", "المبيعات", "عدد العمليات", "البائع"],
            [110, 140, 130, 100, 150])
        tv_sel.configure(height=5)
        config_tree_stripes(tv_sel)
        enable_tree_sorting(tv_sel)
        tv_sel.tag_configure("ret", foreground=RED)
        frm_sel.pack(fill="both", expand=True, padx=2, pady=2)
        add_tip(tv_sel, "عدد العمليات وإجمالياتها لكل بائع على اليوم التجاري الحالي — "
                        "انقر رأس أي عمود للفرز")

        lbl_perm_live = tk.Label(fr_live, text="", bg=BG, fg=RED,
                                 font=("Segoe UI", 10, "bold"), anchor="e",
                                 justify="right", wraplength=920)

        def refresh_live():
            """تحديث كل بيانات اللوحة الحية — الصلاحية تُفحص هنا أيضاً عند
            كل تحديث (دفاع مزدوج: الفتح + كل تحديث)"""
            # دفاع مزدوج: صلاحية التبويب تُفحص عند كل تحديث لا عند الفتح فقط
            if not user_has_permission(self.user_name, "live_dashboard"):
                lbl_perm_live.config(text="🔒 سُحبت صلاحية «اللوحة الحية» — "
                                          "لا يُعرض هذا التبويب (راجع الأدمن)")
                lbl_perm_live.pack(fill="x", padx=10, pady=8)
                return
            lbl_perm_live.pack_forget()
            d = get_business_day()
            n, cash, netw, rets, net = day_totals(d)
            c_cash[1].config(text=money(cash))
            c_netw[1].config(text=money(netw))
            c_rets[1].config(text=money(rets))
            c_net[1].config(text=money(net), fg=(GREEN if net >= 0 else RED))
            # ★★★ إضافة (حزمة الصندوق والرقابة المالية — الميزة 5): تحديث
            # بطاقة الديون المتعثرة — لمن يملك debt_aging_view حصراً (تُفحص
            # عند كل تحديث أيضاً — دفاع مزدوج)، وبنية مستقلة تماماً: أي فشل
            # يُكتب في error_log.txt ولا تمس بقية اللوحة الحية إطلاقًا
            try:
                if (lbl_delinq is not None
                        and user_has_permission(self.user_name,
                                                "debt_aging_view")):
                    _cnt6, _tot6 = delinquent_debts_summary()
                    lbl_delinq.config(
                        text=f"{_cnt6} دين — إجمالي {money(_tot6)}",
                        fg=(RED if _cnt6 > 0 else GREEN))
            except Exception as e:
                log_error(e, sys.exc_info()[2])
            # جدول البائعين اليوم (نفس بيانات day_totals من جدول العمليات)
            with connect() as conn:
                srows = conn.execute("SELECT seller_name, type, COUNT(*) AS c, "
                                     "SUM(total) AS s FROM operations WHERE date=? "
                                     "GROUP BY seller_name, type", (d,)).fetchall()
            agg = {}
            for rr in srows:
                name = rr["seller_name"] or "—"
                a = agg.setdefault(name, {"ops": 0, "sales": 0.0, "rets": 0, "ret_sum": 0.0})
                a["ops"] += rr["c"]
                if rr["type"] == "مرتجع":
                    a["rets"] += rr["c"]
                    a["ret_sum"] += -(rr["s"] or 0)
                else:
                    a["sales"] += (rr["s"] or 0)
            tv_sel.delete(*tv_sel.get_children())
            for i, (name, a) in enumerate(sorted(agg.items(), key=lambda kv: -kv[1]["sales"])):
                tv_sel.insert("", "end", tags=stripe_tags(i),
                    values=(money(a["sales"] - a["ret_sum"]),
                            f"{a['rets']} ({money(a['ret_sum'])})",
                            money(a["sales"]), a["ops"], name))
            # آخر عملية اليوم — الصنف والسعر والبائع والوقت
            tmap = monitor_op_times()
            with connect() as conn:
                last = conn.execute("SELECT * FROM operations WHERE date=? "
                                    "ORDER BY id DESC LIMIT 1", (d,)).fetchone()
            if last is None:
                lbl_last.config(text="آخر عملية: لا حركات على اليوم التجاري الحالي بعد")
            else:
                ts_s = tmap.get(last["id"]) or (str(last["date"]) if " " in str(last["date"]) else "")
                lbl_last.config(text=f"آخر عملية: {last['item_name']} — "
                                     f"{money(last['price'])} ({last['type']}) — البائع: "
                                     f"{last['seller_name'] or '—'} — {ts_s or '—'}")
            # سطر المقارنة مع نفس الوقت الأسبوع الماضي
            lbl_cmp.config(text="المقارنة مع الأسبوع الماضي: " + monitor_compare_last_week(tmap))
            # المتصلون الآن — من صفوف الجلسات الحية على كل الأجهزة
            online = get_online_users()
            if not online:
                lbl_online.config(text="المتصلون الآن: لا أحد ضمن آخر دقيقتين")
            else:
                segs = []
                for u in online:
                    ld = parse_dt_str(u["login_time"])
                    if ld is not None:
                        mins = max(0, int((datetime.now() - ld).total_seconds() // 60))
                        since = (f"منذ {mins // 60} س و{mins % 60} د" if mins >= 60
                                 else f"منذ {mins} دقيقة")
                    else:
                        since = "منذ —"
                    segs.append(f"{u['username']} (جهاز {u['hostname']}) {since}")
                lbl_online.config(text="المتصلون الآن: " + " • ".join(segs))
            # تنبيهات اليوم — تُمسح وتُعاد كلياً من بيانات اليوم وحدها
            tv_al.delete(*tv_al.get_children())
            large = 5000.0
            try:
                v = to_num(get_alert_setting("alert_large_op_amount"))
                if v is not None and v >= 0:
                    large = v
            except Exception:
                pass
            rlim = 3
            try:
                v = to_num(get_alert_setting("alert_returns_limit"))
                if v is not None and v >= 1:
                    rlim = int(v)
            except Exception:
                pass
            alerts = []
            with connect() as conn:
                big = conn.execute("SELECT * FROM operations WHERE date=? AND type IN "
                                   "('نقداً','شبكة') AND total >= ? ORDER BY total DESC",
                                   (d, large)).fetchall()
            for r in big:
                alerts.append(("عملية كبيرة",
                               f"{r['item_name']} — {money(r['total'])} ({r['type']}) — "
                               f"البائع: {r['seller_name'] or '—'} (الحد {money(large)})"))
            for name, a in agg.items():
                if a["rets"] >= rlim:
                    alerts.append(("مرتجعات كثيرة",
                                   f"{name}: {a['rets']} مرتجعًا اليوم (الحد {rlim}) — "
                                   f"قيمتها {money(a['ret_sum'])}"))
            for s in list_out_of_hours_sessions():
                alerts.append(("دخول خارج الدوام",
                               f"{s['username']} من جهاز {s['hostname']} في {s['login_time']}"))
            if not alerts:
                tv_al.insert("", "end", values=("لا تنبيهات اليوم بحدودها الحالية ✅", "—"))
            else:
                for i, (kind, det) in enumerate(alerts):
                    tv_al.insert("", "end", tags=stripe_tags(i), values=(det, kind))

        b_ref_live = self.mk_btn(head, "🔄 تحديث الآن", refresh_live, "#475569")
        b_ref_live.pack(side="left", pady=6)
        add_tip(b_ref_live, "تحديث كل بيانات اللوحة الحية الآن — وتُحدَّث تلقائياً "
                            "كل 60 ثانية ما دامت النافذة مفتوحة")

        # ══════════════ تبويب «الأنشطة غير الطبيعية» (يتطلب anomalies_report) ══════════════
        topbar = tk.Frame(fr_anom, bg=BG)
        topbar.pack(fill="x", pady=(4, 4))
        period_var = tk.StringVar(value="اليوم")
        cb_period = ttk.Combobox(topbar, textvariable=period_var, state="readonly",
                                 values=["اليوم", "آخر 7 أيام", "كل السجل"],
                                 font=F, width=12, justify="center")
        cb_period.pack(side="right", padx=6)
        add_tip(cb_period, "فترة عرض الأحداث على زمن الحدث نفسه: اليوم / "
                           "آخر 7 أيام / كل السجل")
        lbl_anom_count = tk.Label(topbar, text="", bg=BG, fg=GRAY,
                                  font=("Segoe UI", 10))
        lbl_anom_count.pack(side="left", padx=10)
        frm_an, tv_an = self.mk_tree(fr_anom,
            ["الجهاز", "متى", "من", "التفاصيل", "نوع الحدث"],
            [120, 150, 110, 520, 170])
        tv_an.configure(height=16)
        config_tree_stripes(tv_an)
        enable_tree_sorting(tv_an)
        tv_an.tag_configure("hot", foreground=RED)
        frm_an.pack(fill="both", expand=True, pady=2)
        add_tip(tv_an, "قارئ للسجلات القائمة فقط ولا يُنشئ أي حدث جديد: حذف حركة، "
                       "استرجاع محذوفة، إغلاق يوم متأخر، مرتجع سريع، عملية بتاريخ "
                       "سابق، سعر بيع منخفض، دخول خارج دوام المحل، ومحاولة صلاحية "
                       "غير ممنوحة إن وُجدت — انقر رأس أي عمود للفرز")

        lbl_perm_anom = tk.Label(fr_anom, text="", bg=BG, fg=RED,
                                 font=("Segoe UI", 10, "bold"), anchor="e",
                                 justify="right", wraplength=920)

        def refresh_anom():
            """تحديث قائمة الأنشطة غير الطبيعية — الصلاحية تُفحص هنا أيضاً
            عند كل تحديث (دفاع مزدوج: الفتح + كل تحديث)"""
            if not user_has_permission(self.user_name, "anomalies_report"):
                lbl_perm_anom.config(text="🔒 سُحبت صلاحية «الأنشطة غير الطبيعية» — "
                                          "لا يُعرض هذا التبويب (راجع الأدمن)")
                lbl_perm_anom.pack(fill="x", padx=10, pady=8)
                tv_an.delete(*tv_an.get_children())
                lbl_anom_count.config(text="")
                return
            lbl_perm_anom.pack_forget()
            p = period_var.get()
            period = None if p == "كل السجل" else (0 if p == "اليوم" else 7)
            rows = collect_monitor_anomalies(period)
            tv_an.delete(*tv_an.get_children())
            hot = ("دخول خارج دوام المحل", "حذف حركة")
            for i, r in enumerate(rows):
                extra = ("hot",) if r["kind"] in hot else ()
                tv_an.insert("", "end", tags=stripe_tags(i, False, extra),
                             values=(r["host"], r["when"], r["who"], r["details"], r["kind"]))
            lbl_anom_count.config(text=f"عدد الأحداث: {len(rows)} — {p}")

        b_ref_anom = self.mk_btn(topbar, "🔄 تحديث الآن", refresh_anom, "#475569")
        b_ref_anom.pack(side="right", padx=6)
        add_tip(b_ref_anom, "إعادة قراءة الأنشطة غير الطبيعية للفترة المختارة الآن")
        cb_period.bind("<<ComboboxSelected>>", lambda _e: refresh_anom())

        # ---------- مؤقت التحديث التلقائي الجديد المستقل كل 60 ثانية ----------
        # للوحة الحية حصراً كما نُص في المطلب — يموت مع النافذة فلا يبقى
        # مؤقت بعدها، ولا يلمس مؤقت اليوم التجاري ولا أي مؤقت قائم إطلاقاً
        def auto_refresh():
            if not win.winfo_exists():
                return
            try:
                if st["tab"] == "live":
                    refresh_live()
            except Exception:
                pass
            try:
                st["job"] = win.after(60000, auto_refresh)
            except Exception:
                pass
        st["job"] = win.after(60000, auto_refresh)

        def _on_close_monitor():
            if st["job"] is not None:
                try:
                    win.after_cancel(st["job"])
                except Exception:
                    pass
            win.destroy()
        win.protocol("WM_DELETE_WINDOW", _on_close_monitor)

        # التبويب الأول: اللوحة الحية لمن يملك صلاحيتها وإلا الأنشطة
        _select_tab("live" if user_has_permission(self.user_name, "live_dashboard")
                    else "anom")
        place_window(win, 1020, 720, min_w=880, min_h=560, can_resize=True)

    # ═══════════════════════════════════════════════════════════
    # ★★★ إضافة (المرحلة الثالثة — التقارير الإدارية): النافذة ★★★
    # نافذة واحدة بخمسة تبويبات داخل ttk.Notebook بحجم ثابت معقول، كل
    # تبويب يُنشأ لمن يملك مفتاحه الحرفي من الكتالوج القائم فقط (لا يُنشأ
    # لغيره أصلًا — لا تعطيل رمزي البتة)، والفحص الثاني عند الفتح وكل
    # جامع بيانات يفحصها في بدايته (دفاع متعدد الطبقات مع إخفاء الزر)،
    # وبناء كل تبويب داخل try/except مستقل: فشل أي تبويب يُسجل سببه في
    # error_log.txt وتظهر رسالة عربية قصيرة داخل التبويب وحده وتكمل بقية
    # النافذة عملها — وكل التبويبات قراءة فقط: لا تعديل ولا حذف ولا
    # إدخال بيانات، ولا أي استعلام عند بدء تشغيل البرنامج (كل الحسابات
    # عند فتح النافذة أو عند ضغط زر التحديث)، وبنفس ألوان البرنامج
    # وخطوطه واتجاه RTL وتعليقاته العربية
    # ═══════════════════════════════════════════════════════════
    def show_admin_reports(self):
        """★ إضافة (المرحلة الثالثة): فتح «التقارير الإدارية» — الفحص
        الثاني عند الفتح (دفاع مزدوج مع إخفاء الزر في الشريط الجانبي)"""
        if not admin_reports_permission(self.user_name):
            b = getattr(self, "nav_buttons", {}).get("admin_reports")
            if b is not None:
                b.pack_forget()   # زر متقادم بعد تبديل المستخدم: يُخفى فورًا
            messagebox.showwarning("لا تملك صلاحية",
                "التقارير الإدارية تتطلب واحدة على الأقل من صلاحيات التقارير "
                "الخمس:\nالملخص الصباحي / التقرير الأسبوعي / الانضباط / "
                "فحص صحة النظام / مراقبة النسخ الاحتياطي — راجع الأدمن")
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("التقارير الإدارية")
        win.configure(bg=BG)
        # نمط خاص بهذه النافذة وحدها لتبويبات الدفتر — لا يُمس أي نمط قائم
        try:
            _st = ttk.Style(win)
            _st.configure("AdminReports.TNotebook.Tab",
                          font=("Segoe UI", 10, "bold"), padding=(16, 9))
        except Exception:
            pass
        nb = ttk.Notebook(win, style="AdminReports.TNotebook")
        nb.pack(fill="both", expand=True, padx=12, pady=12)

        def _add_tab(key, title, builder):
            """★ إضافة (المرحلة الثالثة): إنشاء تبويب واحد لمن يملك مفتاحه
            فقط، وبناء محتواه داخل try/except مستقل — فشل البناء يُسجل في
            error_log.txt ويظهر نص عربي قصير داخل التبويب وحده ولا يمس
            بقية التبويبات أبدًا"""
            if not user_has_permission(self.user_name, key):
                return               # لا يملك المفتاح: لا يُنشأ التبويب أصلًا
            tab = tk.Frame(nb, bg=BG)
            try:
                builder(tab)
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                tk.Label(tab, text="⚠️ تعذر بناء هذا التبويب — سُجّل السبب في "
                                   "error_log.txt وبقية التبويبات تعمل",
                         bg=BG, fg=RED, font=FB).pack(expand=True)
            nb.add(tab, text=title)

        _add_tab("morning_summary", "📋 الملخص الصباحي",
                 self._build_morning_summary_tab)
        _add_tab("weekly_report", "📅 التقرير الأسبوعي",
                 self._build_weekly_report_tab)
        _add_tab("discipline_report", "⏰ الانضباط",
                 self._build_discipline_tab)
        _add_tab("system_health_view", "🩺 فحص صحة النظام",
                 self._build_system_health_tab)
        _add_tab("backup_monitor_view", "🗄️ مراقبة النسخ الاحتياطي",
                 self._build_backup_monitor_tab)
        # ★ إضافة (كشف الصندوق): التبويب السادس — يُبنى لمن يملك
        # cash_box_view فقط بنفس آلية _add_tab القائمة (إخفاء لا
        # تعطيل)، ومنطق فتح النافذة نفسه لا يتغير (مفاتيح التقارير
        # الخمسة كما هي)
        _add_tab("cash_box_view", "💰 كشف الصندوق",
                 self._build_cash_box_tab)
        # ★ إضافة (ميزة «المصروفات»): التبويب السابع — يُبنى لمن يملك
        # expense_report فقط بنفس آلية _add_tab القائمة (إخفاء لا
        # تعطيل)، وزر الحذف داخله أدمن حصريًا بلا مفتاح جديد، ومنطق فتح
        # النافذة نفسه توسع لمفتاح التقرير الجديد وحده
        # (admin_reports_permission) — والمفاتيح الخمسة كما هي
        _add_tab("expense_report", "💸 المصروفات",
                 self._build_expenses_report_tab)

        if not nb.tabs():
            # سُحبت كل صلاحيات التقارير بعد ظهور الزر: رسالة داخل النافذة
            tk.Label(win, text="لا تملك صلاحية أي تقرير من التقارير الإدارية — "
                               "راجع الأدمن",
                     bg=BG, fg=RED, font=FT).pack(expand=True)
        place_window(win, 950, 720, min_w=900, min_h=640, can_resize=False)

    def _build_cash_box_tab(self, fr):
        """★ إضافة (كشف الصندوق — التبويب السادس في «التقارير الإدارية»):
        حركة النقدية (داخل / خارج / الصافي) لأي فترة تجارية بقاعدة
        05:00 نفسها مع تصفية البائع، وجدول تفصيلي لكل حركة نقدية
        بوقتها الحقيقي من مطابق سجل التدقيق القائم (قراءة فقط) وصفوف
        الداخل بلون وصفوف الخارج بلون آخر، وحاسبة تسوية يدوية (رصيد
        افتتاحي + صافي الحركة مقابل النقد الفعلي) بلا أي حفظ في قاعدة
        البيانات، وزر حفظ نسخة نصية utf-8 في data_dir/reports — وكل دالة
        حساب أو حفظ تبدأ بفحص الصلاحية مجددًا (الطبقة الثانية بعد إخفاء
        التبويب لمن لا يملكه)"""
        state = {"data": None, "f": "", "t": "", "period": "", "net": 0.0}
        PERIODS7 = ("اليوم التجاري الحالي", "أمس (تجاري)", "آخر 7 أيام",
                    "هذا الشهر", "مخصص (من – إلى)")
        # ---------- صف الفترة والبائع وزر التحديث ----------
        bar = tk.Frame(fr, bg=BG)
        bar.pack(fill="x", padx=14, pady=(12, 2))
        tk.Label(bar, text="الفترة:", bg=BG, fg=DARK, font=FB).pack(
            side="right", padx=(0, 4))
        pvar = tk.StringVar(value=PERIODS7[0])
        cb_p = ttk.Combobox(bar, textvariable=pvar, state="readonly",
                            values=list(PERIODS7), font=F, width=18,
                            justify="center")
        cb_p.pack(side="right", padx=4)
        add_tip(cb_p, "فترة الكشف — عند «مخصص» يظهر حقلا من/إلى "
                      "(الصيغ المقبولة: 2026-01-10 أو 10-01-2026 أو 10/01/2026 "
                      "وبالأرقام العربية أيضًا)")
        # حقلا الفترة المخصصة داخل إطار دائم الترتيب (يُفرَّغ محتواه
        # عند غير «مخصص» فلا يختل ترتيب الصف)
        fr_custom = tk.Frame(bar, bg=BG)
        fr_custom.pack(side="right", padx=2)
        e_from = tk.Entry(fr_custom, font=F, justify="center",
                          relief="solid", bd=1, width=11)
        e_to = tk.Entry(fr_custom, font=F, justify="center",
                        relief="solid", bd=1, width=11)
        tk.Label(bar, text="البائع:", bg=BG, fg=DARK, font=FB).pack(
            side="right", padx=(14, 4))
        svar = tk.StringVar(value="كل البائعين")
        cb_s = ttk.Combobox(bar, textvariable=svar, state="readonly",
                            values=cash_box_seller_options(), font=F,
                            width=15, justify="center")
        cb_s.pack(side="right", padx=4)
        add_tip(cb_s, "تصفية الكشف بعمليات بائع واحد: فواتيره وتحصيلاته "
                      "ومرتجعاته وحدها")
        b_upd = self.mk_btn(bar, "🔄 تحديث", lambda: refresh(), ACCENT)
        b_upd.pack(side="left", padx=6)
        add_tip(b_upd, "إعادة حساب الكشف حسب الفترة والبائع المحددين")

        def _show_custom7():
            for w in (e_from, e_to):
                w.pack_forget()
            for w in fr_custom.winfo_children():
                if isinstance(w, tk.Label):
                    w.pack_forget()
            if pvar.get() == "مخصص (من – إلى)":
                if not e_from.get().strip():
                    try:
                        e_from.insert(0, get_business_day())
                    except Exception:
                        pass
                if not e_to.get().strip():
                    try:
                        e_to.insert(0, get_business_day())
                    except Exception:
                        pass
                tk.Label(fr_custom, text="إلى:", bg=BG, fg=DARK,
                         font=FB).pack(side="right")
                e_to.pack(side="right", padx=(2, 0))
                tk.Label(fr_custom, text="من:", bg=BG, fg=DARK,
                         font=FB).pack(side="right")
                e_from.pack(side="right", padx=(2, 4))
        cb_p.bind("<<ComboboxSelected>>", lambda e: _show_custom7())
        _show_custom7()

        # ---------- البطاقات الثلاث الكبيرة ----------
        cards_fr = tk.Frame(fr, bg=BG)
        cards_fr.pack(fill="x", padx=14, pady=4)
        c_in = self.mk_card(cards_fr, "نقد داخل", GREEN)
        c_out = self.mk_card(cards_fr, "نقد خارج", RED)
        c_net = self.mk_card(cards_fr, "صافي الحركة", ACCENT)
        for c in (c_in, c_out, c_net):
            c[0].pack(side="right", fill="x", expand=True, padx=3)

        lbl_desc = tk.Label(fr, text="", bg=BG, fg=GRAY,
                            font=("Segoe UI", 10, "bold"), anchor="e")
        lbl_desc.pack(fill="x", padx=14, pady=(2, 0))
        lbl_perm = tk.Label(fr, text="", bg=BG, fg=RED,
                            font=("Segoe UI", 10, "bold"), anchor="e")

        # ---------- الجدول التفصيلي للحركات النقدية ----------
        frm_t, tv = self.mk_tree(fr,
                                 ["الوقت", "النوع", "رقم الفاتورة", "العميل",
                                  "البائع", "المبلغ", "ملاحظة"],
                                 [120, 140, 85, 150, 105, 115, 200])
        tv.column("المبلغ", anchor="e")
        tv.column("ملاحظة", anchor="w")
        try:
            tv.tag_configure("cb_in", background="#dcfce7")
            tv.tag_configure("cb_out", background="#fee2e2")
        except Exception:
            pass
        frm_t.pack(fill="both", expand=True, padx=14)
        add_tip(tv, "كل حركة نقدية في الفترة مرتبة زمنيًا — الأخضر داخل "
                    "والوردي خارج، والوقت الحقيقي من سجل التدقيق حيثما وُجد")

        # ---------- حاسبة التسوية اليدوية (بلا أي حفظ في القاعدة) ----------
        set_fr = tk.Frame(fr, bg=CARD, highlightbackground=BORDER,
                          highlightthickness=1)
        set_fr.pack(fill="x", padx=14, pady=(6, 12))
        tk.Label(set_fr, text="🧮 حاسبة تسوية الدرج (يدوية — لا تُحفظ في "
                              "قاعدة البيانات)", bg=CARD, fg=DARK,
                 font=("Segoe UI", 10, "bold")).pack(pady=(8, 2))
        row7 = tk.Frame(set_fr, bg=CARD)
        row7.pack(fill="x", padx=10, pady=4)
        tk.Label(row7, text="رصيد افتتاحي:", bg=CARD, fg=GRAY,
                 font=FB).pack(side="right", padx=(0, 4))
        e_open = tk.Entry(row7, font=F, justify="center", relief="solid",
                          bd=1, width=12)
        e_open.pack(side="right", padx=(0, 14))
        digits_only_filter(e_open)
        tk.Label(row7, text="النقد الفعلي في الدرج:", bg=CARD, fg=GRAY,
                 font=FB).pack(side="right", padx=(0, 4))
        e_actual = tk.Entry(row7, font=F, justify="center", relief="solid",
                            bd=1, width=12)
        e_actual.pack(side="right", padx=(0, 14))
        digits_only_filter(e_actual)
        b_clear = self.mk_btn(row7, "🧹 تفريغ الحقول",
                              lambda: _clear_settle7(), "#64748b")
        b_clear.pack(side="left", padx=6)
        add_tip(b_clear, "تفريغ حقلي الرصيد الافتتاحي والنقد الفعلي")
        b_save = self.mk_btn(row7, "💾 حفظ نسخة نصية",
                             lambda: save_text(), "#0d9488")
        b_save.pack(side="left", padx=6)
        add_tip(b_save, "حفظ تقرير الكشف نصًا منسقًا بترميز utf-8 في مجلد "
                        "reports بجانب قاعدة البيانات")
        res7 = tk.Frame(set_fr, bg=CARD)
        res7.pack(fill="x", padx=10, pady=(2, 8))
        lbl_exp7 = tk.Label(res7,
                            text="المتوقع في الدرج = رصيد افتتاحي + صافي "
                                 "الحركة: —", bg=CARD, fg=DARK,
                            font=("Segoe UI", 11, "bold"), anchor="e")
        lbl_exp7.pack(fill="x")
        lbl_res7 = tk.Label(res7, text="النتيجة: —", bg=CARD, fg=GRAY,
                            font=("Segoe UI", 11, "bold"), anchor="e")
        lbl_res7.pack(fill="x")

        def _settle7(_e=None):
            """الطبقة الثانية: فحص الصلاحية أول كل حساب تسوية"""
            if not user_has_permission(self.user_name, "cash_box_view"):
                lbl_exp7.config(text="المتوقع في الدرج = رصيد افتتاحي + "
                                     "صافي الحركة: —", fg=GRAY)
                lbl_res7.config(text="النتيجة: —", fg=GRAY)
                return
            try:
                _op7 = to_num(e_open.get())
                _ac7 = to_num(e_actual.get())
                _op7 = (0.0 if _op7 is None else _op7)
                _net7 = float(state.get("net") or 0.0)
                _exp7 = _op7 + _net7
                lbl_exp7.config(text="المتوقع في الدرج = رصيد افتتاحي + "
                                     f"صافي الحركة: {money(_exp7)}",
                                fg=DARK)
                if _ac7 is None:
                    lbl_res7.config(text="النتيجة: أدخل النقد الفعلي في "
                                         "الدرج", fg=GRAY)
                    return
                _dif7 = _ac7 - _exp7
                if abs(_dif7) < 0.005:
                    lbl_res7.config(text="النتيجة: مطابق تمامًا ✔", fg=GREEN)
                elif _dif7 > 0:
                    lbl_res7.config(text=f"النتيجة: زيادة {money(_dif7)}",
                                    fg=ORANGE)
                else:
                    lbl_res7.config(text=f"النتيجة: عجز {money(-_dif7)}",
                                    fg=RED)
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                lbl_res7.config(text="النتيجة: —", fg=GRAY)

        def _clear_settle7():
            try:
                e_open.delete(0, "end")
                e_actual.delete(0, "end")
                _settle7()
            except Exception as e:
                log_error(e, sys.exc_info()[2])

        e_open.bind("<KeyRelease>", _settle7)
        e_actual.bind("<KeyRelease>", _settle7)

        def _clear_view7():
            tv.delete(*tv.get_children())
            c_in[1].config(text="0.00")
            c_out[1].config(text="0.00")
            c_net[1].config(text="0.00", fg=ACCENT)
            lbl_desc.config(text="")

        def refresh():
            """الطبقة الثانية: فحص الصلاحية أول كل حساب للكشف (بعد إخفاء
            التبويب) — ثم تحديد الفترة (اليوم التجاري بقاعدة 05:00 نفسها
            من get_business_day القائمة حصرًا) وتصفية البائع"""
            if not user_has_permission(self.user_name, "cash_box_view"):
                lbl_perm.config(text="🔒 لا تملك صلاحية «كشف الصندوق» — "
                                     "راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                _clear_view7()
                state["data"] = None
                state["net"] = 0.0
                _settle7()
                return
            try:
                _p7 = pvar.get()
                _bd7 = get_business_day()
                if _p7 == PERIODS7[0]:
                    _f7 = _t7 = _bd7
                elif _p7 == PERIODS7[1]:
                    _ds7 = last_business_days(2)
                    _f7 = _t7 = (_ds7[1] if len(_ds7) > 1 else _ds7[0])
                elif _p7 == PERIODS7[2]:
                    _ds7 = last_business_days(7)
                    _f7, _t7 = min(_ds7), max(_ds7)
                elif _p7 == PERIODS7[3]:
                    _f7 = _bd7[:8] + "01"
                    _t7 = _bd7
                else:
                    _f7 = parse_date_multi(e_from.get())
                    _t7 = parse_date_multi(e_to.get())
                    if _f7 is None or _t7 is None:
                        messagebox.showwarning("تاريخ خاطئ",
                            "صيغة تاريخ غير صحيحة في «من» أو «إلى»\n"
                            "الصيغ المقبولة: 2026-01-10 أو 10-01-2026 "
                            "أو 10/01/2026", parent=fr.winfo_toplevel())
                        return
                    if _f7 == "" or _t7 == "":
                        messagebox.showwarning("فترة ناقصة",
                            "أدخل تاريخي «من» و«إلى» معًا للفترة المخصصة",
                            parent=fr.winfo_toplevel())
                        return
                    if _f7 > _t7:
                        messagebox.showwarning("فترة غير صحيحة",
                            "تاريخ «من» يجب أن يكون قبل تاريخ «إلى» أو "
                            "مساويًا له", parent=fr.winfo_toplevel())
                        return
                _sel7 = (None if svar.get() == "كل البائعين"
                         else svar.get())
                r = cash_box_period_data(self.user_name, _f7, _t7, _sel7)
                if r is None:
                    lbl_perm.config(text="🔒 لا تملك صلاحية «كشف الصندوق» "
                                         "— راجع الأدمن")
                    lbl_perm.pack(fill="x", padx=14, pady=6)
                    _clear_view7()
                    state["data"] = None
                    state["net"] = 0.0
                    _settle7()
                    return
                lbl_perm.pack_forget()
                state.update({"data": r, "f": _f7, "t": _t7,
                              "period": _p7, "net": r["net"]})
                c_in[1].config(text=money(r["cash_in"]))
                c_out[1].config(text=money(r["cash_out"]))
                c_net[1].config(text=money(r["net"]),
                                fg=(GREEN if r["net"] >= 0 else RED))
                lbl_desc.config(
                    text=f"الفترة: من {_f7} إلى {_t7} ({_p7}) — البائع: "
                         f"{svar.get()} — عدد الحركات النقدية: "
                         f"{len(r['movements'])}")
                tv.delete(*tv.get_children())
                if not r["movements"]:
                    tv.insert("", "end",
                              values=("لا حركات نقدية في هذه الفترة",
                                      "—", "—", "—", "—", "—", "—"))
                else:
                    for m in r["movements"]:
                        tv.insert("", "end",
                                  tags=(("cb_in" if m["amount"] >= 0
                                         else "cb_out"),),
                                  values=(m["time"], m["kind"], m["invoice"],
                                          m["customer"], m["seller"],
                                          money(m["amount"]), m["note"]))
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                lbl_perm.config(text="⚠️ تعذر حساب كشف الصندوق — سُجّل السبب "
                                     "في error_log.txt")
                lbl_perm.pack(fill="x", padx=14, pady=6)
            _settle7()

        def save_text():
            """الطبقة الثانية: فحص الصلاحية قبل أي حفظ نصي"""
            if not user_has_permission(self.user_name, "cash_box_view"):
                messagebox.showwarning("لا تملك صلاحية",
                    "لا تملك صلاحية «كشف الصندوق» — لم يُحفظ شيء",
                    parent=fr.winfo_toplevel())
                return
            try:
                if state.get("data") is None:
                    refresh()
                if state.get("data") is None:
                    messagebox.showinfo("تنبيه", "لا توجد بيانات كشف لحفظها",
                                        parent=fr.winfo_toplevel())
                    return
                _op7 = to_num(e_open.get())
                _ac7 = to_num(e_actual.get())
                _store7 = (get_setting("store_name")
                           or "نظام المبيعات والمُرتجعات")
                ok7, msg7 = cash_box_save_text_file(
                    self.user_name, _store7, state["period"], state["f"],
                    state["t"], svar.get(), state["data"], _op7, _ac7)
                if ok7:
                    messagebox.showinfo("تم الحفظ",
                        "حُفظت النسخة النصية بنجاح في:\n" + msg7,
                        parent=fr.winfo_toplevel())
                else:
                    messagebox.showerror("تعذر الحفظ", msg7,
                                         parent=fr.winfo_toplevel())
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                messagebox.showerror("تعذر الحفظ",
                    "تعذر حفظ النسخة النصية — سُجّل السبب في error_log.txt",
                    parent=fr.winfo_toplevel())

        refresh()

    def _build_expenses_report_tab(self, fr):
        """★ إضافة (ميزة «المصروفات» — التبويب السابع في «التقارير
        الإدارية»): مصروفات المحل لأي فترة تجارية بقاعدة 05:00 نفسها
        (اليوم التجاري / أمس / آخر 7 أيام / هذا الشهر / مخصص من–إلى) مع
        بحث نصي في الملاحظة يشمل النوع، وجدول (التاريخ والوقت / المستخدم
        / النوع / الملاحظة / المبلغ) بأرقام مفصولة الآلاف ومحاذاة مناسبة،
        وإجمالي كبير أعلى الجدول وثلاث بطاقات صغيرة (إجمالي الفترة /
        عدد العمليات / أعلى مصروف)، وزر حذف المصروف المحدد أدمن حصريًا
        (الطبقة الأولى: لا يُبنى لغيره أصلًا — بلا مفتاح جديد) بتأكيد
        يذكر المبلغ والملاحظة ويُسجَّل الحذف في error_log.txt للتدقيق —
        وكل حساب أو حذف يبدأ بفحص الصلاحية مجددًا (الطبقة الثانية بعد
        إخفاء التبويب لمن لا يملكه)"""
        state = {"ids": {}}
        PERIODS8 = ("اليوم التجاري الحالي", "أمس (تجاري)", "آخر 7 أيام",
                    "هذا الشهر", "مخصص (من – إلى)")
        # ---------- صف الفترة والبحث وزرا التحديث والحذف ----------
        bar = tk.Frame(fr, bg=BG)
        bar.pack(fill="x", padx=14, pady=(12, 2))
        tk.Label(bar, text="الفترة:", bg=BG, fg=DARK, font=FB).pack(
            side="right", padx=(0, 4))
        pvar = tk.StringVar(value=PERIODS8[0])
        cb_p = ttk.Combobox(bar, textvariable=pvar, state="readonly",
                            values=list(PERIODS8), font=F, width=18,
                            justify="center")
        cb_p.pack(side="right", padx=4)
        add_tip(cb_p, "فترة تقرير المصروفات — عند «مخصص» يظهر حقلا من/إلى "
                      "(الصيغ المقبولة: 2026-01-10 أو 10-01-2026 أو "
                      "10/01/2026 وبالأرقام العربية أيضًا)")
        # حقلا الفترة المخصصة داخل إطار دائم الترتيب (نفس أسلوب كشف
        # الصندوق القائم حرفيًا)
        fr_custom = tk.Frame(bar, bg=BG)
        fr_custom.pack(side="right", padx=2)
        e_from = tk.Entry(fr_custom, font=F, justify="center",
                          relief="solid", bd=1, width=11)
        e_to = tk.Entry(fr_custom, font=F, justify="center",
                        relief="solid", bd=1, width=11)
        tk.Label(bar, text="بحث:", bg=BG, fg=DARK, font=FB).pack(
            side="right", padx=(14, 4))
        e_search = tk.Entry(bar, font=F, justify="center", relief="solid",
                            bd=1, width=16)
        e_search.pack(side="right", padx=4)
        add_tip(e_search, "بحث نصي داخل الملاحظة والنوع معًا — اضغط Enter "
                          "أو زر التحديث للتنفيذ (مثال: نقل)")
        e_search.bind("<Return>", lambda e: refresh())
        b_upd = self.mk_btn(bar, "🔄 تحديث", lambda: refresh(), ACCENT)
        b_upd.pack(side="left", padx=6)
        add_tip(b_upd, "إعادة حساب تقرير المصروفات حسب الفترة والبحث")
        # زر الحذف — الطبقة الأولى (إخفاء لا تعطيل): أدمن حصريًا بلا
        # مفتاح جديد، لا يُبنى أصلًا لغير الأدمن حتى لو ملك expense_report
        if self.role == ADMIN_ROLE:
            b_del = self.mk_btn(bar, "🗑 حذف المحدد",
                                lambda: delete_selected(), RED)
            b_del.pack(side="left", padx=6)
            add_tip(b_del, "حذف المصروف المحدد نهائيًا — أدمن حصريًا، مع "
                           "تأكيد يذكر المبلغ والملاحظة، ويُسجَّل الحذف في "
                           "error_log.txt للتدقيق")

        def _show_custom8():
            for w in (e_from, e_to):
                w.pack_forget()
            for w in fr_custom.winfo_children():
                if isinstance(w, tk.Label):
                    w.pack_forget()
            if pvar.get() == "مخصص (من – إلى)":
                if not e_from.get().strip():
                    try:
                        e_from.insert(0, get_business_day())
                    except Exception:
                        pass
                if not e_to.get().strip():
                    try:
                        e_to.insert(0, get_business_day())
                    except Exception:
                        pass
                tk.Label(fr_custom, text="إلى:", bg=BG, fg=DARK,
                         font=FB).pack(side="right")
                e_to.pack(side="right", padx=(2, 0))
                tk.Label(fr_custom, text="من:", bg=BG, fg=DARK,
                         font=FB).pack(side="right")
                e_from.pack(side="right", padx=(2, 4))

        def _on_period8(_e=None):
            _show_custom8()
            refresh()
        cb_p.bind("<<ComboboxSelected>>", _on_period8)
        _show_custom8()

        # ---------- البطاقات الصغيرة الثلاث ----------
        cards_fr = tk.Frame(fr, bg=BG)
        cards_fr.pack(fill="x", padx=14, pady=4)
        c_total = self.mk_card(cards_fr, "إجمالي الفترة", DARK)
        c_count = self.mk_card(cards_fr, "عدد العمليات", ACCENT)
        c_high = self.mk_card(cards_fr, "أعلى مصروف", RED)
        for c in (c_total, c_count, c_high):
            c[0].pack(side="right", fill="x", expand=True, padx=3)

        # ---------- الإجمالي الكبير أعلى الجدول ----------
        lbl_big = tk.Label(fr, text="إجمالي مصروفات الفترة: 0.00",
                           bg=BG, fg=DARK, font=("Segoe UI", 14, "bold"),
                           anchor="e")
        lbl_big.pack(fill="x", padx=14, pady=(4, 0))
        lbl_desc = tk.Label(fr, text="", bg=BG, fg=GRAY,
                            font=("Segoe UI", 10, "bold"), anchor="e")
        lbl_desc.pack(fill="x", padx=14, pady=(2, 0))
        lbl_perm = tk.Label(fr, text="", bg=BG, fg=RED,
                            font=("Segoe UI", 10, "bold"), anchor="e")

        # ---------- الجدول ----------
        frm_t, tv = self.mk_tree(
            fr, ["التاريخ والوقت", "المستخدم", "النوع", "الملاحظة", "المبلغ"],
            [140, 110, 110, 260, 115])
        tv.column("المبلغ", anchor="e")
        tv.column("الملاحظة", anchor="w")
        config_tree_stripes(tv)
        frm_t.pack(fill="both", expand=True, padx=14)
        add_tip(tv, "مصروفات الفترة من الأحدث إلى الأقدم — كل مصروف يُنسب "
                    "ليومه التجاري بقاعدة 05:00")

        def _clear_view8():
            tv.delete(*tv.get_children())
            state["ids"] = {}
            c_total[1].config(text="0.00")
            c_count[1].config(text="0")
            c_high[1].config(text="0.00")
            lbl_big.config(text="إجمالي مصروفات الفترة: 0.00")
            lbl_desc.config(text="")

        def refresh():
            """الطبقة الثانية: فحص الصلاحية أول كل حساب للتقرير (بعد إخفاء
            التبويب لمن لا يملكه) — ثم تحديد الفترة التجارية بنفس آلية
            كشف الصندوق القائمة حرفيًا وتنفيذ البحث النصي"""
            if not (self.role == ADMIN_ROLE
                    or user_has_permission(self.user_name,
                                           "expense_report")):
                lbl_perm.config(text="🔒 لا تملك صلاحية «عرض تقرير "
                                     "المصروفات» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                _clear_view8()
                return
            try:
                _p8 = pvar.get()
                _bd8 = get_business_day()
                if _p8 == PERIODS8[0]:
                    _f8 = _t8 = _bd8
                elif _p8 == PERIODS8[1]:
                    _ds8 = last_business_days(2)
                    _f8 = _t8 = (_ds8[1] if len(_ds8) > 1 else _ds8[0])
                elif _p8 == PERIODS8[2]:
                    _ds8 = last_business_days(7)
                    _f8, _t8 = min(_ds8), max(_ds8)
                elif _p8 == PERIODS8[3]:
                    _f8 = _bd8[:8] + "01"
                    _t8 = _bd8
                else:
                    _f8 = parse_date_multi(e_from.get())
                    _t8 = parse_date_multi(e_to.get())
                    if _f8 is None or _t8 is None:
                        messagebox.showwarning("تاريخ خاطئ",
                            "صيغة تاريخ غير صحيحة في «من» أو «إلى»\n"
                            "الصيغ المقبولة: 2026-01-10 أو 10-01-2026 "
                            "أو 10/01/2026", parent=fr.winfo_toplevel())
                        return
                    if _f8 == "" or _t8 == "":
                        messagebox.showwarning("فترة ناقصة",
                            "أدخل تاريخي «من» و«إلى» معًا للفترة المخصصة",
                            parent=fr.winfo_toplevel())
                        return
                    if _f8 > _t8:
                        messagebox.showwarning("فترة غير صحيحة",
                            "تاريخ «من» يجب أن يكون قبل تاريخ «إلى» أو "
                            "مساويًا له", parent=fr.winfo_toplevel())
                        return
                r = expenses_report_data(self.user_name, _f8, _t8,
                                         e_search.get())
                if r is None:
                    lbl_perm.config(text="🔒 لا تملك صلاحية «عرض تقرير "
                                         "المصروفات» — راجع الأدمن")
                    lbl_perm.pack(fill="x", padx=14, pady=6)
                    _clear_view8()
                    return
                lbl_perm.pack_forget()
                tv.delete(*tv.get_children())
                state["ids"] = {}
                for i, row in enumerate(r["rows"]):
                    _iid8 = tv.insert(
                        "", "end", tags=stripe_tags(i), values=(
                            (row["created_at"] or "—")[:16],
                            row["username"] or "—",
                            row["category"] or "—",
                            row["note"] or "",
                            money(row["amount"])))
                    state["ids"][_iid8] = row["id"]
                if not r["rows"]:
                    tv.insert("", "end", values=(
                        "لا مصروفات في هذه الفترة", "—", "—", "", "—"))
                c_total[1].config(text=money(r["total"]))
                c_count[1].config(text=str(r["count"]))
                c_high[1].config(text=money(r["highest"]))
                lbl_big.config(text="إجمالي مصروفات الفترة: "
                                    + money(r["total"]))
                lbl_desc.config(
                    text=f"الفترة: من {_f8} إلى {_t8} ({_p8})"
                         + (f" — البحث: «{e_search.get().strip()}»"
                            if e_search.get().strip() else ""))
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                lbl_perm.config(text="⚠️ تعذر حساب تقرير المصروفات — سُجّل "
                                     "السبب في error_log.txt")
                lbl_perm.pack(fill="x", padx=14, pady=6)

        def delete_selected():
            """الطبقة الثانية المزدوجة: expense_report ثم أدمنية المنفّذ —
            وتأكيد يذكر المبلغ والملاحظة قبل أي حذف، والحذف نفسه يعيد
            الفحص ثالثة داخل expense_delete_row"""
            if not (self.role == ADMIN_ROLE
                    and user_has_permission(self.user_name,
                                            "expense_report")):
                messagebox.showwarning(
                    "لا تملك صلاحية",
                    "حذف المصروفات متاح للأدمن فقط — راجع الأدمن",
                    parent=fr.winfo_toplevel())
                return
            try:
                _sel8 = tv.selection()
                if not _sel8:
                    messagebox.showwarning(
                        "لا تحديد",
                        "اختر مصروفًا من الجدول أولًا ثم اضغط «حذف المحدد»",
                        parent=fr.winfo_toplevel())
                    return
                _id8 = state["ids"].get(_sel8[0])
                if _id8 is None:
                    messagebox.showwarning(
                        "لا تحديد", "اختر مصروفًا من الجدول أولًا",
                        parent=fr.winfo_toplevel())
                    return
                _vals8 = tv.item(_sel8[0], "values")
                _amt8 = str(_vals8[4] if len(_vals8) > 4 else "—")
                _typ8 = str(_vals8[2] if len(_vals8) > 2 else "—")
                _note8 = str(_vals8[3] if len(_vals8) > 3 else "—")
                if not messagebox.askyesno(
                        "تأكيد الحذف",
                        "هل تريد حذف هذا المصروف نهائيًا؟\n\n"
                        f"المبلغ: {_amt8}\nالنوع: {_typ8}\n"
                        f"الملاحظة: {_note8}\n\nسيختفي من التقرير ومن كشف "
                        "الصندوق فورًا ويُسجَّل الحذف في error_log.txt",
                        parent=fr.winfo_toplevel()):
                    return
                ok8, msg8 = expense_delete_row(self.user_name, _id8)
                if ok8:
                    refresh()
                    messagebox.showinfo("تم الحذف", msg8,
                                        parent=fr.winfo_toplevel())
                else:
                    messagebox.showwarning("تعذر الحذف", msg8,
                                           parent=fr.winfo_toplevel())
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                messagebox.showerror(
                    "خطأ", "تعذر حذف المصروف — سُجّل السبب في error_log.txt",
                    parent=fr.winfo_toplevel())

        tk.Label(fr, text="كل مصروف مسجل يُخصم تلقائيًا في كشف الصندوق ضمن "
                          "«نقد خارج» — والحذف أدمن حصريًا ويُسجَّل في "
                          "error_log.txt",
                 bg=BG, fg=GRAY, font=("Segoe UI", 9), anchor="e").pack(
                     fill="x", padx=14, pady=(2, 10))
        refresh()

    def _build_morning_summary_tab(self, fr):
        """★ إضافة (المرحلة الثالثة — التبويب 1): الملخص الصباحي — آخر 30
        يومًا تجاريًا في قائمة منسدلة جاهزة (افتراضيًا أمس التجاري — لا حقل
        إدخال تاريخ يدوي إطلاقًا) وبطاقات أرقام اليوم المختار وجدولا أعلى 5
        منتجات مبيعًا وإجماليات البائعين مع عدد الفواتير — قراءة فقط"""
        bar = tk.Frame(fr, bg=BG)
        bar.pack(fill="x", padx=14, pady=(12, 2))
        tk.Label(bar, text="اليوم التجاري:", bg=BG, fg=DARK, font=FB).pack(
            side="right", padx=(0, 6))
        days = last_business_days(30)
        yest = days[1] if len(days) > 1 else days[0]     # افتراضيًا أمس التجاري
        dvar = tk.StringVar(value=f"{yest} ({day_name(yest)})")
        cb = ttk.Combobox(bar, textvariable=dvar, state="readonly",
                          values=[f"{d} ({day_name(d)})" for d in days],
                          font=F, width=22, justify="center")
        cb.pack(side="right", padx=4)
        add_tip(cb, "اختيار اليوم التجاري من آخر 30 يومًا جاهزة — افتراضيًا أمس التجاري")

        cards_fr = tk.Frame(fr, bg=BG)
        cards_fr.pack(fill="x", padx=14, pady=4)
        c_sales = self.mk_card(cards_fr, "إجمالي المبيعات", GREEN)
        c_rets = self.mk_card(cards_fr, "إجمالي المرتجعات", RED)
        c_net = self.mk_card(cards_fr, "الصافي", DARK)
        c_sc = self.mk_card(cards_fr, "عدد عمليات البيع", ACCENT)
        c_rc = self.mk_card(cards_fr, "عدد المرتجعات", ORANGE)
        cards = [c_sales, c_rets, c_net, c_sc, c_rc]
        # بطاقة المقبوضات تُبنى فقط إن وُجد جدول للمقبوضات في القاعدة
        have_receipts = (_reports_receipts_table() is not None)
        if have_receipts:
            c_rec = self.mk_card(cards_fr, "إجمالي المقبوضات", "#0d9488")
            cards.append(c_rec)
        for c in cards:
            c[0].pack(side="right", fill="x", expand=True, padx=3)

        lbl_perm = tk.Label(fr, text="", bg=BG, fg=RED,
                            font=("Segoe UI", 10, "bold"), anchor="e",
                            justify="right", wraplength=900)
        lbl_top = tk.Label(fr, text="🏆 أعلى 5 منتجات مبيعًا", bg=BG, fg=DARK,
                           font=("Segoe UI", 10, "bold"), anchor="e")
        lbl_top.pack(fill="x", padx=14, pady=(4, 0))
        frm_t, tv_t = self.mk_tree(fr, ["الإجمالي", "الكمية", "المنتج"],
                                   [170, 110, 420])
        tv_t.configure(height=5)
        config_tree_stripes(tv_t)
        enable_tree_sorting(tv_t)
        frm_t.pack(fill="x", padx=14)
        add_tip(tv_t, "أعلى 5 أصناف مبيعًا في اليوم المختار — انقر رأس أي عمود للفرز")

        lbl_sel = tk.Label(fr, text="👤 إجماليات البائعين", bg=BG, fg=DARK,
                           font=("Segoe UI", 10, "bold"), anchor="e")
        lbl_sel.pack(fill="x", padx=14, pady=(6, 0))
        frm_s, tv_s = self.mk_tree(fr, ["الإجمالي", "عدد الفواتير", "البائع"],
                                   [170, 130, 400])
        tv_s.configure(height=5)
        config_tree_stripes(tv_s)
        enable_tree_sorting(tv_s)
        frm_s.pack(fill="both", expand=True, padx=14, pady=(0, 10))
        add_tip(tv_s, "إجمالي مبيعات كل بائع في اليوم المختار وعدد فواتيره من سجل "
                      "التدقيق — انقر رأس أي عمود للفرز")

        # ★★★ إضافة (موعد التحصيل): قسم «مستحقات التحصيل» — يُبنى حصريًا لمن
        # يملك collections_list (الطبقة الأولى: إخفاء لا تعطيل — القسم لا
        # يُبنى أصلًا لغيره)، ويعرض الديون ذات المواعيد: اسم العميل والمبلغ
        # المتبقي وموعد التحصيل ورقم الهاتف والحالة (متأخر X يوم / مستحق
        # اليوم / بعد Y يوم) — المتأخرة أولًا ثم مستحقة اليوم ثم أقرب
        # القادمة بحد أقصى 20 صفًا، والمقارنة باليوم الميلادي العادي (لا
        # حد 05:00) لأن الموعد وعد واقعي من العميل
        coll_due_w = None
        if user_has_permission(self.user_name, "collections_list"):
            lbl_cdue = tk.Label(fr, text="⏰ مستحقات التحصيل", bg=BG, fg=DARK,
                                font=("Segoe UI", 10, "bold"), anchor="e")
            lbl_cdue.pack(fill="x", padx=14, pady=(6, 0))
            frm_cd, tv_cd = self.mk_tree(
                fr, ["الحالة", "الهاتف", "موعد التحصيل", "المبلغ المتبقي",
                      "العميل"], [160, 120, 110, 130, 300])
            tv_cd.configure(height=7)
            tv_cd.tag_configure("coverdue", foreground=RED)
            tv_cd.tag_configure("cdue", foreground=ORANGE)
            config_tree_stripes(tv_cd)
            frm_cd.pack(fill="x", padx=14, pady=(0, 10))
            add_tip(tv_cd, "ديون بمواعيد تحصيل — المتأخرة أولًا ثم مستحقة اليوم "
                           "ثم أقرب القادمة (حد أقصى 20 صفًا) — لمن يملك صلاحية "
                           "«قائمة التحصيل اليومية (الديون)»")
            coll_due_w = (lbl_cdue, tv_cd)

        def _clear_all():
            tv_t.delete(*tv_t.get_children())
            tv_s.delete(*tv_s.get_children())
            for c in cards:
                c[1].config(text="—")
            lbl_top.config(text="🏆 أعلى 5 منتجات مبيعًا")
            lbl_sel.config(text="👤 إجماليات البائعين")
            # ★ إضافة (موعد التحصيل): تفريغ قسم المستحقات أيضًا
            if coll_due_w is not None:
                coll_due_w[1].delete(*coll_due_w[1].get_children())
                coll_due_w[0].config(text="⏰ مستحقات التحصيل")

        def refresh():
            """جمع بيانات الملخص الصباحي — الصلاحية تُفحص هنا مجددًا عند كل
            عرض (الطبقة الثانية بعد الإخفاء وبعد فحص فتح النافذة)"""
            if not user_has_permission(self.user_name, "morning_summary"):
                lbl_perm.config(text="🔒 لا تملك صلاحية «الملخص الصباحي» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                _clear_all()
                return
            d = str(dvar.get())[:10]
            r = collect_morning_summary(d)
            if r is None:
                lbl_perm.config(text="🔒 لا تملك صلاحية «الملخص الصباحي» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                _clear_all()
                return
            lbl_perm.pack_forget()
            if r.get("error"):
                lbl_perm.config(text="⚠️ تعذر جمع بيانات الملخص الصباحي — سُجّل "
                                     "السبب في error_log.txt")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                _clear_all()
                return
            c_sales[1].config(text=money(r["sales"]))
            c_rets[1].config(text=money(r["rets"]))
            c_net[1].config(text=money(r["net"]),
                            fg=(GREEN if r["net"] >= 0 else RED))
            c_sc[1].config(text=f"{r['sales_count']:,}")
            c_rc[1].config(text=f"{r['rets_count']:,}")
            if have_receipts:
                c_rec[1].config(text=(money(r["receipts"])
                                      if r["receipts"] is not None else "—"))
            closed_txt = (" — مغلق في الأرشيف" if is_closed(d) else "")
            lbl_top.config(text=f"🏆 أعلى 5 منتجات مبيعًا — {d} "
                                f"({day_name(d)}){closed_txt}")
            lbl_sel.config(text=f"👤 إجماليات البائعين — {d} ({day_name(d)})")
            tv_t.delete(*tv_t.get_children())
            if not r["top_items"]:
                tv_t.insert("", "end", values=("لا مبيعات في هذا اليوم", "—", "—"))
            else:
                for i, it in enumerate(r["top_items"]):
                    tv_t.insert("", "end", tags=stripe_tags(i),
                                values=(money(it["s"]), f"{it['q']:g}", it["name"]))
            tv_s.delete(*tv_s.get_children())
            if not r["sellers"]:
                tv_s.insert("", "end", values=("لا عمليات لبائعين في هذا اليوم", "—", "—"))
            else:
                for i, s in enumerate(r["sellers"]):
                    tv_s.insert("", "end", tags=stripe_tags(i),
                                values=(money(s["total"]), f"{s['invoices']:,}",
                                        s["name"]))
            # ★★★ إضافة (موعد التحصيل): تعبئة قسم مستحقات التحصيل — الطبقة
            # الأولى: القسم غير مبني أصلًا لمن لا يملك collections_list،
            # والفحص يعاد هنا ثانية عند كل عرض (دفاع مزدوج)، والحالة ملونة
            # (أحمر متأخر / برتقالي اليوم / عادي القادم) بأرقام بفواصل الآلاف
            if coll_due_w is not None:
                _lbl_cd_c, _tv_cd_c = coll_due_w
                try:
                    _has_coll_c = user_has_permission(self.user_name,
                                                      "collections_list")
                except Exception:
                    _has_coll_c = False
                if not _has_coll_c:
                    _tv_cd_c.delete(*_tv_cd_c.get_children())
                    _lbl_cd_c.config(text="⏰ مستحقات التحصيل")
                else:
                    _cdue_rows_c = collection_due_rows(limit=20)
                    _tv_cd_c.delete(*_tv_cd_c.get_children())
                    if not _cdue_rows_c:
                        _tv_cd_c.insert("", "end", values=(
                            "لا ديون بمواعيد تحصيل — كل الديون بلا مواعيد أو "
                            "مسددة ✅", "—", "—", "—", "—"))
                        _lbl_cd_c.config(text="⏰ مستحقات التحصيل — لا مواعيد قائمة")
                    else:
                        _tag_map_c = {"late": "coverdue", "today": "cdue"}
                        for _i_c, _row_c in enumerate(_cdue_rows_c):
                            _tg_c = _tag_map_c.get(_row_c["kind"], "")
                            _tv_cd_c.insert(
                                "", "end",
                                tags=((_tg_c,) if _tg_c else ())
                                      + (("odd",) if _i_c % 2 else ()),
                                values=(_row_c["status_text"],
                                        _row_c["phone"],
                                        _row_c["collection_date"],
                                        money(_row_c["remaining"]),
                                        _row_c["cname"]))
                        _lbl_cd_c.config(
                            text=f"⏰ مستحقات التحصيل — {len(_cdue_rows_c):,} دينًا "
                                 f"(المتأخرة أولًا ثم مستحقة اليوم ثم أقرب القادمة)")

        b_ref = self.mk_btn(bar, "🔄 عرض", refresh, "#475569")
        b_ref.pack(side="right", padx=4)
        add_tip(b_ref, "عرض بيانات الملخص الصباحي لليوم التجاري المختار الآن")
        cb.bind("<<ComboboxSelected>>", lambda _e: refresh())
        refresh()

    def _build_weekly_report_tab(self, fr):
        """★ إضافة (المرحلة الثالثة — التبويب 2): التقرير الأسبوعي — آخر 7
        أيام تجارية في جدول مع سطر الإجمالي في الأسفل، وفوقه رسم أعمدة بسيط
        للمبيعات اليومية داخل Canvas من tkinter وحده (لا مكتبة رسم خارجية)
        بأبعاد ثابتة بالأرقام، وتحته جدولا أعلى 5 منتجات وإجماليات البائعين
        خلال الأسبوع — قراءة فقط"""
        bar = tk.Frame(fr, bg=BG)
        bar.pack(fill="x", padx=14, pady=(12, 2))
        tk.Label(bar, text="📅 آخر 7 أيام تجارية (أولها اليوم الجاري)", bg=BG,
                 fg=DARK, font=FB).pack(side="right")
        lbl_perm = tk.Label(fr, text="", bg=BG, fg=RED,
                            font=("Segoe UI", 10, "bold"), anchor="e",
                            justify="right", wraplength=900)

        # رسم الأعمدة — Canvas بأبعاد ثابتة لا يتغير حجمها أبدًا
        cvs = tk.Canvas(fr, width=880, height=120, bg=CARD,
                        highlightbackground=BORDER, highlightthickness=1)
        cvs.pack(pady=(4, 2))
        add_tip(cvs, "أعمدة المبيعات اليومية خلال آخر 7 أيام تجارية — الأخضر "
                     "لليوم المغلق والبرتقالي لليوم الجاري (نفس اتفاقية لوحة "
                     "المعلومات القائمة) واليوم الأحدث على اليمين")

        def draw_chart(days_data):
            """★ إضافة (المرحلة الثالثة): رسم أعمدة المبيعات اليومية — أبعاد
            ثابتة بالأرقام، وإن كانت القيمة العظمى صفرًا لا يُرسم شيء (نص
            صغير بدل الرسم) — والرسم كله داخل try/except فلا ينهار أبدًا"""
            cvs.delete("all")
            W, H = 880, 120
            base_y, top_pad = 98, 30
            try:
                vals = [dd["sales"] for dd in days_data]
                mx = max(vals) if vals else 0.0
                if not vals or mx <= 0:
                    cvs.create_text(W // 2, H // 2,
                                    text="لا مبيعات خلال الأيام السبعة",
                                    fill=GRAY, font=("Segoe UI", 11, "bold"))
                    return
                slot = 860.0 / len(vals)
                for i, dd in enumerate(days_data):
                    v = dd["sales"] or 0.0
                    slot_l = 870.0 - (i + 1) * slot
                    bw = min(72.0, slot * 0.62)
                    x1 = slot_l + (slot - bw) / 2
                    x2 = x1 + bw
                    if v > 0:
                        bh = max(2.0, v / mx * (base_y - top_pad))
                        cvs.create_rectangle(x1, base_y - bh, x2, base_y,
                                             fill=(ORANGE if i == 0 else GREEN),
                                             width=0)
                        cvs.create_text((x1 + x2) / 2, base_y - bh - 9,
                                        text=f"{v:,.0f}", fill=DARK,
                                        font=("Segoe UI", 8))
                    cvs.create_text((x1 + x2) / 2, H - 10,
                                    text=(f"{day_name(dd['date'])} "
                                          f"{dd['date'][8:10]}/{dd['date'][5:7]}"),
                                    fill=GRAY, font=("Segoe UI", 8))
                cvs.create_line(10, base_y, 870, base_y, fill=DARK, width=1)
            except Exception:
                try:
                    cvs.delete("all")
                    cvs.create_text(W // 2, H // 2, text="تعذر رسم الأعمدة",
                                    fill=GRAY, font=("Segoe UI", 10))
                except Exception:
                    pass

        frm_w, tv_w = self.mk_tree(fr, ["الصافي", "المرتجعات", "المبيعات",
                                        "عدد العمليات", "التاريخ"],
                                   [130, 130, 130, 120, 180])
        tv_w.configure(height=8)
        config_tree_stripes(tv_w)
        tv_w.tag_configure("total", background="#dbe3ee",
                           font=("Segoe UI", 10, "bold"))
        frm_w.pack(fill="x", padx=14)
        add_tip(tv_w, "آخر 7 أيام تجارية وسطر الإجمالي في الأسفل")

        bottom = tk.Frame(fr, bg=BG)
        bottom.pack(fill="both", expand=True, padx=14, pady=(6, 10))
        frR = tk.Frame(bottom, bg=BG)
        frR.pack(side="right", fill="both", expand=True, padx=(3, 0))
        tk.Label(frR, text="🏆 أعلى 5 منتجات خلال الأسبوع", bg=BG, fg=DARK,
                 font=("Segoe UI", 10, "bold"), anchor="e").pack(fill="x")
        frm_t, tv_t = self.mk_tree(frR, ["الإجمالي", "الكمية", "المنتج"],
                                   [110, 70, 200])
        tv_t.configure(height=4)
        config_tree_stripes(tv_t)
        enable_tree_sorting(tv_t)
        frm_t.pack(fill="both", expand=True)
        frL = tk.Frame(bottom, bg=BG)
        frL.pack(side="left", fill="both", expand=True, padx=(0, 3))
        tk.Label(frL, text="👤 إجماليات البائعين خلال الأسبوع", bg=BG, fg=DARK,
                 font=("Segoe UI", 10, "bold"), anchor="e").pack(fill="x")
        frm_s, tv_s = self.mk_tree(frL, ["الإجمالي", "عدد الفواتير", "البائع"],
                                   [110, 90, 190])
        tv_s.configure(height=4)
        config_tree_stripes(tv_s)
        enable_tree_sorting(tv_s)
        frm_s.pack(fill="both", expand=True)

        def _clear_all():
            tv_w.delete(*tv_w.get_children())
            tv_t.delete(*tv_t.get_children())
            tv_s.delete(*tv_s.get_children())
            cvs.delete("all")

        def refresh():
            """جمع بيانات التقرير الأسبوعي — الصلاحية تُفحص هنا مجددًا عند
            كل تحديث (الطبقة الثانية)"""
            if not user_has_permission(self.user_name, "weekly_report"):
                lbl_perm.config(text="🔒 لا تملك صلاحية «التقرير الأسبوعي» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                _clear_all()
                return
            r = collect_weekly_report()
            if r is None:
                lbl_perm.config(text="🔒 لا تملك صلاحية «التقرير الأسبوعي» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                _clear_all()
                return
            lbl_perm.pack_forget()
            if r.get("error"):
                lbl_perm.config(text="⚠️ تعذر جمع بيانات التقرير الأسبوعي — سُجّل "
                                     "السبب في error_log.txt")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                _clear_all()
                return
            draw_chart(r["days"])
            tv_w.delete(*tv_w.get_children())
            for i, drow in enumerate(r["days"]):
                tv_w.insert("", "end", tags=stripe_tags(i),
                            values=(money(drow["net"]), money(drow["rets"]),
                                    money(drow["sales"]), f"{drow['ops']:,}",
                                    f"{drow['date']} ({day_name(drow['date'])})"))
            t = r["totals"]
            tv_w.insert("", "end", tags=("total",),
                        values=(money(t["net"]), money(t["rets"]),
                                money(t["sales"]), f"{t['ops']:,}", "الإجمالي"))
            tv_t.delete(*tv_t.get_children())
            if not r["top_items"]:
                tv_t.insert("", "end", values=("لا مبيعات خلال الأسبوع", "—", "—"))
            else:
                for i, it in enumerate(r["top_items"]):
                    tv_t.insert("", "end", tags=stripe_tags(i),
                                values=(money(it["s"]), f"{it['q']:g}", it["name"]))
            tv_s.delete(*tv_s.get_children())
            if not r["sellers"]:
                tv_s.insert("", "end", values=("لا عمليات لبائعين خلال الأسبوع", "—", "—"))
            else:
                for i, s in enumerate(r["sellers"]):
                    tv_s.insert("", "end", tags=stripe_tags(i),
                                values=(money(s["total"]), f"{s['invoices']:,}",
                                        s["name"]))

        b_ref = self.mk_btn(bar, "🔄 تحديث", refresh, "#475569")
        b_ref.pack(side="left", padx=4)
        add_tip(b_ref, "إعادة جمع بيانات التقرير الأسبوعي الآن")
        refresh()

    def _build_discipline_tab(self, fr):
        """★ إضافة (المرحلة الثالثة — التبويب 3): الانضباط — لكل مستخدم ولكل
        يوم: أول تسجيل دخول ناجح وآخر نشاط مسجل باسمه من سجل التدقيق،
        والدقائق المتأخرة عن بداية الدوام (shop_hours_start من إعدادات مركز
        المتابعة) بعد مهلة سماح ثابتة 15 دقيقة لا تُحسب تأخيرًا — قراءة فقط
        من السجلات القائمة (البرنامج يسجل الدخول أصلاً بنوع «تسجيل دخول»
        فلا يُنشأ أي نوع جديد)"""
        bar = tk.Frame(fr, bg=BG)
        bar.pack(fill="x", padx=14, pady=(12, 2))
        tk.Label(bar, text="المدة:", bg=BG, fg=DARK, font=FB).pack(
            side="right", padx=(0, 6))
        pvar = tk.StringVar(value="آخر 7 أيام")
        cbp = ttk.Combobox(bar, textvariable=pvar, state="readonly",
                           values=["آخر 7 أيام", "آخر 14 يومًا", "آخر 30 يومًا"],
                           font=F, width=12, justify="center")
        cbp.pack(side="right", padx=4)
        add_tip(cbp, "مدة عرض بيانات الانضباط: آخر 7 أو 14 أو 30 يومًا")
        lbl_info = tk.Label(fr, text="", bg=BG, fg=GRAY, font=("Segoe UI", 10),
                            anchor="e", justify="right", wraplength=900)
        lbl_info.pack(fill="x", padx=14, pady=(4, 0))
        lbl_perm = tk.Label(fr, text="", bg=BG, fg=RED,
                            font=("Segoe UI", 10, "bold"), anchor="e",
                            justify="right", wraplength=900)
        lbl_empty = tk.Label(fr, text="بيانات الانضباط تُسجل من تاريخ تفعيل هذه المرحلة",
                             bg=BG, fg=ORANGE, font=("Segoe UI", 11, "bold"),
                             anchor="e")
        frm_d, tv_d = self.mk_tree(fr, ["الدقائق المتأخرة", "آخر نشاط",
                                        "أول تسجيل دخول", "اليوم", "المستخدم"],
                                   [130, 110, 120, 190, 150])
        tv_d.configure(height=13)
        config_tree_stripes(tv_d)
        enable_tree_sorting(tv_d)
        tv_d.tag_configure("late", foreground=RED)
        tv_d.tag_configure("ok", foreground=GREEN)
        frm_d.pack(fill="both", expand=True, padx=14, pady=(4, 10))
        add_tip(tv_d, "لكل مستخدم ولكل يوم: أول تسجيل دخول ناجح وآخر حدث تدقيق "
                      "باسمه في اليوم نفسه والدقائق المتأخرة عن بداية الدوام بعد "
                      "مهلة سماح 15 دقيقة — انقر رأس أي عمود للفرز")

        def refresh():
            """جمع بيانات الانضباط — الصلاحية تُفحص هنا مجددًا عند كل عرض،
            وانعدام البيانات يعرض الرسالة المعلومة ولا ينهار التبويب أبدًا"""
            if not user_has_permission(self.user_name, "discipline_report"):
                lbl_perm.config(text="🔒 لا تملك صلاحية «الانضباط» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                lbl_empty.pack_forget()
                tv_d.delete(*tv_d.get_children())
                return
            n = 7
            p = pvar.get()
            if p == "آخر 14 يومًا":
                n = 14
            elif p == "آخر 30 يومًا":
                n = 30
            r = collect_discipline_report(n)
            if r is None:
                lbl_perm.config(text="🔒 لا تملك صلاحية «الانضباط» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                lbl_empty.pack_forget()
                tv_d.delete(*tv_d.get_children())
                return
            lbl_perm.pack_forget()
            if r.get("error"):
                lbl_perm.config(text="⚠️ تعذر جمع بيانات الانضباط — سُجّل السبب "
                                     "في error_log.txt")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                lbl_empty.pack_forget()
                tv_d.delete(*tv_d.get_children())
                return
            lbl_info.config(text=f"بداية الدوام من إعدادات مركز المتابعة: "
                                 f"{r['shop_start']} — مهلة السماح 15 دقيقة "
                                 f"لا تُحسب تأخيرًا")
            tv_d.delete(*tv_d.get_children())
            if not r["rows"]:
                lbl_empty.pack(fill="x", padx=14, pady=6)
                return
            lbl_empty.pack_forget()
            if not r["has_login_data"]:
                lbl_empty.pack(fill="x", padx=14, pady=6)   # لا أحداث دخول بعد
            for i, row in enumerate(r["rows"]):
                late = row["late"]
                late_txt = ("—" if late is None else f"{late:,}")
                extra = (("late",) if (late or 0) > 0
                         else ("ok",) if late == 0 else ())
                tv_d.insert("", "end", tags=stripe_tags(i, False, extra),
                            values=(late_txt,
                                    (row["last_seen"] or "—"),
                                    (row["first_login"] or "—"),
                                    f"{row['day']} ({day_name(row['day'])})",
                                    row["user"]))

        b_show = self.mk_btn(bar, "عرض", refresh, "#475569")
        b_show.pack(side="right", padx=4)
        add_tip(b_show, "عرض بيانات الانضباط للمدة المختارة الآن")
        refresh()

    def _build_system_health_tab(self, fr):
        """★ إضافة (المرحلة الثالثة — التبويب 4): فحص صحة النظام — بطاقات
        معلومات: حجم ملف قاعدة البيانات ونتيجة PRAGMA quick_check وعدد
        سجلات الجداول الرئيسية وحجم error_log.txt وتاريخ آخر خطأ فيه وآخر
        نسخة احتياطية والمساحة الحرة على القرص وإصدار بايثون — وزر «إعادة
        الفحص» يحدّث البطاقات — قراءة فقط"""
        bar = tk.Frame(fr, bg=BG)
        bar.pack(fill="x", padx=14, pady=(12, 2))
        tk.Label(bar, text="🩺 فحص صحة النظام", bg=BG, fg=DARK, font=FB).pack(
            side="right")
        lbl_checked = tk.Label(bar, text="", bg=BG, fg=GRAY,
                               font=("Segoe UI", 9))
        lbl_checked.pack(side="left", padx=8)
        lbl_perm = tk.Label(fr, text="", bg=BG, fg=RED,
                            font=("Segoe UI", 10, "bold"), anchor="e",
                            justify="right", wraplength=900)

        def _hcard(parent, title, color):
            """بطاقة معلومة صغيرة — عنوان رمادي وقيمة غامقة ملونة تلف
            أسطرها الطويلة (كاسم النسخة الاحتياطية)"""
            fc = tk.Frame(parent, bg=CARD, highlightbackground=BORDER,
                          highlightthickness=1)
            tk.Label(fc, text=title, bg=CARD, fg=GRAY,
                     font=("Segoe UI", 9, "bold"), wraplength=250,
                     justify="center").pack(pady=(8, 0), fill="x", padx=6)
            v = tk.Label(fc, text="—", bg=CARD, fg=color,
                         font=("Segoe UI", 11, "bold"), wraplength=250,
                         justify="center")
            v.pack(pady=(2, 8), fill="x", padx=6)
            return fc, v

        grid = tk.Frame(fr, bg=BG)
        grid.pack(fill="both", expand=True, padx=14, pady=(6, 10))
        defs = [("حجم قاعدة البيانات", DARK),
                ("نتيجة فحص السلامة (quick_check)", DARK),
                ("سجلات المبيعات", GREEN),
                ("سجلات المرتجعات", RED),
                ("حسابات المستخدمين", ACCENT),
                ("الجلسات النشطة", "#0d9488"),
                ("حجم سجل الأخطاء", DARK),
                ("تاريخ آخر خطأ مسجل", ORANGE),
                ("آخر نسخة احتياطية", DARK),
                ("المساحة الحرة على القرص", GREEN),
                ("إصدار بايثون الحالي", DARK),
                ("آخر فحص", GRAY)]
        vals = []
        for i, (title, color) in enumerate(defs):
            c = _hcard(grid, title, color)
            c[0].grid(row=i // 3, column=2 - (i % 3),     # RTL: الأولى يمينًا
                      sticky="nsew", padx=3, pady=3)
            vals.append(c[1])
        for col in range(3):
            grid.columnconfigure(col, weight=1)
        for rw in range(4):
            grid.rowconfigure(rw, weight=1)

        def _kb(x):
            return "—" if x is None else f"{x / 1024.0:,.1f} كيلوبايت"

        def _cnt(x):
            return "—" if x is None else f"{x:,}"

        def refresh():
            """إعادة الفحص — الصلاحية تُفحص هنا مجددًا عند كل فحص، وأي بند
            فشل يظهر «—» وحده ولا يوقف بقية البطاقات أبدًا"""
            if not user_has_permission(self.user_name, "system_health_view"):
                lbl_perm.config(text="🔒 لا تملك صلاحية «فحص صحة النظام» — "
                                     "راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                for v in vals:
                    v.config(text="—")
                return
            r = collect_system_health()
            if r is None:
                lbl_perm.config(text="🔒 لا تملك صلاحية «فحص صحة النظام» — "
                                     "راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                for v in vals:
                    v.config(text="—")
                return
            lbl_perm.pack_forget()
            if r.get("error"):
                lbl_perm.config(text="⚠️ تعذر جمع بيانات فحص الصحة — سُجّل السبب "
                                     "في error_log.txt")
                lbl_perm.pack(fill="x", padx=14, pady=6)
            if r["db_size"] is not None and r["db_size"] >= 1024 * 1024:
                vals[0].config(text=f"{r['db_size'] / (1024 * 1024):,.2f} ميجابايت")
            else:
                vals[0].config(text=_kb(r["db_size"]))
            qc = r["quick_check"]
            if qc is None:
                vals[1].config(text="—", fg=GRAY)
            elif qc == "ok":
                vals[1].config(text="✅ سليم (ok)", fg=GREEN)
            else:
                vals[1].config(text="⚠ " + qc[:80], fg=RED)
            vals[2].config(text=_cnt(r["sales_count"]))
            vals[3].config(text=_cnt(r["returns_count"]))
            vals[4].config(text=_cnt(r["users_count"]))
            vals[5].config(text=_cnt(r["sessions_count"]))
            if r["errlog_size"] is None:
                vals[6].config(text="لا يوجد ملف سجل أخطاء")
            else:
                vals[6].config(text=_kb(r["errlog_size"]))
            if r["errlog_last"]:
                vals[7].config(text=r["errlog_last"])
            elif r["errlog_size"] == 0:
                vals[7].config(text="لا أخطاء مسجلة ✅", fg=GREEN)
            else:
                vals[7].config(text="—")
            lb = r["last_backup"]
            if lb is None:
                vals[8].config(text="لا توجد نسخ احتياطية", fg=RED)
            else:
                vals[8].config(text=(f"{lb[0]}\n{lb[1] / 1024.0:,.1f} كيلوبايت — "
                                     f"{lb[2]:%Y-%m-%d %H:%M}"))
            if r["disk_free"] is None:
                vals[9].config(text="—")
            else:
                vals[9].config(text=f"{r['disk_free'] / (1024 ** 3):,.2f} جيجابايت")
            vals[10].config(text=(r["python_version"] or "—"))
            now_s = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            vals[11].config(text=now_s)
            lbl_checked.config(text="آخر فحص: " + now_s)

        b_ref = self.mk_btn(bar, "🔄 إعادة الفحص", refresh, "#475569")
        b_ref.pack(side="left", padx=4)
        add_tip(b_ref, "إعادة فحص كل بطاقات صحة النظام الآن")
        refresh()

    def _build_backup_monitor_tab(self, fr):
        """★ إضافة (المرحلة الثالثة — التبويب 5): مراقبة النسخ الاحتياطي —
        شريط حالة أعلى الجدول (أخضر: آخر نسخة قبل أقل من 24 ساعة / أحمر:
        أكثر من 24 ساعة / أحمر: لا توجد نسخ)، وجدول بملفات مجلد backups من
        الأحدث (الاسم والحجم والتاريخ)، وزر «إنشاء نسخة الآن» يستدعي دالة
        النسخ الفورية القائمة make_instant_backup كما هي دون أي إعادة
        كتابة، وزر «تحديث القائمة» — قراءة فقط"""
        lbl_status = tk.Label(fr, text="", bg=BG, font=("Segoe UI", 12, "bold"),
                              anchor="e", justify="right", wraplength=900)
        lbl_status.pack(fill="x", padx=14, pady=(12, 4))
        bar = tk.Frame(fr, bg=BG)
        bar.pack(fill="x", padx=14, pady=2)
        lbl_perm = tk.Label(fr, text="", bg=BG, fg=RED,
                            font=("Segoe UI", 10, "bold"), anchor="e",
                            justify="right", wraplength=900)
        frm_b, tv_b = self.mk_tree(fr, ["الحجم (KB)", "التاريخ", "الاسم"],
                                   [110, 150, 420])
        tv_b.configure(height=12)
        config_tree_stripes(tv_b)
        enable_tree_sorting(tv_b)
        tv_b.tag_configure("monthly", background="#dcfce7")
        tv_b.tag_configure("instant", background="#e0f2fe")
        tv_b.tag_configure("safety", background="#fef3c7")
        frm_b.pack(fill="both", expand=True, padx=14, pady=(4, 2))
        add_tip(tv_b, "كل ملفات النسخ داخل مجلد backups (يومية وشهرية وفورية "
                      "ونسخ أمان الاستعادة) مرتبة من الأحدث — انقر رأس أي "
                      "عمود للفرز")
        tk.Label(fr, text="النسخ اليومية (آخر 30) والشهرية (دائمة) والفورية "
                          "(آخر 10) ونسخ أمان الاستعادة — كلها داخل مجلد "
                          "backups بجانب البرنامج",
                 bg=BG, fg=GRAY, font=("Segoe UI", 9), wraplength=900,
                 justify="right").pack(fill="x", padx=14, pady=(0, 10))

        def refresh():
            """قراءة حالة النسخ وملفات مجلد backups — الصلاحية تُفحص هنا
            مجددًا عند كل تحديث (الطبقة الثانية)"""
            if not user_has_permission(self.user_name, "backup_monitor_view"):
                lbl_perm.config(text="🔒 لا تملك صلاحية «مراقبة النسخ "
                                     "الاحتياطي» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                lbl_status.config(text="—", fg=GRAY)
                tv_b.delete(*tv_b.get_children())
                return
            r = collect_backup_monitor()
            if r is None:
                lbl_perm.config(text="🔒 لا تملك صلاحية «مراقبة النسخ "
                                     "الاحتياطي» — راجع الأدمن")
                lbl_perm.pack(fill="x", padx=14, pady=6)
                lbl_status.config(text="—", fg=GRAY)
                tv_b.delete(*tv_b.get_children())
                return
            lbl_perm.pack_forget()
            if r.get("error"):
                lbl_perm.config(text="⚠️ تعذر قراءة ملفات النسخ — سُجّل السبب "
                                     "في error_log.txt")
                lbl_perm.pack(fill="x", padx=14, pady=6)
            if r["status"] == "ok":
                lbl_status.config(fg=GREEN,
                                  text="النسخ الاحتياطي سليم — آخر نسخة قبل أقل من 24 ساعة")
            elif r["status"] == "late":
                lbl_status.config(fg=RED,
                                  text="تحذير: لم تُنشأ نسخة احتياطية منذ أكثر من 24 ساعة")
            else:
                lbl_status.config(fg=RED, text="تحذير: لا توجد نسخ احتياطية")
            tv_b.delete(*tv_b.get_children())
            if not r["files"]:
                tv_b.insert("", "end",
                            values=("—", "—", "لا توجد ملفات نسخ في مجلد backups"))
            else:
                for i, f in enumerate(r["files"]):
                    nm = f["name"]
                    tag = ("monthly" if nm.startswith("monthly_") else
                           "instant" if nm.startswith("instant_") else
                           "safety" if nm.startswith("pre_restore_") else "")
                    tv_b.insert("", "end",
                                tags=stripe_tags(i, False, ((tag,) if tag else ())),
                                values=(f"{f['size'] / 1024.0:,.1f}",
                                        f["when"].strftime("%Y-%m-%d %H:%M"),
                                        nm))

        def do_create_now():
            """إنشاء نسخة فورية الآن — الدالة القائمة نفسها كما هي دون أي
            إعادة كتابة، والصلاحية تُفحص هنا أيضًا (دفاع مزدوج)"""
            if not user_has_permission(self.user_name, "backup_monitor_view"):
                messagebox.showwarning(
                    "لا تملك صلاحية",
                    "مراقبة النسخ الاحتياطي تتطلب صلاحية «عرض مراقبة النسخ "
                    "الاحتياطي» — راجع الأدمن", parent=fr.winfo_toplevel())
                return
            try:
                path = make_instant_backup()
                messagebox.showinfo("تم", f"تم إنشاء نسخة احتياطية فورية:\n{path}",
                                    parent=fr.winfo_toplevel())
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                messagebox.showerror("خطأ", f"تعذر إنشاء النسخة:\n{e}",
                                     parent=fr.winfo_toplevel())
            refresh()

        # زر «إنشاء نسخة الآن» موجود لأن دالة النسخ الفورية القائمة
        # make_instant_backup موجودة في الكود — فيستدعيها كما هي حرفيًا
        b_now = self.mk_btn(bar, "🗄️ إنشاء نسخة الآن", do_create_now, "#0d9488")
        b_now.pack(side="right", padx=4)
        add_tip(b_now, "إنشاء نسخة احتياطية فورية الآن (آخر 10 تُحفظ) — "
                       "الدالة القائمة نفسها دون أي تغيير")
        b_ref = self.mk_btn(bar, "🔄 تحديث القائمة", refresh, "#475569")
        b_ref.pack(side="right", padx=4)
        add_tip(b_ref, "إعادة قراءة ملفات مجلد backups وحالة آخر نسخة الآن")
        refresh()

    # ═══════════════════════════════════════════════════════════
    # ★★★ إضافة (المرحلة الرابعة — القسم 4): إعادة بناء الواجهة عند ★★★
    # ★★★ تبديل المستخدم — دالة جديدة كليًا تُستدعى بسطر واحد        ★★★
    # ═══════════════════════════════════════════════════════════
    # ★ إصلاح طوارئ معلن (حالة الطوارئ المصرح بها — البند 4: الاستقرار
    #   أولًا): النسخة السابقة من هذه الدالة كانت تهدم إطار القائمة
    #   الجانبية الحالي كاملًا (بالتسلق من زر «عملية جديدة» حتى إطار
    #   الشريط) ثم تعيد بناءه بـ build_sidebar ثم تعيد حزم الحاوية
    #   الرئيسية pack_forget/pack — وهذا التسلسل الهادم هو الخطوة
    #   الوحيدة في التعديل الأخير كله التي تمزّق شجرة عناصر حية قائمة
    #   أثناء التشغيل (حاوية التمرير Canvas وعنصر create_window
    #   وروابط العجلة وكل الأزرار دفعة واحدة) ويعيد ترتيب حزم النافذة،
    #   وهو الذي لا يستقر على بنية ويندوز/تِك لدى المالك (توصيل حدث
    #   العجلة للعنصر المركز بالفوكس، ومعالجة <Configure> تزامنيًا أثناء
    #   الهدم وإعادة الحزم) — فاستُبدل هنا بمعالجة جراحية آمنة تمامًا
    #   تحقق النتيجة الظاهرة نفسها دون هدم أي شيء: تُفحص وحدها الأزرار
    #   المشروطة التي يديرها هذا القسم (مدخل «الصلاحيات الدقيقة» وزر
    #   «مركز المتابعة والرقابة» — الوحيدان في الشريط كله اللذان يُنشآن
    #   بشرط ولا يديرهما refresh_sidebar_permissions) فيُنشأ من يستحق
    #   الظهور ويُهدم وحده من فقد شرطه، وإطار الشريط وحاوية التمرير
    #   وجميع الأزرار الأخرى وترتيب حزم النافذة كلها لا تُمس إطلاقًا —
    #   والسلوك الظاهر كما هو بلا أي تنازل: النموذج المعتمد الإخفاء لا
    #   التعطيل، فما لا يملكه المستخدم الجديد لا يظهر أصلًا — لا زر
    #   معطل ولا رسالة «لا تتوفر لك الصلاحيات» عند الضغط، والعودة
    #   للشاشة الافتراضية «عملية جديدة»، دون إغلاق البرنامج ودون أي
    #   نسخة ثانية من النافذة، وتغطي التبديل من أي دور إلى أي دور
    #   (أدمن ← مدير/بائع والعكس وكل تركيبة)؛ وبقية أزرار الإدارة
    #   والمجموعات يتكفل بها المعالج القائم نفسه قبل هذه الدالة
    #   (apply_role_ui ثم refresh_sidebar_permissions من داخله) كما هو
    #   قائم منذ الإصدار 8 — وكل خطوة هنا محصنة بـ try/except فأي خلل
    #   يُسجل في error_log ولا يوقف التبديل أبدًا (الاستقرار أولًا)
    # ═════════════════════════════════════════════════════════
    # ★★★ إضافات (المرحلة الرابعة): دوال النافذة والبيع بالدين والموافقة ★★★
    # ═════════════════════════════════════════════════════════

    def _inv_disc_recalc(self):
        """★ إضافة (المرحلة الرابعة — سقف الخصم): العرض اللحظي لإجمالي السلة
        بعد الخصم على أصناف البيع فقط (المرتجعات بسعر أصلها دائماً) + سقف
        خصم المستخدم توضيحياً، ويحمرّ السطر إذا تجاوز الإدخال السقف"""
        try:
            dv4 = 0.0
            if hasattr(self, "e_inv_disc"):
                v = to_num(self.e_inv_disc.get())
                if v is not None and v > 0:
                    dv4 = min(v, 100.0)
            sale = sum(it["total"] for it in (self.cart or [])
                       if it["type"] != "مرتجع")
            ret = sum(it["total"] for it in (self.cart or [])
                      if it["type"] == "مرتجع")
            after = sale * (1.0 - dv4 / 100.0) + ret
            cap = user_discount_cap(CURRENT_USER["name"])
            txt = f"بعد الخصم: {money(after)}" if dv4 > 0 else ""
            over = (dv4 > 0 and cap is not None and dv4 > cap + 1e-9)
            if dv4 > 0 and cap is not None:
                txt += f"  (سقف خصمك: {cap:g}%)"
            self.lbl_inv_after_disc.config(text=txt, fg=(RED if over else GRAY))
        except Exception:
            pass

    def _require_large_op_approval(self, amount):
        """★ إضافة (المرحلة الرابعة — العمليات الكبيرة): (مسموح؟, اسم الموافق
        أو None) — تحت الحد يمر الجميع، وصاحب approve_large_operations يمر
        مباشرة بلا أي نافذة، وغيره تفتح نافذة موافقة عربية يدخل فيها مستخدم
        آخر اسمه وكلمة مروره (نفس آلية التحقق الحالية للدخول حرفياً:
        get_user_row + verify_user_password + active) ولا يُقبل إلا صاحب
        الصلاحية؛ الإلغاء أو فشل التحقق يوقف العملية ولا يُسجل شيء"""
        try:
            if amount < stage4_large_op_threshold() - 1e-9:
                return True, None
            if user_has_permission(CURRENT_USER["name"], "approve_large_operations"):
                return True, None
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            return False, None
        res = {"ok": False, "by": None}
        try:
            win = self.register_window(tk.Toplevel(self))
            win.title("موافقة على عملية كبيرة")
            win.configure(bg=BG)
            win.resizable(False, False)
            try:
                win.transient(self)
            except Exception:
                pass
            card = tk.Frame(win, bg=CARD, highlightbackground=BORDER,
                            highlightthickness=1)
            card.pack(fill="both", expand=True, padx=16, pady=14)
            tk.Label(card, text="🔐 موافقة على عملية كبيرة", bg=CARD, fg=DARK,
                     font=FT).pack(pady=(12, 4))
            tk.Label(card, text=f"عملية كبيرة بمبلغ {money(amount)} — مطلوب موافقة "
                                "مستخدم يملك صلاحية «الموافقة على العمليات الكبيرة»",
                     bg=CARD, fg=RED, font=FB, wraplength=400,
                     justify="center").pack(pady=4, padx=10)
            grid4 = tk.Frame(card, bg=CARD)
            grid4.pack(pady=8)
            tk.Label(grid4, text="اسم المستخدم:", bg=CARD, fg=GRAY, font=FB
                     ).grid(row=0, column=0, sticky="e", padx=8, pady=5)
            e_user4 = tk.Entry(grid4, font=F, justify="center", relief="solid",
                               bd=1, width=22)
            e_user4.grid(row=0, column=1, sticky="w", padx=8, pady=5)
            tk.Label(grid4, text="كلمة المرور:", bg=CARD, fg=GRAY, font=FB
                     ).grid(row=1, column=0, sticky="e", padx=8, pady=5)
            e_pwd4 = tk.Entry(grid4, font=F, justify="center", relief="solid",
                              bd=1, width=22, show="•")
            e_pwd4.grid(row=1, column=1, sticky="w", padx=8, pady=5)
            lbl_err4 = tk.Label(card, text="", bg=CARD, fg=RED,
                                font=("Segoe UI", 9, "bold"))
            lbl_err4.pack(pady=(0, 2))

            def _verify4():
                name = e_user4.get().strip()
                pwd = e_pwd4.get()
                if not name or not pwd:
                    lbl_err4.config(text="اكتب اسم المستخدم وكلمة المرور معاً")
                    return
                row = get_user_row(name)
                if row is None or not verify_user_password(row, pwd):
                    messagebox.showerror("فشل التحقق",
                        "اسم المستخدم أو كلمة المرور غير صحيحة —\n"
                        "توقفت العملية ولم يُسجل شيء", parent=win)
                    res["ok"] = False
                    win.destroy()
                    return
                if not row["active"]:
                    messagebox.showerror("فشل التحقق",
                        "هذا الحساب موقوف — توقفت العملية ولم يُسجل شيء",
                        parent=win)
                    res["ok"] = False
                    win.destroy()
                    return
                if not user_has_permission(name, "approve_large_operations"):
                    messagebox.showerror("غير مصرح",
                        "المستخدم لا يملك صلاحية «الموافقة على العمليات "
                        "الكبيرة» — توقفت العملية ولم يُسجل شيء", parent=win)
                    res["ok"] = False
                    win.destroy()
                    return
                res["ok"] = True
                res["by"] = name
                win.destroy()

            def _cancel4():
                res["ok"] = False
                win.destroy()

            bar4 = tk.Frame(card, bg=CARD)
            bar4.pack(fill="x", pady=(4, 12))
            self.mk_btn(bar4, "✅ تأكيد الموافقة", _verify4, GREEN).pack(
                side="right", padx=6)
            self.mk_btn(bar4, "إلغاء العملية", _cancel4, "#475569").pack(
                side="right", padx=6)
            e_pwd4.bind("<Return>", lambda e: _verify4())
            try:
                win.grab_set()
            except Exception:
                pass
            e_user4.focus_set()
            win.wait_window(win)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            return False, None
        return (True, res["by"]) if res["ok"] else (False, None)

    def _credit_sale_dialog(self, mode="op"):
        """★ إضافة (المرحلة الرابعة — البيع بالدين): نافذة عربية صغيرة —
        اختيار عميل من قائمة الموجودين أو إضافة عميل جديد سريع (الاسم
        إلزامي والهاتف اختياري)، عرض إجمالي الفاتورة، حقل «الدفعة الأولى
        الآن» افتراضه 0 ولا يتجاوز الإجمالي، وتحذير معلوماتي أحمر غير مانع
        إن كان للعميل دين قائم — وعند التأكيد يُضبط سياق الدين ثم تستدعى
        نفس دالة الحفظ القائمة (save_op أو save_invoice) فلا نسخ لمنطق
        البيع أبداً، والباقي يُسجل ديناً على العميل بعد نجاح الحفظ"""
        # الطبقة الثانية (دفاع مزدوج مع إخفاء الزر): لا فتح بلا صلاحية
        if not user_has_permission(CURRENT_USER["name"], "sell_on_credit"):
            messagebox.showwarning("لا تملك صلاحية",
                "البيع بالدين يتطلب صلاحية «البيع بالدين (زر الدين في شاشة "
                "البيع)» — راجع الأدمن")
            return
        try:
            _ensure_stage4_tables()
        except Exception:
            pass
        # إجمالي الفاتورة الحالية (بعد الخصم إن وُجد) حسب الشاشة
        try:
            if mode == "op":
                if self.type_var.get() == "مرتجع":
                    messagebox.showwarning("بيع بالدين",
                        "البيع بالدين لمبيعات نقداً/شبكة فقط — ليس للمرتجعات")
                    return
                q, pr = to_num(self.e_qty.get()), to_num(self.e_price.get())
                if q is None or q <= 0 or pr is None or pr < 0:
                    messagebox.showwarning("بيع بالدين",
                        "أكمل الكمية والسعر أولاً قبل البيع بالدين")
                    return
                dv4 = 0.0
                if hasattr(self, "e_disc"):
                    v = to_num(self.e_disc.get())
                    if v is not None and v > 0:
                        dv4 = min(v, 100.0)
                total = q * pr * (1.0 - dv4 / 100.0)
            else:
                if not self.cart:
                    messagebox.showwarning("بيع بالدين",
                        "السلة فارغة — أضف أصناف البيع أولاً")
                    return
                sale = sum(it["total"] for it in self.cart if it["type"] != "مرتجع")
                if sale <= 0:
                    messagebox.showwarning("بيع بالدين",
                        "لا توجد أصناف بيع في السلة — البيع بالدين لمبيعات "
                        "نقداً/شبكة فقط")
                    return
                dv4 = 0.0
                if hasattr(self, "e_inv_disc"):
                    v = to_num(self.e_inv_disc.get())
                    if v is not None and v > 0:
                        dv4 = min(v, 100.0)
                ret = sum(it["total"] for it in self.cart if it["type"] == "مرتجع")
                total = sale * (1.0 - dv4 / 100.0) + ret
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            return
        if total <= 0:
            messagebox.showwarning("بيع بالدين",
                "إجمالي الفاتورة يجب أن يكون أكبر من صفر")
            return
        win = self.register_window(tk.Toplevel(self))
        win.title("بيع بالدين")
        win.configure(bg=BG)
        win.resizable(False, False)
        try:
            win.transient(self)
        except Exception:
            pass
        card = tk.Frame(win, bg=CARD, highlightbackground=BORDER,
                        highlightthickness=1)
        card.pack(fill="both", expand=True, padx=16, pady=14)
        tk.Label(card, text="🧾 بيع بالدين", bg=CARD, fg=DARK,
                 font=FT).pack(pady=(12, 4))
        tk.Label(card, text=f"إجمالي الفاتورة: {money(total)}",
                 bg=CARD, fg=ACCENT, font=("Segoe UI", 12, "bold")).pack(pady=4)
        # اختيار العميل: موجود أو جديد — نفس أسلوب بقية النوافذ
        cust_mode4 = tk.StringVar(value="موجود")
        cfr4 = tk.Frame(card, bg=CARD)
        cfr4.pack(fill="x", padx=14, pady=(6, 2))
        tk.Radiobutton(cfr4, text="عميل موجود", variable=cust_mode4,
                       value="موجود", font=FB, fg=DARK, bg=CARD,
                       selectcolor="#dbeafe", activebackground=CARD,
                       activeforeground=ACCENT, indicatoron=0, width=12, bd=1,
                       relief="solid", cursor="hand2",
                       command=lambda: _sync_cust4()).pack(side="right", padx=4)
        tk.Radiobutton(cfr4, text="عميل جديد", variable=cust_mode4,
                       value="جديد", font=FB, fg=DARK, bg=CARD,
                       selectcolor="#dbeafe", activebackground=CARD,
                       activeforeground=ACCENT, indicatoron=0, width=12, bd=1,
                       relief="solid", cursor="hand2",
                       command=lambda: _sync_cust4()).pack(side="right", padx=4)
        fr_exist4 = tk.Frame(card, bg=CARD)
        fr_exist4.pack(fill="x", padx=14, pady=4)
        tk.Label(fr_exist4, text="العميل:", bg=CARD, fg=GRAY,
                 font=FB).pack(side="right", padx=(0, 8))
        cb_cust4 = ttk.Combobox(fr_exist4, font=F, width=30, state="readonly")
        cb_cust4.pack(side="right", ipady=3)
        cust_map4 = {}
        try:
            labels = []
            for c in customers_all():
                lbl = c["name"] + (f" — {c['phone']}" if c["phone"] else "")
                labels.append(lbl)
                cust_map4[lbl] = c
            cb_cust4["values"] = labels
            if labels:
                cb_cust4.current(0)
        except Exception as e:
            log_error(e, sys.exc_info()[2])
        fr_new4 = tk.Frame(card, bg=CARD)
        tk.Label(fr_new4, text="اسم العميل (إلزامي):", bg=CARD, fg=GRAY,
                 font=FB).pack(side="right", padx=(0, 8))
        e_cname4 = tk.Entry(fr_new4, font=F, justify="center", relief="solid",
                            bd=1, width=26)
        e_cname4.pack(side="right", padx=(0, 10), ipady=3)
        tk.Label(fr_new4, text="الهاتف (اختياري):", bg=CARD, fg=GRAY,
                 font=FB).pack(side="right", padx=(0, 8))
        e_cphone4 = tk.Entry(fr_new4, font=F, justify="center", relief="solid",
                             bd=1, width=16)
        e_cphone4.pack(side="right", ipady=3)
        lbl_warn4 = tk.Label(card, text="", bg=CARD, fg=RED, font=FB,
                             wraplength=400, justify="center")
        lbl_warn4.pack(pady=(2, 2))
        dfr4 = tk.Frame(card, bg=CARD)
        dfr4.pack(fill="x", padx=14, pady=4)
        tk.Label(dfr4, text="الدفعة الأولى الآن:", bg=CARD, fg=DARK,
                 font=FB).pack(side="right", padx=(0, 8))
        e_down4 = tk.Entry(dfr4, font=F, justify="center", relief="solid",
                           bd=1, width=14)
        e_down4.insert(0, "0")
        e_down4.pack(side="right", ipady=3)
        digits_only_filter(e_down4)
        tk.Label(dfr4, text=f"(0 إلى {money(total)} — الباقي يُسجل ديناً)",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(side="right", padx=6)
        # ★★★ إضافة (موعد التحصيل): خانة الموعد الاختيارية بصيغة YYYY-MM-DD
        # — الحقل الفارغ مقبول تماماً (كالسلوك القديم: دين بلا موعد)، وإن
        # كان مملوءًا وغير صالح فلا يتم البيع حتى تصحيحه أو تفريغه (التحقق
        # داخل _confirm4)، وتحديد الموعد هنا جزء من شاشة البيع بالدين نفسها
        # فلا يحتاج مفتاح صلاحية جديداً (sell_on_credit القائمة تكفي)
        cdfr4 = tk.Frame(card, bg=CARD)
        cdfr4.pack(fill="x", padx=14, pady=4)
        tk.Label(cdfr4, text="موعد التحصيل (اختياري):", bg=CARD, fg=DARK,
                 font=FB).pack(side="right", padx=(0, 8))
        e_cdate4 = tk.Entry(cdfr4, font=F, justify="center", relief="solid",
                            bd=1, width=14)
        e_cdate4.pack(side="right", ipady=3)
        add_tip(e_cdate4, "وعد العميل بالسداد بصيغة YYYY-MM-DD — اتركه فارغاً "
                          "= دين بلا موعد (كالسلوك القديم)")
        tk.Label(cdfr4, text="بصيغة YYYY-MM-DD — فارغ = بلا موعد",
                 bg=CARD, fg=GRAY, font=("Segoe UI", 9)).pack(side="right", padx=6)
        # ثلاثة أزرار سريعة تعبّئ الموعد تلقائيًا من اليوم الميلادي العادي
        # (الموعد وعد واقعي فلا يُحسب بحدود اليوم التجاري 05:00)
        def _fill_cdate4(days_c):
            try:
                e_cdate4.delete(0, "end")
                e_cdate4.insert(0, date.fromordinal(
                    date.today().toordinal() + days_c).isoformat())
            except Exception:
                pass
        qbar4 = tk.Frame(card, bg=CARD)
        qbar4.pack(fill="x", padx=14, pady=(0, 2))
        self.mk_btn(qbar4, "بعد أسبوع", lambda: _fill_cdate4(7),
                    ACCENT).pack(side="right", padx=3)
        self.mk_btn(qbar4, "بعد شهر", lambda: _fill_cdate4(30),
                    ACCENT).pack(side="right", padx=3)
        self.mk_btn(qbar4, "بعد 3 أشهر", lambda: _fill_cdate4(90),
                    ACCENT).pack(side="right", padx=3)
        lbl_err4 = tk.Label(card, text="", bg=CARD, fg=RED,
                            font=("Segoe UI", 9, "bold"), wraplength=400)
        lbl_err4.pack(pady=(2, 0))
        # مراجع للاختبار الآلي والتزاماً بنمط البرنامج
        self._cd_win = win
        self._cd_cb_cust = cb_cust4
        self._cd_e_name = e_cname4
        self._cd_e_phone = e_cphone4
        self._cd_e_down = e_down4
        self._cd_e_cdate = e_cdate4        # ★ إضافة (موعد التحصيل): حقل الموعد
        self._cd_lbl_warn = lbl_warn4
        self._cd_mode_var = cust_mode4

        def _sync_cust4(_e=None):
            try:
                if cust_mode4.get() == "موجود":
                    fr_exist4.pack(fill="x", padx=14, pady=4, before=lbl_warn4)
                    fr_new4.pack_forget()
                else:
                    fr_new4.pack(fill="x", padx=14, pady=4, before=lbl_warn4)
                    fr_exist4.pack_forget()
                    lbl_warn4.config(text="")
                _warn4()
            except Exception:
                pass

        def _warn4(_e=None):
            """تحذير معلوماتي أحمر غير مانع إن كان للعميل دين قائم"""
            try:
                lbl_warn4.config(text="")
                if cust_mode4.get() != "موجود":
                    return
                c = cust_map4.get(cb_cust4.get())
                if c is None:
                    return
                d = customer_debt_total(c["id"])
                if d > 1e-9:
                    lbl_warn4.config(text=f"⚠ تنبيه: العميل لديه دين قائم "
                                          f"بمبلغ {money(d)}")
            except Exception:
                pass

        cb_cust4.bind("<<ComboboxSelected>>", lambda e: _warn4())

        def _confirm4():
            # الطبقة الثانية: فحص الصلاحية مجدداً في بداية مسار الحفظ
            if not user_has_permission(CURRENT_USER["name"], "sell_on_credit"):
                messagebox.showwarning("لا تملك صلاحية",
                    "لا تملك صلاحية «البيع بالدين» — لم يُسجل شيء", parent=win)
                return
            try:
                if cust_mode4.get() == "موجود":
                    c = cust_map4.get(cb_cust4.get())
                    if c is None:
                        lbl_err4.config(text="اختر عميلاً من القائمة أولاً")
                        shake_widget(card)
                        return
                    cid4, cname4 = c["id"], c["name"]
                else:
                    cname4 = e_cname4.get().strip()
                    if not cname4:
                        lbl_err4.config(text="اسم العميل الجديد إلزامي")
                        shake_widget(card)
                        return
                    cphone4 = e_cphone4.get().strip()
                    with connect() as conn:
                        cur4 = conn.execute(
                            "INSERT INTO customers(name, phone, notes, created_at) "
                            "VALUES(?,?,?,?)",
                            (cname4, cphone4 or None, None,
                             datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
                        cid4 = cur4.lastrowid
                down4 = to_num(e_down4.get())
                if down4 is None or down4 < 0:
                    lbl_err4.config(text="قيمة الدفعة الأولى غير صحيحة — أدخل "
                                         "رقماً من 0 فأكثر")
                    shake_widget(card)
                    return
                if down4 > total + 1e-9:
                    lbl_err4.config(text=f"الدفعة الأولى لا يجوز أن تتجاوز إجمالي "
                                         f"الفاتورة ({money(total)})")
                    shake_widget(card)
                    return
                # ★★★ إضافة (موعد التحصيل): الحقل الفارغ مقبول (كالسلوك
                # القديم تماماً: دين بلا موعد)، وإن كان مملوءًا وغير صالح
                # برسالة تحقق عربية ولا يُتم البيع حتى التصحيح أو التفريغ
                _cdate_val4 = None
                _craw_c4 = e_cdate4.get().strip()
                if _craw_c4:
                    _cd_obj4 = parse_collection_date(_craw_c4)
                    if _cd_obj4 is None:
                        lbl_err4.config(text="صيغة موعد التحصيل غير صحيحة — "
                                             "اكتب التاريخ بصيغة YYYY-MM-DD "
                                             "(مثل 2026-10-21) أو اترك الحقل "
                                             "فارغاً")
                        shake_widget(card)
                        return
                    _cdate_val4 = _cd_obj4.isoformat()
                # سياق الدين يُلتقط في بداية دالة الحفظ القائمة نفسها
                self._pending_credit = {"customer_id": cid4,
                                        "customer_name": cname4,
                                        "down": float(down4),
                                        "collection_date": _cdate_val4}
                try:
                    if mode == "op":
                        self.e_customer.delete(0, "end")
                        self.e_customer.insert(0, cname4)
                    else:
                        self.e_inv_customer.delete(0, "end")
                        self.e_inv_customer.insert(0, cname4)
                except Exception:
                    pass
                win.destroy()
                # نفس دالة الحفظ القائمة حرفياً — لا نسخ لمنطق البيع
                if mode == "op":
                    self.save_op()
                else:
                    self.save_invoice()
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                messagebox.showerror("بيع بالدين",
                    "تعذر إتمام البيع بالدين — سُجّل الخطأ في error_log.txt",
                    parent=win)

        def _cancel4():
            win.destroy()

        bar4 = tk.Frame(card, bg=CARD)
        bar4.pack(fill="x", pady=(6, 12))
        self.mk_btn(bar4, "✅ تأكيد البيع بالدين", _confirm4, ORANGE).pack(
            side="right", padx=6)
        self.mk_btn(bar4, "إلغاء", _cancel4, "#475569").pack(side="right", padx=6)
        _sync_cust4()
        _warn4()
        try:
            e_cname4.focus_set()
        except Exception:
            pass

    def show_customers_window(self):
        """★ إضافة (المرحلة الرابعة): فتح «العملاء والديون والضمانات» —
        الفحص الثاني عند الفتح (دفاع مزدوج مع إخفاء الزر في الشريط)، نافذة
        واحدة بحجم ثابت 950×620 ودفتر تبويبات، وكل تبويب يُنشأ لمالك مفتاحه
        فقط (إخفاء لا تعطيل) ويُبنى داخل try/except مستقل يكتب العطل في
        error_log.txt ويبقي بقية التبويبات تعمل"""
        if not (self.role == ADMIN_ROLE
                or any(user_has_permission(self.user_name, k)
                       for k in STAGE4_WINDOW_KEYS)):
            b = getattr(self, "nav_buttons", {}).get("customers_window")
            if b is not None:
                b.pack_forget()
            messagebox.showwarning("لا تملك صلاحية",
                "نافذة «العملاء والديون والضمانات» تتطلب واحدة على الأقل من "
                "صلاحياتها الخمس:\nالعملاء / الديون والتحصيل / الضمانات / "
                "العملاء غير النشطين / أسباب المرتجع — راجع الأدمن")
            return
        try:
            _ensure_stage4_tables()
        except Exception:
            pass
        win = self.register_window(tk.Toplevel(self))
        win.title("العملاء والديون والضمانات")
        win.configure(bg=BG)
        try:
            _st4 = ttk.Style(win)
            _st4.configure("CustomersWin.TNotebook.Tab",
                           font=("Segoe UI", 10, "bold"), padding=(14, 8))
        except Exception:
            pass
        nb4 = ttk.Notebook(win, style="CustomersWin.TNotebook")
        nb4.pack(fill="both", expand=True, padx=10, pady=10)

        def _add_tab4(check, title, builder):
            """إنشاء تبويب واحد لمالك مفتاحه فقط + بناء مستقل آمن"""
            try:
                ok = (self.role == ADMIN_ROLE) or check()
            except Exception:
                ok = False
            if not ok:
                return
            tab = tk.Frame(nb4, bg=BG)
            try:
                builder(tab)
            except Exception as e:
                log_error(e, sys.exc_info()[2])
                tk.Label(tab, text="⚠️ تعذر بناء هذا التبويب — سُجّل السبب في "
                                   "error_log.txt وبقية التبويبات تعمل",
                         bg=BG, fg=RED, font=FB).pack(expand=True)
            nb4.add(tab, text=title)

        _add_tab4(lambda: (user_has_permission(self.user_name, "sell_on_credit")
                           or user_has_permission(self.user_name, "collections_list")),
                  "👥 العملاء", self._build_cw_customers_tab)
        _add_tab4(lambda: user_has_permission(self.user_name, "collections_list"),
                  "💵 الديون والتحصيل", self._build_cw_debts_tab)
        _add_tab4(lambda: user_has_permission(self.user_name, "warranty_reminder"),
                  "🛡️ الضمانات", self._build_cw_warranties_tab)
        _add_tab4(lambda: user_has_permission(self.user_name, "inactive_customers"),
                  "😴 عملاء غير نشطين", self._build_cw_inactive_tab)
        _add_tab4(lambda: user_has_permission(self.user_name, "return_reasons_report"),
                  "↩️ أسباب المرتجع", self._build_cw_reasons_tab)
        if not nb4.tabs():
            tk.Label(win, text="لا تملك صلاحية أي تبويب من تبويبات هذه النافذة — "
                               "راجع الأدمن", bg=BG, fg=RED, font=FB).pack(expand=True)
        place_window(win, 950, 620)

    # ---------- التبويب 1: العملاء ----------
    def _build_cw_customers_tab(self, tab):
        """★ إضافة (المرحلة الرابعة): تبويب العملاء — جدول بالاسم والهاتف
        وإجمالي الدين المتبقي وتاريخ آخر شراء وبحث بالاسم أو الهاتف،
        وأزرار إضافة عميل وتعديل بيانات وبطاقة عميل، والحذف للأدمن فقط
        وممنوع على من عليه دين متبقٍ"""
        bar4 = tk.Frame(tab, bg=BG)
        bar4.pack(fill="x", padx=12, pady=(10, 4))
        tk.Label(bar4, text="بحث (اسم أو هاتف):", bg=BG, fg=GRAY,
                 font=FB).pack(side="right", padx=(0, 6))
        self._cw_search = tk.StringVar()
        e_s4 = tk.Entry(bar4, font=F, justify="center", relief="solid",
                        bd=1, width=22, textvariable=self._cw_search)
        e_s4.pack(side="right", ipady=3)
        self._cw_search.trace_add("write", lambda *_: self._cw_refresh_customers())
        self.mk_btn(bar4, "🔄 تحديث", self._cw_refresh_customers,
                    "#475569").pack(side="left", padx=4)
        self.mk_btn(bar4, "➕ إضافة عميل", self._cw_add_customer,
                    GREEN).pack(side="left", padx=4)
        self.mk_btn(bar4, "✏️ تعديل بيانات", self._cw_edit_customer,
                    ACCENT).pack(side="left", padx=4)
        self.mk_btn(bar4, "🪪 بطاقة عميل", self._cw_customer_card,
                    "#7c3aed").pack(side="left", padx=4)
        if self.role == ADMIN_ROLE:
            self.mk_btn(bar4, "🗑 حذف عميل", self._cw_delete_customer,
                        RED).pack(side="left", padx=4)
        frm4, self._cw_tv_cust = self.mk_tree(
            tab, ["الاسم", "الهاتف", "إجمالي الدين المتبقي", "تاريخ آخر شراء",
                  "أضيف في"], [230, 130, 170, 130, 150])
        frm4.pack(fill="both", expand=True, padx=12, pady=8)
        self._cw_cust_map = {}
        self._cw_refresh_customers()

    def _cw_refresh_customers(self, *_):
        """★ إضافة (المرحلة الرابعة): تحديث جدول العملاء مع البحث بالاسم
        أو الهاتف — قراءة صامتة لا تكسر شيئاً أبداً"""
        try:
            tv = getattr(self, "_cw_tv_cust", None)
            if tv is None or not tv.winfo_exists():
                return
            q4 = (getattr(self, "_cw_search", None) and
                  self._cw_search.get().strip()) or ""
            tv.delete(*tv.get_children())
            self._cw_cust_map = {}
            for c in customers_all():
                if q4 and (q4 not in (c["name"] or "")
                           and q4 not in (c["phone"] or "")):
                    continue
                debt4 = customer_debt_total(c["id"])
                last4 = customer_last_purchase(c["id"], c["name"]) or "—"
                tv.insert("", "end", iid=str(c["id"]),
                          values=(c["name"], c["phone"] or "—",
                                  money(debt4), last4,
                                  (c["created_at"] or "—")[:10]))
                self._cw_cust_map[str(c["id"])] = dict(c)
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    def _cw_selected_customer(self):
        """العميل المحدد في جدول العملاء (dict) أو None"""
        try:
            tv = getattr(self, "_cw_tv_cust", None)
            if tv is None:
                return None
            sel = tv.selection()
            if not sel:
                return None
            return self._cw_cust_map.get(sel[0])
        except Exception:
            return None

    def _cw_add_customer(self):
        """★ إضافة (المرحلة الرابعة): إضافة عميل جديد — الاسم إلزامي
        والهاتف والملاحظات اختيارية"""
        try:
            win = self.register_window(tk.Toplevel(self))
            win.title("إضافة عميل")
            win.configure(bg=BG)
            win.resizable(False, False)
            card = tk.Frame(win, bg=CARD, highlightbackground=BORDER,
                            highlightthickness=1)
            card.pack(fill="both", expand=True, padx=14, pady=12)
            tk.Label(card, text="➕ إضافة عميل جديد", bg=CARD, fg=DARK,
                     font=FT).pack(pady=(10, 4))
            grid4 = tk.Frame(card, bg=CARD)
            grid4.pack(pady=6)
            tk.Label(grid4, text="الاسم (إلزامي):", bg=CARD, fg=GRAY,
                     font=FB).grid(row=0, column=0, sticky="e", padx=8, pady=5)
            e_n4 = tk.Entry(grid4, font=F, justify="center", relief="solid",
                            bd=1, width=24)
            e_n4.grid(row=0, column=1, padx=8, pady=5)
            tk.Label(grid4, text="الهاتف:", bg=CARD, fg=GRAY,
                     font=FB).grid(row=1, column=0, sticky="e", padx=8, pady=5)
            e_p4 = tk.Entry(grid4, font=F, justify="center", relief="solid",
                            bd=1, width=24)
            e_p4.grid(row=1, column=1, padx=8, pady=5)
            tk.Label(grid4, text="ملاحظات:", bg=CARD, fg=GRAY,
                     font=FB).grid(row=2, column=0, sticky="e", padx=8, pady=5)
            e_no4 = tk.Entry(grid4, font=F, justify="center", relief="solid",
                             bd=1, width=24)
            e_no4.grid(row=2, column=1, padx=8, pady=5)
            lbl_err4 = tk.Label(card, text="", bg=CARD, fg=RED,
                                font=("Segoe UI", 9, "bold"))
            lbl_err4.pack()

            def _save4():
                name4 = e_n4.get().strip()
                if not name4:
                    lbl_err4.config(text="اسم العميل إلزامي")
                    shake_widget(card)
                    return
                try:
                    with connect() as conn:
                        conn.execute("INSERT INTO customers(name, phone, notes, "
                                     "created_at) VALUES(?,?,?,?)",
                                     (name4, e_p4.get().strip() or None,
                                      e_no4.get().strip() or None,
                                      datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
                    audit("إضافة عميل", f"العميل: {name4}")
                    win.destroy()
                    self._cw_refresh_customers()
                except Exception as e:
                    log_error(e, sys.exc_info()[2])
                    messagebox.showerror("خطأ", "تعذر حفظ العميل — سُجّل الخطأ "
                                        "في error_log.txt", parent=win)

            def _cancel4():
                win.destroy()

            bar4 = tk.Frame(card, bg=CARD)
            bar4.pack(fill="x", pady=(4, 10))
            self.mk_btn(bar4, "💾 حفظ", _save4, GREEN).pack(side="right", padx=6)
            self.mk_btn(bar4, "إلغاء", _cancel4, "#475569").pack(side="right", padx=6)
            e_n4.focus_set()
            place_window(win, 420, 360)
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    def _cw_edit_customer(self):
        """★ إضافة (المرحلة الرابعة): تعديل بيانات عميل قائم"""
        try:
            c = self._cw_selected_customer()
            if c is None:
                messagebox.showwarning("تنبيه", "اختر عميلاً من الجدول أولاً")
                return
            win = self.register_window(tk.Toplevel(self))
            win.title("تعديل بيانات عميل")
            win.configure(bg=BG)
            win.resizable(False, False)
            card = tk.Frame(win, bg=CARD, highlightbackground=BORDER,
                            highlightthickness=1)
            card.pack(fill="both", expand=True, padx=14, pady=12)
            tk.Label(card, text=f"✏️ تعديل بيانات: {c['name']}", bg=CARD,
                     fg=DARK, font=FT).pack(pady=(10, 4))
            grid4 = tk.Frame(card, bg=CARD)
            grid4.pack(pady=6)
            tk.Label(grid4, text="الاسم (إلزامي):", bg=CARD, fg=GRAY,
                     font=FB).grid(row=0, column=0, sticky="e", padx=8, pady=5)
            e_n4 = tk.Entry(grid4, font=F, justify="center", relief="solid",
                            bd=1, width=24)
            e_n4.insert(0, c["name"])
            e_n4.grid(row=0, column=1, padx=8, pady=5)
            tk.Label(grid4, text="الهاتف:", bg=CARD, fg=GRAY,
                     font=FB).grid(row=1, column=0, sticky="e", padx=8, pady=5)
            e_p4 = tk.Entry(grid4, font=F, justify="center", relief="solid",
                            bd=1, width=24)
            e_p4.insert(0, c["phone"] or "")
            e_p4.grid(row=1, column=1, padx=8, pady=5)
            tk.Label(grid4, text="ملاحظات:", bg=CARD, fg=GRAY,
                     font=FB).grid(row=2, column=0, sticky="e", padx=8, pady=5)
            e_no4 = tk.Entry(grid4, font=F, justify="center", relief="solid",
                             bd=1, width=24)
            e_no4.insert(0, c["notes"] or "")
            e_no4.grid(row=2, column=1, padx=8, pady=5)
            lbl_err4 = tk.Label(card, text="", bg=CARD, fg=RED,
                                font=("Segoe UI", 9, "bold"))
            lbl_err4.pack()

            def _save4():
                name4 = e_n4.get().strip()
                if not name4:
                    lbl_err4.config(text="اسم العميل إلزامي")
                    shake_widget(card)
                    return
                try:
                    with connect() as conn:
                        conn.execute("UPDATE customers SET name=?, phone=?, notes=? "
                                     "WHERE id=?",
                                     (name4, e_p4.get().strip() or None,
                                      e_no4.get().strip() or None, c["id"]))
                    audit("تعديل عميل",
                          f"العميل رقم {c['id']}: {c['name']} ← {name4}")
                    win.destroy()
                    self._cw_refresh_customers()
                except Exception as e:
                    log_error(e, sys.exc_info()[2])
                    messagebox.showerror("خطأ", "تعذر حفظ التعديل — سُجّل الخطأ "
                                        "في error_log.txt", parent=win)

            def _cancel4():
                win.destroy()

            bar4 = tk.Frame(card, bg=CARD)
            bar4.pack(fill="x", pady=(4, 10))
            self.mk_btn(bar4, "💾 حفظ", _save4, GREEN).pack(side="right", padx=6)
            self.mk_btn(bar4, "إلغاء", _cancel4, "#475569").pack(side="right", padx=6)
            place_window(win, 420, 360)
        except Exception as e:
            log_error(e, sys.exc_info()[2])

    def _cw_delete_customer(self):
        """★ إضافة (المرحلة الرابعة): حذف عميل — أدمن فقط، وممنوع منعاً
        باتاً إن كان عليه دين متبقٍ (رسالة عربية تمنع)"""
        try:
            if self.role != ADMIN_ROLE:
                messagebox.showwarning("ممنوع", "حذف العملاء للأدمن حصراً")
                return
            c = self._cw_selected_customer()
            if c is None:
                messagebox.showwarning("تنبيه", "اختر عميلاً من الجدول أولاً")
                return
            debt4 = customer_debt_total(c["id"])
            if debt4 > 1e-9:
                messagebox.showwarning("حذف ممنوع",
                    f"لا يمكن حذف العميل «{c['name']}» — عليه دين متبقٍ "
                    f"بمبلغ {money(debt4)}.\nسدد الدين أو حصّله أولاً.")
                return
            if not messagebox.askyesno("تأكيد الحذف",
                    f"حذف العميل «{c['name']}» نهائياً؟\n"
                    "(فواتيره وضماناته وديونه المسددة تبقى في سجلاتها)"):
                return
            with connect() as conn:
                conn.execute("DELETE FROM customers WHERE id=?", (c["id"],))
            audit("حذف عميل", f"العميل رقم {c['id']}: {c['name']} — بلا دين متبقٍ")
            self._cw_refresh_customers()
        except Exception as e:
            log_error(e, sys.exc_info()[2])
            messagebox.showerror("خطأ", "تعذر حذف العميل — سُجّل الخطأ في "
                                "error_log.txt")

